        [1154] = { name = "Test der Lehre", objective = "Sucht das 'Vermächtnis der Aspekte' und bringt es zu Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge zurück." },
        [1159] = { name = "Test der Lehre", objective = "Sucht Parqual Fintallas in Undercity." },
        [1160] = { name = "Test der Lehre", objective = "Sucht Die Anfänge der Bedrohung durch die Untoten und bringt es zu Parqual Fintallas in Undercity." },
        [1198] = { name = "Auf der Suche nach Thaelrid", objective = "Sucht Argentumwache Thaelrid in der Blackfathom-Tiefe auf." },
        [1199] = { name = "Die Twilight fallen", objective = "Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus" },
        [1200] = { name = "Schurkerei in Blackfathom", objective = "Bringt den Kopf des Twilight-Lords Kelris zu Dämmerungsbehüter Selgorm in Darnassus." },
        [1221] = { name = "Blaulaubknollen", objective = "Schnappt Euch eine Kiste mit Löchern.\nSchnappt Euch einen Schnüffelnasenleitstecken.\nSchnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es.\n\nBenutzt im Kral von Razorfen die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht.\n\nBringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratchet." },
        [1275] = { name = "Erforschung der Verderbnis", objective = "Gershala Nightwhisper in Auberdine möchte 8 verderbte Hirnstämme." },
        [1360] = { name = "Wiederbeschaffte Schätze", objective = "Holt Krom Stoutarms wertvollen Besitz aus seiner Truhe in der nördlichen Bankenhalle von Uldaman und bringt den Schatz zu ihm nach Ironforge." },
        [1394] = { name = "Letzte Überfahrt", objective = "Sprecht mit Dorn Plainstalker in Tausend Nadeln." },
        [1424] = { name = "Tränenteich", objective = "Fel'Zerul in Stonard möchte, dass Ihr 10 Artefakte der Atal'ai sammelt." },
        [1429] = { name = "Der Verbannte der Atal'ai", objective = "Bringt das Artefaktbündel der Atal'ai zu dem Verbannten der Atal'ai ins Hinterland." },
        [1444] = { name = "Rückkehr zu Fel'Zerul", objective = "Kehrt zu Fel'Zerul in Stonard zurück." },
        [1445] = { name = "Der Tempel von Atal'Hakkar", objective = "Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Stonard." },
        [1446] = { name = "Jammal'an der Prophet", objective = "Der Verbannte der Atal'ai im Hinterland möchte den Kopf von Jammal'an." },
        [1448] = { name = "Auf der Suche nach dem Tempel", objective = "Brohann Caskbelly in Stormwind möchte, dass Ihr den Tempel von Atal'Hakkar sucht." },
        [1449] = { name = "Ins Hinterland", objective = "Sprecht mit dem obersten Than, Falstad Wildhammer, in Aerie Peak im Hinterland." },
        [1450] = { name = "Greifenmeister Talonaxe", objective = "Sprecht mit Greifenmeister Talonaxe im Horst bei Aerie Peak." },
        [1451] = { name = "Rhapsody-Shindigger", objective = "Sucht Rhapsody Shindigger im Hinterland." },
        [1452] = { name = "Rhapsodys Kalimdor-Cocktail", objective = "Rhapsody Shindigger im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoc-Lebern und 3 Eisenfelllebern bringt." },
        [1469] = { name = "Rhapsodys Geschichte", objective = "Bringt das Schrifttafelfragment der Atal'ai zu Brohann Caskbelly in Stormwind." },
        [1475] = { name = "Im Tempel von Atal'Hakkar", objective = "Sammelt 10 Schrifttafeln der Atal'ai für Brohann Caskbelly in Stormwind." },
        [1486] = { name = "Deviatbälge", objective = "Nalpak in den Höhlen des Wehklagens möchte 20 Deviatbälge." },
        [1487] = { name = "Ausrottung der Deviat", objective = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckensfange tötet." },
        [1489] = { name = "Hamuul Runentotem", objective = "Sprecht mit Hamuul Runetotem." },
        [1490] = { name = "Nara Wildmähne", objective = "Sprecht mit Nara Wildmane." },
        [1491] = { name = "Klugheitstränke", objective = "Bringt 6 Portionen Klageessenz zu Mebok Mizzyrix in Ratchet." },
        [1651] = { name = "Der Foliant der Ehre", objective = "Verteidigt Daphne Stilwell vor dem Angriff der Defias.\n\nKeiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt.\n\nSprecht erneut mit Daphne Stilwell, wenn Ihr erfolgreich wart." },
        [1652] = { name = "Der Foliant der Ehre", objective = "Sprecht mit Duthorian Rall in Stormwind." },
        [1653] = { name = "Die Prüfung der Rechtschaffenheit", objective = "Sprecht mit Jordan Stilwell in Ironforge." },
        [1654] = { name = "Die Prüfung der Rechtschaffenheit", objective = "Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Kor-Edelstein und bringt alles zusammen zu Jordan Stilwell in Ironforge." },
        [1699] = { name = "Der Rethban-Spießrutenlauf", objective = "Betretet die Rethbanhöhlen, geht bis zur ersten Gabelung und kehrt innerhalb der zulässigen Zeit zu Yorus Gerstenbräu zurück.\n\nIhr dürft nicht sterben und Euren Geist befreien." },
        [1701] = { name = "Feuergehärteter Panzer", objective = "Sammelt die Materialien, die Furen Longbeard benötigt, und bringt sie zu ihm nach Stormwind." },
        [1702] = { name = "Der Schildschmied", objective = "Bringt das Fässlein mit Gerstenbräu zu Furen Longbeard." },
        [1740] = { name = "Die Kugel von Soran'ruk", objective = "Sucht 3 Soran'ruk-Fragmente und 1 großes Soran'ruk-Fragment und bringt sie zu Doan Karhan im Brachland." },
        [1782] = { name = "Furens Rüstung", objective = "Hier ist Eure Rüstung, <Name>. Sie wird dem stärksten Angriff standhalten, oder ich will nicht mehr Furen Longbeard heißen!\n\nUnd ich habe Euch zu danken. Ich habe bei der Arbeit mit dem Material, das Ihr mir brachtet, viel gelernt. Ich glaube, eines Tages werde ich einen weiteren Durchbruch schaffen!\n\nIch werde das, was ich gelernt habe, den anderen Schmieden der Allianz schicken.\n\nIch sage ihnen, was für eine große Hilfe Ihr wart. Vielleicht möchten sie den Gefallen erwidern." },
        [1806] = { name = "Die Prüfung der Rechtschaffenheit", objective = "Wartet, bis Jordan Stilwell eine Waffe für Euch geschmiedet hat." },
        [1824] = { name = "Prüfung auf dem Feld der Riesen", objective = "Bringt 5 zuckende Fühler zu Ruga Ragetotem im Camp Taurajo." },
        [1825] = { name = "Gespräch mit Thun'grim", objective = "Sprecht mit Thun'grim Firegaze im Brachland." },
        [1838] = { name = "Brutale Rüstung", objective = "Bringt Thun'grim Firegaze 15 rauchige Eisenblöcke, 10 pulverisierte Azurite, 10 Eisenbarren und 1 Phiole Phlogiston." },
        [1848] = { name = "Brutale Halsberge", objective = "Ich bin sicher, Ihr habt bei dieser Aufgabe viele Unannehmlichkeiten erduldet und viel Blut vergossen, <Name>. Hier ist das Produkt Eurer Mühsal.\n\nMöge es Euch gute Dienste leisten und möget Ihr eines Tages wiederkommen und erzählen, wie nützlich sie Euch waren." },
        [1954] = { name = "Die Höllenkugel", objective = "Bringt eine Höllenkugel zu Tabetha in den Marschen von Dustwallow." },
        [1955] = { name = "Die Austreibung", objective = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha." },
        [1956] = { name = "Macht in Uldaman", objective = "Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha." },
        [2040] = { name = "Unterirdischer Angriff", objective = "Holt das Gnoam-Sprecklesprocket aus den Todesminen und bringt es Shoni der Schtillen in Stormwind." },
        [2041] = { name = "Sprecht mit Shoni", objective = "Sprecht mit Shoni der Schtillen in Stormwind." },
        [2198] = { name = "Die zerrissene Halskette", objective = "Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren." },
        [2199] = { name = "Lehren haben ihren Preis", objective = "Bringt fünf Silberbarren zu Talvash del Kissel in Ironforge." },
        [2200] = { name = "Rückkehr nach Uldaman", objective = "Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt." },
        [2201] = { name = "Suche nach den Edelsteinen", objective = "Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat.\n\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.\n\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen." },
        [2202] = { name = "Reagenzsuche in Uldaman", objective = "Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Mossmeld." },
        [2204] = { name = "Restaurierung der Halskette", objective = "Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab." },
        [2240] = { name = "Die geheime Kammer", objective = "Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht." },
        [2258] = { name = "Reagenzien-Suche im Ödland", objective = "Bringt Jarkal Mossmeld in Kargath im Ödland 5 Bussard-Mägen, 10 Klippenkojoten-Fangzähne und 5 Felselementarsplitter." },
        [2278] = { name = "Die Platinscheiben", objective = "Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon." },
        [2279] = { name = "Die Platinscheiben", objective = "Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Ironforge." },
        [2280] = { name = "Die Platinscheiben", objective = "Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Thunder Bluff." },
        [2283] = { name = "Wiederbeschaffung der Halskette", objective = "Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt." },
        [2284] = { name = "Wiederbeschaffung der Halskette, Teil 2", objective = "Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine." },
        [2318] = { name = "Übersetzung des Tagebuchs", objective = "Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland." },
        [2338] = { name = "Übersetzung des Tagebuchs", objective = "Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen." },
        [2339] = { name = "Findet die Edelsteine und die Kraftquelle", objective = "Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Mossmeld nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet.\n\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen." },
        [2340] = { name = "Ablieferung der Edelsteine", objective = "Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab." },
        [2341] = { name = "Wiederbeschaffung der Halskette, Teil 3", objective = "Besucht Jarkal Mossmeld in Kargath, um festzustellen, ob er Erfolg gehabt hat." },
        [2342] = { name = "Wiederbeschaffte Schätze", objective = "Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity." },
        [2361] = { name = "Restaurierung der Halskette", objective = "Ich gebe Euch diese Halskette gern, <Klasse>. Ihr habt mir einen unschätzbaren Dienst erwiesen und dafür danke ich Euch. Tragt die Kette mit Stolz und vergesst nicht, immer wieder in der gebührenden Lautstärke zu verkünden, wer sie für Euch gemacht hat!\n\nUnd wenn Ihr auch beiläufig erwähnen könntet, dass die Kette nicht verflucht ist, dann wäre das wirklich wunderbar." },
        [2398] = { name = "Die verschollenen Zwerge", objective = "Sucht in Uldaman nach Baelog." },
        [2418] = { name = "Kraftsteine", objective = "Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum." },
        [2439] = { name = "Die Platinscheiben", objective = "Bringt Euren Belohnungsgutschein zu Dinita Stonemantle im Gewölbe von Ironforge." },
        [2500] = { name = "Reagenzien-Suche im Ödland", objective = "Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar." },
        [2768] = { name = "Wünschel-mato-Rute", objective = "Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle." },
        [2769] = { name = "Die Brüder Brassbolt", objective = "Sprecht mit Wizzle Brassbolts in der schimmernden Ebene." },
        [2770] = { objective = "Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe." },
        [2841] = { name = "Maschinenkriege", objective = "Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar." },
        [2842] = { name = "Chefingenieur Scooty", objective = "Sprecht mit Scooty in Booty Bay." },
        [2843] = { name = "Gnomer-weeeeg!", objective = "Wartet, bis Scooty den Goblin-Transponder kalibriert hat." },
        [2846] = { name = "Tiara der Tiefen", objective = "Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow." },
        [2861] = { name = "Tabethas Aufgabe", objective = "Sprecht mit Tabetha in den Marschen von Dustwallow." },
        [2864] = { objective = "Sprecht mit Tran’rek in Gadgetzan." },
        [2865] = { name = "Skarabäuspanzerschalen", objective = "Bringt Tran’rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen." },
        [2904] = { name = "Eine schöne Bescherung", objective = "Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay." },
        [2922] = { name = "Rettet Techbots Hirn!", objective = "Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge." },
        [2924] = { name = "Grundlegende Artifixe", objective = "Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe." },
        [2926] = { objective = "Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück." },
        [2928] = { name = "Gyrobohrmatische Exkavation", objective = "Bringt 24 robomechanische Innereien zu Shoni nach Stormwind." },
        [2929] = { name = "Der große Verrat", objective = "Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist." },
        [2930] = { name = "Datenrettung", objective = "Bringt Mechanikermeister Castpipe in Ironforge eine Prismalochkarte." },
        [2933] = { name = "Giftflaschen", objective = "Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle." },
        [2934] = { name = "Unbeschädigter Giftbeutel", objective = "Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel." },
        [2935] = { name = "Konsultiert Meister Gadrin", objective = "Sprecht mit Meister Gadrin in Sen'jin." },
        [2936] = { name = "Der Spinnengott", objective = "Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Witherbark zu erfahren, und kehrt dann zu Meister Gadrin zurück." },
        [2945] = { name = "Schmutzverkrusteter Ring", objective = "Findet einen Weg, den schmutzverkrusteten Ring zu säubern." },
        [2947] = { name = "Die Rückkehr des Rings", objective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist." },
        [2948] = { name = "Gnomen-Verbesserungen", objective = "Bringt Talvash del Kissel in Ironforge den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen." },
        [2949] = { name = "Die Rückkehr des Rings", objective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist." },
        [2950] = { name = "Noggs Ringerneuerung", objective = "Bringt Nogg in Orgrimmar den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen." },
        [2951] = { name = "Der Funkelmat 5200!", objective = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren." },
        [2962] = { name = "Das einzige Heilmittel ist mehr grünes Leuchten", objective = "Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.\n\nOzzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist." },
        [2988] = { name = "Käfige der Witherbark", objective = "Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück." },
        [2989] = { name = "Der Altar von Zul", objective = "Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück." },
        [2990] = { name = "Thadius Grimmschatten", objective = "Bringt Scharfschnabels Feder zu Thadius Grimshade in die verwüsteten Lande." },
        [2991] = { name = "Nekrums Medaillon", objective = "Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon." },
        [3042] = { name = "Trollaushärter", objective = "Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan." },
        [3341] = { name = "Das Ende bringen", objective = "Andrew Brownell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt." },
        [3373] = { name = "Die Essenz des Eranikus", objective = "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet." },
        [3380] = { name = "Der versunkene Tempel", objective = "Sucht Marvon Rivetseeker in Tanaris." },
        [3444] = { name = "Der runde Stein", objective = "Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet." },
        [3445] = { name = "Der versunkene Tempel", objective = "Sucht Marvon Rivetseeker in Tanaris." },
        [3446] = { name = "In die Tiefen", objective = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends." },
        [3447] = { name = "Das Geheimnis des Kreises", objective = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt." },
        [3520] = { name = "Kreischergeister", objective = "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück." },
        [3523] = { name = "Geißel der Niederungen", objective = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab." },
        [3525] = { name = "Ausschalten des Götzen", objective = "Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen.\n\nBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten." },
        [3527] = { name = "Die Prophezeiung von Mosh'aru", objective = "Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris." },
        [3528] = { name = "Der Gott Hakkar", objective = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris." },
        [3636] = { name = "Das Licht bringen", objective = "Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln von Razorfen tötet." },
        [3701] = { name = "Die glimmenden Ruinen von Thaurissan", objective = "Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt." },
        [3702] = { name = "Die glimmenden Ruinen von Thaurissan", objective = "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan." },
        [3765] = { name = "Verderbnis in der Fremde", objective = "Reist zu Gershala Nightwhisper in Auberdine." },
        [3801] = { name = "Dunkeleisenerbe", objective = "Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten." },
        [3802] = { name = "Dunkeleisenerbe", objective = "Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright." },
        [3906] = { name = "Disharmonie der Flamme", objective = "Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt." },
        [3907] = { name = "Disharmonie des Feuers", objective = "Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart." },
        [3981] = { name = "Kommandant Gor'shak", objective = "Sucht Kommandant Gor'shak in den Blackrocktiefen.\n\nIhr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen." },
        [3982] = { name = "Was ist los?", objective = "Verteidigt Gor'shak." },
        [4001] = { name = "Was ist los?", objective = "Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar.\n\nIhr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten." },
        [4002] = { name = "Das östliche Königreich", objective = "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen." },
        [4003] = { name = "Die königliche Rettung", objective = "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber." },
        [4004] = { name = "Ist die Prinzessin gerettet?", objective = "Kehrt zu Thrall zurück!" },
        [4024] = { name = "Eine Kostprobe der Flamme", objective = "Begebt Euch in die Blackrocktiefen und tötet Bael'Gar.\n\nIhr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.\n\nBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück." },
        [4061] = { name = "Aufstieg der Maschinen", objective = "Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.\n\nEuch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter." },
        [4062] = { name = "Aufstieg der Maschinen", objective = "Bringt die Elementarsplitterprobe zu Lotwil Veriatus.\n\nIhr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert." },
        [4063] = { name = "Aufstieg der Maschinen", objective = "Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt." },
        [4081] = { name = "SOFORT TÖTEN: Dunkeleisenzwerge", objective = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt." },
        [4082] = { name = "SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge", objective = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt." },
        [4083] = { name = "Der spektrale Kelch", objective = "Der spektrale Kelch schwebt in der Luft, leicht ansteigend und dann absinkend, so, als bewege er sich im Takt eines sterbenden Herzens." },
        [4121] = { name = "Gefährliche Zwickmühle", objective = "Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Blackrock in die sengende Schlucht.\n\nEuch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.\n\nIhr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen." },
        [4122] = { objective = "Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung der Blackrock gesehen worden.\n\nWenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Blackrock in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen." },
        [4123] = { name = "Das Herz des Berges", objective = "Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe." },
        [4126] = { name = "Hurley Pestatem", objective = "Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept." },
        [4128] = { name = "Ragnar Donnerbräu", objective = "Sprecht mit Ragnar Donnerbräu." },
        [4132] = { name = "Operation: Tod dem Zornesschmied", objective = "Begebt Euch zu den Blackrocktiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Goretooth zurück, sobald Ihr diese Aufgabe erledigt habt." },
        [4133] = { objective = "Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath." },
        [4134] = { name = "Verlorenes Donnerbräurezept", objective = "Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept." },
        [4136] = { name = "Ribbly Schraubstutz", objective = "Bringt Yuka Screwspigot in der brennenden Steppe Ribblys Kopf." },
        [4141] = { name = "Muigin und Larion", objective = "Sammelt 15 Blutblüten und kehrt zu Muigin zurück." },
        [4142] = { name = "Ein Besuch bei Gregan", objective = "Bringt Gregan Brewspewer in Feralas eine Blutblüte." },
        [4143] = { name = "Der Dunst des Bösen", objective = "Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Un'Goro Krater." },
        [4145] = { name = "Larion und Muigin", objective = "Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marshals Zuflucht." },
        [4146] = { name = "Schrumpf-Treibstoff", objective = "Bringt Larion in Marshals Zuflucht den ungeladenen Schrumpfer und 5 Proben Dunst der Atal'ai." },
        [4147] = { name = "Marvons Werkstatt", objective = "Reist zu Marvon Rivetseekers Werkstatt in Ratchet." },
        [4182] = { name = "Drachkin-Bedrohung", objective = "Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist." },
        [4183] = { name = "Die wahren Meister", objective = "Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus." },
        [4184] = { name = "Die wahren Meister", objective = "Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor.\n\nBolvar residiert in der Burg Stormwind." },
        [4185] = { name = "Die wahren Meister", objective = "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon." },
        [4186] = { name = "Die wahren Meister", objective = "Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus." },
        [4201] = { name = "Der Liebestrank", objective = "Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Blackrocktiefen." },
        [4223] = { name = "Die wahren Meister", objective = "Sprecht mit Marshal Maxwell in der brennenden Steppe." },
        [4224] = { name = "Die wahren Meister", objective = "Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.\n\nIhr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen." },
        [4241] = { name = "Marschall Windsor", objective = "Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist.\n\nIhr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt." },
        [4242] = { name = "Verlorene Hoffnung", objective = "Überbringt Marshal Maxwell die schlechten Neuigkeiten." },
        [4262] = { name = "Übermeister Pyron", objective = "Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück.\n\nIhr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?" },
        [4263] = { objective = "Sucht Lord Incendius in den Blackrocktiefen und vernichtet ihn!" },
        [4264] = { name = "Eine zusammengeknüllte Notiz", objective = "Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung." },
        [4282] = { name = "Ein Funken Hoffnung", objective = "Holt Marshal Windsors verloren gegangene Informationen zurück.\n\nMarshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden." },
        [4286] = { name = "Feine Sachen", objective = "Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen." },
        [4295] = { name = "Rocknots Bier", objective = "Oh, Bier! Was würde ich nicht für etwas Dunkeleisenbier geben! Schnell, ich werde langsam nüchtern! Das weiß ich, weil mir die Nüchternheit die Sinne trübt... und weil es Euch aussehen lässt wie der <Volk>, den ich letzte Woche erschlagen habe!" },
        [4322] = { name = "Gefängnisausbruch!", objective = "Helft Marshal Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marshal Windsor zurück, wenn Ihr Erfolg hattet." },
        [4324] = { name = "Yuka Schraubstutz", objective = "Sprecht mit Yuka Screwspigot in der brennenden Steppe." },
        [4341] = { name = "Kharan Hammermacht", objective = "Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer.\n\nDer König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten." },
        [4342] = { name = "Kharans Geschichte", objective = "Lasst Kharan Mighthammer seine Geschichte erzählen." },
        [4361] = { name = "Der Überbringer schlechter Botschaften...", objective = "Kehrt nach Ironforge zurück und überbringt König Magni Bronzebeard die schlechten Nachrichten." },
        [4362] = { name = "Das Schicksal des Königreichs", objective = "Kehrt in die Blackrocktiefen zurück und rettet Prinzessin Moira Bronzebeard aus den Fängen des bösen Imperators Dagran Thaurissan." },
        [4363] = { name = "Die Überraschung der Prinzessin", objective = "Kehrt nach Ironforge zurück und sprecht mit König Magni Bronzebeard." },
        [4701] = { name = "Stellt sie ab", objective = "Begebt Euch zur Blackrockspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs." },
        [4724] = { name = "Die Herrin der Meute", objective = "Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte." },
        [4726] = { name = "Brutlingessenz", objective = "Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe." },
        [4729] = { name = "Kiblers Exotische Tiere", objective = "Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler." },
        [4734] = { name = "Ei-Frosten", objective = "Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst." },
        [4735] = { name = "Eiersammlung", objective = "Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe." },
        [4742] = { name = "Siegel des Aufstiegs", objective = "Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.\n\nVaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten." },
        [4743] = { name = "Siegel des Aufstiegs", objective = "Reist zum Drachensumpf in den Marschen von Dustwallow. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.\n\nIn genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!" },
        [4764] = { name = "Doomriggers Schnalle", objective = "Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle." },
        [4766] = { name = "Mayara Wolkenglanz", objective = "Sprecht mit Mayara Brightwing in der brennenden Steppe." },
        [4768] = { name = "Die Darkstone-Schrifttafel", objective = "Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel." },
        [4769] = { name = "Vivian Lagrave und die Darkstone-Schrifttafel", objective = "Sprecht mit Schattenmagierin Vivian Lagrave." },
        [4771] = { name = "Dämmerungstrickfalle", objective = "Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück." },
        [4787] = { name = "Das uralte Ei", objective = "Bringt das uralte Ei zu Yeh'kinya nach Tanaris." },
        [4788] = { name = "Die letzten Schrifttafeln", objective = "Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru." },
        [4808] = { name = "Felnok Stahlfeder", objective = "Gebt Felnok Steelspring Tinkees Brief." },
        [4809] = { name = "Hörner der Eiswindschimären", objective = "Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre." },
        [4810] = { name = "Rückkehr zu Tinkee", objective = "Bringt Tinkee Steamboil in der brennenden Steppe Felnoks Päckchen." },
        [4862] = { name = "Be-Öh-Es-Eh", objective = "Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler.\n\nLogischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden." },
        [4866] = { name = "Muttermilch", objective = "Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann." },
        [4867] = { name = "Urok Schreckensbote", objective = "Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh." },
        [4903] = { name = "Befehl des Kriegsherrn", objective = "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt." },
        [4907] = { name = "Tinkee Kesseldampf", objective = "Sprecht mit Tinkee Steamboil." },
        [4941] = { name = "Eitriggs Weisheit", objective = "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.\n\nIhr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt." },
        [4974] = { name = "Für die Horde!", objective = "Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück." },
        [4981] = { name = "Agentin Bijou", objective = "Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist." },
        [4982] = { name = "Bijous Habseligkeiten", objective = "Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben." },
        [5001] = { name = "Bijous Habseligkeiten", objective = "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!" },
        [5002] = { name = "Nachricht an Maxwell", objective = "Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marshal Maxwell weiter." },
        [5047] = { name = "Finkle Einhorn, zu Euren Diensten!", objective = "Sprecht mit Malyfous Darkhammer in Everlook." },
        [5065] = { name = "Die verlorenen Schrifttafeln von Mosh'aru", objective = "Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru." },
        [5081] = { name = "Maxwells Mission", objective = "Reist zur Blackrockspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist." },
        [5089] = { name = "General Drakkisaths Befehl", objective = "Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe." },
        [5102] = { name = "General Drakkisaths Niedergang", objective = "Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist." },
        [5122] = { name = "Das Medaillon des Glaubens", objective = "Die Macht dieser Kapelle gibt mir die Kraft, der Verderbnis in meinem Herzen zu widerstehen. Wenn ich sie verlasse, werde ich zu einem Todesritter. Aber es gibt ein Medaillon, das Medaillon des Glaubens, das mir so viel Kraft geben wird, dass ich trotzdem gehen kann.\n\nBitte, <Name>, findet das Medaillon für mich. Es wird von Malor dem Eifrigen bewacht, einem wahnsinnigen Mitglied der Scharlachroten Bruderschaft. Er lebt tief in der scharlachroten Bastion im westlichen Stratholme." },
        [5125] = { name = "Aurius' Abrechnung", objective = "<Name>, ich sterbe... aber meine Seele ist gerettet. Dafür schulde ich Euch mehr, als man mit Worten ausdrücken kann. Bitte, nehmt dies... und kämpft weiter so mutig, <Klasse>!" },
        [5127] = { name = "Die Dämonenschmiede", objective = "Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.\n\nIhr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.\n\nBringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterspring." },
        [5160] = { name = "Die oberste Beschützerin", objective = "Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe." },
        [5212] = { name = "Das Fleisch lügt nicht", objective = "Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt." },
        [5213] = { name = "Der aktive Wirkstoff", objective = "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück." },
        [5214] = { name = "Der große Fras Siabi", objective = "Sucht Fras Siabis Raucherladen in Stratholme und bergt einen Kasten von Siabis Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist." },
        [5243] = { name = "Häuser der Heiligen", objective = "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt." },
        [5244] = { name = "Die Ruinen von Kel'Theril", objective = "Sprecht mit Jaron Stoneshaper in Starfall." },
        [5245] = { name = "Die gequälten Seelen von Kel'Theril", objective = "Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern." },
        [5246] = { name = "Fragmente der Vergangenheit", objective = "Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern." },
        [5247] = { name = "Fragmente der Vergangenheit", objective = "Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern." },
        [5250] = { name = "Sternfall", objective = "Sucht Starfall in Winterspring und sprecht mit Wynd Nightchaser." },
        [5251] = { name = "Der Archivar", objective = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv." },
        [5262] = { name = "Die Wahrheit zeigt sich mit Macht", objective = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern." },
        [5263] = { name = "Übertroffen", objective = "Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück." },
        [5281] = { name = "Die ruhelosen Seelen", objective = "Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde." },
        [5282] = { name = "Die ruhelosen Seelen", objective = "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!\n\nBefreit 15 ruhelose Seelen und kehrt zu Egan zurück." },
        [5341] = { name = "Das Familienvermögen der Barovs", objective = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist." },
        [5343] = { name = "Das Familienvermögen der Barovs", objective = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist." },
        [5382] = { name = "Doktor Theolen Krastinov, der Schlächter", objective = "Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt." },
        [5384] = { name = "Kirtonos der Herold", objective = "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.\n\nKämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück." },
        [5461] = { name = "Der Mensch Ras Frostraunen", objective = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduke zurück." },
        [5462] = { name = "Der Sterbende Ras Frostraunen", objective = "Reist zur Hoffnung des Lichts in den Östlichen Pestländern und sucht Leonid Barthalomew den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt." },
        [5463] = { name = "Menethils Geschenk", objective = "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden." },
        [5464] = { name = "Menethils Geschenk", objective = "Bringt das seelengebundene Andenken zu Leonid Barthalomew in den Östlichen Pestländern." },
        [5465] = { name = "Seelengebundenes Andenken", objective = "Kehrt zu Magistrat Marduke in Caer Darrow zurück. Zeigt ihm das seelengebundene Andenken." },
        [5466] = { name = "Der Lich Ras Frostraunen", objective = "Sucht Ras Frostraunen in der Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke." },
        [5515] = { name = "Krastinovs Tasche der Schrecken", objective = "Sucht nach Jandice Barov in der Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff." },
        [5518] = { name = "Der Ogeranzug der Gordok", objective = "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Thimblejack. Momentan ist er im Gordokflügel von Düsterbruch angekettet." },
        [5522] = { name = "Leonidas Bartholomäus", objective = "Bringt die gefrorenen Eier zu Leonid Barthalomew in den Östlichen Pestländern." },
        [5525] = { name = "Befreit Knot!", objective = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...\n\nWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!" },
        [5526] = { name = "Die Splitter der Teufelsranke", objective = "Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade." },
        [5527] = { name = "Ein Reliquiar der Reinheit", objective = "Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück." },
        [5529] = { name = "Verseuchte Jungtiere", objective = "Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück." },
        [5531] = { name = "Betina Moppelzink", objective = "Bringt die gefrorenen Eier zu Betina Bigglezink." },
        [5542] = { name = "Dämonenhunde", objective = "Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt." },
        [5543] = { name = "Blutgefärbter Himmel", objective = "Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück." },
        [5544] = { name = "Aassammlung", objective = "Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt." },
        [5722] = { name = "Die Suche nach dem verloren gegangenen Ranzen", objective = "Sucht im Ragefireabgrund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen." },
        [5723] = { name = "Die Kraft des Feindes wird auf die Probe gestellt", objective = "Sucht in Orgrimmar nach dem Ragefireabgrund, tötet dann 8 Ragefire-Troggs und 8 Ragefire-Schamanen und kehrt anschließend zu Rahauro in Thunder Bluff zurück." },
        [5724] = { name = "Wiederbeschaffung des verloren gegangenen Ranzens", objective = "Bringt den Grimmtotemranzen zu Rahauro nach Thunder Bluff." },
        [5725] = { name = "Die Macht der Zerstörung...", objective = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Undercity." },
        [5726] = { name = "Verborgene Feinde", objective = "Bringt die Insignie eines Offiziers zu Thrall nach Orgrimmar." },
        [5727] = { name = "Verborgene Feinde", objective = "Bringt Neeru Fireblade die Insignie des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Burning Blade seid, und kehrt dann zu Thrall nach Orgrimmar zurück." },
        [5728] = { name = "Verborgene Feinde", objective = "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt." },
        [5742] = { name = "Erlösung", objective = "Hört Euch an, was Tirion Fordring zu sagen hat." },
        [5761] = { name = "Vernichtung der Bestie", objective = "Begebt Euch in den Ragefireabgrund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Fireblade nach Orgrimmar." },
        [5781] = { name = "Von vergessenen Erinnerungen", objective = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt." },
        [5845] = { name = "Von verlorener Ehre", objective = "Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt." },
        [5846] = { name = "Von Liebe und Familie", objective = "Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte." },
        [5848] = { name = "Von Liebe und Familie", objective = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.\n\nBringt das Gemälde zu Tirion Fordring." },
        [5961] = { name = "Der Champion der Bansheekönigin", objective = "Sprecht mit Nathanos Blightcaller in den Östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte." },
        [6022] = { name = "Töten zu einem bestimmten Zweck", objective = "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis." },
        [6042] = { name = "Die kleinen Ärgernisse des Un-Lebens", objective = "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr fertig seid." },
        [6133] = { name = "Das Ersuchen des Waldläuferlords", objective = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge.\n\nAußerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten." },
        [6135] = { name = "Dämmerschwinge, oh, wie ich Euch hasse...", objective = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Blightcaller.\n\nMan sagt, dass Dämmerschwinge nördlich von hier durch das Land streift." },
        [6136] = { name = "Der Korpulente", objective = "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Blightcaller zurück, sobald Ihr diese Mission erledigt habt." },
        [6141] = { name = "Bruder Anton", objective = "Sprecht mit Bruder Anton in Desolace." },
        [6163] = { objective = "Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos." },
        [6402] = { name = "Treffen in Stormwind", objective = "Reist nach Stormwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marshal Windsor über Eure Ankunft informiert." },
        [6403] = { name = "Die große Maskerade", objective = "Folgt Reginald Windsor durch Stormwind. Schützt ihn vor Gefahren!" },
        [6501] = { name = "Das Großdrachenauge", objective = "Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert." },
        [6502] = { name = "Drachenfeueramulett", objective = "Ihr müsst das Blut des schwarzen Großdrachen-Helden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Blackrockspitze." },
        [6521] = { name = "Eine unheilige Allianz", objective = "Bringt den Kopf von Botschafter Malcin zu Varimathras nach Undercity." },
        [6522] = { name = "Eine unheilige Allianz", objective = "Bringt die kleine Rolle zu Varimathras nach Undercity." },
        [6561] = { name = "Blackfathom-Schurkerei", objective = "Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff." },
        [6562] = { name = "Ärger in der Tiefe", objective = "Sprecht in Ashenvale mit Je'neu Sancrea." },
        [6563] = { name = "Die Essenz von Aku'mai", objective = "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale." },
        [6564] = { name = "Treue zu den Alten Göttern", objective = "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale." },
        [6565] = { name = "Treue zu den Alten Göttern", objective = "Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück." },
        [6566] = { name = "Was der Wind erzählt", objective = "Hört Thrall zu." },
        [6567] = { name = "Der Champion der Horde", objective = "Sucht Rexxar auf. Der Kriegshäuptling hat Euch erklärt, wo Ihr ihn finden könnt. Sucht die Wege von Desolace zwischen dem Steinkrallengebirge und Feralas ab." },
        [6568] = { name = "Nachricht von Rexxar", objective = "Überbringt Myranda der Vettel in den westlichen Pestländern Rexxars Nachricht." },
        [6569] = { name = "Oculus-Illusionen", objective = "Reist zur Blackrockspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt." },
        [6570] = { name = "Aschenschwinge", objective = "Reist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge." },
        [6582] = { name = "Die Prüfung der Schädel, Scryer", objective = "Ihr müsst Scryer, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge.\n\nIhr wisst, dass Scryer in Winterspring zu finden ist." },
        [6583] = { name = "Die Prüfung der Schädel, Somnus", objective = "Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück." },
        [6584] = { name = "Die Prüfung der Schädel, Chronalis", objective = "Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge." },
        [6585] = { name = "Die Prüfung der Schädel, Axtroz", objective = "Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des Roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück." },
        [6601] = { name = "Aufstieg...", objective = "Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Blackrockspitze nicht funktioniert. Vielleicht solltet Ihr Rexxar aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist." },
        [6602] = { name = "Blut des schwarzen Großdrachen-Helden", objective = "Begebt Euch zur Blackrockspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rexxar." },
        [6626] = { name = "Ein Hort des Bösen", objective = "Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück." },
        [6627] = { name = "Test der Lehre", objective = "Beantwortet Braug Dimspirits Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid." },
        [6628] = { name = "Test der Lehre", objective = "Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Undercity sein, wenn Ihr bereit seid." },
        [6921] = { name = "Inmitten der Ruinen", objective = "Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale." },
        [6922] = { objective = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale." },
        [6981] = { name = "Der leuchtende Splitter", objective = "Begebt Euch nach Ratchet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.\n\nLiefert dann den Splitter ab, wie Ihr angewiesen wurdet." },
        [7028] = { name = "Dunkles Böses", objective = "Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace." },
        [7029] = { name = "Schlangenzunges Verderbnis", objective = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Vark Battlescar in Shadowprey zurück." },
        [7041] = { name = "Schlangenzunges Verderbnis", objective = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Talendria an der Nijelspitze zurück." },
        [7044] = { name = "Legenden von Maraudon", objective = "Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.\n\nFindet einen Weg, um mit Celebras zu sprechen." },
        [7046] = { name = "Das Szepter von Celebras", objective = "Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.\n\nSprecht mit ihm, nachdem das Ritual vollendet ist." },
        [7064] = { name = "Verderbnis von Erde und Samenkorn", objective = "Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Shadowprey in Desolace zurück." },
        [7065] = { name = "Verderbnis von Erde und Samenkorn", objective = "Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück." },
        [7066] = { name = "Samenkorn des Lebens", objective = "Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens." },
        [7067] = { name = "Die Anweisungen des Pariahs", objective = "Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace." },
        [7068] = { name = "Schattensplitter", objective = "Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar." },
        [7070] = { name = "Schattensplitter", objective = "Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Marschen von Dustwallow." },
        [7201] = { name = "Das letzte Element", objective = "Begebt Euch in die Blackrocktiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat." },
        [7441] = { name = "Pusillin und der Älteste Azj'Tordin", objective = "Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.\n\nKehrt mit dem Buch zu Az'Tordin, an Lariss' Pavillon in Feralas, zurück." },
        [7461] = { name = "Der innere Wahnsinn", objective = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\n\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\n\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück." },
        [7462] = { name = "Der Schatz der Shen'dralar", objective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!" },
        [7463] = { name = "Arcane Erfrischung", objective = "Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück." },
        [7481] = { name = "Elfische Legenden", objective = "Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei Sage Korolusk in Camp Mojache." },
        [7482] = { name = "Elfische Legenden", objective = "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei der Gelehrten Runethorn in Feathermoon." },
        [7483] = { name = "Buchband der Schnelligkeit", objective = "Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2 mal das Blut von Helden, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten." },
        [7484] = { name = "Buchband des Fokus", objective = "Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2 mal Schattenhaut, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten." },
        [7485] = { name = "Buchband des Schutzes", objective = "Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten." },
        [7488] = { name = "Lethtendris' Netz", objective = "Bringt Lethtendris' Netz zu Latronicus Moonspear in der Festung Feathermoon, in Feralas." },
        [7489] = { name = "Lethtendris' Netz", objective = "Bringt Lethtendris' Netz zu Talo Thornhoof im Camp Mojache in Feralas." },
        [7492] = { objective = "Sprecht mit Talo Thornhoof in Camp Mojache, in Feralas." },
        [7494] = { name = "Die Festung Feathermoon", objective = "Sprecht mit Latronicus Moonspear in der Festung Feathermoon, in Feralas." },
        [7498] = { name = "Garona: Eine Studie über Heimlichkeit und Verrat", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
        [7499] = { name = "Kodex der Verteidigung", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
        [7500] = { name = "Das Arkanistenkochbuch", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
        [7501] = { name = "Vom Licht und wie man es schwingt", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
        [7502] = { name = "Schatten einspannen", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
        [7503] = { name = "Das größte Volk von Jägern", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
        [7504] = { name = "Heiliger Fleischklops: Was das Licht Dir nicht erzählt", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
        [7505] = { name = "Frostschock und Du", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
        [7506] = { name = "Der Smaragdgrüne Traum", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
        [7507] = { name = "Forors Kompendium", objective = "Bringt Forors Kompendium des Drachentötens zurück in das Athenaeum." },
        [7563] = { name = "Kochendes Blut", objective = "Mor'zul Bloodbringer in der brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt." },
        [7564] = { name = "Garzeeki Wildeyes", objective = "Bringt den Behälter mit Blut zu Gorzeeki Wildeyes in der brennenden Steppe." },
        [7604] = { name = "Ein verbindlicher Vertrag", objective = "Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Darkbargainer, wenn Ihr die Pläne für das Sulfuron erhalten möchtet." },
        [7623] = { name = "Lord Schattenfluch", objective = "Erwerbt schattenhaftige Tränke von Gorzeeki in der brennenden Steppe.\n\nBenutzt die Tränke um durch Jaedenar zu reisen und sprecht mit Lord Banehollow." },
        [7624] = { name = "Ulathek der Verräter", objective = "Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Banehollow in Jaedenar." },
        [7625] = { name = "Xorothianischer Sternenstaub", objective = "Erwerbt xorothianischen Sternenstaub von Ur'dan. Bringt es anschließend Gorzeeki in der brennenden Steppe." },
        [7626] = { name = "Die Glocke von Dethmoora", objective = "Bringt 10 Elixiere der Schattenmacht zu Gorzeeki Wildeyes in die brennende Steppe." },
        [7627] = { name = "Das Rad des Schwarzen Marsches", objective = "Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildeyes in die brennende Steppe." },
        [7628] = { name = "Die Altarkerze des Jüngsten Gerichts", objective = "Bringt 35 Schuppen eines schwarzen Drachen zu Gorzeeki Wildeyes in der brennenden Steppe." },
        [7629] = { name = "Wichtellieferung", objective = "Bringt den Wichtel im Gefäß in das Alchimielabor in der Scholomance. Bringt nach der Herstellung des Pergaments, dass Gefäß zurück zu Gorzeeki Wildeyes." },
        [7630] = { name = "Arkanit", objective = "Bringt 3 Arkanitbarren zu Gorzeeki in der brennenden Steppe." },
        [7631] = { name = "Schreckensross von Xoroth", objective = "Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch." },
        [7637] = { name = "Ein Opfer darbieten", objective = "Reist nach Ironforge und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen." },
        [7639] = { name = "Lass Gerechtigkeit walten", objective = "Bringt den Weihrauchschwenker zu Lord Grayson Shadowbreaker in Stormwind zurück." },
        [7640] = { name = "Der Exorzismus des Schreckenstals", objective = "Vertreibt mit Hilfe des Weihrauchschwenkers die Geister im Schreckenstal. Vernichtet 25 Schreckenstalgeister und kehrt anschließend zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind zurück." },
        [7641] = { name = "Grimand Elmores Werk", objective = "Sprecht mit Grimand Elmore im Zwergendistrikt von Stormwind." },
        [7642] = { name = "Fünf Dinge", objective = "Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Artha's Tränen, 5 Phiolen heiliges Wasser aus Stratholme und 150 Gold zu Grimand Elmore im Zwergendistrikt von Stormwind." },
        [7643] = { name = "Der uralte Pferdegeist", objective = "Beschafft spezielles Pferdefutter mit dem man ein Geisterpferd füttern kann. Meredith Carlson in Southshore scheint dafür eine recht gute Quelle zu sein.\n\nReist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist das Arkanitpferdegeschirr, um es segnen zu lassen." },
        [7644] = { name = "Gesegnetes Arkanitpferdegeschirr", objective = "Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Lord Grayson Shadowbreaker in das Kathedralenviertel von Stormwind zurück." },
        [7645] = { name = "Mit Mana angereichertes Pferdefutter", objective = "Treibt 20 angereicherte Manakekse - die ausschlaggebende Zutat für die Herstellung von mit Mana angereichertem Pferdefutter - für Merideth Carlson aus Southshore in dem Vorgebirge von Hillsbrad auf. Die Argentumdämmerung ist als alleiniger Händler dieser Kekse bekannt.\n\nZusätzlich müsst Ihr ihre Gefühle noch mit 50 Goldstücken besänftigen." },
        [7646] = { name = "Das Orakel der Anrufung", objective = "Bringt Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind einen Azerothianischen Diamanten und einen makellosen schwarzen Diamanten." },
        [7647] = { name = "Gerechtigkeit und Erlösung", objective = "Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums, in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses.\n\nGebt die Seele des gefallenen Streitrosses und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross zurück." },
        [7648] = { name = "Grimands feinste Arbeit", objective = "Bringt das Arkanitpferdegeschirr zur Begutachtung zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind." },
        [7667] = { name = "Materielle Unterstützung", objective = "Wenn Ihr Sagorne Crestrider im Tal der Weisheit von Orgrimmar helfen wollt, so bringt ihm einen azerothianischen und einen makellosen schwarzen Diamanten." },
        [7668] = { name = "Die Bedrohung durch Schattensichel", objective = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn.\n\nBringt Schattensichels Kopf zu Sagorne Creststrider im Tal der Weisheit in Orgrimmar." },
        [7703] = { name = "Die offene Rechnung der Gordok", objective = "Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch.\n\nKromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat." },
        [7761] = { name = "Blackhands Befehl", objective = "Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen.\n\nDem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen." },
        [7848] = { name = "Abstimmung mit dem Kern", objective = "Begebt Euch zum Portal in den Blackrocktiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Riftwaker am Blackrock zurück." },
        [8151] = { name = "Der Talisman des Jägers", objective = "Sprecht mit Ogtinc in Azshara." },
        [8153] = { name = "Gehörnte Renner", objective = "Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath." },
        [8231] = { name = "Wellenjagd", objective = "Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath." },
        [8232] = { name = "Der grüne Drache", objective = "Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath." },
        [8233] = { name = "Ein simples Anliegen", objective = "Sprecht mit Lord Jorach Ravenholdt im Ravenholdt-Anwesen." },
        [8234] = { name = "Die versiegelte azurblaue Tasche", objective = "Erlangt die versiegelte azurblaue Tasche von dem Schamanen der Holzschlundfeste in Azshara zurück. Bringt sie anschließend zum Erzmagier Xylem, der ebenfalls in Azshara zu finden ist." },
        [8235] = { name = "Verschlüsselte Fragmente", objective = "Bringt Erzmagier Xylem in Azshara 10 verschlüsselte Fragmente." },
        [8236] = { name = "Der azurblaue Schlüssel", objective = "Bringt den azurblauen Schlüssel zu Lord Jorach Ravenholdt." },
        [8250] = { name = "Geschick der Magier", objective = "Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem." },
        [8251] = { name = "Magischer Staub", objective = "Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben." },
        [8252] = { name = "Die Koralle der Sirenen", objective = "Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem." },
        [8253] = { name = "Vernichtet Morphaz", objective = "Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück." },
        [8254] = { name = "Cenarische Hilfe", objective = "Sucht Ogtinc in Azshara auf." },
        [8255] = { name = "Renner für einen höheren Zweck", objective = "Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath." },
        [8256] = { name = "Sekret des Untodes", objective = "Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath." },
        [8257] = { name = "Morphaz' Blut", objective = "Tötet Morphaz im versunkenen Tempel von Atal'Hakkar und bringt Greta Mosshoof im Teufelswald sein Blut. Der Eingang zum versunkenen Tempel liegt in den Sümpfen des Elends." },
        [8410] = { name = "Elementarbeherrschung", objective = "Bath'rah der Windbehüter möchte, dass Ihr jeweils eine Probe Luft, Feuer, Erde und Wasser für ihn sammelt." },
        [8412] = { name = "Geistertotem", objective = "Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem." },
        [8413] = { name = "Die Macht des Voodoos", objective = "Bringt Bath'rah dem Windbehüter die Voodoofedern." },
        [8414] = { name = "Austreibung des Bösen", objective = "Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern." },
        [8415] = { name = "Chillwindspitze", objective = "Sprecht mit Kommandanten Ashlam Valorfist an der Chillwindspitze." },
        [8416] = { name = "Gereinigte Geißelsteine", objective = "Bringt den gereinigten Geißelstein zu Kommandant Ashlan Valorfist an der Chillwindspitze." },
        [8417] = { name = "Ein geplagter Geist", objective = "Sprecht mit dem gefallenen Helden der Horde am Eingang zu den verwüsteten Landen." },
        [8418] = { name = "Erschaffung des Steins der Macht", objective = "Bringt die Voodoofedern zu Ashlam Valorfist." },
        [8419] = { name = "Die Bitte eines Wichtels", objective = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald." },
        [8420] = { name = "Heiß und brennend", objective = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald." },
        [8421] = { name = "Das richtige Zeug", objective = "Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald." },
        [8422] = { name = "Federn von Trollen", objective = "Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel." },
        [8423] = { name = "Kriegerverwandtschaft", objective = "Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück." },
        [8424] = { name = "Krieg den Schattenanbetern", objective = "Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück." },
        [8425] = { name = "Voodoofedern", objective = "Bringt die Voodoofedern der Trolle im versunkenen Tempel zu dem gefallenen Helden der Horde." },
        [8945] = { name = "Die letzte Bitte eines toten Mannes", objective = "Geht nach Stratholme und befreit Ysida Harmon aus den Fängen von Baron Rivendare." },
        [8948] = { name = "Anthions alter Freund", objective = "Bringt Falrin Treeshaper in der Bibliothek von Düsterbruch das unvervollständigte Banner der Provokation." },
        [8949] = { name = "Falrins Rachefeldzug", objective = "Nehmt den Ogern in der Blackrockspitze oder in Düsterbruch 25 Ogerkriegsperlen ab und bringt sie zu Falrin Treeshaper im Athenaeum, der Bibliothek von Düsterbruch." },
        [8950] = { name = "Die Verzauberung des Aufhetzers", objective = "Bringt Falrin Treeshaper in Düsterbruch 1 Essenz eines spöttischen Geisterwesens, 4 Dunkelrunen und 8 große glänzende Splitter." },
        [9015] = { name = "Die Herausforderung", objective = "Reist zum Ring des Gesetzes der Blackrocktiefen und errichtet das Banner der Provokation in dessen Mitte, während Ihr von Oberrichter Grimmstein verurteilt werdet. Tötet Theldren und seine Gladiatoren und kehrt dann mit dem ersten Stück von Lord Valthalaks Amulett zu Anthion Harmon in den östlichen Pestländern zurück." },
        [9051] = { name = "Giftexperiment", objective = "Stecht einen Teufelssaurier mit dem Teufelssaurierhaken." },
        [9052] = { name = "Blutblütengift", objective = "Sammelt Blutkappenpilze und Gorishistachel und kehrt zu Torwa Pathfinder im Un'Goro Krater zurück." },
        [9053] = { name = "Eine bessere Zutat", objective = "Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des versunkenen Tempels und kehrt zu Torwa Pathfinder zurück." },
        [9063] = { name = "Torwa Pfadfinder", objective = "Sprecht im Un'Goro Krater mit Torwa Pathfinder." },
        [78261] = { name = "Das Horn von Xelthos", objective = "Findet das Horn von Xelthos in der Burg Schattenfang. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück. Diesen Auftrag müsst Ihr alleine erledigen." },
        [78307] = { name = "Das Horn von Xelthos" },
        [78676] = { name = "Das Auge von Bhossca", objective = "Findet das Auge von Bhossca im Scharlachroten Kloster. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück. Diesen Auftrag müsst Ihr alleine erledigen." },
        [78699] = { name = "Das Auge von Bhossca" },
        [79007] = { name = "... und diese Notiz, die Ihr gefunden habt.", objective = "Die verkohlten Überreste der Notiz dienen Euch als einziger Wegweiser." },
        [79008] = { name = "... und diese Notiz, die Ihr gefunden habt.", objective = "Die verkohlten Überreste der Notiz dienen Euch als einziger Wegweiser." },
        [79192] = { name = "Trittsteine", objective = "Ihr reißt die Notiz von der Planke und lest die verschmierte Schrift." },
        [79358] = { name = "Sturm, Erde und Feuer", objective = "Sammelt 5 verdrehte Feuertotems, 5 verdrehte Erdtotems, 5 verdrehte Lufttotems und 5 verdrehte Wassertotems für Veyric Thunderhame im Arathihochland." },
        [79360] = { name = "Elementare Hilfe", objective = "Besiegt Charlga Razorflank im Kral von Razorfen und sammelt Informationen über die Pläne der Stacheleber." },
        [79361] = { name = "Sturm, Erde und Feuer", objective = "Sammelt 5 verdrehte Feuertotems, 5 verdrehte Erdtotems, 5 verdrehte Lufttotems und 5 verdrehte Wassertotems für Prate Cloudseer in Tausend Nadeln." },
        [79364] = { name = "Blick zum Himmel", objective = "Sprecht mit Prate Cloudseer in Tausend Nadeln." },
        [79366] = { name = "Hört meinen Ruf", objective = "Verwendet die verdrehten Totems, um das Stacheleberritual ein für alle mal zu beenden." },
        [79442] = { name = "Die Waffen des Sturmgewitters", objective = "Bringt das Auge des Gewittersturms zu Bath'rah dem Windbehüter im Alteracgebirge." },
        [79974] = { name = "Feuchte Angelegenheit", objective = "Beim Abstauben einer vom Boden aufgelesenen Kuriertasche findet Ihr zwischen den Vorräten ein Pergament." },
        [79975] = { name = "Adlerfaust", objective = "Spritzendes Wasser befeuchtet die Luft, der Ausblick ist unglaublich." },
        [79976] = { name = "Das muss der Ort sein", objective = "Wer auch immer hier war, Ihr habt die Person nur knapp verpasst." },
        [79980] = { name = "Weg hier", objective = "Findet, was Euch erwartet." },
        [92401] = { name = "Eine verängstigte Bitte", objective = "Untersucht das Verschwinden von Edward Heartweaver in den Ruinen von Lordaeron." },
        [92415] = { name = "Denk daran, ich liebe dich", objective = "Bringt den blutbefleckten Brief zu Waisenmatrone Nightingale in Stormwind." },
        [92421] = { name = "Die Gerechtigkeit des Lichts", objective = "Sammelt 25 intakte Gliedmaßen in den Ruinen von Lordaeron für Morbin Lightbane in Undercity." },
        [92422] = { name = "Der Zorn von Rath'mael", objective = "Tötet Rath'mael in den Ruinen von Lordaeron für Todeswache Kristof in Brill." },
        [92432] = { name = "Eine alarmierende Bitte", objective = "Meldet Euch beim Abbild der Erzmagierin Modera in der Nähe von Dalaran." },
        [92434] = { name = "Blut in den Straßen", objective = "Findet entlang des Lordameresees einen Weg nach Dalaran." },
        [92456] = { name = "Eine grüne Probe", objective = "Pflückt eine teufelserfüllte Blüte in Dalaran für Shylamiir in Stormwind." },
        [92457] = { name = "Verhungernder Arkaner", objective = "Besiegt 8 suchende Fragmente, 8 gesättigte Fragmente und 8 Manaechos in Dalaran für Erzmagierin Modera vor Dalaran." },
        [92458] = { name = "Das Herz der Störung", objective = "Holt den Arkanpartikel für das Abbild von Erzmagierin Modera in der Nähe von Dalaran." },
        [92489] = { name = "Überwältigende Macht", objective = "Tötet den Manaelementar in Dalaran für Zaubermeister Andromath in Stormwind." },
        [92742] = { name = "Test der Brunnen", objective = "Nutzt das Set für Brunnenwasserproben, um Proben aus den Brunnen auf Jansens Hof und Molsens Hof zu sammeln." },
        [92744] = { name = "Murlochkiemen", objective = "Alba Fairmoon möchtet, dass Ihr 7 Murlockiemen von Longshore an der Küste von Westfall sammelt." },
        [92745] = { name = "Der Status der Minen", objective = "Tötet 4 Koboldbuddler im Jangoschacht und 6 Minenarbeiter der Flusspfoten im Goldküstensteinbruch." },
        [92747] = { name = "Moonbrookspionage", objective = "Sammelt 8 verdächtige Industriebedarfsvorräte von Moonbrook." },
        [92748] = { name = "Explosive Beratung", objective = "Reist zum Zwergendistrikt in Stormwind und findet einen Ingenieur, der Euch helfen kann." },
        [92749] = { name = "Ein explosiver Plan", objective = "Erhaltet 10 Stangen raues Dynamit durch Herstellung, Handel oder im Auktionshaus, und kehrt anschließend zu Sprite Jumpsprocket im Zwergendistrikt von Stormwind zurück." },
        [92750] = { name = "Detonation aus der Ferne", objective = "Sprecht mit jemanden beim Geheimdienst von Stormwind über die Beschaffung eines Fernzünders." },
        [92751] = { name = "Detonation aus der Ferne", objective = "Bringt das Fernzünderset zu Sprite Jumpsprocket im Zwergendistrikt von Stormwind." },
        [92752] = { name = "Explosive Beratung", objective = "Kehrt zu Alba Fairmoon in Westfall zurück." },
        [92753] = { name = "Zerstörung in den Todesminen", objective = "Findet die versteckte Schmiede in den Todesminen und platziert die besonders zerstörerischen Sprengladungen in der Nähe. Trefft dann Alba Fairmoon am Ausgang der Todesminen." },
        [92819] = { name = "Zerstörung in den Todesminen", objective = "Verwendet den Zünder." },
        [92914] = { name = "Seltsame Pylonen", objective = "Erkundet Shen'dralas, um andere Pylonen wie den zu finden, den ihr bereits gefunden habt." },
        [93680] = { name = "Schlüssel zur Stadt", objective = "Holt den Kanalisationsschlüssel von Dalaran für Magus Wordeen Voidglare in Tarrens Mühle." },
        [94877] = { name = "Die Rettung von Sonnengrund", objective = "Besiegt für Demar Brant 8 Twilight-Räuber, 8 Twilight-Schattenbeschwörer und 8 Twilight-Neophyten in Sonnengrund." },
        [94886] = { name = "Die westliche Front", objective = "Findet Sergeant Riftan in der Nähe des Twilight-Schleiers im Westen." },
        [94907] = { name = "Ein kleiner Gefallen", objective = "Beschwört einen Twilight-Knecht aus einer Leitung im Twilight-Schleier und fangt ihn in Amberhalls Seelenstein ein." },
        [94968] = { name = "Auge von Mugg", objective = "Dringt in die Feste Krol'dok ein und bringt Krom'rosh einen Beweis vom Ableben ihres Anführers." },
        [94972] = { name = "Twilightfoliant", objective = "Bergt den Twilightfolianten in der Feste Krol'dok." },
        [94973] = { name = "Abguss von Krol'Dok", objective = "Findet in Rog'mar jemanden, der etwas über die Form wissen könnte." },
        [94975] = { name = "Ein Symbol der Rache", objective = "Sammelt 15 Kultistenohren der Twilight-Hammer in der Feste Krol'dok." },
        [94982] = { name = "Auge von Mugg", objective = "Dringt in die Feste Krol'dok ein und bringt Hauptmann Brant einen Beweis vom Ableben ihres Anführers." },
        [94983] = { name = "Twilight-Andenken", objective = "Sammelt 8 Kultistenarmreife der Twilight-Hammer in der Feste Krol'dok." },
        [94984] = { name = "Twilightfoliant", objective = "Tötet Nar'gurk in der Feste Krol'dok und erbeutet jegliche nützlichen Informationen." },
        [95034] = { name = "Die Schuld", objective = "Sprecht mit Lumina Windsinger im Grabmal." },
        [95036] = { name = "Eine mondgeküsste Klinge", objective = "Sprecht mit Trevan Rol im Grabmal und bringt ihm die Materialien, die er benötigt." },
        [95111] = { name = "Ein unterschätztes Talent", objective = "Sprecht mit Ott und bittet ihn, Eure Klinge zu schmieden." },
        [95125] = { name = "Otts Meisterwerk", objective = "Seht zu, während Ott Eure Klinge schmiedet." },
        [95126] = { name = "Die Mondsilberklinge", objective = "Bringt Otts Meisterwerk zu Trevan Rol im Silberwald." },
        [95140] = { name = "Feuerauge der Alte", objective = "Verwendet die Mondsilberklinge, um Feuerauge den Alten im Silberwald zu vernichten." },
        [95189] = { name = "Wappen von Lordaeron", objective = "Bringt das Wappen von Lordaeron zu Lady Dena Kennedy in Stormwind." },
        [95195] = { name = "Blutverschmiertes Insigne", objective = "Sammelt 10 blutverschmierte Insignien und bringt sie zu General Marcus Jonathan in Stormwind." },
        [95204] = { name = "Wappen von Lordaeron", objective = "Bringt das Wappen von Lordaeron zu Oran Snakewrithe in Undercity." },
        [95216] = { name = "Die neue Seuche", objective = "Bergt den hochgiftigen Erreger von Welkzahn in den Ruinen von Lordaeron für Theodore Griffs in Undercity." },
        [95250] = { name = "Scheußliche Kreaturen", objective = "Holt den Kopf des Barons in den Ruinen von Lordaeron und bringt ihn zu Hauptmann Truman." },
        [95646] = { name = "Schrecken im Hochland", objective = "Tötet einen Hochlandschrecken in den Ausgrabungsstätten und bringt seinen Wurzelkern zu Rethiel dem Sumpfhüter im Sumpfland." },
        [95647] = { name = "Im Dickicht verloren", objective = "Findet Ardin Grassman bei den Ausgrabungsstätten" },
        [95663] = { name = "Gerüchte von den Dragonmaw", objective = "Reist ins Sumpfland und trefft die Todespirscheragentin in den Hügeln über dem Lager der Dragonmaw." },
        [95664] = { name = "Wissen der Ältesten", objective = "Bringt das Relikt der Titanen zur Anhöhe der Ältesten in Thunder Bluff und haltet Ausschau nach jemandem, der Euch mehr darüber erzählen kann." },
        [95682] = { name = "Her damit", objective = "Erledigt die Dragonmawtruppen in der Ausgrabungsstätte und kehrt mit allem, was Ihr dort findet, zur Todespirscheragentin draußen zurück." },
        [95697] = { name = "Geschmackswandel", objective = "Geht zu den Ausgrabungsstätten im Sumpfland und besorgt Dickichtraptorfleisch" },
        [95748] = { name = "Die alten Legenden der Gurubashi", objective = "Verwendet die Haut und die Holzkohle, um ein Abpausbild der dritten Trolllegende anzufertigen." },
        [95770] = { name = "Die Suche nach der verlorenen Stadt", objective = "Erkundet das finstere Riff und findet den Höhleneingang." },
        [95772] = { name = "Suche nach Songblade", objective = "Sucht in Whelgars Ausgrabungsstätte nach dem Bruder von Dorin Songblade, Daewyn." },
        [95773] = { name = "Feinde im Wasser", objective = "Sammelt 10 Laugenschuppendreizacke von Scharmützlern der Laugenschuppen." },
        [95775] = { name = "Die Versunkene Stadt", objective = "Verwendet die Haut und die Holzkohle, um Abpausbilder der Schrifttafeln in der Versunkenen Stadt anzufertigen." },
        [95776] = { name = "...ist eine gute Laugenschuppe", objective = "Tötet Var'Taka in der Versunkenen Stadt." },
        [95786] = { name = "Eine Bekanntschaft in Southshore", objective = "Findet den Meister der Lehren Dibbs in Southshore und bringt ihm das Berichtsbündel der Ungezähmten Küste." },
        [95787] = { name = "Zwei mit Wasser einnehmen", objective = "Verwendet die Haut und die Holzkohle, um Abpausbilder der Schrifttafeln in der Versunkenen Stadt anzufertigen." },
        [95788] = { name = "Die Magie der Versunkenen Stadt", objective = "Sammelt 5 Fetische von I'lalai von Trollen in der Versunkenen Stadt." },
        [95789] = { name = "Zwielichtige Salzseher", objective = "Sammelt 10 voodooerfüllte Artefakte von den Salzseherpiraten in der Versunkenen Stadt." },
        [95791] = { name = "Der Kapitän der Salzseher", objective = "Tötet 3 Leichensammler der Salzseher und Captain Dreadrise in der Versunkenen Stadt." },
        [95795] = { name = "Gefallen im Moor", objective = "Kehrt zu Dorin Songblade zurück" },
        [95799] = { name = "Bericht für die Forscherliga", objective = "Bringt die Übersetzungen aus I'lalai vom Meister der Lehren Dibbs zu Historiker Karnik in Ironforge." },
        [95809] = { name = "Herzverwoben", objective = "Kehr zu Caitlin Grassman im Hafen von Menethil zurück." },
        [95810] = { name = "Reliktbeförderung", objective = "Bringt das Relikt der Titanen zu Ausgrabungsleiter Whelgar an der Ausgrabungsstätte des Sumpflands." },
        [96010] = { name = "Die Fragmente der Pylonen", objective = "Bergt Scherben und Fragmente der Pylonen, die in den Dörfern der Magram und der Gelkis bewacht werden, und bringt sie zurück zu Mordent Evenshade." },
