        [870] = { name = "Las Charcas del Olvido", objective = "Informa a Tonga Runatótem con tus hallazgos." },
        [877] = { name = "El Oasis Estancado", objective = "Vuelve junto a Tonga en El Cruce después de investigar El Oasis Estancado." },
        [880] = { name = "Fuentes de vida", objective = "Llévale 8 caparazones de quijafortes alterados a Tonga Runatótem en El Cruce." },
        [914] = { name = "Líderes del Colmillo", objective = "Lleva las gemas de Cobrahn, Anacondra, Pythas y Serpentis a Nara Bravacrín en Cima del Trueno." },
        [959] = { name = "¡A por la botella!", objective = "El operador de grúa Pelardo de Trinquete quiere que le consigas una botella de porto de 99 años de Magglish el Loco que se esconde en las Cuevas de los Lamentos." },
        [962] = { name = "Repitilia", objective = "La boticaria Zamah de Cima del Trueno quiere que recojas 10 reptilias." },
        [971] = { name = "El conocimiento de las profundidades", objective = "Lleva el manuscrito de Lorgalis a Gerrig Agarrahueso, que está en la Caverna Abandonada en Forjaz." },
        [1013] = { name = "El Libro de Ur", objective = "Lleva el Libro de Ur al guardián Bel'dugur al Apothecarium de Entrañas." },
        [1014] = { name = "Arugal debe morir", objective = "Mata a Arugal y lleva su cabeza a Dalar Tejalba en El Sepulcro." },
        [1048] = { name = "En el Monasterio Escarlata", objective = "Mata a la alta inquisidora Melenablanca, al comandante Escarlata Mograine, a Herod el campeón Escarlata y al domador de jaurías Loksey, y después ve a ver de nuevo a Varimathras a Entrañas." },
        [1049] = { name = "El Compendio de los Caídos", objective = "Recupera el Compendio de los Caídos del Monasterio que se encuentra en los Claros de Tirisfal y regresa ante Sabio Buscaverdad, que está en Cima del Trueno." },
        [1050] = { name = "Mitología de los Titanes", objective = "Coge Mitología de los Titanes en el monasterio y llévaselo a la bibliotecaria Mae Palipolvo a Forjaz." },
        [1051] = { name = "La venganza de Vorrel", objective = "Lleva la alianza de Vorrel Sengutz a Monika Sengutz de Molino Tarren." },
        [1052] = { name = "El sendero Escarlata", objective = "Lleva la carta de mención honorífica del hermano Antón a Raleigh el Devoto, en Costasur." },
        [1053] = { name = "En el nombre de la Luz", objective = "Mata a la alta inquisidora Melenablanca, al Comandante Escarlata Mograine, a Herod, el Campeón Escarlata y al domador de jaurías Loksey. A continuación, preséntate ante Raleigh el Devoto, en Costasur." },
        [1098] = { name = "Mortacechadores en Colmillo Oscuro", objective = "Encuentra a los mortacechadores Adamant y Vincent." },
        [1100] = { name = "El diario de Henrig Soliceja", objective = "Lee el diario de Henrig Soliceja." },
        [1101] = { name = "La bruja del Horado", objective = "Llévale el medallón de Filonavaja a Díscolo Falfildel de Thalanaar." },
        [1102] = { name = "Un destino vengador", objective = "Llévale el corazón de Filonavaja a Auld Picopiedra, que está en Cima del Trueno." },
        [1109] = { name = "Guano del Horado", objective = "Llévale una pila de guano del Horado al maestro boticario Faranell de Entrañas." },
        [1113] = { name = "Corazones de fervor", objective = "El maestro boticario Faranell de Entrañas quiere 20 corazones de fervor." },
        [1139] = { name = "Las tablillas perdidas de Voluntad", objective = "Encuentra la tablilla de Voluntad y llévasela al consejero Belgrum en Forjaz." },
        [1142] = { name = "Decaída mortal", objective = "Encuentra el colgante de Treshala Arroyobarbecho y llévaselo a Darnassus." },
        [1144] = { name = "Willix el Importador", objective = "Ayuda a Willix el Importador a salir de Horado Rajacieno." },
        [1149] = { name = "Prueba de fe", objective = "Si tienes fe, salta desde las tablas que dominan Las Mil Agujas." },
        [1150] = { name = "Prueba de resistencia", objective = "Llévale la garra de Grenka a Dorn Acechaprados, que está en Las Mil Agujas." },
        [1151] = { name = "Prueba de fuerza", objective = "Llévale fragmentos de Rok'Alim a Dorn Acechaprados, que está en Las Mil Agujas." },
        [1152] = { name = "Prueba de conocimiento", objective = "Encuentra a Braug Espiritoscuro cerca de la entrada de El Paso del Espolón en Sierra Espolón." },
        [1154] = { name = "Prueba de conocimiento", objective = "Encuentra el Legado de los Aspectos y devuélveselo a Braug Espiritoscuro que se encuentra cerca de la entrada de El Paso del Espolón en Sierra Espolón." },
        [1159] = { name = "Prueba de conocimiento", objective = "Encuentra a Parqual Fintallas en Entrañas." },
        [1160] = { name = "Prueba de conocimiento", objective = "Encuentra la Guía básica para no-muertos y devuélvesela a Parqual Fintallas, que está en Entrañas." },
        [1198] = { name = "Buscando a Thaelrid", objective = "Busca al guardia Argenta Thaelrid en las Cavernas de Brazanegra." },
        [1199] = { name = "Cascada del Crepúsculo", objective = "Lleva 10 colgantes del Azote al guardia Argenta Manados a Darnassus." },
        [1200] = { name = "La vileza de Brazanegra", objective = "Llévale la cabeza del Señor Crepuscular Kelris a Selgorm Guardalbas en Darnassus." },
        [1221] = { name = "Los tubérculos hojazul", objective = "Coge un cajón agujereado.\nCoge una vara de mando de Husmeador.\nLee el manual del propietario del Husmeador. \n\nCuando llegues a Horado Rajacieno, usa el cajón agujereado para invocar un husmeador taltuza; usa la vara para que busque tubérculos. \n\nLleva 6 tubérculos hojazul, la vara de mando de Husmeador y el cajón agujereado a Mebok Mizzyrix a Trinquete." },
        [1275] = { name = "Investigaciones acerca de la corrupción", objective = "Gershala Noctusurro de Auberdine quiere 8 bulbos raquídeos corruptos." },
        [1360] = { name = "Los tesoros reclamados", objective = "Recoge la posesión más preciada de Krom Brazorrecio de su cofre, que está en la Sala Comunal Norte de Uldaman, y llévasela a Forjaz." },
        [1394] = { name = "La recta final", objective = "Habla con Dorn Acechaprados en Las Mil Agujas." },
        [1424] = { name = "Charca de Lágrimas", objective = "Fel'zerul, en Rocal, quiere que consigas 10 artefactos Atal'ai." },
        [1429] = { name = "El exiliado Atal'ai", objective = "Lleva los artefactos Atal'ai al exiliado Atal'ai en las Tierras del Interior." },
        [1444] = { name = "Vuelve con Fel'Zerul", objective = "Vuelve a ver a Fel'Zerul en Rocal." },
        [1445] = { name = "El Templo de Atal'Hakkar", objective = "Reúne 20 fetiches de Hakkar y llévaselos a Fel'Zerul en Rocal." },
        [1446] = { name = "El profeta Jammal'an", objective = "El exiliado de Atal'ai, en las Tierras del Interior, quiere la cabeza de Jammal'an." },
        [1448] = { name = "En búsqueda del templo", objective = "Brohann Barriliga, en Ventormenta, quiere que busques el Templo de Atal'Hakkar." },
        [1449] = { name = "A las Tierras del Interior", objective = "Habla con el Gran señor feudal Falstad Martillo Salvaje en el Pico Nidal, en las Tierras del Interior." },
        [1450] = { name = "Maestro de grifos Garracha", objective = "Habla con el maestro de grifos Garracha dentro de la pajarera del Pico Nidal." },
        [1451] = { name = "Rapsodio Machacacanillas", objective = "Busca a Rapsodio Machacacanillas en las Tierras del Interior." },
        [1452] = { name = "El cubata de Kalimdor de Rapsodio", objective = "Rapsodio Machacacanillas, en las Tierras del Interior, quiere que le lleves 3 mollejas de Roc, 3 hígados de Groddoc y 3 hígados de piel pétrea." },
        [1469] = { name = "El relato de Rapsodio", objective = "Lleva el fragmento de la tablilla Atal'ai a Brohann Barriliga, en Ventormenta." },
        [1475] = { name = "En El Templo de Atal'Hakkar", objective = "Consigue 10 tablillas de Atal'ai para Brohann Barriliga, en Ventormenta." },
        [1486] = { name = "Pellejo de los descarriados", objective = "Nalpak de las Cuevas de los Lamentos quiere 20 cueros descarriados." },
        [1487] = { name = "Erradicación de descarriados", objective = "Ebru de las Cuevas de los Lamentos quiere que mates 7 devastadores descarriados, 7 víboras descarriadas, 7 arrastrados descarriados y 7 colminfernos descarriados." },
        [1489] = { name = "Hamuul Runatótem", objective = "Habla con Hamuul Runatótem." },
        [1490] = { name = "Nara Bravacrín", objective = "Habla con Nara Bravacrín." },
        [1491] = { name = "Las bebidas astutas", objective = "Llévale 6 unidades de esencia de lamentos a Mebok Mizzyrix en Trinquete" },
        [1651] = { name = "Libro del valor", objective = "Defiende a Daphne Fontana del ataque de los Defias.\n\nSi quieres tener éxito, vuestros espíritus no pueden salir de sus espirales mortales.\n\nCuando lo hayas conseguido, vuelve a hablar con Daphne Fontana." },
        [1652] = { name = "Libro del valor", objective = "Habla con Duthorian Rall en Ventormenta." },
        [1653] = { name = "La prueba de rectitud", objective = "Habla con Jordan Fontana en Forjaz." },
        [1654] = { name = "La prueba de rectitud", objective = "Consulta la lista y llévale a Jordan Fontana de Forjaz lo siquiente: madera de roble de Piedrablanca, envío de oro refinado de Bailor, el martillo de herrero de Jordan y una gema Kor." },
        [1699] = { name = "El guantelete de Rethban", objective = "Entra en las Cavernas de Rethban, llega hasta la primera bifurcación y regresa junto a Yorus Cebadiz en el tiempo estipulado.\n\nNo debes morir y liberar tu espíritu." },
        [1701] = { name = "Armadura de mallas endurecida con fuego", objective = "Reúne los materiales que necesita Furen Barbalarga y llévaselos a Ventormenta." },
        [1702] = { name = "El forjador de escudos", objective = "Lleva el barril de brebaje a Furen Barbalarga." },
        [1740] = { name = "El orbe de Soran'ruk", objective = "Encuentra 3 fragmentos de Soran'ruk y 1 fragmento grande de Soran'ruk y llévaselos a Doan Karhan en Los Baldíos." },
        [1782] = { name = "La armadura de Furen" },
        [1806] = { name = "La prueba de rectitud", objective = "Espera mientras Jordan Fontana te forja un arma." },
        [1824] = { name = "Prueba en Tierra de Gigantes", objective = "Lleva 5 antenas agitadas a Ruga Furiatótem de Campamento Taurajo." },
        [1825] = { name = "Habla con Thun'grim", objective = "Habla con Thun'grim Vistafuego en Los Baldíos." },
        [1838] = { name = "Armadura brutal", objective = "Lleva 15 lingotes de hierro humeantes, 10 azuritas en polvo, 10 lingotes de hierro y un vial de flogisto a Thun'grim Vistafuego." },
        [1848] = { name = "Camisote brutal", objective = "Habrás tenido que soportar duras privaciones y habrás derramado mucha sangre cumpliendo mi tarea, <nombre>. Este es el producto de todo tu esfuerzo.\n\nUtilízalo bien y quizás un día vuelvas a contarme cuántas veces te ha sido de ayuda." },
        [1954] = { name = "El orbe infernal", objective = "Lleva un orbe infernal a Tabetha en el Marjal Revolcafango." },
        [1955] = { name = "El exorcismo", objective = "Mata al demonio del orbe y habla con Tabetha." },
        [1956] = { name = "Poder en Uldaman", objective = "Hazte con una fuente de poder obsidiano y llévasela a Tabetha en el Marjal Revolcafango." },
        [2040] = { name = "Asalto subterráneo", objective = "Recupera la Trituradora Piñonera de Las Minas de la Muerte y devuélveselo a Shoni el Shilenshioso, en Ventormenta." },
        [2041] = { name = "Habla con Shoni", objective = "Habla con Shoni la Silenciosa en Ventormenta." },
        [2198] = { name = "El collar hecho añicos", objective = "Busca al creador del collar hecho añicos y descubre para qué sirve." },
        [2199] = { name = "Esa información tiene un precio", objective = "Lleva 5 lingotes de plata a Talvash del Kissel a Forjaz." },
        [2200] = { name = "El regreso a Uldaman", objective = "Busca pistas sobre el paradero del collar de Talvash en Uldaman. Dijo que un paladín muerto fue su último dueño." },
        [2201] = { name = "Encuentra las gemas", objective = "Encuentra el rubí, el zafiro y el topacio que están desperdigados por Uldaman. Cuando los tengas, contacta con Talvash del Kissel mediante la ampolla de adivinación que él te dio.\n\nA través del diario, sabes que...\n*El rubí está escondido en una zona de Forjatiniebla con barricadas.\n*El topacio permanece oculto en una urna en una de las zonas de los troggs, cerca de algunos enanos de la Alianza.\n\n*El zafiro obra en poder de Grimlok, el líder de los enanos, según él mismo afirma." },
        [2202] = { name = "Componentes de Uldaman", objective = "Llévale 12 setas moradas a Musgofusión en Kargath." },
        [2204] = { name = "Restaurar el collar", objective = "Obtén una fuente de energía del constructo más poderoso que encuentres en Uldaman, y entrégasela a Talvash del Kissel en Forjaz." },
        [2240] = { name = "La cámara oculta", objective = "Lee el diario de Baelog, inspecciona la cámara oculta y ve a informar al prospector Pico Tormenta." },
        [2258] = { name = "Componentes de Tierras Inhóspitas", objective = "Llévale 5 mollejas de águila ratonera, 10 colmillos de coyote del risco y 5 fragmentos de elemental de piedra a Jarkal Musgofusión en Kargath, en las Tierras Inhóspitas." },
        [2278] = { name = "Los discos de platino", objective = "Habla con el guardapiedras y descubre qué conocimiento antiguo alberga. Cuando hayas adquirido el conocimiento que te ofrece, activa los Discos de Norgannon." },
        [2279] = { name = "Los discos de platino", objective = "Lleva la reproducción en miniatura de los Discos de Norgannon a la Liga de Expedicionarios de Forjaz." },
        [2280] = { name = "Los discos de platino", objective = "Lleva la reproducción en miniatura de los Discos de Norgannon a uno de los sabios de Cima del Trueno." },
        [2283] = { name = "La recuperación del collar", objective = "Busca el collar en la excavación de Uldaman y llévaselo a Dran Droffers a Orgrimmar.  Puede que el collar esté estropeado." },
        [2284] = { name = "La recuperación del collar, 2ª parte", objective = "Busca pistas sobre el paradero de las gemas en las profundidades de Uldaman." },
        [2318] = { name = "La traducción del diario", objective = "Encuentra a alguien que pueda traducir el diario del paladín. El lugar más cercano en el que podrás encontrar a alguien es Kargath, en las Tierras Inhóspitas." },
        [2338] = { name = "La traducción del diario", objective = "Préstale el collar a Jarkal. A cambio, te traducirá el diario." },
        [2339] = { name = "Encuentra las gemas y la fuente de poder", objective = "Recupera las 3 gemas y una fuente de energía para el collar de Uldaman y llévalo todo a Jarkal Musgofusión en Kargath. Jarkal cree que es posible que la fuente de energía más poderosa se halle en un constructo de Uldaman.\n\nPor el diario sabes…\n* Que han ocultado el rubí en una zona cerrada con barricadas en Forjatiniebla.\n* Que el topacio se ha ocultado en una urna en un área trogg, cerca de los enanos de la Alianza.\n* Que Grimlok, el jefe trogg, se ha quedado con el zafiro." },
        [2340] = { name = "Entregar las gemas", objective = "Entrégale el collar y la gema salvaje a Dran Droffers en Orgrimmar." },
        [2341] = { name = "La recuperación del collar, 3ª parte", objective = "Habla con Jarkal Musgofusión en Kargath." },
        [2342] = { name = "Los tesoros reclamados", objective = "Coge el tesoro de la familia de Patrick Garrett del cofre de su familia que se encuentra en la Sala Comunal Sur de Uldaman y llévasela a él a Entrañas." },
        [2361] = { name = "Restaurar el collar" },
        [2398] = { name = "Los enanos desaparecidos", objective = "Encuentra a Baelog en Uldaman." },
        [2418] = { name = "Las piedras de energía", objective = "Llévale 8 piedras de energía de dentrio y 8 piedras de energía de An'Alleum a Aparejez en las Tierras Inhóspitas." },
        [2439] = { name = "Los discos de platino", objective = "Lleva tu vale de recompensa a Dinita Quebrantarrocas, que está en las Arcas de Forjaz." },
        [2500] = { name = "Componentes de Tierras Inhóspitas", objective = "Ve a las Tierras Inhóspitas a buscar los ingredientes que te ha pedido Ghak Sanadón y llévaselos a Thelsamar." },
        [2768] = { name = "Cetro Divinomático", objective = "Lleva el Cetro Divinomático al ingeniero jefe Silvaina en Gadgetzan." },
        [2769] = { name = "Los hermanos Pernolatón", objective = "Habla con Wizzle Pernolatón en El Desierto de Sal." },
        [2770] = { objective = "Llévale la escama electrificada de Gahz'rilla a Wizzle Pernolatón, que está en El Desierto de Sal." },
        [2841] = { name = "Las guerras de la plataforma", objective = "Consigue la combinación de la caja fuerte de Termochufe en Gnomeregan y lleva los planos de la plataforma a Nogg a Orgrimmar." },
        [2842] = { name = "Scooty, ingeniero jefe", objective = "Habla con Scooty en Bahía del Botín." },
        [2843] = { name = "¡Gnomer-yaaaaa!", objective = "Espera a que Scooty calibre el transpondedor goblin." },
        [2846] = { name = "Tiara de la Profundidad", objective = "Lleva la Tiara de la Profundidad a Tabetha en el Marjal Revolcafango." },
        [2861] = { name = "La tarea de Tabetha", objective = "Habla con Tabetha en el Marjal Revolcafango." },
        [2864] = { objective = "Habla con Tran'rek en Gadgetzan." },
        [2865] = { name = "Caparazones de escarabajo", objective = "Lleva 5 caparazones de escarabajos sin grietas a Tran'rek en Gadgetzan." },
        [2904] = { name = "Un buen lío", objective = "Acompaña a Kernobee a La rampa del engranaje y luego ve a ver a Scooty a Bahía del Botín." },
        [2922] = { name = "¡Salva el cerebro de Techrobot!", objective = "Lleva el procesador central de memoria del techrobot al maestro manitas Sobrechispa a Forjaz." },
        [2924] = { name = "Esencias artificiales", objective = "Lleva 12 esencias artificiales a Klockmort Palmalicate a Forjaz." },
        [2926] = { objective = "Usa la ampolla de plomo con invasores o saqueadores radiactivos para recoger restos radiactivos. Cuando esté llena, llévasela a Ozzie Voltiflop a Kharanos." },
        [2928] = { name = "Excavadoras gyroagujereamáticas", objective = "Lleva veinticuatro entrañas robomecánicas a Shoni en Ventormenta." },
        [2929] = { name = "La gran traición", objective = "Ve a Gnomeregan y mata al mekigeniero Termochufe. Ve a ver al Manitas Mayor Mekkatorque cuando hayas terminado." },
        [2930] = { name = "Rescatar los datos", objective = "Lleva una tarjeta perforada prismática al maestro mecánico Funditubo a Forjaz." },
        [2933] = { name = "Botellas de veneno", objective = "Lleva una botella de veneno a algún boticario de Molino Tarren." },
        [2934] = { name = "Glándula de veneno intacta", objective = "Lleva una glándula de veneno intacta al boticario Lydon de Molino Tarren." },
        [2935] = { name = "Consulta al maestro Gadrin", objective = "Habla con el maestro Gadrin en el Poblado Sen'jin." },
        [2936] = { name = "Diosa araña", objective = "Lee el nombre de la diosa araña de los Secacorteza en la tablilla de Theka y vuelve a ver al maestro Gadrin." },
        [2945] = { name = "Un anillo sucio", objective = "Encuentra la manera de limpiar el anillo sucio." },
        [2947] = { name = "La devolución del anillo", objective = "Puedes quedarte el anillo o buscar a quien realizó los grabados de la parte interior." },
        [2948] = { name = "Mejora gnómica", objective = "Lleva tu anillo de oro, 1 lingote de plata, 1 ágata musgosa y 30 monedas de plata a Talvash del Kissel a Forjaz." },
        [2949] = { name = "La devolución del anillo", objective = "Puedes quedarte el anillo o buscar a quien realizó los grabados de la parte interior." },
        [2950] = { name = "Nogg mejora el anillo", objective = "Lleva tu anillo de oro, 1 lingote de plata, 1 ágata musgosa y 30 monedas de plata a Nogg a Orgrimmar." },
        [2951] = { name = "¡El Destellamatic 5200!", objective = "Inserta un objeto sucio en el Destellamatic 5200 y asegúrate de tener 3 monedas de plata a mano." },
        [2962] = { name = "Necesitamos más material verdoso", objective = "Viaja hasta Gnomeregan y recupera los restos radiactivos de gran potencia. Pero ten cuidado, ya que es inestable y podría explotar en cualquier momento.\n\nOzzie también quiere que traigas la ampolla pesada de plomo una vez que hayas terminado el trabajo." },
        [2988] = { name = "Las jaulas de Secacorteza", objective = "Mira en las jaulas de los poblados Secacorteza y vuelve a ver al maestro de grifos Garracha." },
        [2989] = { name = "El Altar de Zul", objective = "Mira en el Altar de Zul y vuelve a ver al maestro de grifos Garracha." },
        [2990] = { name = "Thadius Sombramacabra", objective = "Lleva la pluma de Picoafilado a Thadius Sombramacabra a Las Tierras Devastadas." },
        [2991] = { name = "Medallón de Nekrum", objective = "Lleva el medallón de Nekrum a Thadius Sombramacabra a Las Tierras Devastadas." },
        [3042] = { name = "Temple trol", objective = "Lleva 20 viales de temple trol a Trenton Mazaligera en Gadgetzan." },
        [3341] = { name = "Acaba con la amenaza", objective = "Andrew Brownell quiere que mates a Amnennar el Gélido y que le lleves su calavera." },
        [3373] = { name = "Esencia de Eranikus", objective = "Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido." },
        [3380] = { name = "El Templo Sumergido", objective = "Encuentra a Marvon Buscarroblones en Tanaris." },
        [3444] = { name = "El Círculo de Piedras", objective = "Recupera el Círculo de Piedras del taller de Marvon Buscarroblones, en Trinquete." },
        [3445] = { name = "El Templo Sumergido", objective = "Encuentra a Marvon Buscarroblones en Tanaris." },
        [3446] = { name = "En las profundidades", objective = "Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas." },
        [3447] = { name = "El secreto del círculo", objective = "Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas." },
        [3520] = { name = "Los espíritus de los estriadores", objective = "Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor." },
        [3523] = { name = "La plaga de la Zahúrda", objective = "Si decides ayudar a Belnistrasz, habla con él otra vez y devuélvele la piedra de juramento." },
        [3525] = { name = "Extinguir el ídolo", objective = "Acompaña a Belnistrasz al ídolo jabaespín en Zahúrda Rajacieno. \n\nProtégelo mientras realiza el ritual para inutilizar el ídolo." },
        [3527] = { name = "La profecía de Mosh'aru", objective = "Llévale la primera y segunda tablillas de Mosh'aru a Yeh'kinya, que está en Tanaris." },
        [3528] = { name = "El dios Hakkar", objective = "Llévale el Huevo relleno de Hakkar a Yeh'kinya, que está en Tanaris." },
        [3636] = { name = "Trae la Luz", objective = "El Arzobispo Bendictus quiere que mates a Amnennar el Gélido en Zahúrda Rajacieno." },
        [3701] = { name = "Las ruinas humeantes de Thaurissan", objective = "Ve a las Ruinas de Thaurissan, en las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa al historiador regio Archesonus." },
        [3702] = { name = "Las ruinas humeantes de Thaurissan", objective = "Escucha al historiador regio Archesonus relatar la historia de Thaurissan." },
        [3765] = { name = "Lejana corrupción", objective = "Ve a ver a Gershala Noctusurro en Auberdine." },
        [3801] = { name = "El legado de los Hierro Negro", objective = "Habla con Franclorn Forjafina si te interesa obtener una llave de la ciudad." },
        [3802] = { name = "El legado de los Hierro Negro", objective = "Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjafina." },
        [3906] = { name = "La discordia de las llamas", objective = "Ve a la cantera de la Montaña Roca Negra y ejecuta al gran maestro Pyron. Vuelve junto a Truenozón cuando hayas completado este encargo." },
        [3907] = { name = "La discordia de las llamas", objective = "Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Truenozón." },
        [3981] = { name = "Comandante Gor'shak", objective = "Encuentra al comandante Gor'shak en las Profundidades de Roca Negra.\n\nRecuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar." },
        [3982] = { name = "¿Qué pasa?", objective = "Defiende a Gor'shak." },
        [4001] = { name = "¿Qué pasa?", objective = "Habla con Kharan Martillazo y recaba información sobre el secuestro de la princesa Moira Barbabronce. Llévale esa información a Thrall en Orgrimmar.\n\nRecuerdas que Gor'shak mencionó que Kharan estaba preso en una celda cercana." },
        [4002] = { name = "Los Reinos del Este", objective = "Si aceptas la misión, habla con Thrall." },
        [4003] = { name = "El rescate real", objective = "Mata al emperador Dagran Thaurissan para liberar a la princesa Barbabronce del hechizo." },
        [4004] = { name = "¿Princesa salvada?", objective = "¡Vuelve junto a Thrall!" },
        [4024] = { name = "Un sabor a llamarada", objective = "Viaja hasta las Profundidades de Roca Negra y mata a Bael'Gar.\n\nSolo sabes que el gigante vive en las Profundidades de Roca Negra. Acuérdate de usar la escama alterada de Vuelo Negro sobre los restos de Bael'Gar para capturar la esencia fiera.\n\nLlévale la esencia fiera recubierta a Cyrus Therepentio." },
        [4061] = { name = "La revuelta de las máquinas", objective = "Adéntrate en Las Estepas Ardientes y recupera 10 fragmentos de elemental agrietado para Hierofante Theodora Mulvadania.\n\nRecuerdas que Theodora mencionó que los golems y elementales de esa región eran la fuente de estos fragmentos." },
        [4062] = { name = "La revuelta de las máquinas", objective = "Lleva el ejemplar de fragmento de Elemental a Lotwil Veriatus.\n\nRecuerdas que Theodora dijo que Lotwil se encontraba en un campamento hacia el este." },
        [4063] = { name = "La revuelta de las máquinas", objective = "Encuentra al Señor Gólem Argelmach y mátalo. Llévale su cabeza a Lotwil. Asimismo tendrás que reunir 10 núcleos de elemental intactos de los golems Furiatracadores y de los constructos belisario que protegen a Argelmach. Lo sabes porque eres un adivino." },
        [4081] = { name = "MATAR INMEDIATAMENTE: enanos Hierro Negro", objective = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!\n\nEl señor de la guerra Dientegore quiere que mates a 15 custodios de Yunque Colérico, 10 alcaides de Yunque Colérico y 5 lacayos de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea." },
        [4082] = { name = "MATAR INMEDIATAMENTE: oficiales Hierro Negro de alto rango", objective = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!\n\nEl señor de la guerra Dientegore quiere que mates a 10 médicos de Yunque Colérico, 10 soldados de Yunque Colérico y 10 oficiales de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea." },
        [4083] = { name = "El cáliz espectral", objective = "El cáliz espectral flota en el aire, ascendiendo y descendiendo lentamente… como el latido de un corazón moribundo." },
        [4121] = { name = "¡Estás en un aprieto!", objective = "Escolta al prisionero, Grark Lorkrub, a través de Las Estepas Ardientes y la Montaña Roca Negra hasta La Garganta de Fuego.\n\nRecuerdas que Lexlort mencionó que tendría a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido.\n\nTambién tendrás que entregarle a Lexlort los grilletes de torio." },
        [4122] = { objective = "Ve a Las Estepas Ardientes y encuentra a Grark Lorkrub. Recuerdas que Lexlort mencionó que lo habían visto por última vez en una colosal fortaleza Roca Negra.\n\nCuando encuentres a Grark Lorkrub, usa los grilletes de torio para atarlo y condúcelo de vuelta por la Montaña Roca Negra hasta La Garganta de Fuego. Lexlort tendrá a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido." },
        [4123] = { name = "El Corazón de la Montaña", objective = "Llévale el Corazón de la Montaña a Maxwort Suprandor en Las Estepas Ardientes." },
        [4126] = { name = "Hurley Negrálito", objective = "Llévale la receta perdida de Cebatruenos a Ragnar Cebatruenos en Kharanos." },
        [4128] = { name = "Ragnar Cebatruenos", objective = "Habla con Ragnar Cebatruenos." },
        [4132] = { name = "Operación: muerte a Forjafuria", objective = "Viaja hasta las Profundidades de Roca Negra ¡y mata al general Forjira! Vuelve junto al señor de la guerra Dientegore cuando hayas acabado la tarea." },
        [4133] = { name = "Vivian Latumba", objective = "Habla con la nigromante Vivian Latumba en Kargath." },
        [4134] = { name = "La receta perdida de Cebatruenos", objective = "Llévale la receta perdida de Cebatruenos a Vivian Latumba en Kargath." },
        [4136] = { name = "Ribbly Llavenrosca", objective = "Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes." },
        [4141] = { name = "Muigin y Larion", objective = "Recoge 15 pétalos de sangre y ve a ver a Muigin." },
        [4142] = { name = "Visita a Gregan", objective = "Llévale un pétalo de sangre a Gregan Vomitabrebaje de Feralas." },
        [4143] = { name = "Bruma del mal", objective = "Reúne 5 muestras de bruma Atal'ai y después ve a ver de nuevo a Muigin al Cráter de Un'Goro." },
        [4145] = { name = "Larion y Muigin", objective = "Caza 5 latigadores Pétalo de Sangre, 5 trilladores Pétalo de Sangre, 5 desolladores Pétalo de Sangre y 5 tramperos Pétalo de Sangre para Larion en el Refugio de Marshal." },
        [4146] = { name = "Combustible de irradior", objective = "Entrega el Controlador descargado y 5 muestras de bruma Atal'ai a Larion, en el Refugio de Marshal." },
        [4147] = { name = "El taller de Marvon", objective = "Viaja hasta el taller de Marvon Buscarroblones en Trinquete." },
        [4182] = { name = "La amenaza de los dragonantes", objective = "Mata 15 cachorrillos negros, 10 dragauros negros, 4 vermis negros y 1 draco negro. Vuelve junto a Helendis Rivacuerno cuando hayas acabado la tarea." },
        [4183] = { name = "Los verdaderos maestros", objective = "Viaja a Villa del Lago y entrégale la carta de Helendis Rivacuerno al magistrado Salomón." },
        [4184] = { name = "Los verdaderos maestros", objective = "Ve a Ventormenta para entregar la petición de ayuda de Solomon al Gran Señor Bolvar Fordragon. \n\nVive en el Castillo de Ventormenta." },
        [4185] = { name = "Los verdaderos maestros", objective = "Habla con el Alto Señor Bolvar Fordragon después de hablar con Lady Katrana Prestor." },
        [4186] = { name = "Los verdaderos maestros", objective = "Lleva el decreto de Bolvar al magistrado Salomón en la Villa del Lago." },
        [4201] = { name = "La poción de enamoramiento", objective = "Llévale 4 gromsanguinas, 10 venas de plata gigantescas y el vial lleno de Nagmara a la maestra Nagmara en las Profundidades de Roca Negra." },
        [4223] = { name = "Los verdaderos maestros", objective = "Habla con el alguacil Maxwell en Las Estepas Ardientes." },
        [4224] = { name = "Los verdaderos maestros", objective = "Habla con John Andrajoso para averiguar el destino del alguacil Windsor y vuelve junto al alguacil Maxwell cuando hayas completado la tarea.\n\nRecuerdas que el alguacil Maxwell comentó algo sobre buscarlo en una cueva hacia el norte." },
        [4241] = { name = "El alguacil Windsor", objective = "Viaja a la Montaña Roca Negra al noroeste y adéntrate en las Profundidades de Roca Negra. Averigua qué le ha ocurrido al alguacil Windsor.\n\nRecuerdas que John Andrajoso había comentado que se habían llevado a una cárcel a Windsor." },
        [4242] = { name = "Esperanza perdida", objective = "Dale las malas noticias a alguacil Maxwell." },
        [4262] = { name = "Gran maestro Pyron", objective = "Mata al gran maestro Pyron y vuelve junto a Jalinda Sprig.\n\nRecuerdas que Jalinda dijo que Pyron guardaba la cantera. Quizás deberías empezar a buscar allí." },
        [4263] = { name = "¡Incendius!", objective = "Encuentra a Lord Incendius en las Profundidades de Roca Negra ¡y acaba con él!" },
        [4264] = { name = "Una nota arrugada", objective = "Puede que acabes de toparte con algo que le interesaría ver al alguacil Windsor. Puede que haya esperanza, después de todo." },
        [4282] = { name = "Una esperanza hecha trizas", objective = "Devuélvele al alguacil Windsor la información perdida.\n\nEl alguacil Windsor cree que la información está siendo retenida en manos del Señor Gólem Argelmach y del general Forjira." },
        [4286] = { name = "Buena mercancía", objective = "Viaja a las Profundidades de Roca Negra y recupera 20 riñoneras Hierro Negro. Vuelve junto a Oralius cuando hayas completado esta tarea. Se da por sentado que los enanos Hierro Negro de las Profundidades de Roca Negra llevan estos inventos de riñoneras." },
        [4295] = { name = "La cerveza de Sinrosca", objective = "¡Oh, cerveza! ¡¡Mataría por algo de cerveza Hierro Negro!! ¡Rápido, que me estoy poniendo sobrio! Lo sé porque la sobriedad me nubla la vista... ¡y eso hace que te parezcas al <raza> que maté la semana pasada!" },
        [4322] = { name = "La fuga de la prisión", objective = "Ayuda al alguacil Windsor a recuperar su equipo y a liberar a sus amigos. Vuelve junto al alguacil Maxwell si lo consigues." },
        [4324] = { name = "Yuka Llavenrosca", objective = "Habla con Yuka Llavenrosca en Las Estepas Ardientes." },
        [4341] = { name = "Kharan Martillazo", objective = "Ve a las Profundidades de Roca Negra y encuentra a Kharan Martillazo.\n\nEl rey dijo que estaba prisionero allí; busca una cárcel." },
        [4342] = { name = "La leyenda de Kharan", objective = "Escucha la historia de Kharan Martillazo." },
        [4361] = { name = "Portador de malas noticias", objective = "Regresa a Forjaz y dale las malas noticias al rey Magni Barbabronce." },
        [4362] = { name = "El destino del reino", objective = "Vuelve a las Profundidades de Roca Negra y rescata a la princesa Moira Barbabronce de las garras del emperador Dragan Thaurissan." },
        [4363] = { name = "La sorpresa de la princesa", objective = "Regresa a Forjaz y habla con el rey Magni Barbabronce." },
        [4701] = { name = "Acaba con el origen de la amenaza", objective = "Viajar hasta la Cumbre de Roca Negra y destruye el origen de la amenaza del lupo. Cuando dejaste a Helendis, gritó un nombre: Halycon. Es la palabra que los orcos usan para referirse al lupo." },
        [4724] = { name = "La maestra de la manada", objective = "Mata a Halycon, empaqueta la Maestra del lupo Hacha de Sangre." },
        [4726] = { name = "Esencia de cría", objective = "Llévale 8 esencias de cría y el Draco Incarcinatrix 900 a Tinkee Vaporino en el Peñacho Llamarada, en Las Estepas Ardientes." },
        [4729] = { name = "Las mascotas exótica de Kibler", objective = "Viaja hasta la Cumbre de Roca Negra y encuentra mascolupos Hacha de Sangre. Usa la jaula para transportar a esas feroces fierecillas. Llévale a Kibler 1 mascolupo enjaulado." },
        [4734] = { name = "Un huevo congelado", objective = "Usa el prototipo de ovosciloscopio sobre un huevo de El Grajero." },
        [4735] = { name = "La colecta de huevos", objective = "Llévale 8 huevos de dragón y el módulo colectrónico a Tinkee Vaporino en el Peñacho Llamarada, en Las Estepas Ardientes." },
        [4742] = { name = "El Sello de Ascensión", objective = "Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el Sello de Ascensión sin adornos a Vaelan.\n\nLos generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el Alto señor Omokk de los Cumbrerroca y el Señor Supremo Vermiothalak de los Hacha de Sangre." },
        [4743] = { name = "El Sello de Ascensión", objective = "Viaja a la Ciénaga de Fuego en Marjal Revolcafango. Encuentra al anciano draco Brasaliza y derrótalo sin contemplaciones hasta doblegar su voluntad.\n\nEste es el preciso momento en el que debes colocar el Sello de ascensión sin forjar ante la colosal bestia. Debes entonces ser rápido en usar el orbe de energía dracónica sobre su debilitada forma y reclamar el dominio sobre sus facultades mentales. ¡Controla la bestia y dirige las llamas del Vuelo Negro sobre el Sello de ascensión sin forjar!" },
        [4764] = { name = "El Broche de Equipasino", objective = "Llévale el broche de Equipasino a Mayara Alasol en Las Estepas Ardientes." },
        [4766] = { name = "Mayara Alasol", objective = "Habla con Mayara Alasol en Las Estepas Ardientes." },
        [4768] = { name = "La tablilla de Rocanegra", objective = "Llévale la tablilla de Rocanegra a la maga oscura Vivian Latumba en Kargath." },
        [4769] = { name = "Vivian Latumba y la tablilla de Rocanegra", objective = "Habla con la maga oscura Vivian Latumba Vivian Latumba." },
        [4771] = { name = "Gambito del Alba", objective = "Coloca el Gambito del Alba en la Sala de la Visión de Scholomance.  Derrota a Vectus y ve a ver a Betina Bigglezink." },
        [4787] = { name = "El huevo antiguo", objective = "Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris." },
        [4788] = { name = "Las últimas tablillas", objective = "Llévale la quinta y sexta tablillas de Mosh'aru al prospector Ferrobota, que está en Tanaris." },
        [4808] = { name = "Felnok Acerovera", objective = "Entrégale la carta de Tinkee a Felnok Acerovera." },
        [4809] = { name = "Cuernos de quimera venfresco", objective = "Llévale 8 cuernos de quimera venfresco sin fisuras a Felnok Acerovera." },
        [4810] = { name = "Vuelve con Tinkee", objective = "Llévale el paquete de Felnok a Tinkee Vaporio en Las Estepas Ardientes." },
        [4862] = { name = "Bestia amaestrada", objective = "Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler.\n\nYo diría que se pueden encontrar estos huevos cerca de arañas." },
        [4866] = { name = "La leche de la madre", objective = "En el corazón de la Cumbre de Roca Negra encontrarás a Madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti." },
        [4867] = { name = "Urok Aullasino", objective = "Lee el pergamino de Warosh. Llévale el mojo de Warosh a Warosh." },
        [4903] = { name = "La orden del Señor de la Guerra", objective = "Mata al Alto señor Omokk, al maestro de guerra Voone y al Señor Supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión." },
        [4907] = { name = "Tinkee Vaporino", objective = "Habla con Tinkee Vaporio." },
        [4941] = { name = "La sabiduría de Eitrigg", objective = "Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall.\n\nRecuerdas haber visto a Eitrigg en la Cámara de Thrall." },
        [4974] = { name = "¡Por la Horda!", objective = "Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Llévale su cabeza a Orgrimmar." },
        [4981] = { name = "La espía Bijou", objective = "Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou." },
        [4982] = { name = "Las pertenencias de Bijou", objective = "Encuentra las pertenencias de Bijou y devuélveselas. Recuerdas que ella mencionó haberlas ocultado en la planta baja de la ciudad." },
        [5001] = { name = "Las pertenencias de Bijou", objective = "Encuentra las pertenencias de Bijou y devuélveselas. ¡Suerte!" },
        [5002] = { name = "Un mensaje para Maxwell", objective = "Viaja a Las Estepas Ardientes y dale la información sobre Bijou al alguacil Maxwell." },
        [5047] = { name = "¡Finkle Unicornín, a tu servicio!", objective = "Habla con Malyfous Martilloscuro en Vista Eterna." },
        [5065] = { name = "Las tablillas perdidas de Mosh'aru", objective = "Llévale la tercera y cuarta tablillas de Mosh'aru al prospector Ferrobota, que está en Tanaris." },
        [5081] = { name = "La misión de Maxwell", objective = "Viaja a la Cumbre de Roca Negra y destruye al maestro de guerra Voone, al alto señor Omokk y al Señor Supremo Vermiothalak. Vuelve junto al alguacil Maxwell cuando hayas acabado tu trabajo." },
        [5089] = { name = "Orden del general Drakkisath", objective = "Llévale la orden del general Drakkisath al alguacil Maxwell en Las Estepas Ardientes." },
        [5102] = { name = "Muerte al general Drakkisath", objective = "Viaja hasta la Cumbre de Roca Negra y mata al general Drakkisath. Vuelve junto al alguacil Maxwell cuando hayas acabado tu trabajo." },
        [5122] = { name = "El medallón de Fe", objective = "El poder de esta capilla me da la fuerza para resistir la corrupción que habita en mi corazón. Si cedo, me convertiré en un caballero de la muerte. Pero hay un medallón, el medallón de fe, que me dará la fuerza que necesito para partir.\n\nPor favor, <nombre>, recupera el medallón. Está en manos de Malor el Fanático, un miembro demente de la Hermandad Escarlata, que reside en las profundidades del Bastión Escarlata en Stratholme occidental." },
        [5125] = { name = "La estimación de Aurius", objective = "<nombre>, me estoy muriendo... pero mi alma está salvada. Por eso, te debo más de lo que jamás podré expresar. Por favor, acepta esto, ¡y sigue luchando... valiente <clase>!" },
        [5127] = { name = "La forja demoníaca", objective = "Viaja a la Cumbre de Roca Negra y encuentra a Goraluk Yunquegrieta. Mátale y utiliza el Pico manchado de sangre sobre su cadáver. Cuando hayas absorbido su alma, el pico estará manchado de alma.\n\nTambién debes encontrar el peto cubierto de runas sin forjar.\n\nLleva el pico manchado de alma y el peto cubierto de runas sin forjar a Lorax en Cuna del Invierno." },
        [5160] = { name = "El Protectorado de la matrona", objective = "Viaja hasta la Cuna del Invierno y encuentra a Haleh. Dale la escama de Awbee." },
        [5212] = { name = "La carne no miente", objective = "Recoge 20 muestras de carne infestada de Stratholme y vuelve con Betina Bigglezink. Sospechas que podrías obtener una muestra de cualquier criatura de Stratholme." },
        [5213] = { name = "El agente activo", objective = "Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink." },
        [5214] = { name = "El gran Fras Siabi", objective = "Encuentra la Tienda de humo de Fras Siabi en Stratholme y recupera una caja del tabaco de calidad de Siabi. Cuando lo hayas hecho, vuelve con Smokey LaRue." },
        [5243] = { name = "Las casas de lo sagrado", objective = "Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido." },
        [5244] = { name = "Las ruinas de Kel'Theril", objective = "Habla con Jaron Tallapiedras en Aldea Estrella Fugaz." },
        [5245] = { name = "Espíritus condenados de Kel'Theril", objective = "Utiliza el pico de Jaron para encontrar los cuatro fragmentos de reliquia de los altonatos. Llévaselas a Aurora Llamacielo en las Tierras de la Peste del Este." },
        [5246] = { name = "Fragmentos del pasado", objective = "Encuentra las escrituras altonatas sagradas del templo de Zin-Malor en Azshara y tráelas para Aurora Llamacielo, en la Torre del Paso Norte en las Tierras de la Peste del Este." },
        [5247] = { name = "Fragmentos del pasado", objective = "Consigue una barra encantada de torio, 5 cristales de restauración y un vial de agua funesta para Aurora Llamacielo, en la Torre del Paso Norte, en las Tierras de la Peste del Este." },
        [5250] = { name = "Estrella Fugaz", objective = "Encuentra la Aldea Estrella Fugaz en Cuna del Invierno y habla con Wynd Cazanoche." },
        [5251] = { name = "El archivista", objective = "Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata." },
        [5262] = { name = "La verdad cae del cielo", objective = "Lleva la cabeza de Balnazzar al Duque Nicholas Zverenhoff en las Tierras de la Peste del Este." },
        [5263] = { name = "Por encima y más allá", objective = "Viaja a Stratholme y acaba con el barón Osahendido. Coge su cabeza y vuelve con el duque Nicolas Zverenhoff." },
        [5281] = { name = "Espíritus inquietos", objective = "Encuentra a Egan. Solo sabes que fue visto por última vez en los alrededores de Stratholme." },
        [5282] = { name = "Espíritus inquietos", objective = "Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre.\n\nLibera 15 almas y regresa a Egan." },
        [5341] = { name = "La fortuna de la familia Barov", objective = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras del Molino Tarren y Las escrituras de Costasur. Regresa con Alexi Barov cuando hayas terminado esta tarea." },
        [5343] = { name = "La fortuna de la familia Barov", objective = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras del Molino Tarren y Las escrituras de Costasur. Regresa con Weldon Barov cuando hayas terminado esta tarea." },
        [5382] = { name = "Doctor Theolen Krastinov, el Carnicero", objective = "Busca al doctor Theolen Krastinov en el interior de Scholomance. Acaba con él y quema los restos de Eva Sarkhoff y los restos de Lucien Sarkhoff. Cuando hayas terminado tu tarea regresa con Eva Sarkhoff." },
        [5384] = { name = "Kirtonos el Heraldo", objective = "Vuelve a Scholomance con la Sangre de los inocentes. Busca el Porche y coloca la Sangre de los inocentes en el blandón. Kirtonos acudirá a devorar tu alma.\n\nLucha con valentía, ¡no cedas ni una pulgada! Destruye a Kirtonos y vuelve con Eva Sarkhoff." },
        [5461] = { name = "El humano, Ras Levescarcha", objective = "Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Recuerdo de Evocación. Si lo encuentras llévaselo al magistrado Marduke." },
        [5462] = { name = "El moribundo, Ras Levescarcha", objective = "Viaja a Esperanza de la Luz en las Tierras de la Peste del Este y busca a Leonid Barthalomew el Venerado. Enséñale el Recuerdo de Evocación y cuéntale todo lo que has descubierto." },
        [5463] = { name = "El Obsequio de Menethil", objective = "Viaja a Stratholme y encuentra el Obsequio de Menethil. Coloca el Recuerdo de Evocación en suelo no consagrado." },
        [5464] = { name = "El Obsequio de Menethil", objective = "Lleva las Memorias del Vínculo del Alma a Leonid Barthalomew a las Tierras de la Peste del Este." },
        [5465] = { name = "Memorias del Vínculo del Alma", objective = "Vuelve con el magistrado Marduke a Castel Darrow. Muéstrale las Memorias del Vínculo del Alma." },
        [5466] = { name = "El Lich, Ras Levescarcha", objective = "Busca a Ras Levescarcha en Scholomance. Cuando lo hayas encontrado utiliza las Memorias del Vínculo del Alma sobre su rostro no-muerto. Si consiguieras convertirlo en mortal, derrótale y recupera la Cabeza humana de Ras Levescarcha. Lleva la cabeza al magistrado Marduke." },
        [5515] = { name = "Bolsa de los horrores de Krastinov", objective = "Localiza a Jandice Barov en Scholomance y destrúyela. En su cadáver encontrarás la Bolsa de los horrores de Krastinov. Devuélvele la bolsa a Eva Sarkhoff." },
        [5518] = { name = "El traje de orgo Gordok", objective = "Lleva 4 madejas de paño rúnico, 8 retales de cuero basto, 2 hebras de hilo rúnico y tanino de ogro a Knot Llavededo.  Actualmente está encadenado en el interior del ala Gordok de La Masacre." },
        [5522] = { objective = "Lleva los huevos congelados a Leonid Barthalomew a las Tierras de la Peste del Este." },
        [5525] = { name = "¡Libera a Knot!", objective = "Se llama llave de los grilletes de Gordok... bueno, así es como la llaman esos graciosillos. Creo que podría tenerla cualquiera de los ogros, pero no sé cuáles en concreto. Probablemente podrían tenerla los guardias...\n\n¿Pero qué estoy diciendo? ¡Si tú ya la tienes! ¡¿No?! ¡¿¿No es eso que tienes ahí??!" },
        [5526] = { name = "Fragmentos de gangrevid", objective = "Encuentra gangrevid en La Masacre y coge un fragmento.  Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal.  Usa el relicario de pureza para guardar el fragmento y llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna." },
        [5527] = { name = "Un relicario de pureza", objective = "Ve a Silithus a buscar un relicario de pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna." },
        [5529] = { name = "Crías infestadas", objective = "Mata a 20 crías de dragón infectadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz." },
        [5531] = { objective = "Lleva los huevos congelados a Betina Bigglezink, que está fuera." },
        [5542] = { name = "Perros demoníacos", objective = "Mata 20 cachorros de can de la Peste, 5 canes de la Peste y 5 canes de la Peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Fordring." },
        [5543] = { name = "Cielos sangrientos", objective = "Mata 30 murcípestes y vuelve con Tirion Fordring." },
        [5544] = { name = "Gusanos carroñeros", objective = "Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Fordring cuando tengas 14 trozos de carne de gusano carroñero." },
        [5722] = { name = "Buscando la cartera perdida", objective = "Inspecciona la Sima Ígnea en busca del cuerpo de Maur Tótem Siniestro y comprueba si porta algún objeto de interés." },
        [5723] = { name = "Midiendo fuerzas con el enemigo", objective = "Localiza la Sima Ígnea en Orgrimmar y después mata a 8 troggs Furia Ardiente y 8 chamanes Furia Ardiente y después ve a ver de nuevo a Rahauro a Cima del Trueno." },
        [5724] = { name = "La vuelta de la cartera perdida", objective = "Lleva la cartera de Tótem Siniestro hasta Rahauro, en Cima del Trueno." },
        [5725] = { name = "Poder destructivo", objective = "Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Varimathras, que está en Entrañas." },
        [5726] = { name = "Enemigos ocultos", objective = "Lleva una insignia de General a Thrall a Orgrimmar." },
        [5727] = { name = "Enemigos ocultos", objective = "Lleva la insignia de General a Neeru Hojafuego. Averigua si cree que eres miembro de Filo Ardiente; luego ve a ver a Thrall a Orgrimmar." },
        [5728] = { name = "Enemigos ocultos", objective = "Mata a Bazzalan y a Jergosh el Invocador y ve a ver a Thrall a Orgrimmar." },
        [5742] = { name = "Redención", objective = "Escucha lo que Tirion Fordring tiene que contarte." },
        [5761] = { name = "Matar a la bestia", objective = "Ve a la Sima Ígnea, mata a Taragaman el Hambriento y llévale su corazón a Neeru Hojafuego a Orgrimmar." },
        [5781] = { name = "De recuerdos olvidados", objective = "Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring." },
        [5845] = { name = "Del honor perdido", objective = "Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo del Honor Perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring." },
        [5846] = { name = "De amor y familia", objective = "Viaja a la isla de Castel Darrow, en la región sur del centro de las Tierras de la Peste. Allí, busca pistas sobre el paradero del cuadro." },
        [5848] = { name = "De amor y familia", objective = "Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'De amor y familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo.\n\nDevuelve la pintura a Tirion Fordring." },
        [5961] = { name = "Campeón de la reina alma en pena", objective = "Habla con Nathanos Clamorinfecto en las Tierras de la Peste del Este. Se dice que ahora vive en la Hacienda de Marris." },
        [6022] = { name = "Matar con un propósito", objective = "Viaja al Cruce de Corin al este y mata a los miembros de la Plaga que habitan allí. Recoge 7 piezas de putrefacción viva en 10 minutos. Utiliza el mortero y la mano de mortero para convertir la putrefacción viva en putrefacción coagulada." },
        [6042] = { name = "Los pequeños problemas de la no-vida", objective = "Mata a 20 murcipestes tóxicos y 10 murcipestes monstruosos. Vuelve con Nathanos Clamorinfecto cuando hayas acabado." },
        [6133] = { name = "La orden del Señor de exploradores", objective = "Viaja a la frontera norte de las Tierras de la Peste del Este y recupera el Registro de Quel'Thalas. Se encuentra en algún lugar del Refugio Quel'Lithien.\n\nTambién tienes que matar a 8 exploradores, 8 zancaminos y 8 Leñantros." },
        [6135] = { name = "Alatardecer, cómo te odio…", objective = "Encuentra a Alatardecer y mátalo. Recoge un parche de piel de Alatardecer de su cadáver y llévaselo a Nathanos Clamorinfecto.\n\nSe dice que Alatardecer vaga por el campo, al norte de la Hacienda de Marris." },
        [6136] = { name = "El corpulento", objective = "Encuentra a Borelgore en las planicies del norte de las Tierras de la Peste del Este y destrúyelo. Vuelve junto a Nathanos Clamorinfecto cuando hayas cumplido la misión." },
        [6141] = { name = "Hermano Antón", objective = "Habla con el hermano Antón en Desolace." },
        [6163] = { objective = "Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos." },
        [6402] = { name = "Tienes un cita en Ventormenta", objective = "Viaja hasta Ventormenta y aventúrate tras las puertas de la ciudad. Habla con el escudero Rowe para que haga saber al alguacil Windsor sobre tu llegada." },
        [6403] = { name = "La gran farsa", objective = "Sigue a Reginald Windsor por Ventormenta. ¡Protégele del peligro!" },
        [6501] = { name = "El Ojo del dragón", objective = "Debes buscar por todo el mundo y encontrar un ser capaz de restaurar el poder del fragmento del Ojo del dragón. La única información que tienes sobre dicho ser, es que existe." },
        [6502] = { name = "Amuleto Pirodraco", objective = "Tienes que recuperar la sangre de dragón negro campeón, la tiene el general Drakkisath. Puedes encontrar a Drakkisath en su sala del trono, tras las Salas de la Ascensión, en la Cumbre de Roca Negra." },
        [6521] = { name = "Una alianza nefasta", objective = "Lleva la cabeza del embajador Malcin a Varimathras, que está en Entrañas." },
        [6522] = { name = "Una alianza nefasta", objective = "Lleva el pergamino a Varimathras, que está en Entrañas." },
        [6561] = { name = "La vileza de Brazanegra", objective = "Llévale la cabeza del Señor Crepuscular Kelris a Bashana Runatótem en Cima del Trueno." },
        [6562] = { name = "Problemas en las profundidades", objective = "Habla con Je'neu Sancrea en Vallefresno." },
        [6563] = { name = "La esencia de Aku'Mai", objective = "Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno." },
        [6564] = { name = "Lealtad a los dioses antiguos", objective = "Llévale la nota humedecida a Je'neu Sancrea en Vallefresno." },
        [6565] = { name = "Lealtad a los dioses antiguos", objective = "Mata a Lorgus Jett en las Cavernas de Brazanegra y vuelve junto a Je'neu Sancrea en Vallefresno." },
        [6566] = { name = "Lo que trae el viento", objective = "Escucha a Thrall." },
        [6567] = { name = "El Campeón de la Horda", objective = "Busca a Rexxar. El Jefe de Guerra ha dicho que estará en Desolace, entre Sierra Espolón y Feralas." },
        [6568] = { name = "El testamento de Rexxar", objective = "Entrega el testamento de Rexxar a Myranda la Fada. Está en las Tierras de la Peste del Oeste." },
        [6569] = { name = "Ilusiones oculares", objective = "Viaja a la Cumbre de Roca Negra y recoge 20 ojos de dragauro negro. Cuando hayas terminado tu tarea regresa con Myranda la Fada." },
        [6570] = { name = "Brasaliza", objective = "Viaja a la Ciénaga de Fuego del Marjal Revolcafango y busca el Cubil de Brasaliza. Cuando estés dentro ponte el Amuleto de Subversión Dracónica y habla con Brasaliza." },
        [6582] = { name = "La prueba de las calaveras, Arúspice", objective = "Debes encontrar a Arúspice, el campeón draco del Vuelo Azul y matarlo. Separa su calavera de su cuerpo y llévasela a Brasaliza.\n\nSabes que puedes encontrar a Arúspice en Cuna del Invierno." },
        [6583] = { name = "La prueba de las calaveras, Somnus", objective = "Destruye al campeón draco del Vuelo Verde, Somnus. Lleva su calavera a Brasaliza." },
        [6584] = { name = "La prueba de las calaveras, Chronalis", objective = "Chronalis, hijo de Nozdormu, custodia las Cavernas del Tiempo en el Desierto de Tanaris. Destrúyelo y lleva su calavera a Brasaliza." },
        [6585] = { name = "La prueba de las calaveras, Axtroz", objective = "Viaja a Grim Batol y encuentra a Axtroz, el campeón draco del Vuelo Rojo. Destrúyelo y hazte con su calavera. Llévasela a Brasaliza." },
        [6601] = { name = "El ascenso", objective = "Diría que se acabaron las charadas. Ya sabes que el Amuleto de Subversión Dracónica que Myranda la Fada creó para ti no funcionará en el interior de la Cumbre de Roca Negra. Quizás deberías buscar a Rexxar y explicarle el apuro en el que te encuentras. Enséñale el amuleto pirodraco apagado. Con un poco de suerte, él sabrá que hay que hacer ahora." },
        [6602] = { name = "La sangre de dragón negro campeón", objective = "Viaja a la Cumbre de Roca Negra y mata al general Drakkisath. Recoge su sangre y llévasela a Rexxar." },
        [6626] = { name = "Un anfitrión del mal", objective = "Mata a  8 guardias de batalla y 8 tejespinas Rajacieno y 8 adeptos Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno." },
        [6627] = { name = "Prueba de conocimiento", objective = "Responde la pregunta de Braug Espiritoscuro con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés <listo/lista>." },
        [6628] = { name = "Prueba de conocimiento", objective = "Responde la pregunta de Parqual Fintallas con acierto y después habla con él de nuevo. Se quedará en Entrañas hasta que estés <listo/lista>." },
        [6921] = { name = "Entre ruinas", objective = "Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno." },
        [6922] = { name = "Barón Aquanis", objective = "Llévale el extraño globo de agua a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno." },
        [6981] = { name = "El fragmento brillante", objective = "Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento brillante.\n\nEntrega el fragmento como se te indique." },
        [7028] = { name = "Los males de Maraudón", objective = "Recoge 25 tallas de cristal terádrico y llévaselas a Willow a Desolace." },
        [7029] = { name = "La corrupción de Lenguavil", objective = "Llena el vial revestido en el estanque naranja de Maraudon. \n\nAplica el líquido a la hiedra tallovil para que emerja el vástago tóxico. \n\nCura 8 plantas eliminando su vástago tóxico e informa a Vark Marcaguerra en la Aldea Cazasombras." },
        [7041] = { name = "La corrupción de Lenguavil", objective = "Llena el vial revestido en el estanque naranja de Maraudon. \n\nAplica el líquido a la hiedra tallovil para que emerja el vástago tóxico. \n\nCura 8 plantas eliminando su vástago tóxico e informa a Talendria en Punta de Nijel." },
        [7044] = { name = "Leyendas de Maraudón", objective = "Recupera las 2 partes del Cetro de Celebras: la vara y el diamante Celebrian. \n\nEncuentra el modo de hablar con Celebras." },
        [7046] = { name = "El Cetro de Celebras", objective = "Ayuda a Celebras el Redimido mientras reconstruye el Cetro de Celebras. \n\nHabla con él después del ritual." },
        [7064] = { name = "Corrupción de la tierra y de la semilla", objective = "Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace." },
        [7065] = { name = "Corrupción de la tierra y de la semilla", objective = "Mata a la princesa Theradras y ve a ver al guardián Marandis a Punta de Nijel, en Desolace." },
        [7066] = { name = "La semilla de la vida", objective = "Busca a Remulos en Claro de la Luna y dale la semilla de la vida." },
        [7067] = { name = "Las instrucciones del Paria", objective = "Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace." },
        [7068] = { name = "Fragmentos Oscuros", objective = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar." },
        [7070] = { name = "Fragmentos Oscuros", objective = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango." },
        [7201] = { name = "El último elemento", objective = "Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los golems y a los creadores de golems. Recuerdas que Vivian Latumba también murmuró entre dientes algo sobre los elementales." },
        [7441] = { name = "Pusillín y el ancestro Azj'Tordin", objective = "Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de conjuros de Azj'Tordin, por cualquier medio. \n\nSi consigues hacerte con el libro de conjuros, vuelve al Pabellón Lariss de Feralas y busca a Azj'Tordin." },
        [7461] = { name = "Locura interior", objective = "Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará. \n\nEntra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum. \n\nSi consigues completar esta misión, ve al patio a buscar al Anciano Shen'dralar." },
        [7462] = { name = "El tesoro de los Shen'dralar", objective = "Regresa a El Athenaeum y encuentra el tesoro de Shen'dralar. ¡Reclama tu recompensa!" },
        [7463] = { name = "El refresco arcano", objective = "Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al guardián del Conocimiento Lydros que está en El Athenaeum." },
        [7481] = { name = "Leyendas élficas", objective = "Busca a Kariel Winthalus en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres." },
        [7482] = { name = "Leyendas élficas", objective = "Busca a Kariel Winthalus en La Masacre. Vuelve al Bastión Plumaluna a informar al erudito Runaespina de lo que hayas encontrado." },
        [7483] = { name = "El Tratado de Prontitud", objective = "Lleva 1 Tratado de Prontitud, 1 diamante negro prístino, 2 grandes fragmentos brillantes y 2 unidades de sangre de héroes al guardián del Conocimiento Lydros a La Masacre para conseguir un arcano de prontitud." },
        [7484] = { name = "El Tratado de Concentración", objective = "Lleva 1 Tratado de Concentración, 1 diamante negro prístino, 4 grandes fragmentos brillantes y 2 pieles de sombra al guardián del Conocimiento Lydros a La Masacre para conseguir un arcano de concentración." },
        [7485] = { name = "El Tratado de Protección", objective = "Lleva 1 Tratado de Protección, 1 diamante negro prístino, 2 grandes fragmentos brillantes y 1 costura desgarrada de abominación al guardián del Conocimiento Lydros a La Masacre para conseguir un arcano de protección." },
        [7488] = { name = "La Membrana de Lethtendris", objective = "Lleva la Membrana de Lethtendris a Latronicus Lanzaluna al Bastión Plumaluna de Feralas." },
        [7489] = { name = "La Membrana de Lethtendris", objective = "Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas." },
        [7492] = { name = "Campamento Mojache", objective = "Ve al Campamento Mojache de Feralas y habla con Talo Pezuñahendida." },
        [7494] = { name = "Bastión Plumaluna", objective = "Habla con Latronicus Lanzaluna. Lo encontrarás en el Bastión Plumaluna de Feralas." },
        [7498] = { name = "Garona: un estudio acerca de la discreción y la traición", objective = "Devuelve el libro a sus legítimos dueños." },
        [7499] = { name = "Códice de Defensa", objective = "Devuelve el libro a sus legítimos dueños." },
        [7500] = { name = "El Recetario del Arcanista", objective = "Devuelve el libro a sus legítimos dueños." },
        [7501] = { name = "La Luz y cómo alterarla", objective = "Devuelve el libro a sus legítimos dueños." },
        [7502] = { name = "Controlar las Sombras", objective = "Devuelve el libro a sus legítimos dueños." },
        [7503] = { name = "La mayor raza de cazadores", objective = "Devuelve el libro a sus legítimos dueños." },
        [7504] = { name = "Sagrada Bologna: lo que la Luz nunca te dirá", objective = "Devuelve el libro a sus legítimos dueños." },
        [7505] = { name = "El choque de Escarcha y tú", objective = "Devuelve el libro a sus legítimos dueños." },
        [7506] = { name = "El Sueño Esmeralda", objective = "Devuelve el libro a sus legítimos dueños." },
        [7507] = { name = "Compendio de Foror", objective = "Devuelve el Compendium of Dragon Slaying de Foror a El Athenaeum." },
        [7563] = { name = "La ira de sangre", objective = "Llévale 30 botellas de sangre de bestia embravecida a Mor'zul Sangredoble en Las Estepas Ardientes." },
        [7564] = { name = "Ojosalvajes", objective = "Llévale el estuche de sangre a Gorzeeki Ojosalvajes en Las Estepas Ardientes." },
        [7604] = { name = "Un contrato vinculante", objective = "Entrégale el contrato de La Hermandad del torio a Lokhtos Tratoscuro si quieres recibir los planes de Sulfuron." },
        [7623] = { name = "Lord Pesadilla", objective = "Cómprale oscuras pociones a Gorzeeki en Las Estepas Ardientes.\n\nUsa la pociones para viajar por Jaedenar y habla con Lord Pesadilla." },
        [7624] = { name = "Ulathek el Traidor", objective = "Enfréntate a Ulathek y llévale el corazón del traidor a Lord Pesadilla en Jaedenar." },
        [7625] = { name = "Polvo estelar xorotiano", objective = "Cómprale polvo estelar xorotiano a Ur'dan. Llévaselo a Gorzeeki Ojosalvajes en Las Estepas Ardientes." },
        [7626] = { name = "La Campana de Dethmoora", objective = "Llévale 10 elixires de poder de las sombras a Gorzeeki Ojosalvajes en Las Estepas Ardientes." },
        [7627] = { name = "Rueda de la Marcha Negra", objective = "Llévale 6 grandes fragmentos brillantes y 25 minerales de hierro negro a Gorzeeki Ojosalvajes en Las Estepas Ardientes." },
        [7628] = { name = "La Vela del Apocalipsis", objective = "Lleva 35 escamas de dragón negro a Gorzeeki Ojosalvajes a Las Estepas Ardientes." },
        [7629] = { name = "Entrega de diablillo", objective = "Llévale el diablillo en un tarro al laboratorio de alquimia de Scholomance. Después de crear el pergamino llévale el tarro a Gorzeeki Ojosalvajes." },
        [7630] = { name = "La arcanita", objective = "Lleva 3 lingotes de arcanita a Gorzeeki Ojosalvajes a Las Estepas Ardientes." },
        [7631] = { name = "Terrorecus de Xoroth", objective = "Lee las instrucciones de Mor'zul. Invoca al Corcel de la Muerte Xorothiano, derrótalo y después vincula su espíritu al tuyo." },
        [7637] = { name = "Énfasis en el sacrificio", objective = "Viaja a Forjaz y consigue el incensario de exorcismos del sumo sacerdote Rohan. Tendrás que hacer una donación de 150 monedas de oro para conseguirlo." },
        [7639] = { name = "Mostrarse juicioso", objective = "Devuelve el incensario de exorcismos a Lord Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
        [7640] = { name = "Exorcismo en Valle del Terror", objective = "Utiliza el incensario de exorcismos para expulsar los espíritus que atormentan el Valle del Terror. Cuando hayas matado 25 espíritus del Valle del Terror, vuelve a ver a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
        [7641] = { name = "El trabajo de Grimand Elmore", objective = "Habla con Grimand Elmore en el Distrito de los Enanos, en Ventormenta." },
        [7642] = { name = "Recopilación de artículos", objective = "Lleva 40 paños rúnicos, 6 lingotes de arcanita, 10 lágrimas de Arthas, 5 frascos de agua sagrada de Stratholme y 150 monedas de oro a Grimand Elmore en el Distrito de los Enanos de Ventormenta." },
        [7643] = { name = "El antiguo espíritu equino", objective = "Consigue comida para caballos para alimentar a un espíritu equino. Por lo visto, Merideth Carlson, en Costasur, tiene esa comida.\n\nVe a la mazmorra de La Masacre, en Feralas y mata a Tendris Madeguerra. Al hacerlo, liberarás al antiguo espíritu equino. Dale la comida para caballos y lo aplacarás. Por último, dale la gualdrapa de arcanita para que la bendiga." },
        [7644] = { name = "La gualdrapa de arcanita bendecida", objective = "Devuelve la Blessed Arcanite Barding a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
        [7645] = { name = "Alimento para caballo enriquecido con maná", objective = "Consigue 20 galletas de maná, ingrediente principal del alimento especial para caballos, y llévaselas a Merideth Carlson a las Laderas de Trabalomas, en Costasur. Solo Alba Argenta fabrica esas galletas.\n\nTambién tienes que darle 50 piezas de oro para aplacar su orgullo herido." },
        [7646] = { name = "Arúspice", objective = "Lleva un diamante de Azeroth y un diamante negro prístino a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
        [7647] = { name = "Juzgar y redimir", objective = "Utiliza el augurador en el centro del sótano de El Gran Osario en Scholomance. Al hacerlo, aparecerán los espíritus que tienes que juzgar. Si derrotas a esos espíritus, aparecerá el Caballero de la Muerte Atracoscuro. Acaba con él y reclama el alma perdida del cargo caído.\n\nEntrega el alma redimida del cargo y la gualdrapa encantada bendecida al cargo caído de Atracoscuro." },
        [7648] = { name = "Un trabajo bien hecho", objective = "Lleva la gualdrapa de arcanita a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta para que la inspeccione." },
        [7667] = { name = "Asistencia material", objective = "Si te interesa ayudar a Sagorne Montacresta, llévale 1 diamante de Azeroth y 1 diamante negro prístino al Valle de la Sabiduría, en Orgrimmar." },
        [7668] = { name = "La amenaza de Atracoscuro", objective = "Usa el augurador que se encuentra en el corazón del sótano de El Gran Osario en Scholomance. Al hacerlo se presentarán los espíritus a los que tienes que enfrentarte. La derrota de estos espíritus invoca al Caballero de la Muerte Atracoscuro, derrótalo.\n\nLlévale la cabeza de Atracoscuro a Sagorne Montacresta en el Valle de la Sabiduría, en Orgrimmar." },
        [7703] = { name = "El aunto inacabado de Gordok", objective = "Encuentra el Guante del Poder de Gordok y llévaselo al capitán Kromcrush a La Masacre. \n\nSegún Kromcrush, una \"historia muy, muy vieja\" dice que Tortheldrin, un elfo \"asqueroso\" que se llamaba a sí mismo príncipe, robó el guantelete a uno de los reyes de Gordok." },
        [7761] = { name = "La orden de Puño Negro", objective = "¡Será estúpido ese orco! Al parecer, tienes que encontrar esta señal y ganar la marca de Drakkisath para poder acceder al orbe de orden.\n\nSegún la carta, el general Drakkisath guarda la señal. Quizás deberías investigarlo." },
        [7848] = { name = "Armonización con el Núcleo", objective = "Entra en el Núcleo de Magma de las Profundidades de Roca Negra y recoge un fragmento de núcleo. LLévaselo a Lothos Levantagrietas a la Montaña Roca Negra." },
        [8151] = { name = "El talismán del cazador", objective = "Habla con Ogtinc en Azshara." },
        [8153] = { name = "Cuernos de corcel", objective = "Llévale un par de cuernos de corcel perfectos a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
        [8231] = { name = "Los vándalos marinos", objective = "Llévale 6 escamas de vándalo marino a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
        [8232] = { name = "El draco verde", objective = "Llévale el colmillo de Morphaz a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
        [8233] = { name = "Un pedido sencillo", objective = "Habla con Lord Jorach Ravenholdt en la Mansión Ravenholdt." },
        [8234] = { name = "Bolsa azur sellada", objective = "Recupera la bolsa azur sellada del chamán Fauces de Madera en Azshara. Llévale entonces la bolsa al archimago Xylem, que también se encuentra en Azshara." },
        [8235] = { name = "Los fragmentos codificados", objective = "Llévale 10 fragmentos codificados al archimago Xylem en Azshara." },
        [8236] = { name = "La llave azur", objective = "Devuélvele la llave azur a Lord Jorach Ravenholdt." },
        [8250] = { name = "Pura magia", objective = "Busca a Sanath Lim-yo y obtén permiso para ver al archimago Xylem." },
        [8251] = { name = "El polvo mágico", objective = "Llévale 10 puñados de polvo purpuríneo al archimago Xylem." },
        [8252] = { name = "El coral de las sirenas", objective = "Reúne 6 corales encantados y llévaselos al archimago Xylem." },
        [8253] = { name = "Destruye a Morphaz", objective = "Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem." },
        [8254] = { name = "Ayuda a Cenarion", objective = "Busca a Ogtinc en Azshara." },
        [8255] = { name = "Los corceles Pezuñamusgo", objective = "Consigue 4 glándulas de corcel sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
        [8256] = { name = "El icor de los no-muertos", objective = "Consigue un icor de los no-muertos para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
        [8257] = { name = "La sangre de Morphaz", objective = "Mata a Morphaz en el hundido Templo de Atal'Hakkar y lleva su sangre a Greta Pezuñamusgo en Frondavil. Encontrarás la entrada al templo hundido en el Pantano de las Penas." },
        [8410] = { name = "Maestría elemental", objective = "Recoge una muestra de aire, fuego, tierra y agua para Bath'rah el Cazavientos." },
        [8412] = { name = "Tótem espiritual", objective = "Lleva lo necesario para el tótem del espíritu a Bath'rah el Cazavientos." },
        [8413] = { name = "Vudú", objective = "Lleva las plumas vudú a Bath'rah el Cazavientos." },
        [8414] = { name = "Expulsión de los demonios", objective = "Recoge 20 Piedras de la Plaga de esbirros y entrégaselas al Alto Sacerdote Thel'danis en las Tierras de la Peste del Oeste." },
        [8415] = { name = "Alto del Orvallo", objective = "Habla con el comandante Ashlam Puñovalor en el Alto del Orvallo." },
        [8416] = { name = "Piedras inertes de la Plaga", objective = "Lleva la Piedra inerte de la Plaga al comandante Ashlam Puñovalor en el Alto del Orvallo." },
        [8417] = { name = "Un espíritu afligido", objective = "Habla con el Héroe Caído de la Horda en la entrada de Las Tierras Devastadas." },
        [8418] = { name = "La forja de la piedra del poderío", objective = "Lleva las plumas vudú a Ashlam Puñovalor." },
        [8419] = { name = "Pedido de un diablillo", objective = "Lleva una pieza de tela de inferi a Diblis en Frondavil." },
        [8420] = { name = "Caliente y picante", objective = "Lleva un retal de tela de inferi a Diblis a Frondavil." },
        [8421] = { name = "La mercancía equivocada", objective = "Lleva 10 maderas putrefactas y 4 esencias de veneno a Diblis a Frondavil." },
        [8422] = { name = "Plumas de trol", objective = "Reúne un total de 6 plumas vudú en el Templo Sumergido." },
        [8423] = { name = "Parentesco guerrero", objective = "Mata a 7 jabinfernos de Las Tierras Devastadas y vuelve junto al Héroe Caído de la Horda." },
        [8424] = { name = "La guerra contra los Sombra Jurada", objective = "Acaba con los Sombra Jurada en las Tierras Devastadas y regresa junto al Héroe Caído de la Horda." },
        [8425] = { name = "Plumas Vudú", objective = "Llévale las plumas vudú de los trols del Templo Sumergido al Héroe Caído de la Horda." },
        [8945] = { name = "La súplica de un muerto", objective = "Ve a Stratholme y rescata a Ysida Harmon del Barón Osahendido." },
        [8948] = { name = "Un viejo amigo de Anthion", objective = "Lleva el estandarte de la Provocación incompleto a Falrin Tallarbol que está en la biblioteca de La Masacre." },
        [8949] = { name = "La vendetta de Falrin", objective = "Reúne 25 Ogre Warbeads de los ogros de La Masacre o de la Cumbre de Roca Negra y vuelve a El Athenaeum de La Masacre a hablar con Falrin Tallarbol." },
        [8950] = { name = "El encantamiento del provocador", objective = "Lleva a Falrin Tallarbol a La Masacre, lo siguiente: 1 Jeering Spectre's Essence, 4 Dark Runes y 8 grandes fragmentos brillantes." },
        [9015] = { name = "El reto", objective = "Dirígete al Círculo de la Ley en las Profundidades de Roca Negra y coloca el estandarte de la Provocación en el centro cuando el Alto justiciero Pedrasiniestra pronuncie tu veredicto. Mata a Theldren y a sus gladiadores y regresa junto a Anthion Harmon en las Tierras de la Peste del Este con la primera pieza del amuleto de Lord Valthalak." },
        [9051] = { name = "Prueba de toxicidad", objective = "Clávale la púa de devilsaurio a un devilsaurio. Ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro cuando hayas completado tu tarea." },
        [9052] = { name = "Veneno de pétalo de sangre", objective = "Reúne 8 champiñones de sangre y 8 aguijones Gorishi, y ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro." },
        [9053] = { name = "Un ingrediente mejor", objective = "Consigue una vid pútrida de las que custodia el guardián en las profundidades del Templo Sumergido y después ve a ver de nuevo a Torwa Abrecaminos." },
        [9063] = { name = "Torwa Abrecaminos", objective = "Habla con Torwa Abrecaminos en el Cráter de Un'Goro." },
        [78261] = { name = "El Cuerno de Xelthos", objective = "Encuentra el Cuerno de Xelthos dentro del Castillo de Colmillo Oscuro. Después llévalo al escondite secreto de C cerca de la Aldea Piroleña. Debes hacerlo en solitario." },
        [78307] = { name = "El Cuerno de Xelthos", objective = "Registro" },
        [78676] = { name = "El ojo de Bhossca", objective = "Encuentra el Ojo de Bhossca dentro del Monasterio Escarlata. Después llévalo al escondite secreto de C cerca de la Aldea Piroleña. Debes hacerlo en solitario." },
        [79007] = { name = "y la nota que has encontrado...", objective = "Los restos chamuscados de la nota son tu única guía." },
        [79008] = { name = "y la nota que has encontrado...", objective = "Los restos chamuscados de la nota son tu única guía." },
        [79192] = { name = "Peldaños", objective = "Arrancas la nota del tablón y lees el contenido garabateado." },
        [79366] = { name = "Acudid a mi llamada", objective = "Utiliza los tótems retorcidos para poner fin al ritual de los jabaespines." },
        [79974] = { name = "Un trabajo sucio", objective = "Le quitas el polvo a una bolsa de mensajero medio enterrada y descubres un papiro entre los suministros." },
        [79975] = { name = "El puño del águila", objective = "El vapor de agua humedece el aire y la vista es increíble." },
        [79976] = { name = "Este debe de ser el lugar", objective = "Quienquiera que estuviese aquí acaba de irse." },
        [79980] = { name = "Revolver", objective = "Descubre lo que te aguarda." },
        [92401] = { name = "Una petición aterradora", objective = "Investiga la desaparición de Edward Tejecorazón en las Ruinas de Lordaeron." },
        [92415] = { name = "Recuerda el amor que te tengo", objective = "Lleva la carta manchada de sangre a la supervisora de huérfanos Ruiseñor en la Ciudad de Ventormenta." },
        [92421] = { name = "Justicia de la Luz", objective = "Consigue 25 extremidades intactas en las Ruinas de Lordaeron y llévaselas a Morbin Penívea en Entrañas." },
        [92422] = { name = "La cólera de Rath'mael", objective = "Mata a Rath'mael en las Ruinas de Lordaeron por encargo del guardia de la Muerte Kristof, que espera en Rémol." },
        [92432] = { name = "Una petición alarmante", objective = "Informa a la imagen de la archimaga Modera a las afueras de la Ciudad de Dalaran." },
        [92434] = { name = "Sangre en las calles", objective = "Busca una forma de entrar en Dalaran a lo largo del Lago Lordamere." },
        [92456] = { name = "Una muestra verde", objective = "Recolecta una flor imbuida de vileza en la Ciudad de Dalaran para Shylamiir, que está en la Ciudad de Ventormenta." },
        [92457] = { name = "Arcana famélica", objective = "Derrota a 8 remanentes buscadores, 8 remanentes saturados y 8 ecos de maná en la Ciudad de Dalaran, e informa a la archimaga Modera a las afueras." },
        [92458] = { name = "El corazón de la perturbación", objective = "Consigue la mota Arcana para la imagen de la archimaga Modera a las afueras de la Ciudad de Dalaran." },
        [92489] = { name = "Poder sobrecogedor", objective = "Acaba con el elemental de maná en la Ciudad de Dalaran y vuelve con el sumo hechicero Andromath en la Ciudad de Ventormenta." },
        [92742] = { name = "Probar los pozos", objective = "Usa el equipo de muestras de agua de pozo para conseguir muestras de los pozos de la Finca de Jansen y la Granja de Molsen." },
        [92744] = { name = "Branquias de múrloc", objective = "Alba Lunajusta quiere que consigas 7 branquias de múrloc de Playa Larga por la cosa de los Páramos de Poniente." },
        [92745] = { name = "El estado de las minas", objective = "Acaba con 4 cavadores kóbolds en la Mina de Jango y con 6 mineros Zarparrío en la Mina de la Costa del Oro." },
        [92747] = { name = "Espionaje en Arroyo de la Luna", objective = "Consigue 8 suministros industriales sospechosos en Arroyo de la Luna." },
        [92748] = { name = "Consultoría explosiva", objective = "Viaja al Distrito de los Enanos de Ventormenta y busca a algún ingeniero que pueda ayudarte." },
        [92749] = { name = "Un plan explosivo", objective = "Consigue 10 unidades de dinamita férrea mediante fabricación, comercio o en la casa de subastas y luego vuelve con Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta." },
        [92750] = { name = "Detonación a distancia", objective = "Habla con alguien del servicio secreto de Ventormenta para conseguir un detonador a distancia." },
        [92751] = { name = "Detonación a distancia", objective = "Llévale el equipo de detonador a distancia a Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta." },
        [92752] = { name = "Consultoría explosiva", objective = "Vuelve con Alba Lunajusta en los Páramos de Poniente." },
        [92753] = { name = "Destrucción en las Minas de la Muerte", objective = "Encuentra la forja oculta en las Minas de la Muerte y coloca los explosivos extradestructivos cerca. Luego, reúnete con Alba Lunajusta en la salida de las minas." },
        [92819] = { name = "Destrucción en las Minas de la Muerte", objective = "Utiliza el detonador." },
        [94907] = { name = "Un pequeño favor", objective = "Invoca un Siervo Crepuscular de un conducto en el Sudario Crepuscular y atrápalo con la piedra de alma de Salámbar." },
        [94968] = { name = "El ojo de Mugg", objective = "Infíltrate en el Bastión Krol'dok y lleva a Krom'rosh una prueba de la muerte de su líder." },
        [94972] = { name = "El escrito del Crepúsculo", objective = "Recupera el Escrito del Crepúsculo en el Bastión Krol'dok." },
        [94975] = { name = "Una prueba de venganza", objective = "Consigue 15 orejas de cultores del Martillo Crepuscular en el Bastión Krol'dok." },
        [94983] = { name = "Recuerdos Crepusculares", objective = "Consigue 8 broches de cultor del Martillo Crepuscular en el Bastión Krol'dok." },
        [94984] = { name = "El escrito del Crepúsculo", objective = "Mata a Nar'gurk en la Bastión Krol'dok y consigue cualquier información que pueda ser valiosa." },
        [95034] = { name = "La deuda", objective = "Habla con Lumina Vientocantor en El Sepulcro." },
        [95036] = { name = "Una hoja tocada por la luna", objective = "Habla con Trevan Rol en El Sepulcro y llévale los materiales que requiere." },
        [95111] = { name = "Un talento infravalorado", objective = "Habla con Ott y pídele que forje tu hoja." },
        [95125] = { name = "Obra maestra de Ott", objective = "Observa cómo Ott forja tu hoja." },
        [95126] = { name = "La hoja de plata lunar", objective = "Llévale la obra maestra de Ott a Trevan Rol en el Bosque de Argénteos." },
        [95140] = { name = "Viejo Ojofuego", objective = "Usa la hoja de plata lunar para destruir al Viejo Ojofuego en el Bosque de Argénteos." },
        [95189] = { name = "El blasón de Lordaeron", objective = "Devuelve el blasón de Lordaeron a lady Dena Kennedy en la Ciudad de Ventormenta." },
        [95195] = { name = "La insignia ensangrentada", objective = "Consigue 10 insignias ensangrentadas y llévaselas al general Marcus Jonathan en la Ciudad de Ventormenta." },
        [95204] = { name = "El blasón de Lordaeron", objective = "Lleva el blasón de Lordaeron a Oran Contorpiente en Entrañas." },
        [95216] = { name = "La nueva peste", objective = "Consigue la cepa muy tóxica de Colmimarchito en las Ruinas de Lordaeron y llévasela a Theodore Griffs en Entrañas." },
        [95250] = { name = "Criaturas abominables", objective = "Consigue la cabeza del barón en las Ruinas de Lordaeron y llévasela al capitán Truman." },
        [95646] = { name = "Horrores en las Tierras Altas", objective = "Mata a un horror de las Tierras Altas en una excavación y lleva su núcleo a Rethiel el Guardaverde en Los Humedales." },
        [95647] = { name = "Perdido en la espesura", objective = "Encuentra a Ardin Pastal en la excavación." },
        [95663] = { name = "Rumores de los Faucedraco", objective = "Viaja a Los Humedales y reúnete con la agente de los Mortacechadores en las colinas sobre el campamento Faucedraco." },
        [95664] = { name = "Sabiduría ancestral", objective = "Lleva la reliquia titánica al Alto de los Ancestros, en Cima del Trueno, y busca a alguien que pueda contarte más acerca de ella." },
        [95682] = { name = "Abre las Fauces", objective = "Mata a las fuerzas de los Faucedraco en las excavaciones y vuelve con la agente de los Mortacechadores fuera con lo que hayas recuperado." },
        [95697] = { name = "Cambio de paladar", objective = "Entra en la excavación de Los Humedales y consigue carne de raptor de la espesura." },
        [95772] = { name = "En busca de Filosón", objective = "Busca a Daewyn, el hermano de Dorin Filosón, en la Excavación de Whelgar." },
        [95775] = { name = "La Ciudad Sumergida", objective = "Usa el pellejo y el carbón para crear calcos de las tablillas de la Ciudad Sumergida." },
        [95776] = { name = "El único Escamasalada bueno...", objective = "Mata a Var'Taka en la Ciudad Sumergida." },
        [95787] = { name = "Segunda prueba con el agua", objective = "Usa el pellejo y el carbón para crear calcos de las tablillas de la Ciudad Sumergida." },
        [95788] = { name = "La magia de la Ciudad Sumergida", objective = "Recoge 5 fetiches I'lalai de los trols en la Ciudad Sumergida." },
        [95789] = { name = "Videntesal sospechosos", objective = "Recoge 10 artefactos imbuidos de vudú de los piratas Videntesal en la Ciudad Sumergida." },
        [95791] = { name = "El capitán Videntesal", objective = "Asesina a 3 pesquisadores Videntesal y al capitán Alzapavor en la Ciudad Sumergida." },
        [95795] = { name = "Muerte en el pantano", objective = "Vuelve con Dorin Filosón." },
        [95809] = { name = "Tejido en el corazón", objective = "Vuelve con Caitlin Pastal en el Puerto de Menethil." },
        [95810] = { name = "Transporte de reliquia perdida", objective = "Llévale la reliquia titánica al prospector Whelgar, que está en su excavación de Los Humedales." },
        [96135] = { name = "Acudid a mi llamada", objective = "Utiliza los tótems retorcidos para poner fin al ritual de los jabaespines." },
        [96391] = { name = "Mapa subterráneo", objective = "Entrega el mapa Hierro Negro al videnterra Farsen en Dun Morogh." },
        [96393] = { name = "Incursión en la Antigua Forjaz", objective = "Entra en el Salón de los Feudales bajo Antigua Forjaz y hazte con la cabeza de Durgen Martillo Funesto." },
        [96394] = { name = "Los muertos sin descanso", objective = "Mata a 15 apariciones iracundas y 10 almas atormentadas, antes de acabar con el espíritu de Yunquemar." },
        [96395] = { name = "Un agravio antiguo", objective = "Devuelve el espíritu de Faldrim Yunquemar a su descanso eterno y luego vuelve con el auxiliar fantasmal en el Salón de los Feudales." },
        [96403] = { name = "Reliquias importantes", objective = "Recupera 8 reliquias enanas en el Salón de los Feudales." },
        [96771] = { name = "La venganza del Altonato", objective = "Viaja al Bastión Krol'dok y mata a Zalfan Umbraluna." },
        [96774] = { name = "Un antiguo ídolo Gurubashi", objective = "Recupera un antiguo ídolo Gurubashi en la Ciudad Sumergida." },
        [96800] = { name = "Fuera de plazo", objective = "Recupera el libro \"La magia perdida de los maestros de runas\" para el Monasterio Escarlata." },
        [96984] = { name = "El corazón de la perturbación", objective = "Recupera la mota Arcana en la Ciudad de Dalaran para el magus Wordeen Vacuamirada, en Molino Tarren." },
        [96986] = { name = "El Caballero de la Tumba", objective = "Derrota a Atrexis el Caballero de la Tumba en la Ciudad de Dalaran. Después, informa a Melisara en Molino Tarren." },
