        [1014] = { name = "Arugal doit mourir", objective = "Tuer Arugal et apporter sa Tête à Dalar Dawnweaver au Sépulcre." },
        [1048] = { name = "Au monastère écarlate", objective = "Tuer le grand inquisiteur Whitemane, le commandant Mograine de la Croisade, le champion Herod et le maître-chien Loksey, et retourner faire son rapport à Varimathras à Fossoyeuse." },
        [1049] = { name = "Compendium des Déchus", objective = "Trouver le « Compendium des Déchus » au Monastère dans les Clairières de Tirisfal et retourner voir le Sage Truthseeker à Thunder Bluff." },
        [1050] = { name = "Mythologie des Titans", objective = "Reprendre « la Mythologie des Titans » au Monastère et le rapporter au Bibliothécaire Mae Paledust à Forgefer." },
        [1051] = { name = "La vengeance de Vorrel", objective = "Rapporter l'anneau de mariage de Vorrel Sengutz à Monica Sengutz à Moulin-de-Tarren." },
        [1052] = { name = "Sur le chemin écarlate", objective = "Apporter la Lettre de recommandation du Frère Anton à Raleigh le Dévot à Austrivage." },
        [1053] = { name = "Au nom de la Lumière", objective = "Tuer le grand inquisiteur Whitemane, le commandant Mograine de la Croisade, le champion Herod de la Croisade et le maître-chien Loksey, et retourner faire un rapport à Raleigh le Dévot à Austrivage." },
        [1098] = { name = "Des Traqueurs noirs à Ombrecroc", objective = "Trouver les Traqueurs noirs Adamant et Vincent." },
        [1100] = { name = "Journal de Lonebrow", objective = "Lire le Journal de Henrig Lonebrow." },
        [1101] = { name = "La mégère du Kraal", objective = "Apporter le Médaillon de Trancheflanc à Falfindel Waywarder à Thalanaar." },
        [1102] = { name = "Un destin funeste", objective = "Apporter le Cœur de Trancheflanc à Stonespire le Vieil, à Thunder Bluff." },
        [1109] = { name = "Corvée de guano", objective = "Apporter 1 tas de Guano du kraal au Maître Apothicaire Faranell à Fossoyeuse." },
        [1113] = { name = "Des cœurs zélés", objective = "Le maître apothicaire Faranell, à Fossoyeuse, veut 20 Cœurs zélés." },
        [1139] = { name = "La tablette de volonté", objective = "Trouver la Tablette de Volonté et la rapporter au Conseiller Belgrum à Forgefer." },
        [1142] = { name = "Le déclin et la mort", objective = "Trouver et rapporter le Pendentif de Treshala à Treshala Fallowbrook à Darnassus." },
        [1144] = { name = "Willix l’Importateur", objective = "Escorter Willix l'Importateur hors du Kraal de Tranchebauge." },
        [1149] = { name = "L'épreuve de la Foi", objective = "Si vous avez la Foi, sautez des planches qui dominent les Mille pointes." },
        [1150] = { name = "L’épreuve de l’Endurance", objective = "Apporter la Griffe de Grenka au traqueur des plaines Dorn, aux Mille pointes." },
        [1151] = { name = "L'épreuve de la Force", objective = "Apporter des Fragments de Rok'Alim au traqueur des plaines Dorn dans les Mille pointes." },
        [1152] = { name = "L'épreuve de la Connaissance", objective = "Trouver Braug Dimspirit près de l’entrée de la Perce des Serres dans les Serres-Rocheuses." },
        [1154] = { name = "L'épreuve de la Connaissance", objective = "Trouver l’Héritage des Aspects et l’apporter à Braug Dimspirit, à côté de l’entrée de la Perce des Serres, dans les Serres-Rocheuses." },
        [1159] = { name = "L'épreuve de la Connaissance", objective = "Trouver Parqual Fintallas à Fossoyeuse." },
        [1160] = { name = "L'épreuve de la Connaissance", objective = "Trouver « Les commencements de la menace des morts-vivants » et le rapporter à Parqual Fintallas à Fossoyeuse." },
        [1198] = { name = "À la recherche de Thaelrid", objective = "Aller chercher le Garde d'argent Thaelrid dans les Profondeurs de Brassenoire." },
        [1199] = { name = "Le crépuscule descend", objective = "Apporter 10 Pendentifs du Crépuscule au Garde d'argent Manados à Darnassus." },
        [1200] = { name = "L'infamie de Brassenoire", objective = "Apporter la Tête du Seigneur du crépuscule Kelris au Veilleur de l'aube Selgorm, à Darnassus." },
        [1221] = { name = "Racines de Feuillebleue", objective = "Prendre une Caisse percée.\nPrendre un Bâton de commandement de Sniffetarin.\nLire le Manuel d'utilisateur de Sniffetarin.\n\nAu Kraal de Tranchebauge, utiliser la Caisse pour invoquer un Ecureuil Sniffetarin et utiliser le Bâton de commandement pour ordonner à l'Ecureuil de chercher les racines.\n\nRamener 6 Racines de Feuillebleue, le Bâton de commandement de Sniffetarin et la Caisse percée à Mebok Mizzyrix, à Ratchet." },
        [1275] = { name = "Recherches sur la corruption", objective = "Gershala Nightwhisper d'Auberdine veut 8 Souches de cerveau corrompu." },
        [1360] = { name = "Des Trésors à recouvrer", objective = "Récupérer les biens de Krom Stoutarm dans son coffre dans le hall commun nord d'Uldaman et les lui rapporter à Forgefer." },
        [1394] = { name = "Le dernier voyage", objective = "Parler au traqueur des plaines Dorn aux Mille pointes." },
        [1424] = { name = "Le bassin des larmes", objective = "Fel’zerul à Pierrêche veut que vous rassembliez 10 Artefacts atal'ai." },
        [1429] = { name = "L'Exilé atal'ai", objective = "Apporter les Artefacts atal'ai à l'Exilé atal'ai dans les Hinterlands." },
        [1444] = { name = "De retour vers Fel’Zerul", objective = "Retourner voir Fel’Zerul à Pierrêche." },
        [1445] = { name = "Le temple d'Atal'Hakkar", objective = "Rassembler 20 Fétiches d'Hakkar et les apporter à Fel’Zerul à Pierrêche." },
        [1446] = { name = "Jammal'an le Prophète", objective = "L'Exilé atal'ai des Hinterlands veut la Tête de Jammal'an." },
        [1448] = { name = "À la recherche du temple", objective = "Brohann Caskbelly à Hurlevent veut que vous recherchiez le temple d'Atal'Hakkar." },
        [1449] = { name = "Vers les Hinterlands", objective = "Parler au haut-thane Falstad Wildhammer, au Nid-de-l'Aigle des Hinterlands." },
        [1450] = { name = "Le Maître des gryphons Talonaxe", objective = "Parler au Maître des gryphons Talonaxe dans la Volière de Nid-de-l'Aigle" },
        [1451] = { name = "Rhapsody Croquejarret", objective = "Chercher Rhapsody Shindigger dans les Hinterlands." },
        [1452] = { name = "Le Kocktail Kalimdor de Rhapsody", objective = "Rhapsody Shindigger dans les Hinterlands veut que vous lui rameniez 3 Gésiers de roc, 3 Foies de Groddoc et 3 Foies de Ferpoil." },
        [1469] = { name = "L'histoire de Rhapsody", objective = "Apporter le Fragment de tablette atal'ai à Brohann Caskbelly à Hurlevent." },
        [1475] = { name = "Dans le temple d'Atal'Hakkar", objective = "Rassembler 10 Tablettes atal'ai pour Brohann Caskbelly à Hurlevent." },
        [1486] = { name = "Les peaux communes", objective = "Napalk dans les Cavernes des lamentations veut 20 Peaux communes." },
        [1487] = { name = "L'éradication des Déviants", objective = "Ebru, des Cavernes des lamentations, veut que vous tuiez 7 Ravageurs Déviant, 7 Vipères Déviant, 7 Glacials Déviant et 7 Crocs-d'effroi Déviant." },
        [1489] = { name = "Hamuul Totem-runique", objective = "Parler à Hamuul Runetotem." },
        [1490] = { name = "Nara Crin-Sauvage", objective = "Parler à Nara Wildmane." },
        [1491] = { name = "Les potions d'intelligence", objective = "Apporter 6 doses d'Essence de lamentation à Mebok Mizzyrix, à Ratchet." },
        [1651] = { name = "Le Tome de la bravoure", objective = "Défendez Daphne Stilwell contre les attaques des Défias.\n\nAucun de vous deux ne doit mourir, si vous voulez réussir la quête.\n\nQuand vous aurez réussi, reparlez à Daphne Stilwell." },
        [1652] = { name = "Le Tome de la bravoure", objective = "Parler à Duthorian Rall à Hurlevent." },
        [1653] = { name = "Le test de droiture", objective = "Parler à Jordan Stilwell à Forgefer" },
        [1654] = { name = "Le test de droiture", objective = "Utiliser les Notes sur les armes de Jordan, trouver du Bois de chêne de blanchepierre, la Cargaison de Minerai raffiné de Bailor, le Marteau de forge de Jordan et une Gemme de Kor, puis revenir voir Jordan Stilwell à Forgefer." },
        [1699] = { name = "Le défi de Rethban", objective = "Entrer dans les Cavernes de Rethban jusqu'à la première fourche, et revenir voir Barleybrew dans le temps imparti.\n\nVous ne devez pas mourir." },
        [1701] = { name = "Une cotte de mailles en acier trempé", objective = "Réunir les matériaux dont Furen Longbeard a besoin et lui apporter à Hurlevent." },
        [1702] = { name = "Fabricant de bouclier", objective = "Apporter le Tonneau de Scalder à Furen Longbeard." },
        [1740] = { name = "L'Orbe de Soran'ruk", objective = "Trouver 3 Fragments de Soran'ruk et 1 Grand Fragment de Soran'ruk et les rapporter à Doan Karhan dans les Tarides." },
        [1782] = { name = "L'armure de Furen", objective = "Voici votre armure, <nom>. Elle résistera au plus dur des coups ou je ne m'appelle pas Furen Longbeard !\n\nEt je dois vous remercier. J'ai beaucoup appris en travaillant les matériaux que vous m'avez apportés. Je pense que je ferai une autre découverte capitale un de ces jours !\n\nJe vais transmettre ce que j'ai appris aux autres forgerons de l'Alliance.\n\nJe leur dirai que vous m'avez été d'une grande aide, et peut-être qu'ils vous récompenseront." },
        [1806] = { name = "Le test de droiture", objective = "Attendre que Jordan Stilwell finisse de forger votre arme." },
        [1824] = { name = "L'épreuve du Champ des géants", objective = "Apporter 5 Antennes mobiles à Ruga Ragetotem au Camp Taurajo." },
        [1825] = { name = "Parler à Thun'grim", objective = "Parler à Thun'grim Firegaze dans les Tarides." },
        [1838] = { name = "Armure de brutalité", objective = "Apporter à Thun'grim Firegaze 15 Lingots de Fer cendré, 10 Azurites en poudre, 10 Barres de Fer et une Fiole de Phlogiston." },
        [1848] = { name = "Le haubert de brutalité", objective = "Je sais que vous avez enduré beaucoup de privations et versé beaucoup de sang à mon service, <nom>. Voici le fruit de votre dur labeur.\n\nPuissiez-vous bien le porter et revenir ici un jour pour me conter les services qu'il vous aura rendus." },
        [1954] = { name = "L'orbe infernal", objective = "Apporter un Orbe infernal à Tabetha dans le marécage d'Âprefange." },
        [1955] = { name = "L'Exorcisme", objective = "Tuer le démon de l'Orbe puis parler à Tabetha." },
        [1956] = { name = "L'Energie d'Uldaman", objective = "Récupérer une Source d'énergie en obsidienne et la rapporter à Tabetha dans le marécage d'Âprefange." },
        [2040] = { name = "Assaut souterrain", objective = "Récupérer l'Indicateur Gnoam dans les mortemines et le ramener à Shoni la Silencieuse à Hurlevent." },
        [2041] = { name = "Allez voir Shoni", objective = "Aller voir Shoni la Silencieuse à Hurlevent." },
        [2198] = { name = "Le Collier brisé", objective = "Chercher celui qui a fabriqué le Collier brisé pour découvrir sa valeur potentielle." },
        [2199] = { name = "Le Prix de la Connaissance", objective = "Apporter 5 Barres d'Argent à Talvash del Kissel, à Forgefer." },
        [2200] = { name = "Retour à Uldaman", objective = "Chercher des indices sur le Collier de Talvash à Uldaman. Le paladin dont il a parlé est la dernière personne à l'avoir porté." },
        [2201] = { name = "Trouver les Gemmes", objective = "Trouvez le rubis, le saphir et la topaze qui sont éparpillés à travers Uldaman. Une fois que vous les aurez, contactez Talvash del Kissel en utilisant la Fiole de divination qu’il vous a donnée précédemment.\n\nC'est dans le journal, vous savez...\n* Le rubis a été caché dans une zone barricadée des Ombreforge.\n* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance.\n* Le saphir est en possession du chef trogg, Grimlok." },
        [2202] = { name = "Rechercher les composants à Uldaman", objective = "Apporter 12 Champignons magenta à Jarkal Mossmeld à Kargath." },
        [2204] = { name = "Réparer le Collier", objective = "Obtenir une Source d'énergie de la construction la plus puissante que vous pouvez trouver à Uldaman, puis la remettre à Talvash del Kissel à Forgefer." },
        [2240] = { name = "La Chambre secrète", objective = "Lire le journal de Baelog, explorer la Chambre secrète, puis rendre compte au Prospecteur Foudrepique." },
        [2258] = { name = "Les réactifs des Terres ingrates", objective = "Apporter 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d'élémentaire de roche à Jarkal Mossmeld, à Kargath, dans les Terres ingrates." },
        [2278] = { name = "Les Disques de platine", objective = "Parler au Gardien des pierres pour connaître le Savoir qu'il défend. Une fois découvert ce qu'ils peuvent offrir, activer les Disques de Norgannon." },
        [2279] = { name = "Les Disques de platine", objective = "Apporter la version miniature des Disques de Norgannon à la Ligue des Explorateurs à Forgefer." },
        [2280] = { name = "Les Disques de platine", objective = "Apporter la version miniature des Disques de Norgannon à l'un des Sages de Thunder Bluff." },
        [2283] = { name = "Réparer le Collier", objective = "Rechercher dans l'excavation d'Uldaman un Collier de prix et le rapporter à Dran Droffers à Orgrimmar. Ce Collier peut être endommagé." },
        [2284] = { name = "Réparer le Collier, deuxième prise", objective = "Trouver, dans les profondeurs d'Uldaman, des indices sur la localisation des Gemmes." },
        [2318] = { name = "La Traduction du Journal", objective = "Trouver quelqu'un qui puisse traduire le journal du paladin. L'endroit le plus proche est Kargath, dans les Terres ingrates." },
        [2338] = { name = "La Traduction du Journal", objective = "Laisser Jarkal emprunter le Collier en échange de la traduction du Journal." },
        [2339] = { name = "Trouver les Gemmes et la Source d'énergie", objective = "Récupérer, dans Uldaman, les trois gemmes et une source d’énergie pour le collier, puis les rapporter à Jarkal Mossmeld, à Kargath. Jarkal pense que vous pouvez trouver une source d’énergie sur la machine la plus puissante d’Uldaman.\n\nC'est dans le journal, vous savez...\n* Le rubis a été caché dans une zone barricadée des Ombreforge.\n* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance.\n* Le saphir est possession du chef trogg, Grimlok." },
        [2340] = { name = "Livrer les Gemmes", objective = "Apporter Les gemmes et le collier récupérés à Dran Droffers, à Orgrimmar." },
        [2341] = { name = "Réparer le collier, troisième prise", objective = "Rendre visite à Jarkal Mossmeld à Kargath pour constater (ou non) son succès." },
        [2342] = { name = "Des Trésors à recouvrer", objective = "Rapporter à Patrick Garrett, à Fossoyeuse, son Trésor de famille, qui se trouve dans le Coffre de famille dans le Hall commun sud d'Uldaman." },
        [2361] = { name = "Réparer le Collier", objective = "C'est avec joie que je vous donne ce collier, <classe>. Vous m'avez rendu un service inestimable. Portez-le avec fierté et n'hésitez pas à citer fréquemment et à voix haute le nom du fabriquant ! \n\nEt si vous pouviez préciser au passage qu'il n'est pas maudit, ce serait parfait." },
        [2398] = { name = "Les nains perdus", objective = "Trouver Baelog dans Uldaman." },
        [2418] = { name = "Les pierres de puissance", objective = "Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puissance An'Alleum à Rigglefuzz dans les Terres ingrates." },
        [2439] = { name = "Les Disques de platine", objective = "Apporter le Bon de récompense à Dinita Stonemantle à la Chambre forte de Forgefer." },
        [2500] = { name = "Les réactifs des Terres ingrates", objective = "Aller chercher les réactifs dont Ghak Healtouch a besoin dans les Terres ingrates, puis les lui rapporter à Thelsamar." },
        [2768] = { name = "Le bâtonnet divino-matic", objective = "Rapporter le Bâtonnet divino-matic à l'Ingénieur en chef Bilgewhizzle, à Gadgetzan." },
        [2769] = { name = "Les frères Brassbolts", objective = "Parler à Wizzle Brassbolts dans les Salines." },
        [2770] = { objective = "Rapporter les Ecailles électrifiées de Gahz'rilla à Wizzle Brassbolts dans les Salines." },
        [2841] = { name = "Guerre des plates-formes", objective = "Obtenir la Combinaison du coffre de Thermaplugg, prendre les Plans de la plate-forme et les apporter à Nogg à Orgrimmar." },
        [2842] = { name = "L'ingénieur en chef Scooty", objective = "Parler à Scooty à Baie-du-Butin." },
        [2843] = { name = "Gnomer-paaarti !", objective = "Attendre que Scooty calibre le transpondeur des gobelins." },
        [2846] = { name = "La tiare des abysses", objective = "Rapporter la Tiare des abysses à Tabetha au marécage d'Âprefange." },
        [2861] = { name = "La mission de Tabetha", objective = "Parler à Tabetha dans le marécage d'Âprefange." },
        [2864] = { objective = "Parler à Tran'rek à Gadgetzan." },
        [2865] = { name = "Les carapaces de Scarabées", objective = "Rapporter 5 Carapaces de scarabée intactes à Tran'rek à Gadgetzan." },
        [2904] = { name = "Une jolie pagaille", objective = "Escorter Kernobee jusqu’à la sortie de la Fuite du temps, puis faire un rapport à Scooty, à Baie-du-Butin." },
        [2922] = { name = "Sauver le cerveau de Techbot !", objective = "Rapporter la Mémoire principale de Techbot au maître-artisan Overspark à Forgefer." },
        [2924] = { name = "Les cerveaux mécaniques", objective = "Rapporter 12 Cerveaux mécaniques à Klockmort Spannerspan à Forgefer." },
        [2926] = { objective = "Utiliser la Fiole de collecte plombée vide sur les Envahisseurs ou les Pilleurs irradiés pour recueillir des retombées radioactives. Une fois pleine, rapportez-la à Ozzie Togglevolt à Kharanos." },
        [2928] = { name = "Excavateurs gyrodrilmatiques", objective = "Rapporter 24 Entrailles mécaniques de robot à Shoni à Hurlevent." },
        [2929] = { name = "La grande trahison", objective = "Aller à Gnomeregan et tuer le mekgénieur Thermaplugg. Puis retourner voir le Grand Bricoleur Mekkatorque." },
        [2930] = { name = "Sauvetage de données", objective = "Apporter une Carte perforée prismatique au Maître mécanicien Castpipe, à Forgefer." },
        [2933] = { name = "Bouteilles de venin", objective = "Apporter une Bouteille de venin à un apothicaire, au Moulin-de-Tarren." },
        [2934] = { name = "Glande à venin intacte", objective = "Rapporter une Glande à venin intacte à l'Apothicaire Lydon, au Moulin-de-Tarren." },
        [2935] = { name = "Consulter Maître Gadrin", objective = "Parler à Maître Gadrin au Village de Sen'jin." },
        [2936] = { name = "Le dieu-araignée", objective = "Lire la Tablette de Theka pour connaître le véritable nom du dieu-araignée des Witherbark, puis retourner voir Maître Gadrin." },
        [2945] = { name = "Anneau sali", objective = "Trouver un moyen de nettoyer l'Anneau sali." },
        [2947] = { name = "Le retour de l'anneau", objective = "Garder l'anneau ou retrouver la personne qui y a gravé les lettres." },
        [2948] = { name = "Amélioration gnomique", objective = "Apporter l’Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d’argent à Talvash del Kissel, à Forgefer." },
        [2949] = { name = "Le retour de l'anneau", objective = "Garder l'anneau ou retrouver la personne qui y a gravé les lettres." },
        [2950] = { name = "Nogg améliore l'anneau", objective = "Apporter l’Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d’argent à Nogg, à Orgrimmar." },
        [2951] = { name = "Le Décapeur 5200 !", objective = "Insérer un Objet sali dans le Décapeur 5200, sans oublier de jeter trois pièces d'argent dans la fente, pour démarrer la machine." },
        [2962] = { name = "Encore plus de Lueur verte !", objective = "Voyager à Gnomeregan et rapporter de la Matière radioactive à haut potentiel. Attention, la matière radioactive est instable et se désactive rapidement.\n\nAprès le travail, conserver la Flasque plombée lourde, pour Ozzie." },
        [2988] = { name = "Les cages Witherbark", objective = "Inspecter les cages dans les deux villages Witherbark, puis retourner auprès du Maître des gryphons Talonaxe." },
        [2989] = { name = "L'autel de Zul", objective = "Regarder sur le dessus de l'autel de Zul, puis retourner auprès du Maître des gryphons Talonaxe." },
        [2990] = { name = "Thadius Sinissombre", objective = "Apporter la Plume de Bec-tranchant à Thadius Grimshade, dans les Terres foudroyées." },
        [2991] = { name = "Médaillon de Nekrum", objective = "Apporter le Médaillon de Nekrum à Thadius Grimshade, dans les Terres foudroyées." },
        [3042] = { name = "Agent durcissant troll", objective = "Apporter 20 Fioles d'agent durcissant troll à Trenton Lighthammer, dans Gadgetzan." },
        [3341] = { name = "L'anéantissement", objective = "Andrew Brownell veut que vous tuiez Amnennar le Porte-froid et que vous lui rameniez son crâne." },
        [3373] = { name = "L'Essence d'Eranikus", objective = "Placer l'Essence d'Eranikus dans le Réceptacle d'essence situé dans son antre dans le Temple englouti." },
        [3380] = { name = "Le Temple englouti", objective = "Trouver Marvon Rivetseeker à Tanaris." },
        [3444] = { name = "Le Cercle de pierres", objective = "Récupérer le Cercle de pierres à l'Atelier de Marvon Rivetseeker à Ratchet." },
        [3445] = { name = "Le Temple englouti", objective = "Trouver Marvon Rivetseeker à Tanaris." },
        [3446] = { name = "Dans les profondeurs", objective = "Trouver l'Autel d'Hakkar dans le Temple englouti du marais des Chagrins." },
        [3447] = { name = "Le secret du cercle", objective = "Voyager jusqu'au Temple englouti et découvrir le secret du cercle de statues." },
        [3520] = { name = "Esprits de Hurleurs", objective = "Capturer l’Esprit de 3 Hurleurs en Feralas, puis retourner voir Yeh'kinya à Port Gentepression." },
        [3523] = { name = "Le Fléau des Souilles", objective = "Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu’il vous avait donnée." },
        [3525] = { name = "L'extinction de l'idole", objective = "Escorter Belnistrasz jusqu'à l'Idole des hurans dans les Souilles de Tranchebauge.\n\nProtéger Belnistrasz tandis qu'il exécute le rituel pour arrêter l'idole." },
        [3527] = { name = "La prophétie de Mosh'aru", objective = "Apporter les Première et Deuxième tablettes Mosh'Aru à Yeh'kinya, à Tanaris." },
        [3528] = { name = "Le dieu Hakkar", objective = "Apporter l'Oeuf Rempli d'Hakkar à Yeh'kinya dans Tanaris." },
        [3636] = { name = "Apportez la Lumière", objective = "Tuer Amnennar le Porte-froid, aux Souilles de Tranchebauge, pour l’Archevêque Benedictus." },
        [3701] = { name = "Les ruines fumantes de Thaurissan", objective = "Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l’Historienne royale Archesonus." },
        [3702] = { name = "Les ruines fumantes de Thaurissan", objective = "Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan." },
        [3765] = { name = "La dépravation au loin", objective = "Aller voir Gershala Nightwhisper à Auberdine." },
        [3801] = { name = "Héritage Sombrefer", objective = "Parler à Franclorn Forgewright si obtenir une clé de la Cité majeure vous intéresse." },
        [3802] = { name = "Héritage Sombrefer", objective = "Tuer Fineous Darkvire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Forgewright." },
        [3906] = { name = "Discordance des flammes", objective = "Partir pour la carrière dans le mont Rochenoire et tuer le Grand maître Pyron. Retourner voir Thunderheart une fois votre mission accomplie." },
        [3907] = { name = "Discordance des flammes", objective = "Pénétrer dans les Profondeurs de Blackrock et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart." },
        [3981] = { name = "Le commandant Gor'shak", objective = "Trouver le commandant Gor'shak dans les Profondeurs de Blackrock.\n\nLe dessin grossier représentait également des barreaux. Peut-être devriez-vous rechercher un genre de prison." },
        [3982] = { name = "Que se passe-t-il ?", objective = "Défendre Gor'shak." },
        [4001] = { name = "Que se passe-t-il ?", objective = "Parler à Kharan Mighthammer et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Bronzebeard. Apporter ces renseignements à Thrall à Orgrimmar.\n\nGor'shak a dit que Kharan était détenu dans une cellule proche." },
        [4002] = { name = "Les Royaumes de l'est", objective = "Parler à Thrall si vous êtes <prêt/prête> à vous charger de la mission qu'il a prévue." },
        [4003] = { name = "Un sauvetage royal", objective = "Tuer l'Empereur Thaurissan et libérer la princesse Moira Bronzebeard de son sort maléfique." },
        [4004] = { name = "La Princesse sauvée ?", objective = "Retourner voir Thrall !" },
        [4024] = { name = "Un goût de flammes", objective = "Partir pour les Profondeurs de Rochenoire et tuer Bael'Gar.\n\nVous savez seulement que le géant demeure à l'intérieur des Profondeurs de Rochenoire. Se souvenir d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence ardente.\n\nApporter l'Essence ardente recouverte à Cyrus Therepentous." },
        [4061] = { name = "La révolte des machines", objective = "S'aventurer dans les Steppes ardentes et récupérer 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania.\n\nTheodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments." },
        [4062] = { name = "La révolte des machines", objective = "Apporter l'Echantillon de fragment d'élémentaire à Lotwil Veriatus.\n\nTheodora vous a dit qu'il se trouvait au camp à l'est." },
        [4063] = { name = "La révolte des machines", objective = "Trouver et tuer le seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium." },
        [4081] = { name = "TUER A VUE : nains Sombrefer", objective = "Pénétrer dans les Profondeurs de Rochenoire et tuer les vils agresseurs !\n\nLe chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie." },
        [4082] = { name = "TUER A VUE : Officiers de haut rang Sombrefer", objective = "Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs !\n\nLe Chef de guerre Goretooth veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie." },
        [4083] = { name = "Le Calice spectral", objective = "Le Calice spectral flotte dans les airs, descendant et remontant tout doucement… au rythme d'un cœur agonisant." },
        [4121] = { name = "Situation précaire", objective = "Escortez votre prisonnier, Grark Lorkrub, au-delà des Steppes ardentes et du mont Blackrock, jusqu'à la gorge des Vents brûlants.\n\nRappelez-vous que Lexlort a précisé que ses hommes attendraient de l'autre côté pour arrêter Grark.\n\nOn vous demandera également de remettre vos chaînes en thorium à Lexlort." },
        [4122] = { objective = "Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort a mentionné le fait que la dernière fois où on l'a vu, il se trouvait dans une imposante forteresse des Blackrock.\n\nUne fois Grark Lorkrub découvert, l'enchaîner avec les chaînes en thorium, puis le ramener par le mont Blackrock jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté de la gorge et le mettront sous bonne garde." },
        [4123] = { name = "Le Coeur de la montagne", objective = "Apporter le Cœur de la montagne à Maxwort Uberglint dans les Steppes ardentes." },
        [4126] = { name = "Hurley Soufflenoir", objective = "Apporter la Recette perdue de la Thunderbrew à Ragnar Thunderbrew à Kharanos." },
        [4128] = { name = "Ragnar Tonnebière", objective = "Parler à Ragnar Thunderbrew." },
        [4132] = { name = "Opération : Mort à Forgehargne", objective = "Voyagez jusqu'aux Profondeurs de Blackrock et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth." },
        [4133] = { objective = "Parler à la maîtresse des ombres Vivian Lagrave à Kargath." },
        [4134] = { name = "La recette perdue de Thunderbrew", objective = "Apporter la Recette perdue de la Thunderbrew à Vivian Lagrave à Kargath." },
        [4136] = { name = "Ribbly Fermevanne", objective = "Apporter la Tête de Ribbly à Yuka Screwspigot dans les Steppes ardentes." },
        [4141] = { name = "Muigin et Larion", objective = "Récolter 15 Pétales-de-sang et retourner voir Muigin." },
        [4142] = { name = "Visite à Gregan", objective = "Apporter une Pétale-de-sang à Gregan Brewspewer en Feralas." },
        [4143] = { name = "Brouillard maléfique", objective = "Récupérer 5 Echantillons de brume atal'ai puis retourner voir Muigin dans le cratère d'Un'Goro." },
        [4145] = { name = "Larion et Muigin", objective = "Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal." },
        [4146] = { name = "Carburant de baguette", objective = "Remettre la Baguette déchargée et 5 Echantillons de brume atal'ai à Larion au refuge des Marshal." },
        [4147] = { name = "Atelier de Marvon", objective = "Se rendre à l'Atelier de Marvon Rivetseeker à Ratchet." },
        [4182] = { name = "La menace des draconiens", objective = "Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Riverhorn une fois la tâche accomplie." },
        [4183] = { name = "Les véritables maîtres", objective = "Voyager jusqu'au Lakeshire et remettre la Lettre d'Helendis Riverhorn au Magistrat Solomon." },
        [4184] = { name = "Les véritables maîtres", objective = "Voyager vers Stormwind et remettre la Demande d'aide de Solomon au généralissime Bolvar Fordragon.\n\nBolvar demeure dans le Donjon de Stormwind." },
        [4185] = { name = "Les véritables maîtres", objective = "Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor." },
        [4186] = { name = "Les véritables maîtres", objective = "Apporter le Décret de Bolvar au Magistrat Solomon au Lakeshire." },
        [4201] = { name = "Le philtre d'amour", objective = "Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Blackrock." },
        [4223] = { name = "Les véritables maîtres", objective = "Parler au maréchal Maxwell dans les Steppes ardentes." },
        [4224] = { name = "Les véritables maîtres", objective = "Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche.\n\nVous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord." },
        [4241] = { name = "Maréchal Windsor", objective = "Partir pour le mont Blackrock au nord-ouest et pénétrer dans les Profondeurs de Blackrock. Découvrir ce qu'il est advenu du Maréchal Windsor.\n\nVous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison." },
        [4242] = { name = "Espoir abandonné", objective = "Donner les mauvaises nouvelles au maréchal Maxwell." },
        [4262] = { name = "Grand seigneur Pyron", objective = "Tuer le Grand seigneur Pyron et retourner voir Jalinda Sprig.\n\nJalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?" },
        [4263] = { name = "Incendius !", objective = "Trouver le Seigneur Incendius dans les Profondeurs de Blackrock et le détruire !" },
        [4264] = { name = "Une Note chiffonnée", objective = "Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout…" },
        [4282] = { name = "Un espoir en lambeaux", objective = "Rapporter les Renseignements perdus du maréchal Windsor.\n\nLe maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne." },
        [4286] = { name = "Du beau matériel", objective = "Se rendre dans les Profondeurs de Rochenoire et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Rochenoire." },
        [4295] = { name = "La bière de Rocknot", objective = "Oh, de la bière ! Je tuerais pour une bonne bière de Sombrefer, <nom> ! Vite, je deviens sobre ! Je le sais car la sobriété trouble ma vision… et cela vous fait ressembler à celui que j'ai massacré la semaine dernière !" },
        [4322] = { name = "Evasion !", objective = "Aider le maréchal Windsor à récupérer son équipement et à libérer ses amis. Ensuite, retourner voir le maréchal Maxwell." },
        [4324] = { name = "Yuka Fermevanne", objective = "Parler à Yuka Screwspigot dans les Steppes ardentes." },
        [4341] = { name = "Kharan Force-martel", objective = "Aller dans les Profondeurs de Blackrock et trouver Kharan Mighthammer.\n\nLe roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison." },
        [4342] = { name = "Légende de Kharan", objective = "Écouter Kharan Mighthammer raconter son histoire." },
        [4361] = { name = "Le porteur des mauvaises nouvelles", objective = "Retourner à Ironforge et apporter la mauvaise nouvelle au Roi Magni Bronzebeard." },
        [4362] = { name = "Le destin du Royaume", objective = "Retourner dans les Profondeurs de Blackrock et secourir la Princesse Moira Bronzebeard, prisonnière de l'Empereur Dagran Thaurissan." },
        [4363] = { name = "La surprise de la Princesse", objective = "Retourner à Ironforge et parler au roi Magni Bronzebeard." },
        [4701] = { name = "Abattez-la", objective = "Allez au Pic Blackrock et anéantir la menace worg à sa source. Tandis que vous quittiez Helendis, il a crié un nom : Halycon. C'est ce que disent les orcs en parlant des worgs." },
        [4724] = { name = "La maîtresse de meute", objective = "Tuer Halycon, la maîtresse de la meute des worgs Bloodaxe." },
        [4726] = { name = "L'essence de rejeton", objective = "Apporter 8 Essences de Rejeton et le Draco-Incarcinatrix 900 à Tinkee Steamboil à la Corniche des flammes dans les Steppes ardentes." },
        [4729] = { name = "Les animaux exotiques de Kibler", objective = "Aller au pic Rochenoire et trouver de Jeunes worgs Bloodaxe. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler." },
        [4734] = { name = "Un oeuf congelé", objective = "Utiliser le Prototype d'Oeufilloscope sur un oeuf dans la Colonie." },
        [4735] = { name = "La collecte d'oeufs", objective = "Apporter 8 Oeufs de dragon collectés et le Module collectronique à Tinkee Steamboil à la Corniche des flammes dans les Steppes Ardentes." },
        [4742] = { name = "Le sceau de l'ascension", objective = "Trouver les trois gemmes de commandement : la Gemme de Smolderthorn, la Gemme de Pierre-du-pic et la Gemme de Bloodaxe. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan.\n\nLes généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Smolderthorn ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Bloodaxe." },
        [4743] = { name = "Le sceau de l'ascension", objective = "Allez à la tourbière du Ver dans le marécage d'Âprefange. Trouvez l'ancien drake, Brandeguerre, et frappez-le sans merci jusqu'à ce que sa volonté soit brisée.\n\nA cet instant précis, vous devez placer le Sceau d'ascension brut devant l'énorme bête. Vous devez ensuite utiliser rapidement l'Orbe d'énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d'ascension brut !" },
        [4764] = { name = "Le fermoir de Doomrigger", objective = "Apporter le Fermoir de Doomrigger à Mayara Brightwing, dans les Steppes ardentes." },
        [4766] = { name = "Mayara Luisaile", objective = "Parler à Mayara Brightwing, dans les Steppes Ardentes." },
        [4768] = { name = "La tablette de Darkstone", objective = "Apporter la Tablette de Darkstone à l'ombremage Vivian Lagrave à Kargath." },
        [4769] = { name = "Vivian Lagrave et la tablette de Darkstone", objective = "Parler à l'ombremage Vivian Lagrave." },
        [4771] = { name = "Le gambit de l'aube", objective = "Placer le Gambit de l'aube dans la Chambre des visions de Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink." },
        [4787] = { name = "L'oeuf antique", objective = "Apporter l'Oeuf antique à Yeh'kinya à Tanaris." },
        [4788] = { name = "Les dernières tablettes", objective = "Apporter la cinquième et la sixième Tablette Mosh'aru au Prospecteur Ironboot à Tanaris." },
        [4808] = { name = "Felnok Ressordacier", objective = "Donner la Lettre de Tinkee à Felnok Steelspring." },
        [4809] = { name = "Cornes de Noroît", objective = "Apporter 8 Cornes intactes de Noroît à Felnok Steelspring." },
        [4810] = { name = "Retourner voir Tinkee", objective = "Apporter le Paquet de Felnok à Tinkee Steamboil dans les Steppes ardentes." },
        [4862] = { name = "Mauvais", objective = "Aller au pic Rochenoire et ramasser 15 Oeuf d'araignée du pic pour Kibler.\n\nCes oeufs peuvent être trouvés à proximité des araignées." },
        [4866] = { name = "Le lait matriarcal", objective = "Vous trouverez la Matriarche Couveuse au coeur du pic Rochenoire. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois <empoisonné/empoisonnée>, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon." },
        [4867] = { name = "Urok Hurleruine", objective = "Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh." },
        [4903] = { name = "Ordre du chef de guerre", objective = "Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents de Rochenoire. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie." },
        [4907] = { name = "Brikolette Toutevapeur", objective = "Parler à Tinkee Steamboil." },
        [4941] = { name = "Sagesse d'Eitrigg", objective = "Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall.\n\nVous avez déjà vu Eitrigg dans les Appartements de Thrall." },
        [4974] = { name = "Pour la Horde !", objective = "Aller au pic Rochenoire et tuer le Chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar." },
        [4981] = { name = "Agent Bijou", objective = "Aller au pic Rochenoire et découvrir ce qui est arrivé à Bijou." },
        [4982] = { name = "Les effets de Bijou", objective = "Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville." },
        [5001] = { name = "Les effets de Bijou", objective = "Retrouver les Affaires de Bijou et les lui rapporter. Bonne chance !" },
        [5002] = { name = "Message à Maxwell", objective = "Se rendre dans les Steppes ardentes et confier les Renseignements de Bijou au maréchal Maxwell." },
        [5047] = { name = "Finkle Einhorn, à votre service !", objective = "Parler à Malyfous Darkhammer à Long-guet." },
        [5065] = { name = "Les tablettes perdues de Mosh'aru", objective = "Apporter la troisième et la quatrième tablette Mosh'aru au Prospecteur Ironboot à Tanaris." },
        [5081] = { name = "Mission de Maxwell", objective = "Se rendre au Pic Blackrock et tuer le maître de guerre Voone, le généralissime Omokk, et le seigneur Wyrmthalak. Retourner auprès du maréchal Maxwell quand la tâche a été accomplie." },
        [5089] = { name = "Ordres du général Drakkisath", objective = "Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes." },
        [5102] = { name = "La reddition du général Drakkisath", objective = "Rendez-vous au Pic Blackrock et tuez le général Drakkisath, puis retournez voir le maréchal Maxwell." },
        [5122] = { name = "Le médaillon de foi", objective = "Le pouvoir de cette chapelle me donne la force de résister à la corruption qui envahit mon coeur. Si je la quitte, je deviendrai un Chevalier de la mort. Mais il existe un médaillon de la foi qui me donnera la force dont j'ai besoin pour partir.\n\nS'il vous plaît, <nom>, trouvez le médaillon. Il est gardé par Malor le Zélé, un membre fou de la Croisade écarlate qui réside aux tréfonds du Bastion écarlate à l'ouest de Stratholme." },
        [5125] = { name = "L'estimation d'Aurius", objective = "<nom>, je me meurs… mais mon âme est sauve, et pour cela je vous dois plus que les mots peuvent exprimer. Je vous en prie, prenez ceci… et continuez le combat, brave <classe> !" },
        [5127] = { name = "La forge démoniaque", objective = "Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme.\n\nTrouver aussi la Cuirasse couverte de runes inachevée.\n\nRapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver." },
        [5160] = { name = "Le Protectorat de la matrone", objective = "Aller jusqu’au Berceau-de-l'Hiver et trouver Haleh. Lui donner l’Ecaille d'Awbee." },
        [5212] = { name = "La chair ne ment pas", objective = "Récupérer 20 Echantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair." },
        [5213] = { name = "L'agent actif", objective = "Se rendre jusqu’à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink." },
        [5214] = { name = "Le grand Ezra Grimm", objective = "Trouver le magasin de tabac d’Ezra Grimm à Stratholme et récupérer une boîte de Tabac d’Ezra. Retourner auprès de Smokey LaRue quand ce sera fait." },
        [5243] = { name = "Les demeures du Sacré", objective = "Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni." },
        [5244] = { name = "Les ruines de Kel'Theril", objective = "Parler à Jaron Stoneshaper au village de Pluie-d'Etoiles" },
        [5245] = { name = "Les Esprits troublés de Kel'Theril", objective = "Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Skycaller dans les Maleterres de l’est." },
        [5246] = { name = "Fragments du passé", objective = "Trouver les Ecrits sacrés des Bien-nés dans le temple de Zin-Malor à Azshara et les apporter à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l'est." },
        [5247] = { name = "Fragments du passé", objective = "Apporter une Barre de thorium enchanté, 5 Cristaux de restauration et une Fiole d'eau redoutable à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l’est." },
        [5250] = { name = "Pluie-d'Etoiles", objective = "Trouver le village de Pluie-d'Etoiles dans le Berceau-de-l'Hiver et parler à Wynd Nightchaser." },
        [5251] = { name = "L'archiviste", objective = "Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates." },
        [5262] = { name = "La vérité vient du ciel", objective = "Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’est." },
        [5263] = { name = "Au-dessus et au-delà", objective = "S’aventurer dans Stratholme et tuer le baron Rivendare. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff." },
        [5281] = { name = "Âmes tourmentées", objective = "Trouver Egan. Vous savez seulement qu’on l’a vu pour la dernière fois aux alentours de Stratholme." },
        [5282] = { name = "Âmes tourmentées", objective = "Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres !\n\nLibérer 15 Esprits sans repos puis retourner auprès d’Egan." },
        [5341] = { name = "Fortune de la famille Barov", objective = "S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d’Austrivage. Revenir auprès d’Alexi Barov quand la tâche est accomplie." },
        [5343] = { name = "Fortune de la famille Barov", objective = "S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d’Austrivage. Revenir auprès de Weldon Barov quand la tâche est accomplie." },
        [5382] = { name = "Docteur Theolen Krastinov, le boucher", objective = "Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie." },
        [5384] = { name = "Kirtonos le héraut", objective = "Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.\n\nCombattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff." },
        [5461] = { name = "L'humain, Ras Murmegivre", objective = "Voyager jusqu’aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke." },
        [5462] = { name = "Le moribond, Ras Murmegivre", objective = "Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert." },
        [5463] = { name = "Le cadeau de Menethil", objective = "Voyager jusqu’à Stratholme et trouver le cadeau de Menethil. Placer le Souvenir de la mémoire sur le sol impie." },
        [5464] = { name = "Le cadeau de Menethil", objective = "Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l’est." },
        [5465] = { name = "Souvenir lié", objective = "Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié." },
        [5466] = { name = "La Liche, Ras Murmegivre", objective = "Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke." },
        [5515] = { name = "Sac des horreurs de Krastinov", objective = "Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff." },
        [5518] = { name = "La tenue d'ogre gordok", objective = "Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Knot Thimblejack. Il est actuellement enchaîné dans l’aile Gordok de Hache-tripes." },
        [5522] = { objective = "Apporter les Oeufs congelés à Leonid Barthalomew dans les Maleterres de l’est." },
        [5525] = { name = "Libérez Knot !", objective = "C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…\n\nMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?" },
        [5526] = { name = "Fragment de la Gangrevigne", objective = "Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu’après la mort d’Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit." },
        [5527] = { name = "Un reliquaire de pureté", objective = "Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, ramenez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune." },
        [5529] = { name = "Portée contaminée", objective = "Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l’Espoir de Lumière." },
        [5531] = { objective = "Apporter les Oeufs congelés à Betina Bigglezink." },
        [5542] = { name = "Chiens-démons", objective = "Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring, quand la mission sera terminée." },
        [5543] = { name = "Ciel couleur de sang", objective = "Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring." },
        [5544] = { name = "Larve putride", objective = "Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées." },
        [5722] = { name = "À la recherche de la sacoche perdue", objective = "Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Grimtotem et tout élément intéressant." },
        [5723] = { name = "Tester la force de l'ennemi", objective = "Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro à Thunder Bluff." },
        [5724] = { name = "Rapporter la sacoche perdue", objective = "Apporter la Sacoche du Totem sinistre à Rahauro à Thunder Bluff." },
        [5725] = { name = "Le pouvoir de détruire...", objective = "Apporter les livres de Sorts des Ombres et d’Incantations du Néant à Varimathras, à Fossoyeuse." },
        [5726] = { name = "Ennemis cachés", objective = "Apporter un Insigne de lieutenant à Thrall à Orgrimmar." },
        [5727] = { name = "Ennemis cachés", objective = "Apporter l'Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar." },
        [5728] = { name = "Ennemis cachés", objective = "Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar." },
        [5742] = { name = "Rédemption", objective = "Écouter ce que Tirion Fordring a à dire." },
        [5761] = { name = "Tuer la bête", objective = "Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son coeur à Neeru Fireblade à Orgrimmar." },
        [5781] = { name = "Aux mémoires perdues", objective = "Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l’est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission." },
        [5845] = { name = "De l'honneur perdu", objective = "Se rendre à Valnord, dans la région nord-est des Maleterres de l’est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie." },
        [5846] = { name = "L'amour et la famille", objective = "Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau." },
        [5848] = { name = "De l'amour et de la famille", objective = "Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.\n\nRapporter le tableau à Tirion Fordring." },
        [5961] = { name = "Le champion de la reine banshee", objective = "Parler à Nathanos le Flétrisseur, dans les Maleterres de l’est. Il se trouve actuellement à la ferme des Marris." },
        [6022] = { name = "Tuer utile", objective = "Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez sept morceaux de Pourriture vivante en moins de dix minutes. Utilisez le Mortier et le pilon pour réduire la Pourriture vivante en Pourriture coagulée." },
        [6042] = { name = "Les petits soucis de la non-vie", objective = "Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait." },
        [6133] = { name = "L'ordre du seigneur forestier", objective = "Aller vers la frontière nord des Maleterres de l’est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien.\n\nTuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons." },
        [6135] = { name = "Crépuscaile, oh comme je te hais !", objective = "Trouver Crépuscaile et la tuer. Récupérer une Touffe de fourrure de Crépuscaile sur son cadavre, puis l’apporter à Nathanos le Flétrisseur.\n\nIl paraît que Crépuscaile hante les terres qui se trouvent au nord de la ferme des Marris." },
        [6136] = { name = "Le corpulent", objective = "Trouver Creusechair, dans les terres au nord des Maleterres de l’est, et le tuer. Retourner voir Nathanos le Flétrisseur quand la mission sera terminée." },
        [6141] = { name = "Frère Anton", objective = "Adressez-vous au frère Anton, en Désolace." },
        [6163] = { objective = "Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos." },
        [6402] = { name = "Le rendez-vous à Stormwind", objective = "Aller à la Cité de Stormwind et se rendre aux portes de la ville. Parlez à l'écuyer Rowe, afin qu'il informe le maréchal Windsor de votre arrivée." },
        [6403] = { name = "La grande mascarade", objective = "Suivre Reginald Windsor dans Stormwind. Le protéger contre toute menace !" },
        [6501] = { name = "L'Œil de dragon", objective = "Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c’est qu’elle existe." },
        [6502] = { name = "Amulette drakefeu", objective = "Récupérer le Sang du Champion des dragons noirs sur le général Drakkisath. Il se trouve dans sa salle du trône, derrière les Halls d'Ascension, sur le Pic Blackrock." },
        [6521] = { name = "Une alliance impie", objective = "Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Fossoyeuse." },
        [6522] = { name = "Une alliance impie", objective = "Apporter le Petit parchemin à Varimathras, à Fossoyeuse." },
        [6561] = { name = "L'infamie de Brassenoire", objective = "Apporter la tête du Seigneur du crépuscule Kelris à Bashana Runetotem, à Thunder Bluff." },
        [6562] = { name = "Problèmes dans les profondeurs", objective = "Parler à Je'neu Sancrea, à Ashenvale." },
        [6563] = { name = "L'Essence d'Aku'Mai", objective = "Apporter 20 Saphirs d'Aku'Mai à Je'neu Sancrea, à Ashenvale." },
        [6564] = { name = "Allégeance aux Dieux très anciens", objective = "Apporter la Note humide à Je'neu Sancrea, à Ashenvale." },
        [6565] = { name = "Allégeance aux Dieux très anciens", objective = "Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Ashenvale." },
        [6566] = { name = "Ce que le vent apporte", objective = "Écouter Thrall." },
        [6567] = { name = "Le Champion de la Horde", objective = "Chercher Rexxar. Le Chef de guerre vous a dit où il était. Chercher sur les chemins de Désolace, entre les Serres-Rocheuses et Feralas." },
        [6568] = { name = "Le testament de Rexxar", objective = "Apporter le Testament de Rexxar à Myranda la Mégère, dans les Maleterres de l’ouest." },
        [6569] = { name = "Illusions d'Occulus", objective = "Aller au Pic Blackrock et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère, quand la tâche sera terminée." },
        [6570] = { name = "Brandeguerre", objective = "Aller à la tourbière du Ver, dans le marécage d'Âprefange, et chercher la tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre." },
        [6582] = { name = "L'épreuve des crânes, Clairvoyant", objective = "Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre.\n\nClairvoyant se trouve au Berceau-de-l'Hiver." },
        [6583] = { name = "L'épreuve des crânes, Somnus", objective = "Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre." },
        [6584] = { name = "L'épreuve des crânes, Chronalis", objective = "Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre." },
        [6585] = { name = "L'épreuve des crânes, Axtroz", objective = "Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre." },
        [6601] = { objective = "Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire." },
        [6602] = { name = "Le sang du champion des dragons noirs", objective = "Aller au Pic Blackrock, et tuer le général Drakkisath. Récupérer son sang et retourner voir Rexxar." },
        [6626] = { name = "L'hôte du mal", objective = "Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Moonsinger, à l’entrée des Souilles de Tranchebauge." },
        [6627] = { name = "L'épreuve de la Connaissance", objective = "Réussir à répondre à la question de Braug Dimspirit, puis lui reparler. Il se trouve dans les Serres-Rocheuses." },
        [6628] = { name = "L'épreuve de la Connaissance", objective = "Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Fossoyeuse." },
        [6921] = { name = "Parmi les ruines", objective = "Apporter le Noyau de la brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale." },
        [6922] = { objective = "Apporter le Globe d'eau étrange à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale." },
        [6981] = { name = "L'Eclat luminescent", objective = "Allez à Ratchet pour trouver quelqu'un qui puisse vous en dire plus sur l'Eclat luminescent.\n\nPuis livrez l'Eclat, selon les instructions." },
        [7028] = { name = "Forces maléfiques retorses", objective = "Collecter 25 Ciselures de Cristaux Théradriques pour Saule, en Désolace." },
        [7029] = { name = "La corruption de Vylelangue", objective = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon.\n\nEn faire usage sur les Vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.\n\nSoigner 8 plantes en tuant les Engeances de Noxxious, puis retourner voir Vark Battlescar, à Proie-de-l'Ombre." },
        [7041] = { name = "La corruption de Vylelangue", objective = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon.\n\nEn faire usage sur les vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.\n\nSoigner 8 plantes en tuant les Engeances, puis retourner voir Taliendra, à la Combe de Nijel." },
        [7044] = { name = "Légendes de Maraudon", objective = "Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras.\n\nTrouvez un moyen de parler à Celebras." },
        [7046] = { name = "Le sceptre de Celebras", objective = "Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras.\n\nParlez-lui après la réussite du rituel." },
        [7064] = { name = "Corruption de la terre et de la graine", objective = "Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace." },
        [7065] = { name = "Corruption de la terre et de la Graine", objective = "Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace." },
        [7066] = { name = "Graine de vie", objective = "Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de vie." },
        [7067] = { name = "Les instructions du paria", objective = "Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace." },
        [7068] = { name = "Fragments d'Ombréclat", objective = "Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar." },
        [7070] = { name = "Fragments d'Ombréclat", objective = "Collecter 10 Fragments d'Ombréclats, et les porter à l'archimage Tervosh, dans le marécage d'Âprefange." },
        [7201] = { name = "Le dernier élément", objective = "Partir pour les Profondeurs de Blackrock et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires." },
        [7441] = { name = "Pusillin et l'Ancien Azj'Tordin", objective = "Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin.\n\nSi vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Feralas." },
        [7461] = { name = "Folie intérieure", objective = "Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera.\n\nEntrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum.\n\nLorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour." },
        [7462] = { name = "Le trésor des Shen'dralar", objective = "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !" },
        [7463] = { name = "Rafraîchissement arcanique", objective = "Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l’élémentaire de l’eau. Retournez voir le Gardien du savoir Lydros à l’Athenaeum avec l’Essence d’Hydrogénos." },
        [7481] = { name = "Légendes elfiques", objective = "Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les au Sage Korolusk du Camp Mojache." },
        [7482] = { name = "Légendes elfiques", objective = "Fouillez Hache-tripes à la recherche de Kariel Winthalus. Lorsque vous aurez des informations, donnez-les à l’Erudite Runethorn, à Feathermoon." },
        [7483] = { name = "Libram de Rapidité", objective = "Apportez un Libram de rapidité, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 2 doses de Sang des héros au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de rapidité." },
        [7484] = { name = "Libram de focalisation", objective = "Apportez un Libram de focalisation, 1 Diamant noir en parfait état, 4 Grands éclats brillants et 2 Peaux des ombres au Gardien du savoir Lydros à Hache-tripes pour recevoir un arcanum de focalisation." },
        [7485] = { name = "Libram de Protection", objective = "Apportez un Libram de protection, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 1 Couture d'abomination effilochée au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de protection." },
        [7488] = { name = "Le filet de Lethtendris", objective = "Ramenez le Filet de Lethtendris à Latronicus Moonspear au bastion de Feathermoon en Feralas." },
        [7489] = { name = "Le filet de Lethtendris", objective = "Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas." },
        [7492] = { name = "Le camp Mojache", objective = "Parlez à Talo Thornhoof au Camp Mojache, en Feralas." },
        [7494] = { name = "Le bastion de Feathermoon", objective = "Parlez à Latronicus Moonspear au bastion de Feathermoon en Feralas." },
        [7498] = { name = "Garona : une étude en discrétion et en trahison", objective = "Rendez ce livre à ses légitimes propriétaires." },
        [7499] = { name = "Le codex de défense", objective = "Rendez ce livre à ses légitimes propriétaires." },
        [7500] = { name = "Les recettes de l’arcaniste", objective = "Rendez ce livre à ses légitimes propriétaires." },
        [7501] = { name = "La lumière et comment l'altérer", objective = "Rendez ce livre à ses légitimes propriétaires." },
        [7502] = { name = "Contrôler les ombres", objective = "Rendez ce livre à ses légitimes propriétaires." },
        [7503] = { name = "La plus grande race de chasseurs", objective = "Rendez ce livre à ses légitimes propriétaires." },
        [7504] = { name = "Sainte Bolognaise : Ce que la lumière ne vous dit pas", objective = "Rendez ce livre à ses légitimes propriétaires." },
        [7505] = { name = "Le Horion de givre et vous", objective = "Rendez ce livre à ses légitimes propriétaires." },
        [7506] = { name = "Le Rêve d'Emeraude…", objective = "Rendez ce livre à ses légitimes propriétaires." },
        [7507] = { name = "Le guide de Dagharn", objective = "Rendez “Le guide de Dagharn du tueur de dragons“ à l’Athenaeum." },
        [7563] = { name = "Rage de sang", objective = "Apporter 30 bouteilles de Sang de bêtes enragées à Mor'zul Bloodbringer dans les Steppes ardentes." },
        [7564] = { name = "Gorzeeki Wildeyes", objective = "Apporter la Caisse de sang à Gorzeeki Wildeyes dans les Steppes ardentes." },
        [7604] = { name = "Un contrat contraignant", objective = "Apportez le Contrat de la Confrérie du Thorium à Lokhtos Darkbargainer, si vous voulez recevoir les plans du marteau de sulfuron." },
        [7623] = { name = "Le seigneur Banehollow", objective = "Achetez des Potions des ténèbres à Gorzeeki dans les Steppes ardentes.\n\nServez-vous en pour vous rendre à Jaedenar, et parlez au seigneur Banehollow." },
        [7624] = { name = "Ulathek le traître", objective = "Affrontez Ulathek, puis apportez le Coeur du traître au seigneur Banehollow à Jaedenar." },
        [7625] = { name = "Poussière d'étoile xorothienne", objective = "Acheter de la Poussière d’étoiles xorothienne à Ur’dan. L’apporter à Gorzeeki dans les Steppes ardentes." },
        [7626] = { name = "La Cloche de Dethmoora", objective = "Apportez 10 Elixirs de Puissance de l'ombre à Gorzeeki Wildeyes dans les Steppes ardentes." },
        [7627] = { name = "La Roue de la Marche noire", objective = "Apportez 6 Grands éclats brilliants et 25 charges de Minerai de sombre fer à Gorzeeki dans les Steppes ardentes." },
        [7628] = { name = "La Chandelle de l'apocalypse", objective = "Apportez 35 Ecailles de dragon noir à Gozeeki WIldeyes dans les Steppes ardentes." },
        [7629] = { name = "Livraison de diablotin", objective = "Apporter le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, retournez voir Gorzeeki Wildeyes." },
        [7630] = { name = "L'arcanite", objective = "Apporter 3 Barres d’arcanite à Gorzeeki dans les Steppes ardentes." },
        [7631] = { name = "Le destrier de l'effroi de Xoroth", objective = "Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit." },
        [7637] = { name = "L'accent sur le sacrifice", objective = "Rendez-vous à Ironforge et procurez-vous l’Encensoir d’exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d’or." },
        [7639] = { name = "Des preuves de jugement", objective = "Ramener l’Encensoir d’exorcisme au seigneur Grayson Shadowbreaker, dans le Quartier de cathédrale de Stormwind." },
        [7640] = { name = "Exorciser Val-Terreur", objective = "Servez-vous de l’Encensoir d’exorcisme pour chasser les esprits qui tourmentent Val-Terreur. Lorsque vous aurez tué 25 Esprits de Val-Terreur, retournez voir le seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind." },
        [7641] = { name = "L'œuvre de Grimand Elmore", objective = "Parlez à Grimand Elmore dans le Quartier des nains de Stormwind." },
        [7642] = { name = "Une ribambelle d'objets", objective = "Apporter 40 Etoffes runiques, 6 Barres d’arcanite, 10 Larmes d’Arthas, 5 Fioles d’eau sacrée de Stratholme, et 150 pièces d’or à Grimand Elmore, au Quartier des nains de Stormwind." },
        [7643] = { name = "L'ancien esprit équin", objective = "Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Southshore, sache en fabriquer.\n\nEnsuite, rendez-vous au donjon de Hache-tripes en Feralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse." },
        [7644] = { name = "Le caparaçon en arcanite béni", objective = "Retourner dans le quartier de la cathédrale de Stormwind avec le Caparaçon d’arcanite béni pour voir le seigneur Grayson Shadowbreaker." },
        [7645] = { name = "Fourrage enrichi en manne", objective = "Récupérer 20 Biscuits enrichis en manne, l’ingrédient vital qui permet de préparer du Fourrage enrichi en manne, pour le compte de Merideth Carlson de Southore dans les contreforts d’Hillsbrad. L’Aube d’argent est la seule à fabriquer ces biscuits.\n\nVous devrez également lui donner 50 pièces d’or pour apaiser sa susceptibilité." },
        [7646] = { name = "Le Clairvoyant", objective = "Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind." },
        [7647] = { name = "Jugement et rédemption", objective = "Utilisez le Clairvoyant au coeur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu’ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l’âme du destrier déchu.\n\nEnsuite, donnez l’Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre." },
        [7648] = { name = "Le chef d'œuvre de Grimand", objective = "Présentez le Caparaçon d’arcanite au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind, pour inspection." },
        [7667] = { name = "Assistance matérielle", objective = "Si vous voulez aider Sagorne Crestrider de la vallée de la Sagesse d'Orgrimmar, apportez-lui un Diamant d’Azeroth et un Diamant noir en parfait état." },
        [7668] = { name = "La menace de Ravassombre", objective = "Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le.\n\nRamenez la Tête de Ravassombre à Sagorne Crestrider de la vallée de la Sagesse, à Orgrimmar." },
        [7703] = { name = "Affaires inachevées chez les Gordok", objective = "Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes.\n\nSelon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok." },
        [7761] = { name = "Les ordres de Blackhand", objective = "Cet orc est stupide. Il semble que vous deviez trouver un moyen d’obtenir la Marque de Drakkisath pour accéder à l’Orbe de commandement.\n\nD’après la lettre, la Marque est gardée par le général Drakkisath. Vous devriez peut-être enquêter." },
        [7848] = { name = "Harmonisation avec le Cœur du Magma", objective = "Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Blackrock et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Riftwalker au mont Blackrock." },
        [8151] = { name = "Le charme du chasseur", objective = "Parlez à Ogtinc en Azshara." },
        [8153] = { name = "La ramure de coursier", objective = "Rapporter deux Ramures de coursier parfaites à Ogtinc en Azshara. Ogtinc vit au sommet des collines au nord-est des ruines d’Eldarath." },
        [8231] = { name = "Vandales des flots", objective = "Apporter 6 Ecailles de vandale des flots à Ogtinc en Azshara.  Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath." },
        [8232] = { name = "Le drake vert", objective = "Apporter la Dent de Morphaz à Ogtinc en Azshara.  Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath." },
        [8233] = { name = "Une requête toute simple", objective = "Parler au seigneur Jorach Ravenholdt, au manoir de Ravenholdt." },
        [8234] = { name = "Sac azur scellé", objective = "Récupérer le Sac azur scellé auprès du chaman Grumegueule en Azshara.  Puis apportez le sac à l'archimage Xylem, également en Azshara." },
        [8235] = { name = "Les fragments codés", objective = "Apporter 10 Fragments codés à l'archimage Xylem à Azshara." },
        [8236] = { name = "La clé d’azur", objective = "Rendre la Clé d'azur au seigneur Jorach Ravenholdt." },
        [8250] = { name = "L'art du mage", objective = "Trouver Sanath Lim-yo et obtenir d'être mené à l'archimage Xylem." },
        [8251] = { name = "La poussière magique", objective = "Procurer 10 doses de Poussière lumineuse à l’archimage Xylem." },
        [8252] = { name = "Le corail des sirènes", objective = "Récupérer 6 Coraux enchantés et les apporter à l’archimage Xylem." },
        [8253] = { name = "Détruire Morphaz", objective = "Récupérer le Fragment d’arcane sur Morphaz et le rendre à l’archimage Xylem." },
        [8254] = { name = "Aider le Cercle", objective = "Chercher Ogtinc en Azshara." },
        [8255] = { name = "Courser les coursiers", objective = "Récupérer 4 Glandes de coursier en bonne santé et les apporter à Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d’Eldarath." },
        [8256] = { name = "L'ichor de non-mort", objective = "Récupérer une dose d’Ichor de non-mort pour le compte d’Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d’Eldarath." },
        [8257] = { name = "Le sang de Morphaz", objective = "Tuez Morphaz dans le temple englouti d’Atal'Hakkar, et ramenez son sang à Greta Mosshoof à Gangrebois. L’entrée du temple englouti se trouve dans le marais des Chagrins." },
        [8410] = { name = "La maîtrise des éléments", objective = "Rassembler un échantillon d'air, de feu, de terre et d'eau pour Bath'rah la Vigie des Vents." },
        [8412] = { name = "Le totem des esprits", objective = "Apportez les différents morceaux du Totem des esprits à Bath’rah la Vigie des Vents." },
        [8413] = { name = "Vaudou !", objective = "Apporter les Plumes vaudou à Bath'rah la Vigie des vents." },
        [8414] = { name = "La dissipation du mal", objective = "Récupérez 20 Pierres du Fléau des serviteurs et apportez-les au grand prêtre Thel'danis dans les Maleterres de l'ouest." },
        [8415] = { name = "La pointe du Noroît", objective = "Parler au commandant Ashlam Valorfist à la pointe du Noroît." },
        [8416] = { name = "Pierres du Fléau inertes", objective = "Apporter la Pierre du Fléau inerte au commandant Ashlam Valorfist à la pointe du Noroît." },
        [8417] = { name = "Un esprit troublé", objective = "Parler au Héros déchu de la Horde à l'entrée des Terres foudroyées." },
        [8418] = { name = "Forger la pierre de pouvoir", objective = "Apporter les plumes vaudou à Ashlam Valorfist." },
        [8419] = { name = "La demande d'un diablotin", objective = "Apportez un morceau de Gangrétoffe à Démonet à Gangrebois." },
        [8420] = { name = "Chaud et piquant", objective = "Apportez un morceau de gangrétoffe à Démonet à Gangrebois." },
        [8421] = { name = "L'anti-étoffe des héros", objective = "Apporter 10 morceaux de Bois pourri et 4 Essences de Vénéneuse à Démonet, en Gangrebois." },
        [8422] = { name = "Les trolls d'un même plumage…", objective = "Apporter 6 Plumes vaudou des trolls du Temple englouti." },
        [8423] = { name = "Fraternité entre guerriers", objective = "Tuer 7 Sangliers infernaux dans les Terres foudroyées et revenir voir le Héros déchu de la Horde." },
        [8424] = { name = "La guerre contre les liges d'ombre", objective = "Tuez les Liges d'ombre dans les Terres foudroyées et revenez voir le Héros déchu de la Horde." },
        [8425] = { name = "Plumes vaudou", objective = "Apportez les Plumes vaudou des trolls du Temple englouti au Héros déchu de la Horde." },
        [8945] = { name = "La supplique du mort", objective = "Entrez à Stratholme et sauvez Ysida Harmon du baron Rivendare." },
        [8948] = { name = "Le vieil ami d'Anthion", objective = "Apportez la Bannière de défi incomplète à Farlin Treeshaper, dans la bibliothèque de Hache-tripes." },
        [8949] = { name = "La vendetta de Falrin", objective = "Collecter 25 Perles de guerre ogres à l’intérieur de Hache-tripes ou du Pic Blackrock, puis revenir voir Falrin Treeshaper, à l'intérieur de l'Athenaeum à Hache-tripes." },
        [8950] = { name = "L'enchantement du provocateur", objective = "Apportez les choses suivantes à Falrin Treeshaper dans Hache-tripes : 1 Essence de spectre railleur, 4 Runes ténébreuses et 8 Grands éclats brillants." },
        [9015] = { name = "Le défi", objective = "Rendez-vous dans le Cercle de la loi, dans les profondeurs de Blackrock, et placez la Bannière de provocation en son centre lorsque vous serez <condamné/condamnée> par le Juge supérieur Grimstone. Tuez Theldren et ses gladiateurs, puis retournez voir Anthion Harmon dans les Maleterres de l’est avec le premier morceau de l’amulette du seigneur Valthalak." },
        [9051] = { name = "Test de toxicité", objective = "Piquez un Diablosaure avec l'Aiguillon de diablosaure. Retournez voir Torwa Pathfinder au Cratère d'Un'goro lorsque vous aurez accompli cette tâche." },
        [9052] = { name = "Le poison de Pétale-de-sang", objective = "Récupérez 8 Chapeaux de sang et 8 Dards de Gorishi, puis retournez voir Torwa Pathfinder au cratère d'Un'goro." },
        [9053] = { name = "Un meilleur ingrédient", objective = "Récupérez une Liane putride sur le Gardien au fond du Temple englouti et revenez voir Torwa Pathfinder." },
        [9063] = { name = "Torwa le Guide", objective = "Parler à Torwa Pathfinder au cratère d'Un'goro." },
        [78261] = { name = "La Corne de Xelthos", objective = "Trouvez la Corne de Xelthos dans le donjon d’Ombrecroc. Puis rapportez-la au point de livraison de C, près du village de Bois-du-Bûcher. Vous devez accomplir cette tâche sans l’aide de personne." },
        [78307] = { name = "La Corne de Xelthos", objective = "Journal" },
        [78676] = { name = "L’Œil de Bhossca", objective = "Trouvez l’Œil de Bhossca dans le monastère Écarlate. Puis rapportez-la au point de livraison de C, près du village de Bois-du-Bûcher. Vous devez accomplir cette tâche sans l’aide de personne." },
        [78699] = { name = "L’Œil de Bhossca", objective = "Journal" },
        [79007] = { name = "… et cette note que vous avez trouvée", objective = "Vous n’avez pour vous guider que ce qui reste de la note calcinée." },
        [79008] = { name = "… et cette note que vous avez trouvée", objective = "Vous n’avez pour vous guider que ce qui reste de la note calcinée." },
        [79192] = { name = "Tort-tue", objective = "Vous arrachez la note de la planche et lisez le reste du message." },
        [79358] = { name = "Tempête, terre et feu", objective = "Récupérez 5 totems de feu tordus, 5 totems de terre tordus, 5 totems d’air tordus et 5 totems d’eau tordus pour Veyric Hametonne dans les hautes-terres Arathies." },
        [79360] = { name = "Soutien élémentaire", objective = "Éliminez Charlga Trancheflanc au kraal de Tranchebauge et recueillez des renseignements sur les plans des Hurans." },
        [79361] = { name = "Tempête, terre et feu", objective = "Récupérez 5 totems de feu tordus, 5 totems de terre tordus, 5 totems d’air tordus et 5 totems d’eau tordus pour Prate Œil-des-Nuages dans les Mille pointes." },
        [79364] = { name = "Surveiller les cieux", objective = "Parlez à Prate Œil-des-Nuages aux Mille pointes." },
        [79366] = { name = "Entendez mon appel", objective = "Utilisez les totems tordus pour mettre un terme au rituel des Hurans." },
        [79442] = { name = "Les armes de la tempête", objective = "Remettez l’œil de la tempête à Bath’rah la Vigie des vents, dans les montagnes d’Alterac." },
        [79974] = { name = "Travail humide", objective = "Vous époussetez une besace qui dépasse de la terre et trouvez un parchemin au milieu des provisions." },
        [79975] = { name = "Le poing de l’aigle", objective = "Les embruns saturent l’air, et le panorama est saisissant." },
        [79976] = { name = "Ça doit être ici", objective = "Vous avez raté de peu la personne qui se trouvait ici." },
        [79980] = { name = "Décaniller", objective = "Trouvez ce qui vous attend." },
        [92401] = { name = "Une requête apeurée", objective = "Enquêtez sur la disparition d’Edward Tissecœur dans les ruines de Lordaeron." },
        [92415] = { name = "N’oublie pas que je t’aime", objective = "Apportez la lettre tachée de sang à la directrice de l’orphelinat Rossignol, à Hurlevent." },
        [92421] = { name = "Justice de la Lumière", objective = "Récupérez 25 membres intacts dans les ruines de Lordaeron pour Morbin Plaie-lumineuse, à Fossoyeuse." },
        [92422] = { name = "La colère de Rath’mael", objective = "Tuez Rath’mael, dans les ruines de Lordaeron, pour le nécrogarde Kristof, à Brill." },
        [92432] = { name = "Une requête alarmante", objective = "Allez voir l’image de l’archimage Modera près de la cité de Dalaran." },
        [92434] = { name = "Du sang dans les rues", objective = "Trouvez un moyen d’entrer dans Dalaran sur les rives du lac Lordamere." },
        [92456] = { name = "Un échantillon vert", objective = "Récupérez une floraison gangrimprégnée de la cité de Dalaran pour Shylamiir à Hurlevent." },
        [92457] = { name = "Arcanes affamées", objective = "Éliminez 8 vestiges en chasse, 8 vestiges saturés et 8 échos de mana dans Dalaran pour l’archimage Modera, qui se tient devant la cité." },
        [92458] = { name = "Cœur de la perturbation", objective = "Collectez le granule arcanique pour l’image de l’archimage Modera, près de la cité de Dalaran." },
        [92489] = { name = "Puissance accablante", objective = "Tuez l’élémentaire de mana pour le grand sorcier Andromath à Hurlevent." },
        [92742] = { name = "Tester les puits", objective = "Utilisez le kit d’échantillonnage d’eau de puits pour collecter des échantillons dans les puits de la ferme des Jansen et de la ferme des Molsen." },
        [92744] = { name = "Des branchies de Murloc", objective = "Alba Lunepâle vous demande de récupérer 7 branchies de Murloc de Longrivage sur les côtes de la marche de l’Ouest." },
        [92745] = { name = "Quelles sales mines !", objective = "Tuez 4 terrassiers kobold à la mine Veine-de-Jango et 6 mineurs Rivepatte à la carrière de la côte de l’Or." },
        [92747] = { name = "Espionnage de Ruisselune", objective = "Récupérez 8 fournitures d’ingénierie suspectes à Ruisselune." },
        [92748] = { name = "Consultation explosive", objective = "Rendez-vous au quartier des Nains à Hurlevent et cherchez un ingénieur pour vous aider." },
        [92749] = { name = "Un plan explosif", objective = "Obtenez 10 bâtons de dynamite basique en les fabriquant, en les échangeant ou à l’hôtel des ventes, puis retournez voir Fée Dérailleur dans le quartier des Nains, à Hurlevent." },
        [92750] = { name = "Détonation à distance", objective = "Parlez à une personne du renseignement de Hurlevent pour obtenir un détonateur à distance." },
        [92751] = { name = "Détonation à distance", objective = "Apportez le kit de détonateur à distance à Fée Dérailleur, au quartier des Nains de Hurlevent." },
        [92752] = { name = "Consultation explosive", objective = "Retournez voir Alba Lunepâle à la marche de l’Ouest." },
        [92753] = { name = "Destruction dans les Mortemines", objective = "Trouvez la forge cachée dans les Mortemines et placez les explosifs de destruction ultime à proximité. Rejoignez ensuite Alba Lunepâle à la sortie des Mortemines." },
        [92819] = { name = "Destruction dans les Mortemines", objective = "Utilisez le détonateur." },
        [92914] = { name = "D’étranges pylônes", objective = "Explorez Shen’dralas pour trouver d’autres pylônes semblables à celui que vous avez découvert." },
        [93680] = { name = "Clé de la ville", objective = "Récupérez la clé des égouts de Dalaran pour le magus Wordeen Toisevide à Moulin-de-Tarren." },
        [94877] = { name = "Sauver Clairsoleil", objective = "Terrassez 8 écumeurs du Crépuscule, 8 ténébromanciens du Crépuscule et 8 néophytes du Crépuscule à Clairsoleil, pour Demar Brant." },
        [94879] = { name = "Chutes d’informations", objective = "Récupérez 5 pages du Crépuscule à Clairsoleil pour Ashe Ambrehall, au donjon de Fort-Lointain." },
        [94881] = { name = "De curieux bijoux", objective = "Récupérez 25 charmes du Crépuscule sur les ténébromanciens du Crépuscule et sur les néophytes du Crépuscule à Clairsoleil pour Ashe Ambrehall, au donjon de Fort-Lointain." },
        [94888] = { name = "On n’abandonne personne", objective = "Secourez 5 éclaireurs de Fort-Lointain au Suaire du Crépuscule pour le sergent Faillan." },
        [94889] = { name = "Tracer un chemin", objective = "Éliminez 8 fanatiques du Crépuscule, 8 corrupteurs du crépuscule et 8 champions du Crépuscule au Suaire du Crépuscule pour le sergent Faillan." },
        [94907] = { name = "Un petit service", objective = "Invoquez un esclave du Crépuscule depuis un conduit du Suaire du Crépuscule et capturez-le à l’aide de la pierre d’âme d’Ambrehall." },
        [94968] = { name = "L’œil de Mugg", objective = "Infiltrez-vous dans le bastion Krol’dok et retournez à Krom’rosh avec la preuve de la mort de son chef." },
        [94972] = { name = "Tome du Crépuscule", objective = "Récupérez le tome du Crépuscule au bastion Krol’dok." },
        [94975] = { name = "Un gage de vengeance", objective = "Récupérez 15 oreilles de sectateurs auprès du Marteau du crépuscule dans le bastion Krol’dok." },
        [94983] = { name = "Souvenirs du Crépuscule", objective = "Récupérez 8 bracelets de sectateurs auprès du Marteau du crépuscule dans le bastion Krol’dok." },
        [94984] = { name = "Tome du Crépuscule", objective = "Tuez Nar’gurk au bastion Krol’dok et récupérez toute information de valeur." },
        [95034] = { name = "La dette", objective = "Parlez avec Lumina Chantelevent, au Sépulcre." },
        [95036] = { name = "Une lame caressée par la lune", objective = "Allez voir Trevan Rol, au Sépulcre, et apportez-lui les matériaux nécessaires." },
        [95111] = { name = "Un talent sous-coté", objective = "Parlez à Ott et demandez-lui de vous forger une lame." },
        [95125] = { name = "Le chef-d’œuvre d’Ott", objective = "Regardez Ott forger votre lame." },
        [95126] = { name = "La lame de sélénargent", objective = "Apportez le chef-d’œuvre d’Ott à Trevan Rol, dans la forêt des Pins-Argentés." },
        [95140] = { name = "Le vieil Œil-de-feu", objective = "Utilisez la lame de sélénargent pour tuer le vieil Œil-de-feu, dans la forêt des Pins-Argentés." },
        [95189] = { name = "Écu de Lordaeron", objective = "Rendez l’écu de Lordaeron à dame Dena Kennedy, à Hurlevent." },
        [95195] = { name = "Insigne ensanglanté", objective = "Récupérez 10 insignes ensanglantés et remettez-les au général Marcus Jonathan, à Hurlevent." },
        [95204] = { name = "Écu de Lordaeron", objective = "Rapportez l’écu de Lordaeron à Oran Serpenroule, à Fossoyeuse." },
        [95216] = { name = "La peste nouvelle", objective = "Récupérez la souche hautement toxique auprès de Croc-Flétri dans les ruines de Lordaeron, pour Theodore Griffs, à Fossoyeuse." },
        [95250] = { name = "Abominables créatures", objective = "Récupérez la tête du baron dans les ruines de Lordaeron et rapportez-la au capitaine Truman." },
        [95646] = { name = "Horreurs dans les hautes-terres", objective = "Tuez une horreur des hautes-terres dans les excavations et rapportez son cœur-racine à Rethiel le Gardien vert dans les Paluns." },
        [95647] = { name = "Perdu dans les fourrés", objective = "Trouver Ardin Grassman dans les excavations" },
        [95663] = { name = "Rumeurs sur les Gueules-de-Dragon", objective = "Rendez-vous dans les Paluns et retrouvez l’agente nécrotraqueuse dans les collines qui dominent le campement gueule-de-dragon." },
        [95664] = { name = "Le savoir des anciens", objective = "Apportez la relique des Titans à la cime des Anciens, aux Pitons-du-Tonnerre, et cherchez quelqu’un qui saura vous en apprendre davantage à son sujet." },
        [95682] = { name = "Gueule-de-bois", objective = "Éliminez les forces des Gueules-de-dragon présentes sur le site de fouilles, puis retournez auprès de l’agent des nécrotraqueurs à l’extérieur et remettez-lui tout ce que vous aurez récupéré." },
        [95697] = { name = "Goûts changeants", objective = "Pénétrez dans les excavations des Paluns et rapportez de la viande de raptor des fourrés." },
        [95748] = { name = "Les anciennes légendes des Gurubashi", objective = "Utilisez la peau et le charbon pour créer une reproduction de la tablette de la troisième légende trolle." },
        [95770] = { name = "À la recherche de la cité perdue", objective = "Explorez le récif Infâme et trouvez l’entrée de la grotte." },
        [95772] = { name = "À la recherche de Lame-chantante", objective = "Cherchez Daewyn, le frère de Dorin Lame-chantante, dans les Excavations de Whelgar." },
        [95773] = { name = "Des adversaires sous les flots", objective = "Récupérez 10 tridents d’écaille-de-mer sur des tirailleurs écaille-de-mer." },
        [95775] = { name = "La cité Submergée", objective = "Utilisez la peau et le charbon pour créer des reproductions des tablettes trouvées dans la cité Submergée." },
        [95776] = { name = "Le seul bon Écaille-de-mer…", objective = "Tuez Var’Taka dans la cité Submergée." },
        [95786] = { name = "Une connaissance d’Austrivage", objective = "Trouvez le maître des traditions Dibbs à Austrivage et apportez-lui l’ensemble de rapports de reconnaissance de la côte Sauvage." },
        [95787] = { name = "Cap sur les eaux troubles", objective = "Utilisez la peau et le charbon pour créer des reproductions des tablettes trouvées dans la cité Submergée." },
        [95788] = { name = "Les magies de la cité Submergée", objective = "Récupérez 5 fétiches d’I’lalai sur des Trolls de la cité Submergée." },
