        [1113] = { name = "열정의 증거", objective = "언더시티에 있는 수석 연금술사 파라넬에게 열정의 증거 20개를 가져가야 합니다." },
        [1139] = { name = "잃어버린 결의의 서판", objective = "결의의 서판을 찾아 아이언포지에 있는 조언자 벨그룸에게 가져가야 합니다." },
        [1142] = { name = "꺼져가는 생명의 불씨", objective = "트레샬라의 펜던트를 찾아 다르나서스에 있는 트레샬라 팰로우브룩에게 돌려주어야 합니다." },
        [1144] = { name = "수입업자 윌릭스", objective = "수입업자 윌릭스를 호위해 가시덩굴 우리에서 나가야 합니다." },
        [1149] = { name = "믿음의 시험", objective = "믿음이 있다면 버섯구름 봉우리가 내려다보이는 높은 곳에서 판자 아래로 뛰어내리십시오." },
        [1150] = { name = "인내의 시험", objective = "버섯구름 봉우리에 있는 도른 플레인스토커에게 그렌카의 발톱을 가져가야 합니다." },
        [1151] = { name = "용기의 시험", objective = "버섯구름 봉우리에 있는 도른 플레인스토커에게 로크알림의 파편을 가져가야 합니다." },
        [1152] = { name = "지혜의 시험", objective = "돌발톱 산맥에 있는 돌발톱 토굴길 입구 근처에서 브라우그 딤스피릿을 찾아야 합니다." },
        [1154] = { name = "지혜의 시험", objective = "고대의 유산을 찾아 돌발톱 산맥에 있는 돌발톱 토굴길 입구 근처에서 브라우그 딤스피릿에게 가져가야 합니다." },
        [1159] = { name = "지혜의 시험", objective = "언더시티에서 파쿠알 핀탈라스를 찾아야 합니다." },
        [1160] = { name = "지혜의 시험", objective = "언데드 위협의 기원을 찾아 언더시티에 있는 파쿠알 핀탈라스에게 가져가야 합니다." },
        [1198] = { name = "타엘리드 찾기", objective = "검은심연 나락에서 은빛경비병 타엘리드를 찾아야 합니다." },
        [1199] = { name = "황혼의망치단의 몰락", objective = "다르나서스에 있는 은빛경비병 마나도스에게 황혼의 펜던트 10개를 가져가야 합니다." },
        [1200] = { name = "검은심연의 음모", objective = "황혼의 군주 켈리스를 처치하고 그 증거로 머리카락을 다르나서스에 있는 새벽감시자에게 가져가야 합니다." },
        [1221] = { name = "청엽수 줄기", objective = "구멍 난 상자를 집어야 합니다.\n땅다람쥐 지휘봉도 챙겨야 합니다.\n땅다람쥐 설명서를 찾아서 읽어야 합니다.\n\n가시덩굴 우리에서 구멍 난 상자를 사용해 땅다람쥐를 소환하고 지휘봉을 사용해 땅다람쥐에게 청엽수 줄기를 찾아내도록 해야 합니다.\n\n톱니항에 있는 메보크 미지릭스에게 청엽수 줄기 6개와 사용한 땅다람쥐 지휘봉과 구멍 난 상자를 가져가야 합니다." },
        [1275] = { name = "타락에 대한 연구", objective = "아우버다인에 있는 게르샬라 나이트위스퍼가 변이된 뇌간 8개를 가져다 달라고 부탁했습니다." },
        [1360] = { name = "보물 찾기", objective = "울다만의 북쪽 대전당에 있는 궤짝에서 크롬 스타우트암의 보물을 찾아서 아이언포지에 있는 크롬 스타우트암에게 가져다주어야 합니다." },
        [1394] = { name = "최후의 시험", objective = "버섯구름 봉우리에 있는 도른 플레인스토커와 대화하십시오." },
        [1424] = { name = "눈물의 연못", objective = "스토나드에 있는 펠제룰이 아탈라이 유물 10개를 모아 달라고 부탁했습니다." },
        [1429] = { name = "추방된 아탈라이 트롤", objective = "동부 내륙지에 있는 추방된 아탈라이트롤에게 아탈라이 유물 자루를 가져가야 합니다." },
        [1444] = { name = "펠제룰에게 돌아가기", objective = "스토나드에 있는 펠제룰에게 돌아가야 합니다." },
        [1445] = { name = "아탈학카르 신전", objective = "스토나드에 있는 펠제룰에게 학카르의 우상 20개를 가져가야 합니다." },
        [1446] = { name = "예언자 잠말란", objective = "잠말란을 처치하고 그 증거로 그의 머리카락을 동부 내륙지에 있는 추방된 아탈라이트롤에게 가져가야 합니다." },
        [1448] = { name = "신전을 찾아서", objective = "스톰윈드에 있는 브로한 캐스크벨리가 아탈학카르 신전을 찾아 달라고 부탁했습니다." },
        [1449] = { name = "동부 내륙지로", objective = "동부 내륙지 맹금의 봉우리에 있는 대영주 폴스타트 와일드해머와 대화해야 합니다." },
        [1450] = { name = "그리핀 조련사 탈론액스", objective = "맹금의 봉우리 출격장 안에 있는 그리핀 조련사 탈론액스와 대화해야 합니다." },
        [1451] = { name = "랩소디 신디거", objective = "동부 내륙지에서 랩소디 신디거를 찾아야 합니다." },
        [1452] = { name = "랩소디의 칼림도어 칵테일", objective = "동부 내륙지에 있는 랩소디 신디거가 로크 모래주머니 3개, 그로독 고릴라 간 3개, 무쇠곰 간 3개를 가져다 달라고 부탁했습니다." },
        [1469] = { name = "랩소디의 이야기", objective = "스톰윈드에 있는 브로한 캐스크벨리에게 아탈라이 서판 조각을 가져가야 합니다." },
        [1475] = { name = "아탈학카르 신전으로", objective = "스톰윈드에 있는 브로한 캐스크벨리에게 아탈라이 서판 10개를 가져가야 합니다." },
        [1486] = { name = "돌연변이 통가죽", objective = "통곡의 동굴에 있는 날팍이 돌연변이 통가죽 20개를 가져다 달라고 부탁했습니다." },
        [1487] = { name = "돌연변이 짐승 섬멸", objective = "통곡의 동굴에 있는 에브루가 돌연변이 약탈자랩터 7마리, 돌연변이 독사 7마리, 돌연변이 늪괴물 7마리, 돌연변이 송곳니천둥매 7마리를 처치해 달라고 부탁했습니다." },
        [1489] = { name = "하뮬 룬토템", objective = "하뮬 룬토템과 대화하십시오." },
        [1490] = { name = "나라 와일드메인", objective = "나라 와일드메인과 대화하십시오." },
        [1491] = { name = "영리해지는 음료", objective = "톱니항에 있는 메보크 미지릭스에게 통곡의 정수 6병을 가져가야 합니다." },
        [1651] = { name = "용맹의 고서", objective = "데피아즈단의 공격으로부터 대프니 스틸웰을 보호하십시오.\n\n둘 중 하나라도 죽으면 실패하게 됩니다.\n\n성공한 후에 대프니 스틸웰과 다시 대화해야 합니다." },
        [1652] = { name = "용맹의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화하십시오." },
        [1653] = { name = "정의의 시험", objective = "아이언포지에 있는 조던 스틸웰과 대화해야 합니다." },
        [1654] = { name = "정의의 시험", objective = "조던의 쪽지를 참고해 흰돌참나무 재목, 조던의 제련된 광석 상자, 조던의 대장장이 망치, 그리고 코르석을 찾아 아이언포지에 있는 조던 스틸웰에게 가져가야 합니다." },
        [1699] = { name = "레스밴 도전", objective = "주어진 시간 내에 레스밴 동굴의 첫번째 분기점까지 들어갔다가 요루스 발리브루에게로 되돌아와야 합니다.\n\n죽어서 영혼이 빠져나가서는 안 됩니다." },
        [1701] = { name = "불에 달궈 만든 갑옷", objective = "스톰윈드에 있는 푸렌 롱비어드에게 그가 필요로 하는 재료들을 모아서 가져가야 합니다." },
        [1702] = { name = "방패 상인", objective = "푸렌 롱비어드에게 스칼더 술통을 가져가야 합니다." },
        [1740] = { name = "소랜루크 수정구", objective = "소랜루크 조각 3개와 큰 소랜루크 조각 1개를 찾아 불모의 땅에 있는 도안 카르한에게 가져가야 합니다." },
        [1782] = { name = "푸렌의 갑옷", objective = "여기 자네 갑옷일세. 이 갑옷에 구멍이 난다면 내 이름은 푸렌 롱비어드가 아닐세. 내 장담하지!\n\n그리고 자네한텐 고마운 마음뿐이야. 자네가 가져온 재료로 작업을 하면서 많은 것을 배웠다네. 언젠가 또 큰 발전을 이루게 될 것 같단 말이지!\n\n내가 배운 것을 얼라이언스의 다른 대장장이들에게도 보내도록 하겠네.\n\n자네가 아주 큰 도움이 됐다고 얘기해 주도록 하지. 그러면 혹시 그들이 자네에게 보답을 할지도 모르니까 말이야, 허허!" },
        [1806] = { name = "정의의 시험", objective = "조던 스틸웰이 무기를 다 만들 때까지 기다려야 합니다." },
        [1824] = { name = "거인의 들판에서의 시험", objective = "타우라조 야영지에 있는 루가 레이지토템에게 꿈틀거리는 더듬이 5개를 가져가야 합니다." },
        [1825] = { name = "툰그림과의 대화", objective = "불모의 땅에 있는 툰그림 파이어게이즈와 대화하십시오." },
        [1838] = { name = "투사의 방어구", objective = "툰그림 파이어게이즈에게 연기나는 철제 주괴 15개, 아주라이트 가루 10개, 철 주괴 10개, 연소 약병 1개를 가져가야 합니다." },
        [1848] = { name = "투사 갑옷" },
        [1954] = { name = "지옥의 보주", objective = "먼지진흙 습지대에 있는 타베사에게 지옥의 보주를 가져가야 합니다." },
        [1955] = { name = "악마 퇴치", objective = "보주의 악마를 물리치고 타베사와 대화하십시오." },
        [1956] = { name = "울다만의 마력원천", objective = "흑요석 마력원천을 구해서 먼지진흙 습지대에 있는 타베사에게 가져가야 합니다." },
        [2040] = { name = "지하 공격", objective = "죽음의 폐광에서 노암 톱니구동장치를 찾아 스톰윈드에 있는 쇼니에게 가져가야 합니다." },
        [2041] = { name = "쇼니와의 대화", objective = "스톰윈드에 있는 쇼니와 대화하십시오." },
        [2198] = { name = "부서진 목걸이", objective = "부서진 목걸이의 잠재적 가치를 알아내기 위해 원 제작자를 찾아야 합니다." },
        [2199] = { name = "정보의 대가", objective = "아이언포지에 있는 탈바쉬 델 키젤에게 은괴 5개를 가져가야 합니다." },
        [2200] = { name = "울다만으로 돌아가기", objective = "울다만 안에서 탈바쉬의 목걸이의 행방에 대한 단서를 찾아야 합니다. 탈바쉬가 말했던 성기사가 그 단서를 가진 최후의 인물일 것입니다." },
        [2201] = { name = "보석 찾기", objective = "울다만에 흩어져 있는 루비, 사파이어, 토파즈를 찾아야 합니다. 모두 찾으면 탈바쉬가 준 수정점 유리병을 사용하여 그에게 연락해야 합니다.\n\n일지에 의하면... \n*루비는 어둠괴철로단 드워프들이 있는 지역에 숨겨져 있습니다.\n*토파즈는 얼라이언스 드워프들이 있는 곳 근처에 트로그 지역에 있는 항아리 중 하나에 숨겨져 있습니다.\n\n*사파이어는 트로그 대장인 그림로크가 가지고 있습니다." },
        [2202] = { name = "울다만에서 재료 찾기", objective = "카르가스에 있는 자칼 모스멜드에게 자홍버섯 12개를 가져가야 합니다." },
        [2204] = { name = "목걸이 복원", objective = "울다만에서 가장 강력한 피조물을 찾아 부서진 목걸이의 마력원천을 손에 넣은 다음, 아이언포지에 있는 탈바쉬 델 키젤에게 목걸이와 함께 가져가야 합니다." },
        [2240] = { name = "비밀 석실", objective = "밸로그의 일지를 읽고 비밀 석실을 조사한 후 발굴조사단장 스톰파이크에게 보고해야 합니다." },
        [2258] = { name = "황야의 땅에서 재료 찾기", objective = "황야의 땅에서 자칼 모스멜드에게 대머리수리 모래주머니 5개, 바위산코요테 송곳니 10개, 바위 정령 파편 5개를 가져가야 합니다." },
        [2278] = { name = "백금 원반", objective = "바위감시자와 대화하고 그가 알고 있는 고대의 지식을 배우십시오. 지식을 배운 후에는 노르간논의 원반을 가동하십시오." },
        [2279] = { name = "백금 원반", objective = "아이언포지에 있는 탐험가 연맹에 노르간논의 소형 백금 원반을 가져가야 합니다." },
        [2280] = { name = "백금 원반", objective = "썬더 블러프에 있는 현자 중 하나에게 노르간논의 소형 원반을 가져가야 합니다." },
        [2283] = { name = "목걸이 회수", objective = "울다만 발굴 현장에서 값진 목걸이를 찾아 오그리마에 있는 드란 드로퍼스에게 가져다주어야 합니다. 목걸이는 파손된 것이라도 괜찮습니다." },
        [2284] = { name = "목걸이 회수 - 2차 시도", objective = "울다만 깊은 곳에서 보석의 행방에 대한 단서를 찾아야 합니다." },
        [2318] = { name = "일지 번역", objective = "성기사의 일지를 번역할 수 있는 이를 찾아야 합니다. 그런 자가 있을만한 가장 가까운 곳은 황야의 땅에 있는 카르가스입니다." },
        [2338] = { name = "일지 번역", objective = "자칼에게 목걸이를 빌려주면 그에 대한 보답으로 일지를 번역해 줄 것입니다." },
        [2339] = { name = "보석과 마력원천 찾기", objective = "울다만에서 목걸이에 필요한 보석 3개와 마력원천을 회수한 후 카르가스에 있는 자칼 모스멜드에게 가져다주어야 합니다. 자칼의 말에 의하면 울다만에서 가장 강한 피조물을 처치하면 마력원천을 얻을 수 있다고 합니다.\n\n일지의 내용을 보니 루비는 어둠괴철로단의 방어진에 숨겨져 있습니다.\n\n토파즈는 얼라이언스 드워프 근처에 있는 트로그 구역 중 하나에 있는 항아리에 숨겨져 있습니다.\n\n사파이어는 트로그의 우두머리인 그림로크가 가지고 있습니다.\n\n마력원천은 울다만에서 가장 강한 피조물을 처치하면 얻을 수 있습니다." },
        [2340] = { name = "보석 전달", objective = "오그리마에 있는 드란 드로퍼스에게 회수한 목걸이와 보석을 가져다주어야 합니다." },
        [2341] = { name = "목걸이 회수 - 3차 시도", objective = "카르가스에 있는 자칼 모스멜드를 만나 그의 실험이 성공했는지 알아보십시오." },
        [2342] = { name = "보물 되찾기", objective = "울다만의 남쪽 대전당에 있는 궤짝에서 가레트가의 보물을 찾아 언더시티에 있는 그에게 가져가야 합니다." },
        [2361] = { name = "목걸이 복원", objective = "이 목걸이를 기꺼이 당신에게 주겠소. 당신은 나에게 헤아릴 수 없이 귀중한 일을 해 주었소. 정말 고맙소이다. 자, 자랑스럽게 걸고 다니시오. 그리고 누가 만든 것인지 크게, 그리고 많이 말해 주시오!\n\n실제로 목걸이가 저주받지 않았다는 사실도 곁들여주면 더 고맙겠군." },
        [2398] = { name = "길 잃은 드워프", objective = "울다만에서 밸로그를 찾아야 합니다." },
