        [2439] = { name = "백금 원반", objective = "아이언포지 은행에 있는 디니타 스톤맨틀에게 사례 보증 서류를 가져가야 합니다." },
        [2500] = { name = "황야의 땅에서 재료 찾기", objective = "황야의 땅에서 필요한 재료를 구한 후 텔사마에 있는 가크 힐터치에게 돌아가야 합니다." },
