        [2948] = { name = "노움의 실력 향상", objective = "아이언포지에 있는 탈바쉬 델 키젤에게 은괴 1개, 태마노 1개와 반짝이는 금반지와 30실버를 주어야 합니다." },
        [2949] = { name = "반지의 귀환", objective = "반지를 그냥 가지거나, 반지 안쪽 부분에 새겨진 인장 자국의 주인을 찾아야 합니다." },
