        [2962] = { name = "유일한 치료법", objective = "놈리건으로 가서 고농축 방사성 폐기물을 가져와야 합니다. 이 폐기물은 불안정하여 성분이 금방 변할 수 있으니 주의하십시오.\n\n임무를 완수한 후 빈 대형 가연채집병을 오지에게 돌려줘야 합니다." },
        [2988] = { name = "마른나무껍질부족 우리", objective = "마른나무껍질 마을 두 곳에 있는 우리들을 확인한 후, 그리핀 조련사 탈론액스에게 돌아가십시오." },
