        [3042] = { name = "트롤 경화제", objective = "가젯잔에 있는 트렌튼 라이트해머에게 트롤 경화제 20병을 가져가야 합니다." },
        [3341] = { name = "암네나르 처치", objective = "앤드류 브로넬이 혹한의 암네나르를 처치하고 혹한의 해골을 가져다 달라고 부탁했습니다." },
        [3373] = { name = "에라니쿠스의 정수", objective = "가라앉은 사원의 이 안식처에 있는 정수의 샘에 에라니쿠스의 정수를 놓아야 합니다." },
        [3380] = { name = "가라앉은 사원", objective = "타나리스에서 마본 리벳시커를 찾아야 합니다." },
        [3444] = { name = "돌무리", objective = "톱니항에 있는 마본 리벳시커의 작업장에서 마본의 궤짝에 담긴 아탈라이 돌무리를 회수해야 합니다." },
        [3445] = { name = "가라앉은 사원", objective = "타나리스에서 마본 리벳시커를 찾아야 합니다." },
