        [3447] = { name = "돌무리의 비밀", objective = "가라앉은 사원으로 가서 원 모양으로 서 있는 석상들에 감춰진 비밀을 알아내야 합니다." },
        [3520] = { name = "계곡천둥매의 영혼", objective = "페랄라스에 있는 3마리의 계곡천둥매의 영혼을 모은 후 스팀휘들 항구에 있는 예킨야에게 돌아가야 합니다." },
        [3523] = { name = "가시덩굴 구릉의 스컬지", objective = "그가 당신에게 서약의 돌을 줄 것입니다. 벨리스트라즈의 계획을 돕는 것에 동의하면 다시 그와 대화하여 그에게 서약의 돌을 돌려주십시오." },
        [3525] = { name = "우상 진화", objective = "가시덩굴 구릉에 있는 가시멧돼지의 우상까지 벨리스트라즈를 호위해야 합니다.\n\n우상을 진화하는 의식을 수행하는 동안 벨리스트라즈를 보호해야 합니다." },
        [3527] = { name = "모쉬아루의 예언", objective = "타나리스에 있는 예킨야에게 첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 가져가야 합니다." },
        [3528] = { name = "학카르의 화신", objective = "타나리스에 있는 예킨야에게 충만한 학카르의 알을 가져가야 합니다." },
        [3636] = { name = "빛의 힘", objective = "대주교 베네딕투스가 가시덩굴 구릉에 있는 혹한의 암네나르를 처치해달라고 부탁했습니다." },
        [3701] = { name = "불타는 타우릿산의 폐허", objective = "불타는 평원, 타우릿산의 폐허에 있는 타우릿산 유물에서 정보를 얻어야 합니다. 정보를 발견하면 왕실사학자 아케소누스에게 돌아가야 합니다." },
        [3702] = { name = "불타는 타우릿산의 폐허", objective = "왕실사학자 아케소누스가 들려 주는 타우릿산의 역사를 들어야 합니다." },
        [3765] = { name = "먼 곳에 퍼진 타락", objective = "아우버다인에 있는 게르샬라 나이트위스퍼를 찾아가야 합니다." },
        [3801] = { name = "검은무쇠단 유물", objective = "도시 주요 지역으로 통하는 열쇠를 얻고 싶다면 프랑클론 포지라이트와 대화하십시오." },
        [3802] = { name = "검은무쇠단 유물", objective = "파이너스 다크바이어를 처치하고 거대한 망치, 무쇠지옥을 회수해야 합니다. 무쇠지옥을 타우릿산의 제단으로 가져가서 프랑클론 포지라이트의 석상에 두어야 합니다." },
        [3906] = { name = "화염의 부조화", objective = "검은바위 산에 있는 채석장으로 가서 멸망의 파이론을 처치해야 합니다. 이 임무를 완수한 후 썬더하트에게 돌아가십시오." },
        [3907] = { name = "불의 부조화", objective = "검은바위 나락에 들어가 불의군주 인센디우스를 찾아, 그를 처치한 후 얻게 되는 모든 정보를 썬더하트에게 가져가야 합니다." },
        [3981] = { name = "사령관 고르샤크", objective = "검은바위 나락에서 사령관 고르샤크를 찾아야 합니다.\n\n조잡하게 그려진 오크 그림에 쇠창살이 그려져 있던 것이 생각납니다. 감옥 같은 곳을 찾아봐야 할 것 같습니다." },
        [3982] = { name = "사태 파악", objective = "고르샤크를 보호해야 합니다." },
        [4001] = { name = "사태 파악", objective = "카란 마이트해머와 대화하여 공주 모이라 브론즈비어드의 납치에 대한 정보를 모은 후, 그 정보를 오그리마에 있는 스랄에게 가져가야 합니다.\n\n고르샤크가 카란이 근처 감방에 갇혀 있다고 말했던 것이 기억납니다." },
        [4002] = { name = "동부 왕국", objective = "스랄이 계획한 임무를 맡을 준비가 되었으면 스랄과 다시 한번 대화하십시오." },
        [4003] = { name = "공주 구출", objective = "제왕 다그란 타우릿산을 처치하고 그의 사악한 마법에서 공주 모이라 브론즈비어드를 해방시켜야 합니다." },
        [4004] = { name = "구출된 공주?", objective = "스랄에게 돌아가야 합니다!" },
        [4024] = { name = "화염의 맛", objective = "검은바위 나락으로 가서 밸가르를 처치하십시오.\n\n이 거인이 검은바위 나락 내에 살고 있다는 것만 알고 있으며 밸가르의 시체에 변형된 검은용군단 허물을 사용해 불의 정수를 추출해야만 합니다.\n\n키루스 테레펜터스에게 담겨진 불의 정수를 가져가야 합니다." },
        [4061] = { name = "기계들의 봉기", objective = "불타는 평원으로 가서 제사장 테오도라 뮬바다니아에게 가져갈 부서진 원소 파편 10개를 모아야 합니다.\n\n그 지역의 골렘과 정령들에게서 이 파편을 구할 수 있을 거라고 테오도라가 말했던 것이 기억납니다." },
        [4062] = { name = "기계들의 봉기", objective = "로트윌 베리아투스에게 원소 파편 견본을 가져가야 합니다.\n\n테오도라가 로트윌은 동쪽 야영지에 있다고 얘기했던 것이 기억납니다." },
        [4063] = { name = "기계들의 봉기", objective = "골렘 군주 아젤마크를 찾아 처치하고 그 증거로 그의 머리카락을 로트윌에게 가져가야 합니다. 그리고 아젤마크를 호위하는 재앙의 피조물과 맹위의 전투골렘들에게서 온전한 원소핵 10개도 모아야 합니다." },
        [4081] = { name = "죽음의 본보기: 검은무쇠단 드워프", objective = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오!\n\n장군 고어투스가 성난모루단 보초 15명, 성난모루단 교도관 10명, 성난모루단 보병 5명을 처치해 달라고 부탁했습니다. 임무를 완수하면 장군 고어투스에게 돌아가십시오." },
        [4082] = { name = "죽음의 본보기: 검은무쇠단 고위 관리", objective = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오!\n\n장군 고어투스가 성난모루단 간호병 10명, 성난모루단 병사 10명, 그리고 성난모루단 장교 10명을 처치해 달라고 부탁했습니다. 임무를 완수하면 고어투스에게 돌아가십시오." },
        [4083] = { name = "유령의 성배", objective = "유령의 성배가 마치 죽어가는 심장의 고동에 맞추어 춤을 추듯이 천천히 움직이면서 공중에 떠다닙니다." },
        [4121] = { name = "곤경", objective = "포로인 그랄크 로크럽을 호송해 불타는 평원을 지나고 검은바위 산을 넘어 이글거리는 협곡으로 가야 합니다.\n\n반대편에서 렉스로트의 부하들이 기다리다가 그랄크 로크럽을 인계받도록 하겠다고 렉스로트가 말했던 것이 기억납니다.\n\n또한 토륨 족쇄를 렉스로트에게 전해주어야 합니다." },
        [4122] = { name = "그랄크 로크럽", objective = "불타는 평원으로 가서 그랄크 로크럽을 찾아야 합니다. 렉스로트가 그를 마지막으로 거대한 검은바위 요새에서 보았다고 말했던 것이 기억납니다.\n\n그랄크 로크럽을 찾으면 토륨 족쇄를 사용해 그를 포박한 뒤 다시 검은바위 산을 지나 이글거리는 협곡으로 데려가야 합니다. 렉스로트의 부하들이 반대편에서 기다리고 있다가 그랄크를 인계받을 것입니다." },
        [4123] = { name = "산의 정수", objective = "불타는 평원에 있는 맥스워트 우버글린트에게 산의 정수를 가져가야 합니다." },
        [4126] = { name = "헐레이 블랙브레스", objective = "카라노스에 있는 라그나르 썬더브루에게 잃어버린 썬더브루 제조법을 가져가야 합니다." },
        [4128] = { name = "라그나르 썬더브루", objective = "라그나르 썬더브루와 대화해야 합니다." },
        [4132] = { name = "앵거포지 척살 작전", objective = "검은바위 나락으로 가서 사령관 앵거포지를 처치한 후 장군 고어투스에게 돌아가야 합니다." },
        [4133] = { name = "비비안 라그레이브", objective = "카르가스에 있는 비비안 라그레이브와 대화해야 합니다." },
        [4134] = { name = "잃어버린 썬더브루 제조법", objective = "카르가스에 있는 비비안 라그레이브에게 잃어버린 썬더브루 제조법을 가져가야 합니다." },
        [4136] = { name = "리블리 스크류스피곳", objective = "리블리를 처치하고 그 증거로 그의 머리카락을 불타는 평원에 있는 유카 스크류스피곳에게 가져가야 합니다." },
        [4141] = { name = "무이긴과 라리온", objective = "붉은꽃잎 15개를 모아 무이긴에게 돌아가야 합니다." },
        [4142] = { name = "그레간 방문", objective = "페랄라스에 있는 그레간 브루스퓨에게 붉은꽃잎을 가져가야 합니다." },
        [4143] = { name = "악의 아지랑이", objective = "아탈라이 아지랑이 5개를 모은 후 운고로 분화구에 있는 무이긴에게 돌아가야 합니다." },
        [4145] = { name = "라리온과 무이긴", objective = "마샬의 야영지에 있는 라리온에게 채찍줄기 붉은꽃잎덩굴손 5마리, 덩이줄기 붉은꽃잎덩굴손 5마리, 칼날가시 붉은꽃잎덩굴손 5마리, 질긴뿌리 붉은꽃잎덩굴손 5마리를 사냥해야 합니다." },
        [4146] = { name = "구제장치 연료", objective = "마샬의 야영지에 있는 라리온에게 충전 안된 구제장치와 아탈라이 아지랑이 5개를 가져가야 합니다." },
        [4147] = { name = "마본의 작업장", objective = "톱니항에 있는 마본 리벳시커의 작업장으로 가야 합니다." },
        [4182] = { name = "용혈족의 위협", objective = "검은 새끼용 15마리, 검은용혈족 10마리, 검은고룡족 4마리와 검은 비룡 1마리를 처치한 후, 헬렌디스 리버혼에게 돌아가야 합니다." },
        [4183] = { name = "진정한 지도자", objective = "레이크샤이어로 가서 집정관 솔로몬에게 헬렌디스 리버혼의 편지를 전달해야 합니다." },
        [4184] = { name = "진정한 지도자", objective = "스톰윈드로 가서 대영주 볼바르 폴드라곤에게 볼바르에게 보내는 솔로몬의 탄원서를 전해주어야 합니다.\n\n볼바르는 스톰윈드 왕궁에 있습니다." },
        [4185] = { name = "진정한 지도자", objective = "여군주 카트라나 프레스톨과 얘기를 나눈 후, 대영주 볼바르 폴드라곤과 대화하십시오." },
        [4186] = { name = "진정한 지도자", objective = "레이크샤이어에 있는 집정관 솔로몬에게 볼바르의 명령서를 가져가야 합니다." },
        [4201] = { name = "사랑의 묘약", objective = "검은바위 나락에 있는 여왕 나그마라에게 그롬의 피 4개, 거대한 은 광석 10개, 가득 찬 나그마라의 약병을 가져가야 합니다." },
        [4223] = { name = "진정한 지도자", objective = "불타는 평원에 있는 치안대장 맥스웰과 대화하십시오." },
        [4224] = { name = "진정한 지도자", objective = "털보 존을 만나 치안대장 윈저의 행방에 대해서 알아낸 다음 치안대장 맥스웰에게 돌아가 보고해야 합니다.\n\n치안대장 맥스웰은 북쪽에 있는 동굴에서 털보 존을 찾아보라고 했습니다." },
        [4241] = { name = "치안대장 윈저", objective = "북서쪽에 있는 검은바위 산으로 가서 검은바위 나락으로 들어가십시오. 치안대장 윈저에게 무슨 일이 있었는지 알아내야 합니다.\n\n털보 존은 윈저가 감옥으로 끌려갔다고 했습니다." },
        [4242] = { name = "실망", objective = "치안대장 맥스웰에게 나쁜 소식을 전해줘야 합니다." },
        [4262] = { name = "멸망의 파이론", objective = "멸망의 파이론을 처치한 후 잘린다 스프리그에게 돌아가야 합니다.\n\n잘린다가 말하기를 파이론은 채석장을 지키고 있다고 하니 그곳을 수색해야 할 것 같습니다." },
        [4263] = { name = "인센디우스!", objective = "검은바위 나락에서 불의군주 인센디우스를 찾아 처치해야 합니다." },
        [4264] = { name = "꼬깃꼬깃한 쪽지", objective = "방금 우연히 치안대장 윈저가 보고 싶어할 듯한 물건을 찾은 것 같습니다. 어쩌면 희망이 있을지도 모릅니다." },
        [4282] = { name = "잔존하는 희망", objective = "치안대장 윈저의 잃어버린 단서를 가져 와야 합니다.\n\n치안대장 윈저는 골렘 군주 아젤마크와 사령관 앵거포지가 이 정보를 가지고 있을 것이라 생각합니다." },
        [4286] = { name = "좋은 물건", objective = "검은바위 나락으로 가서 검은무쇠단 벨트주머니 20개를 얻어야 합니다. 이 임무를 완수하면 랄리우스에게 돌아가십시오. 검은바위 나락 안에 사는 검은무쇠단 드워프들이 이 '벨트주머니'라는 물건을 지니고 다닐 것입니다." },
        [4295] = { name = "락노트의 에일 맥주", objective = "아, 에일 맥주! 검은무쇠단 에일 맥주가 마시고 싶어 죽겠군! 어서, 술이 깨려 하고 있다고! 어떻게 아느냐고? 난 술이 깨면 눈 앞이 흐려진단 말이지... 그리고 눈 앞이 흐려지니 당신이 마치 내가 지난주에 처치한 <race>처럼 보이고 있다고!" },
        [4322] = { name = "탈옥!", objective = "치안대장 윈저가 자신의 장비를 되찾고 갇힌 동료들을 풀어 주는 것을 도와야 합니다. 성공하면 치안대장 맥스웰에게 돌아가십시오." },
        [4324] = { name = "유카 스크류스피곳", objective = "불타는 평원에 있는 유카 스크류스피곳과 대화해야 합니다." },
        [4341] = { name = "카란 마이트해머", objective = "검은바위 나락으로 가서 카란 마이트해머를 찾아야 합니다.\n\n국왕은 카란이 그곳에 포로로 잡혀 있을 것이라고 말했습니다. 그곳 감옥을 찾아보는 것이 좋겠습니다." },
        [4342] = { name = "카란의 이야기", objective = "카란 마이트해머가 하는 이야기를 들어야 합니다." },
        [4361] = { name = "나쁜 소식 전달", objective = "아이언포지로 돌아가 국왕 마그니 브론즈비어드에게 이 나쁜 소식을 전해야 합니다." },
        [4362] = { name = "왕국의 운명", objective = "검은바위 나락으로 돌아가 제왕 다그란 타우릿산의 사악한 손아귀에서 공주 모이라 브론즈비어드를 구출해야 합니다." },
        [4363] = { name = "브론즈비어드 공주", objective = "아이언포지로 돌아가서 국왕 마그니 브론즈비어드와 대화해야 합니다." },
        [4701] = { name = "검은늑대 위협의 근원 파괴", objective = "검은바위 첨탑으로 가서 검은늑대 위협의 근원을 파괴해야 합니다. 헬렌디스를 떠날 때 헬렌디스가 오크들이 특정한 검은늑대를 부르는 말인 할리콘이라는 이름을 외치는 것을 들었습니다." },
        [4724] = { name = "검은늑대 무리의 어미", objective = "도끼부대 검은늑대 무리의 어미, 할리콘을 처치해야 합니다." },
        [4726] = { name = "새끼용의 정수", objective = "불타는 평원의 화염 마루에 있는 팅키 스팀보일에게 새끼용의 정수 8개와 새끼용 속박장치 900을 가져가야 합니다." },
        [4729] = { name = "키블러의 진귀한 애완동물", objective = "검은바위 첨탑으로 가서 새끼 도끼부대 검은늑대를 찾아야 합니다. 우리를 사용하여 이 사나운 야수들을 운반하여 키블러에게 사로잡은 새끼 검은늑대를 가져가야 합니다." },
        [4734] = { name = "알껍질 냉동", objective = "알껍질급속냉각기 견본을 둥지에 있는 알에 사용해야 합니다." },
        [4735] = { name = "알 수집", objective = "불타는 평원의 화염 마루에 있는 팅키 스팀보일에게 수집한 용의 알 8개를 가져가야 합니다." },
        [4742] = { name = "승천의 인장", objective = "사령관의 세 가지 보석인 가시불꽃부족 보석, 뾰족바위일족 보석, 도끼부대 보석을 찾아, 가공하지 않은 승천의 인장과 함께 밸란에게 가져가야 합니다.\n\n밸란이 말한 장군들은 가시불꽃부족의 대장군 부네, 뾰족바위일족의 대군주 오모크와 도끼부대의 대군주 웜타라크입니다." },
        [4743] = { name = "승천의 인장", objective = "먼지진흙 습지대에 있는 용의 둥지로 가서 고대 비룡, 엠버스트라이프를 찾아 그의 의지가 꺾일 때까지 무자비하게 공격을 펼쳐야 합니다.\n\n바로 그때 거대한 엠버스트라이프 앞에 벼려지지 않은 승천의 인장을 가져다 놓으십시오. 그리고 약해진 엠버스트라이프에게 재빨리 용력의 보주를 사용해 그의 정신력을 조종해야 합니다. 엠버스트라이프를 조종해 검은용군단의 화염을 벼려지지 않은 승천의 인장에 뿜어야 합니다!" },
        [4764] = { name = "파멸의 기념물", objective = "불타는 평원에 있는 마야라 브라이트윙에게 파멸의 기념물을 가져가야 합니다." },
        [4766] = { name = "마야라 브라이트윙", objective = "불타는 평원에 있는 마야라 브라이트윙과 대화해야 합니다." },
        [4768] = { name = "다크스톤 서판", objective = "카르가스에 있는 어둠마법사 비비안 라그레이브에게 다크스톤 서판을 가져가야 합니다." },
        [4769] = { name = "비비안 라그레이브와 다크스톤 서판", objective = "어둠마법사 비비안 라그레이브와 대화해야 합니다." },
        [4771] = { name = "여명의 계략", objective = "스칼로맨스의 스칼로맨스 강당 문에 여명의 계략을 놓아두고 벡투스를 처치한 후 베티나 비글징크에게 돌아가야 합니다." },
        [4787] = { name = "고대의 알", objective = "고대의 알을 타나리스에 있는 예킨야에게 가져다주어야 합니다." },
        [4788] = { name = "마지막 서판", objective = "다섯 번째와 여섯 번째 모쉬아루 서판을 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다." },
        [4808] = { name = "펠노크 스틸스프링", objective = "팅키의 편지를 펠노크 윈터스프링에게 가져다주어야 합니다." },
        [4809] = { name = "서리바람 키메라의 뿔", objective = "펠노크 윈터스프링에게 온전한 서리바람 키메라의 뿔 8개를 가져가야 합니다." },
        [4810] = { name = "팅키에게 돌아가는 길", objective = "불타는 평원의 팅키 스팀보일에게 펠노크의 소포를 가져가야 합니다." },
        [4862] = { name = "더러운 거미알", objective = "검은바위 첨탑으로 가서 키블러를 위해 첨탑 거미알 15개를 수집해야 합니다.\n\n들리는 소문으로는 그 알들은 거미들이 서식하는 근처에서 찾을 수 있다고 합니다." },
        [4866] = { name = "여왕 거미의 독", objective = "검은바위 첨탑 중심부에서 여왕 불그물거미를 찾을 수 있습니다. 여왕 불그물거미를 공격하거나 접근하여 그 독에 중독되어야 합니다. 독에 걸릴 확률을 높이기 위해서는 거미를 죽여야 할 수도 있습니다. 중독되면 털보 존에게 돌아가서 그가 그 독을 추출하게 해야 합니다." },
        [4867] = { name = "우로크 둠하울", objective = "와로쉬의 두루마리를 읽어야 합니다. 와로쉬에게 그의 부적을 가져가야 합니다." },
        [4903] = { name = "장군의 명령", objective = "대군주 오모크와 대장군 부네, 대군주 웜타라크를 처단해야 합니다. 검은바위의 중요한 문서들을 확보해야 합니다. 임무를 완수하는 대로 카르가스의 장군 고어투스에게로 돌아가야 합니다." },
        [4907] = { name = "팅키 스팀보일", objective = "팅키 스팀보일과 대화해야 합니다." },
        [4941] = { name = "아이트리그의 지혜", objective = "오그리마의 스랄의 요새에 있는 아이트리그와 대화해야 합니다. 아이트리그의 얘기를 듣고 난 후에는 대족장 스랄과 상의해야 합니다." },
        [4974] = { name = "호드를 위하여!", objective = "검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다." },
        [4981] = { name = "요원 비쥬", objective = "검은바위 첨탑으로 가서 비쥬에게 무슨 일이 생겼는지 알아봐야 합니다." },
        [4982] = { name = "비쥬의 물건들", objective = "비쥬의 소지품을 찾아서 그녀에게 돌아가야 합니다. 비쥬가 도시의 바닥에 소지품을 숨겼다고 했습니다." },
        [5001] = { name = "비쥬의 소지품", objective = "비쥬의 소지품을 찾아 그녀에게 돌려줘야 합니다!" },
        [5002] = { name = "멕스웰에게의 전보", objective = "불타는 평원에 있는 치안대장 맥스웰에게 비쥬의 정보를 전해야 합니다." },
        [5047] = { name = "핀클 에인혼, 명을 받듭니다!", objective = "눈망루 마을에 있는 말리퍼스 다크해머와 대화해야 합니다." },
        [5065] = { name = "모쉬아루의 잃어버린 서판", objective = "세 번째와 네 번째 모쉬아루 서판을 찾아 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다." },
        [5081] = { name = "맥스웰의 임무", objective = "검은바위 첨탑으로 가서 대장군 부네와 대군주 오모크, 그리고 요새의 대군주 웜타라크를 처치해야 합니다. 임무를 완수하면 맥스웰 치안 대장에게 돌아가십시오." },
        [5089] = { name = "사령관 드라키사스의 명령서", objective = "불타는 평원에 있는 치안대장 맥스웰에게 사령관 드라키사스의 명령서를 가져가야 합니다." },
        [5102] = { name = "사령관 드라키사스 처치", objective = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치해야 합니다. 임무를 완수하면 치안대장 맥스웰에게 돌아가야 합니다." },
        [5122] = { name = "신념의 메달", objective = "난 이 교회의 힘으로 내 가슴 속의 타락에 저항하고 있소. 내가 이곳을 떠나면 죽음의 기사로 변해 버리게 될거요. 하지만 신념의 메달만 있으면 내가 이곳을 떠날 수 있는 힘을 줄 거요.\n\n부탁이니 그 메달을 가져다주시오. 그 메달은 광신자 말로가 지키고 있는데, 이 미친 녀석은 스트라솔름 서쪽에 있는 붉은십자군 성채에 사는 붉은십자군의 일원이라오." },
        [5125] = { name = "아우리우스의 복수", objective = "난 죽어가지만... 내 영혼은 구제되었소. 당신에게 뭐라 말로 표현할 수 없는 신세를 진 거요. 부디 이걸 받아주시오. 그리고 계속 싸우시오, 용맹한 <class>|1이여;여;!" },
        [5127] = { name = "악마의 룬", objective = "검은바위 첨탑으로 가서 고랄루크 앤빌크랙을 찾아 처치한 후, 핏물이 깃든 창을 그의 심장에 꽂으십시오. 창이 그의 영혼을 흡수하면 영혼이 깃든 창으로 변합니다.\n\n벼려지지 않은 룬문자 흉갑도 찾아야 합니다.\n\n영혼이 깃든 창과 벼려지지 않은 룬문자 흉갑을 여명의 설원에 있는 로락스에게 갖다주십시오." },
        [5160] = { name = "대섭정", objective = "여명의 설원으로 가서 헬레를 찾아 그녀에게 아우비의 비늘을 전해야 합니다." },
        [5212] = { name = "거짓말하지 않는 육체", objective = "스트라솔름에서 20개의 역병걸린 살덩어리 견본을 베티나 비글징크에게 가져다주어야 합니다. 스트라솔름의 어떤 생물에서든 살덩어리 견본을 구할 수 있을 것 같습니다." },
        [5213] = { name = "활성 역병 인자", objective = "스트라솔름으로 가서 지구라트를 조사해야 합니다. 스컬지 자료를 찾아 베티나 비글징크에게 돌아가야 합니다." },
        [5214] = { name = "위대한 프라스 샤비", objective = "스트라솔름에서 샤비의 최고급 담배를 회수하여 스모키 라루에게 가져가야 합니다." },
        [5243] = { name = "성스러운 집", objective = "북쪽에 있는 스트라솔름으로 가서 도시 어딘가에 흩어진 보급품 상자를 찾아 스트라솔름 성수 5병을 가져와야 합니다. 성수를 충분히 모으고 나면 존경받는 리어니드 바돌로매에게 돌아가야 합니다." },
        [5244] = { name = "켈테릴의 폐허", objective = "별똥별 마을에 있는 야론 스톤셰이퍼와 대화하십시오." },
        [5245] = { name = "켈테릴의 고통받는 영혼", objective = "야론의 곡괭이를 사용해 귀족 유물 조각 4개를 찾아 동부 역병지대에 있는 아우로라 스카이콜러에 갖다주어야 합니다." },
        [5246] = { name = "과거의 조각들", objective = "아즈샤라에 있는 진말로의 신전에서 귀족의 성서를 찾아야 합니다. 동부 역병지대의 북부관문 경비탑 근처에 있는 아우로라 스카이콜러에게 가져가십시오." },
        [5247] = { name = "과거의 조각", objective = "마력 깃든 토륨 주괴 1개와 회복의 수정 5개, 그리고 혈투의 웅덩이 물병을 동부 역병지대의 북부관문 경비탑 근처에 있는 아우로라 스카이콜러에게 가져가야 합니다." },
        [5250] = { name = "별똥별 마을", objective = "여명의 설원에서 별똥별 마을을 찾아 윈드 나이트체이서와 대화하십시오." },
        [5251] = { name = "기록관", objective = "스트라솔름으로 가서 붉은십자군의 기록관, 갈포드를 찾아서 그를 처치하고 붉은십자군 기록을 불태워 버려야 합니다." },
        [5262] = { name = "밝혀지는 진실", objective = "동부 역병지대에 있는 공작 니콜라스 즈바른호프에게 발나자르의 혼을 가져가야 합니다." },
        [5263] = { name = "뛰어난 존재", objective = "스트라솔름으로 가서 남작 리븐데어를 처치하고 그의 혼을 공작 니콜라스 즈바른호프에게 가져가야 합니다." },
        [5281] = { name = "잠 못드는 영혼", objective = "스트라솔름 주변에서 목격된다고 알려진 에간을 찾아야 합니다." },
        [5282] = { name = "잠 못드는 영혼", objective = "스트라솔름 시민의 영혼과 원혼들에게 에간의 제령포를 사용해야 합니다. 원혼들이 그들을 가두고 있던 감옥에서 풀려나면 다시 총을 사용하여 그들에게 자유를 선사하십시오!\n\n15명의 잠 못드는 영혼을 자유롭게 하고 에간에게 돌아가야 합니다." },
        [5341] = { name = "바로브 가의 유산", objective = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 재산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 임무를 완수한 후 알렉시 바로브에게 돌아가야 합니다." },
        [5343] = { name = "바로브 가의 유산", objective = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 유산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 이 임무를 완수한 후 웰던 바로브에게 돌아가야 합니다." },
        [5382] = { name = "도살자, 테올렌 크라스티노브", objective = "스칼로맨스 내에서 학자 테올렌 크라스티노브를 찾아 처치한 후 에바 사크호프의 유해와 루시엔 사크호프의 유해를 불태우십시오. 임무를 완수하면 에바 사크호프에게 돌아가야 합니다." },
        [5384] = { name = "사자 키르토노스", objective = "순결한 피를 가지고 스칼로맨스로 돌아가야 합니다. 사자의 창을 찾아 사자의 화롯불에 순결한 피를 올려 놓으면 키르토노스가 영혼을 차지하기 위해 나타납니다.\n\n용맹하게 싸우고 단 한 발짝도 물러서지 마십시오! 키르토노스를 처치한 후 에바 사크호프에게 돌아가야 합니다." },
        [5461] = { name = "라스 프로스트위스퍼", objective = "아라시 고원에 있는 스트롬가드 폐허로 가십시오. 스트롬가드에서 추억의 유품을 찾아야 합니다. 그런 물건을 찾으면 집정관 마르듀크에게 돌아가야 합니다." },
        [5462] = { name = "망자, 라스 프로스트위스퍼", objective = "동부 역병지대에 있는 희망의 빛 예배당으로 가서 존경받는 리어니드 바돌로매를 찾아서 추억의 유품을 보여 주고 알아낸 사실에 대해 모두 얘기해야 합니다." },
        [5463] = { name = "메네실의 선물", objective = "스트라솔름으로 가서 메네실의 선물을 찾아서 그 부정한 땅 위에 추억의 유품을 두어야 합니다." },
        [5464] = { name = "메네실의 선물", objective = "동부 역병지대에 있는 리어니드 바돌로매에게 영혼이 씌인 유품을 가져가야 합니다." },
        [5465] = { name = "영혼이 씌인 유품", objective = "카엘 다로우에 있는 집정관 마르듀크에게 돌아가십시오. 그에게 영혼이 씌인 유품을 보여줘야 합니다." },
        [5466] = { name = "리치, 라스 프로스트위스퍼", objective = "스칼로맨스에서 라스 프로스트위스퍼를 찾아야 합니다. 영혼이 쓰인 유품을 언데드 상태인 라스의 얼굴에 사용하십시오. 그를 산 자로 되돌리는 데 성공하면 그를 쓰러뜨리고 사람이 된 라스 프로스트위스퍼의 머리카락을 가지고 집정관 마르듀크에게 가야 합니다." },
        [5515] = { name = "소름끼치는 크라스티노브의 가방", objective = "스칼로맨스에서 잔다이스 바로브를 찾아 처치해야 합니다. 그녀의 시체에서 소름끼치는 크라스티노브의 가방을 찾은 후 에바 사크호프에게 가져가야 합니다." },
        [5518] = { name = "고르독 오우거 위장복", objective = "룬무늬 두루마리 4개, 튼튼한 가죽 8장, 룬문자 실타래 2개, 그리고 오우거 타닌을 노트 팀블잭에게 가져가야 합니다. 노트 팀블잭은 혈투의 전장에 있는 고르독일족 은신처 구석에 족쇄에 묶여 있습니다." },
        [5522] = { name = "리어니드 바돌로매", objective = "동부 역병지대에 있는 리어니드 바돌로매에게 얼어붙은 알을 가져가야 합니다." },
        [5525] = { name = "노트 구출 대작전", objective = "그건 고르독 족쇄 열쇠라고 하는 물건이지. 이 오우거 얼간이들이 그렇게 부르더군. 이곳 오우거들이라면 누구나 지니고 있을 텐데, 어떤 오우거 녀석들이 지니고 있는지는 모르겠단 말이야. 경비병들이라면 갖고 있을 확률이 더 높겠지...\n\n아니, 내가 지금 뭔 소리 하는 거야. 당신 벌써 그 열쇠 갖고 있지?! 그게 바로 그 열쇠야?!" },
        [5526] = { name = "악령덩굴 조각", objective = "혈투의 전장에서 악령덩굴 조각을 채취하십시오. 칼날바람 알진을 물리쳐야만 얻을 수 있을 것입니다. 정화의 성물함에 단단히 봉인한 후, 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다." },
        [5527] = { name = "정화의 성물함", objective = "실리더스로 가서 마파람 마을 부근 유적지에 있을 정화의 성물함을 찾아내야 합니다. 찾게 되면 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다." },
        [5529] = { name = "역병 걸린 작은 새끼용", objective = "역병 걸린 작은 새끼용 20마리를 처치한 후 희망의 빛 예배당에 있는 베티나 비글징크에게 돌아가야 합니다." },
        [5531] = { name = "베티나 비글징크", objective = "베티나 비글징크에게 얼어붙은 알을 가져가야 합니다." },
        [5542] = { name = "지옥개", objective = "새끼 역병사냥개 20마리, 역병사냥개 5마리와 광포한 역병사냥개 5마리를 처치하십시오. 임무를 완수하면 티리온 폴드링에게 돌아가야 합니다." },
        [5543] = { name = "핏빛 하늘", objective = "역병박쥐 30마리를 처치한 후 티리온 폴드링에게 돌아가야 합니다." },
        [5544] = { name = "청소부구더기", objective = "부근에서 청소부구더기와 걸신들린 청소부구더기를 찾아 처치하고 청소부구더기 고기덩어리 15개를 모은 후 티리온 폴드링에게 돌아가야 합니다." },
        [5722] = { name = "잃어버린 가방 찾기", objective = "성난불길 협곡에서 마우리 그림토템의 시체를 찾아 도움이 될 만한 것들을 찾아야 합니다." },
        [5723] = { name = "성난불길 협곡의 트로그", objective = "오그리마에 있는 성난불길 협곡을 찾아 성난불길 트로그 8마리와 성난불길일족 주술사 8마리를 처치하고 썬더 블러프에 있는 라하우로에게 돌아가야 합니다." },
        [5724] = { name = "잃어버린 가방 돌려주기", objective = "썬더 블러프에 있는 라하우로에게 그림토템 가방을 가져가야 합니다." },
        [5725] = { name = "파괴해야 할 힘", objective = "언더시티에 있는 바리마트라스에게 어둠의 주문서와 황천의 마법서를 가져가야 합니다." },
        [5726] = { name = "내부의 배신자", objective = "오그리마에 있는 스랄에게 부관의 휘장을 가져가야 합니다." },
        [5727] = { name = "내부의 배신자", objective = "부관의 휘장을 네루 파이어블레이드에게 가져간 다음 대화를 해야 합니다. 네루 파이어블레이드가 당신을 불타는칼날단의 일원으로 믿고 있는지 확인한 다음 오그리마에 있는 스랄에게 돌아가야 합니다." },
        [5728] = { name = "내부의 배신자", objective = "바잘란과 기원사 제로쉬를 제거한 다음 오그리마에 있는 스랄에게 돌아가야 합니다." },
        [5742] = { name = "구원", objective = "티리온 폴드링이 하려고 하는 말이 무엇인지 들어야 합니다." },
        [5761] = { name = "야수 처단", objective = "성난불길 협곡으로 가서 욕망의 타라가만을 제거한 다음 그의 심장을 오그리마에 있는 네루 파이어블레이드에게 가져가야 합니다." },
        [5781] = { name = "잃어버린 기억들", objective = "동부 역병지대의 최남쪽에 있는 지하 납골당으로 가서 탤런의 망치를 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다." },
        [5845] = { name = "명예의 상징", objective = "동부 역병지대의 북동쪽에 있는 노스데일로 가서 실추된 명예의 상징을 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다." },
        [5846] = { name = "가족과 사랑", objective = "역병지대의 남쪽 중앙에 있는 카엘 다로우로 가서 초상화가 어디쯤 있는지에 대한 단서를 찾아야 합니다." },
        [5848] = { name = "가족과 사랑", objective = "역병지대의 북쪽, 스트라솔름에 있는 붉은십자군 성채로 가서 쌍둥이 달 그림을 찾으십시오.\n\n그 뒤에 숨겨진 '가족과 사랑'이라는 그림을 찾아 티리온 폴드링에게 가져가야 합니다." },
        [5961] = { name = "밴시 여왕의 용사", objective = "동부 역병지대의 마리스 농장에 살고 있는 나타노스 블라이트콜러와 대화해야 합니다." },
        [6022] = { name = "이유 있는 살육", objective = "동쪽의 코린 삼거리로 가서 마을에 사는 스컬지를 해치워 10분 안에 살아있는 부패물 7개를 모으십시오. 막자 사발을 사용해서 살아있는 부패물을 갈아 응고된 부패물로 만들어야 합니다." },
        [6042] = { name = "성가신 녀석들", objective = "맹독 역병박쥐 20마리와 기괴한 역병박쥐 10마리를 해치운 후 나타노스 블라이트 콜러에게 돌아가야 합니다." },
        [6133] = { name = "순찰대장의 명령", objective = "동부 역병지대의 북쪽 경계로 이동하여 쿠엘탈라스 기록부를 찾아야 합니다. 기록부는 쿠엘리시엔 오두막 어딘가에 있습니다.\n\n순찰자 8명, 길잡이 8명, 수렵꾼 8명을 해치워야 합니다." },
        [6135] = { name = "혐오스런 그늘날개", objective = "마리스 농장 북부의 변두리를 배회하고 있는 그늘날개를 찾아 해치워야 합니다. 시체에서 그늘날개 모피 조각을 찾아 나타노스 브라이트콜러에게 가져가야 합니다." },
        [6136] = { name = "뚱뚱보 괴물", objective = "동부 역병지대 북부 불모지에서 피고름구더기를 찾아 물리친 후 나타노스 블라이트콜러에게 돌아가야 합니다." },
        [6141] = { name = "수사 안톤", objective = "잊혀진 땅에 있는 수사 안톤과 대화해야 합니다." },
        [6163] = { name = "람스타인", objective = "스트라솔름으로 가서 먹보 람스타인을 처치하고 그 증거로 그의 머리카락을 나타노스에게 가져가야 합니다." },
        [6402] = { name = "스톰윈드 회합", objective = "스톰윈드 도시 성문으로 가서, 수습기사 로우와 대화하면 그가 당신의 도착을 치안대장 윈저에게 알릴 것입니다." },
        [6403] = { name = "대단한 가장무도회", objective = "레지널드 윈저를 따라 스톰윈드를 통과해 왕궁으로 가야합니다. 윈저를 보호하십시오!" },
        [6501] = { name = "용의 눈", objective = "전 세계를 뒤져 용의눈 조각의 힘을 복원할 수 있는 자를 찾아야 합니다. 이와 관련해 알고 있는 유일한 정보는 그러한 자들이 존재한다는 것뿐입니다." },
        [6502] = { name = "비룡불꽃 아뮬렛", objective = "사령관 드라키사스에게서 검은용 용사의 피를 가져와야 합니다. 드라키사스는 검은바위 첨탑의 승천의 전당 뒤에 있는 알현실에 있습니다." },
        [6521] = { name = "사악한 동맹", objective = "사절 말킨을 처치한 다음 언더시티에 있는 바리마트라스에게 그의 머리카락을 증거로 가져가야 합니다." },
        [6522] = { name = "사악한 동맹", objective = "작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다." },
        [6561] = { name = "검은심연의 음모", objective = "황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다." },
        [6562] = { name = "검은심연의 나락으로...", objective = "잿빛 골짜기에 있는 제네우 생크리와 대화하십시오." },
        [6563] = { name = "아쿠마이의 정수", objective = "잿빛 골짜기에 있는 제네우 생크리에게 아쿠마이의 사파이어 20개를 가져가야 합니다." },
        [6564] = { name = "고대 신들에 대한 충성", objective = "축축한 메모를 잿빛 골짜기의 제네우 생크리에게 가져가십시오." },
        [6565] = { name = "고대 신들에 대한 충성", objective = "검은심연 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오." },
        [6566] = { name = "바람이 전해 온 소식", objective = "스랄의 이야기를 들어야 합니다." },
        [6567] = { name = "호드의 용사", objective = "렉사르를 찾아야 합니다. 그의 행방은 대족장이 설명해 주었습니다. 돌발톱 산맥과 페랄라스 사이에 있는 잊혀진 땅의 길에서 찾아 보십시오." },
        [6568] = { name = "렉사르의 유언", objective = "서부 역병지대에 있는 노파 미란다에게 렉사르의 유서를 전달해야 합니다." },
        [6569] = { name = "눈동자의 환영", objective = "검은바위 첨탑으로 가서 검은 용혈족의 눈동자 20개를 모아서 노파 미란다에게 돌아가야 합니다." },
        [6570] = { name = "엠버스트라이프", objective = "먼지진흙 습지대에 있는 용의 둥지로 가서 엠버스트라이프의 굴을 찾아야 합니다. 안으로 들어가서 용족 파멸의 아뮬렛을 착용하고 엠버스트라이프와 대화해야 합니다." },
        [6582] = { name = "해골 시험 - 스크라이어", objective = "여명의 설원에서 찾을 수 있는 푸른용군단의 용사 스크라이어를 찾아 처치해야 합니다. 그의 시체에서 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다." },
        [6583] = { name = "해골 시험 - 솜누스", objective = "녹색용군단의 우두머리 솜누스를 처치한 후 그의 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다." },
        [6584] = { name = "해골 시험 - 크로날리스", objective = "노즈도르무의 자손인 크로날리스가 타나리스 사막에 있는 시간의 동굴을 지키고 있습니다. 그를 처치한 후 그의 해골을 엠버스트라이프에게 가져가야 합니다." },
        [6585] = { name = "해골 시험 - 악트로즈", objective = "그림 바톨로 가서 붉은용군단의 우두머리 악트로즈를 찾아 그를 처치한 다음 그의 해골을 수습하여 엠버스트라이프에게 돌아가야 합니다." },
        [6601] = { name = "진급", objective = "이제 가면놀이는 끝난 것 같습니다. 노파 미란다가 만든 용족 파멸의 아뮬렛이 검은바위 첨탐 안에서 원래 구실을 하지 않는 것을 알고 있습니다. 아마도 렉사르를 찾아가 곤경에 처한 상황을 설명하는 것이 좋겠습니다. 렉사르에게 흐릿한 비룡불꽃 아뮬렛을 보여주면 아마도 필요한 게 무엇인지 알 수 있을 겁니다." },
        [6602] = { name = "검은용 용사의 피", objective = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치하고 사령관의 피를 모아 렉사르에게 가져가야 합니다." },
        [6626] = { name = "악의 무리", objective = "가시덩굴일족 전투호위병과 가시덩굴일족 가시마술사, 그리고 죽음의 머리교 신도를 각각 8마리씩 죽인 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다." },
        [6627] = { name = "지혜의 시험", objective = "브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다." },
        [6628] = { name = "지혜의 시험", objective = "파쿠알 핀탈라스의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 파쿠알 핀탈라스는 언더시티에 있을 것입니다." },
        [6921] = { name = "폐허 사이로", objective = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다." },
        [6922] = { name = "군주 아쿠아니스", objective = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다." },
        [6981] = { name = "빛나는 조각", objective = "톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오.\n\n그에게 지시를 받아, 빛나는 조각을 전달해야 합니다." },
        [7028] = { name = "뒤틀린 악마", objective = "트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다." },
        [7029] = { name = "바일텅의 타락", objective = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.\n\n오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다.\n\n녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가야 합니다." },
        [7041] = { name = "바일텅의 타락", objective = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.\n\n오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다.\n\n녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 나이젤의 야영지에 있는 탈렌드리아에게 돌아가야 합니다." },
        [7044] = { name = "마라우돈의 전설", objective = "셀레브라스의 홀 조각인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 찾아야 합니다.\n\n셀레브라스와 대화를 나눌 방법을 찾아야 합니다." },
        [7046] = { name = "셀레브라스의 홀", objective = "회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다.\n\n의식을 마친 후 그와 대화하십시오." },
        [7064] = { name = "대지와 씨앗의 오염", objective = "공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다." },
        [7065] = { name = "대지와 씨앗의 오염", objective = "공주 테라드라스를 해치우고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스를 찾아가야 합니다." },
        [7066] = { name = "생명의 씨앗", objective = "달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다." },
        [7067] = { name = "추방자의 지시서", objective = "추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다." },
        [7068] = { name = "음영석 조각", objective = "마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다." },
        [7070] = { name = "음영석 조각", objective = "마라우돈에서 음영석 조각 10개를 모아서 먼지진흙 습지대의 해안에 위치한 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다." },
        [7201] = { name = "마지막 원소", objective = "검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것도 기억이 납니다." },
        [7441] = { name = "푸실린과 노쇠한 아즈토르딘", objective = "혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다.\n\n마법서를 회수하면 페랄라스의 라리스 정자에 있는 아즈토리딘에게 돌아가야 합니다." },
        [7461] = { name = "내면의 광기", objective = "이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다.\n\n이몰타르의 감옥에 들어가 그 심장부에 서 있는 사악한 이몰타르를 처치하고, 마지막으로 도서관에 있는 토르텔드린 왕자와 맞서 싸우십시오.\n\n이 임무를 완수하면 안마당에 있는 셴드랄라 고대인에게 돌아가야 합니다." },
        [7462] = { name = "셴드랄라의 보물", objective = "도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!" },
        [7463] = { name = "신비의 원기 회복 주문", objective = "혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다." },
        [7481] = { name = "엘프의 전설", objective = "혈투의 전장을 뒤져 카리엘 윈탈루스를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다." },
        [7482] = { name = "엘프의 전설", objective = "혈투의 전장을 뒤져 카리엘 윈탈루스를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 페더문 요새에 있는 학자 룬쏜에게 돌아가야 합니다." },
        [7483] = { name = "신속의 성서", objective = "신속의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 그리고 영웅의 피 2개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 신속의 영석을 받아야 합니다." },
        [7484] = { name = "집중의 성서", objective = "집중의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 4개, 그리고 어둠의 허물 2개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 집중의 영석을 받아야 합니다." },
        [7485] = { name = "보호의 성서", objective = "보호의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 그리고 닳아해진 누더기골렘 조각 1개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 보호의 영석을 받아야 합니다." },
        [7488] = { name = "레스텐드리스의 그물", objective = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어에게 레스텐드리스의 그물을 가져가야 합니다." },
        [7489] = { name = "레스텐드리스의 그물", objective = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다." },
        [7492] = { name = "모자케 야영지", objective = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프와 대화하십시오." },
        [7494] = { name = "페더문 요새", objective = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어와 대화하십시오." },
        [7498] = { name = "가로나: 은신과 기만에 대한 연구", objective = "주인에게 책을 되돌려주십시오." },
        [7499] = { name = "방어의 고서", objective = "주인에게 책을 되돌려주십시오." },
        [7500] = { name = "신비술사의 요리책", objective = "주인에게 책을 되돌려주십시오." },
        [7501] = { name = "빛과 정의에 관하여", objective = "주인에게 책을 되돌려주십시오." },
        [7502] = { name = "지배의 그림자", objective = "주인에게 책을 되돌려주십시오." },
        [7503] = { name = "사냥꾼의 위대한 혈통", objective = "주인에게 책을 되돌려주십시오." },
        [7504] = { name = "성스러운 볼로냐: 빛이 알려주지 않는 것들", objective = "주인에게 책을 되돌려주십시오." },
        [7505] = { name = "냉기 충격과 주술", objective = "주인에게 책을 되돌려주십시오." },
        [7506] = { name = "에메랄드의 꿈...", objective = "주인에게 책을 되돌려주십시오." },
        [7507] = { name = "폴로르의 용사냥 개론", objective = "폴로르의 용사냥 개론을 도서관에 되돌려주어야 합니다." },
        [7563] = { name = "피의 광란", objective = "불타는 평원에 있는 모르줄 블러드브링어에게 흉포한 올빼미야수의 피 30병을 가져가야 합니다." },
        [7564] = { name = "와일드아이즈", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 피가 담긴 상자를 가져가야 합니다." },
        [7604] = { name = "대장조합 계약서", objective = "설퍼론 도면을 받으려면 설퍼론 주괴와 토륨 대장조합 계약서를 로크토스 다크바게이너에게 가져가야 합니다." },
        [7623] = { name = "군주 베인할로우", objective = "불타는 평원에 있는 고르지키에게서 어둠의 물약을 구입해야 합니다.\n\n이 물약을 사용하여 자에데나르로 가서 군주 베인할로우와 대화하십시오." },
        [7624] = { name = "배신자 울라텍", objective = "울라텍과 맞서 싸운 후 자에데나르에 있는 베인할로우 군주에게 배신자의 증거를 가져가야 합니다." },
        [7625] = { name = "소로시안 별가루", objective = "우르단에게서 소로시안 별가루를 구입한 후, 불타는 평원에 있는 고르지키 와일드아이즈에게 가져가야 합니다." },
        [7626] = { name = "데스무라의 종", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 암흑 강화의 비약 10개를 가져가야 합니다." },
        [7627] = { name = "어둠의 물레", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 눈부신 큰 결정 6개와 검은무쇠 광석 25개를 가져가야 합니다." },
        [7628] = { name = "심판의 양초", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 검은용 비늘 35개를 가져가야 합니다." },
        [7629] = { name = "임프 배달", objective = "단지 안에 든 임프를 스칼로맨스에 있는 연금술 실험대로 가져가야 합니다. 양피지가 완성되면 단지를 고르지키 와일드아이즈에게 되돌려 주십시오." },
        [7630] = { name = "아케이나이트", objective = "불타는 평원에 있는 고르지키에게 아케이나이트 주괴 3개를 가져가야 합니다." },
        [7631] = { name = "소로스의 공포마", objective = "모르줄의 지시서를 잘 읽으십시오. 소로시안 공포마를 소환해 물리친 후 그 영혼을 결속시켜야 합니다." },
        [7637] = { name = "희생의 중요성", objective = "아이언포지에 가서 대사제 로한의 퇴마 향로를 가져와야 합니다. 퇴마 향로를 얻으려면 150골드를 기부해야 합니다." },
        [7639] = { name = "희생과 심판", objective = "퇴마 향로를 가지고 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다." },
        [7640] = { name = "테러데일 퇴마", objective = "퇴마 향로를 사용하여 테러데일에 고통을 주는 영혼을 몰아내야 합니다. 25명의 테러데일 영혼을 해치운 다음 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다." },
        [7641] = { name = "그리만트 엘모어의 마갑", objective = "스톰윈드의 드워프 지구에 있는 그리만트 엘모어와 대화해야 합니다." },
        [7642] = { name = "마갑 재료 수집", objective = "룬무늬 옷감 40개, 아케이나이트 주괴 6개, 아서스의 눈물 10개, 스트라솔름 성수 물병 5개 그리고 150골드를 스톰윈드의 드워프 지구에 있는 그리만트 엘모어에게 가져가야 합니다." },
        [7643] = { name = "고대 준마의 영혼", objective = "사우스쇼어에 있는 메리데스 칼슨에게 말의 영혼에게 먹일 특별한 말 먹이를 얻어야 합니다.\n\n페랄라스에 있는 혈투의 전장 던전으로 가서 굽이나무 텐드리스를 무찔러야 합니다. 굽이나무 텐드리스를 무찌르고 고대 준마의 영혼이 풀려나면 특별한 말 먹이를 먹여 영혼을 진정시키십시오. 마지막으로 아케이나이트 마갑을 주면 영혼이 축복을 내릴 것입니다." },
        [7644] = { name = "축복받은 아케이나이트 마갑", objective = "축복받은 아케이나이트 마갑을 가지고 스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다." },
        [7645] = { name = "맛좋은 만나 사료", objective = "맛좋은 만나빵 20개를 모아서 힐스브래드 구릉지의 사우스쇼어에 있는 메리데스 칼슨에게 가져가야 합니다. 맛좋은 만나빵은 맛좋은 만나 사료에 꼭 필요한 재료입니다. 맛좋은 만나빵은 은빛 여명회에서 독점적으로 파는 것으로 알려져 있습니다.\n\n메리데스 칼슨에게도 50골드를 주어야만 화가 난 마음을 진정시킬 수 있습니다." },
        [7646] = { name = "예언의 탐지기", objective = "스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져가야 합니다." },
        [7647] = { name = "심판과 구원의 손길", objective = "스칼로맨스에 있는 대형 납골당 지하의 중심부로 가서 예언의 탐지기를 사용해야 합니다. 그러면 영혼들이 나타날 것이니 그들을 해치우십시오. 그들을 해치우면 죽음의 기사 다크리버가 나타날 것이니 그를 물리친 다음 군마의 영혼의 잃어버린 영혼을 되찾아야 합니다.\n\n구원된 군마의 영혼과 축복받은 아케이나이트 마갑을 다크리버 군마의 영혼에게 돌려줘야 합니다." },
        [7648] = { name = "그리만트의 걸작품", objective = "스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아케이나이트 마갑을 가져가야 합니다." },
        [7667] = { name = "물질적인 부탁", objective = "오그리마, 지혜의 골짜기에 있는 사고른 크레스트스트라이더의 일을 도우려면 그에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져가야 합니다." },
        [7668] = { name = "다크리버의 위협", objective = "스칼로맨스에 있는 대형 납골당 지하의 중앙으로 가서 예언의 탐지기를 사용하십시오. 그러면 유령들이 나타날 것입니다. 그들을 해치우십시오. 그리고 곧이어 나타날 죽음의 기사 다크리버를 해치워야 합니다.\n\n그런 다음 그 증거로 오그리마, 지혜의 골짜기에 있는 사고른 크레스트스트라이더에게 다크리버의 머리카락을 가져가야 합니다." },
        [7703] = { name = "고르독 일 마무리", objective = "권력의 고르독 건틀릿을 찾아 혈투의 전장에 있는 대장 크롬크러쉬에게 가져가야 합니다.\n\n크롬크러쉬의 \"옛날 얘기\"에 따르면 자칭 왕자라는 토르텔드린이라는 이름의 \"기분 나쁜\" 엘프가 고르독 왕에게서 빼앗아갔다고 합니다." },
        [7761] = { name = "블랙핸드의 명령서", objective = "아주 멍청한 오크로군요. 지배의 보주를 사용하려면 드라키사스의 낙인을 찾아 드라키사스의 징표를 받아야 할 거 같습니다.\n\n이 편지에 따르면 드라키사스 사령관이 낙인을 지키고 있다고 하니 조사해 보는 것이 좋겠습니다." },
        [7848] = { name = "심장부와의 조화", objective = "검은바위 나락의 화산 심장부 입구에 있는 차원의 문으로 가서 핵 조각을 하나 찾아야 합니다. 핵 조각을 가지고 검은바위 산에 있는 로소스 리프트웨이커에게로 돌아가십시오." },
        [8151] = { name = "사냥꾼의 부적", objective = "아즈샤라에 있는 오그틴크와 대화해야 합니다." },
        [8153] = { name = "순록 뿔", objective = "아즈샤라에 있는 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 완전한 순록 뿔 한 쌍을 가져가야 합니다." },
        [8231] = { name = "폭풍히드라 사냥", objective = "아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 폭풍히드라 비늘 6개를 가져가야 합니다." },
        [8232] = { name = "녹색 비룡 몰파즈", objective = "아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 몰파즈의 이빨을 가져가야 합니다." },
        [8233] = { name = "간단한 부탁", objective = "라벤홀트 장원에 있는 조라크 라벤홀트 경과 대화해야 합니다." },
        [8234] = { name = "봉인된 하늘색 자루", objective = "아즈샤라에 있는 나무구렁일족 주술사에게서 봉인된 하늘색 자루를 되찾은 후, 그 가방을 아즈샤라에 있는 대마법사 실렘에게 가져가야 합니다." },
        [8235] = { name = "암호화된 페이지", objective = "아즈샤라에 있는 대마법사 실렘에게 암호화 된 페이지 10개를 가져가야 합니다." },
        [8236] = { name = "하늘색 열쇠", objective = "조라크 라벤홀트 경에게 하늘색 열쇠를 가져가야 합니다." },
        [8250] = { name = "마법 공예", objective = "대마법사 실렘을 만나기 위한 허가를 얻기 위해 사나스 림요를 찾아야 합니다." },
        [8251] = { name = "마법의 티끌", objective = "대마법사 실렘에게 반짝이는 가루 10개를 가져가야 합니다." },
        [8252] = { name = "세이렌의 산호", objective = "대마법사 실렘에게 마력 깃든 산호 6개를 가져가야 합니다." },
        [8253] = { name = "몰파즈 처치", objective = "몰파즈에게서 신비의 결정을 되찾아 대마법사 실렘에게 가져가야 합니다." },
        [8254] = { name = "세나리온 의회 지원", objective = "아즈샤라에서 오그틴크를 찾아야 합니다." },
        [8255] = { name = "순록을 찾아서", objective = "건강한 순록의 분비샘 4개를 찾아 아즈샤라의 오그틴크에게 가져가야 합니다. 오그틴크는 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있습니다." },
        [8256] = { name = "불사의 영액", objective = "아즈샤라의 오그틴크에게 불사의 영액을 가져다주어야 합니다. 오그틴크는 엘다라스 폐허 북동쪽 절벽 꼭대기에 있습니다." },
        [8257] = { name = "몰파즈의 피", objective = "아탈학카르 신전에서 몰파즈를 처치하고 그의 피를 악령의 숲에 있는 그레타 모스후프에게 가져다주어야 합니다. 가라앉은 신전의 입구는 슬픔의 늪에 있습니다." },
        [8410] = { name = "원소에 대한 깨달음", objective = "물, 불, 대지, 바람의 샘플을 수집하여 바람의감시자 바스라에게 가져가야 합니다." },
        [8412] = { name = "정기의 토템", objective = "바람의감시자 바스라에게 정기의 토템을 만드는데 필요한 재료들을 가져가야 합니다." },
        [8413] = { name = "부두교 마법", objective = "바람의감시자 바스라에게 부두 깃털들을 가져가야 합니다." },
        [8414] = { name = "악마 퇴치", objective = "서부 역병지대에 있는 대사제 텔다니스에게 앞잡이의 스컬지석 20개를 모아 가져가야 합니다." },
        [8415] = { name = "서리바람 거점으로", objective = "서리바람 거점에 있는 사령관 아쉬람 발러피스트와 대화해야 합니다." },
        [8416] = { name = "마력을 잃은 스컬지석", objective = "서리바람 거점에 있는 사령관 아쉬람 발러피스트에게 마력을 잃은 스컬지석을 가져가야 합니다." },
        [8417] = { name = "영혼이 된 영웅의 고통", objective = "저주받은 땅의 입구에 있는 호드 영웅의 넋과 대화해야 합니다." },
        [8418] = { name = "퇴마석 만들기", objective = "아쉬람 발러피스트에게 황색 부두 깃털, 청색 부두 깃털, 녹색 부두 깃털을 각 2개씩 가져가야 합니다." },
        [8419] = { name = "임프의 부탁", objective = "악령의 숲에 있는 임프시에게 지옥 옷감을 한 장 가져가야 합니다." },
        [8420] = { name = "뜨거운 소유욕", objective = "악령의 숲에 있는 임프시에게 지옥 옷감을 한 장 가져가야 합니다." },
        [8421] = { name = "인형 재료", objective = "악령의 숲에 있는 임프시에게 썩은 나무 10개와 피멍울 정수 4개를 가져가야 합니다." },
        [8422] = { name = "트롤의 깃털", objective = "가라앉은 사원에 있는 트롤의 부두 깃털 6개를 가져가야 합니다." },
        [8423] = { name = "전사의 일족", objective = "저주받은 땅에 있는 지옥멧돼지 7마리를 처치하고 호드 영웅의 넋에게 돌아가야 합니다." },
        [8424] = { name = "어둠의혈맹과의 전쟁", objective = "저주받은 땅에서 어둠의혈맹 숙련사제, 이교도, 암살단원을 각 20명씩 해치우고 호드 영웅의 넋에게 돌아가야 합니다." },
        [8425] = { name = "부두 깃털", objective = "호드 영웅의 넋에게 가라앉은 사원에 있는 트롤들에게서 황색 부두 깃털, 청색 부두 깃털, 녹색 부두 깃털을 빼앗아 각 2개씩 가져가야 합니다." },
        [8945] = { name = "죽은 자의 부탁", objective = "스트라솔름으로 가서 남작 리븐데어로부터 이시다 하몬을 구해야 합니다." },
        [8948] = { name = "안시온의 오랜 친구", objective = "혈투의 전장의 도서관에 있는 팔린 트리셰이퍼에게 미완성된 도전의 깃발을 가져가야 합니다." },
        [8949] = { name = "팔린의 피의 복수", objective = "혈투의 전장이나 검은바위 첨탑의 오우거로부터 오우거 전투 목걸이 25개를 모은 후 도서관 안에 있는 팔린 트리셰이퍼에게 돌아가야 합니다." },
        [8950] = { name = "주동자의 마법", objective = "혈투의 전장 안 도서관에 있는 팔린 트리셰이퍼에게 다음 재료를 가져가야 합니다: 도깨비 정수 1개, 암흑의 룬 4개, 눈부신 큰 결정 8개" },
        [9015] = { name = "도전", objective = "검은바위 나락의 법의 심판장으로 가서 대법관 그림스톤에 의해 선고받은대로 한가운데에 도전의 깃발을 설치해야 합니다. 텔드렌과 그의 검투사들을 해치운 후 군주 발타라크의 첫 번째 아뮬렛 조각을 가지고 동부 역병지대에 있는 안시온 하몬에게 돌아가야 합니다." },
        [9051] = { name = "독성 테스트", objective = "데빌사우루스 가시로 데빌사우루스를 찔러야 합니다. 임무를 완수하면 운고로 분화구에 있는 토르와 패스파인더에게 돌아가야 합니다." },
        [9052] = { name = "붉은꽃잎 독", objective = "붉은갓버섯 8개와 고리쉬 독침 8개를 모아서 운고로 분화구에 있는 토르와 패스파인더에게 돌아가십시오." },
        [9053] = { name = "더욱 강력한 재료", objective = "가라앉은 사원 하층부의 수호병으로부터 썩은 덩굴을 찾은 후 토르와 패스파인더에게 돌아가십시오." },
        [9063] = { name = "토르와 패스파인더", objective = "운고로 분화구에 있는 토르와 패스파인더와 대화하십시오." },
        [78261] = { name = "젤토스의 뿔", objective = "그림자송곳니 성채에서 젤토스의 뿔을 찾아야 합니다. 그런 다음 장작나무 마을 주변에 있는 C의 비밀 점선 지점에 반환해야 합니다. 이 일은 혼자서 완료해야 합니다." },
        [78307] = { name = "젤토스의 뿔", objective = "기록" },
        [79007] = { name = "...그때 찾은 그 기록", objective = "길잡이로 삼을 만한 물건이라곤 불타버린 쪽지의 잔해뿐입니다." },
        [79008] = { name = "...그때 찾은 그 기록", objective = "길잡이로 삼을 만한 물건이라곤 불타버린 쪽지의 잔해뿐입니다." },
        [79192] = { name = "디딤돌", objective = "당신은 판자에서 쪽지를 뜯어내 휘갈긴 글귀를 읽습니다." },
        [79358] = { name = "폭풍과 대지와 불", objective = "뒤틀린 불의 토템 5개, 뒤틀린 대지 토템 5개, 뒤틀린 바람 토템 5개, 뒤틀린 물 토템 5개를 모아 아라시 고원에 있는 베이릭 썬더헤임에게 전달해야 합니다." },
        [79361] = { name = "폭풍과 대지와 불", objective = "뒤틀린 불의 토템 5개, 뒤틀린 대지 토템 5개, 뒤틀린 바람 토템 5개, 뒤틀린 물 토템 5개를 모아 버섯구름 봉우리에 있는 프레이트 클라우드시어에게 전달해야 합니다." },
        [79974] = { name = "손 더럽히는 일", objective = "땅에 떨어져 있던 배낭에 묻은 흙을 털어낸 뒤 내부를 살펴보자, 여러 보급품과 양피지가 들어 있습니다." },
        [79975] = { name = "독수리의 주먹", objective = "분사되는 물이 공기를 습하게 만들자 장관이 펼쳐집니다." },
        [79976] = { name = "여기가 분명해", objective = "누군지 몰라도 간발의 차로 놓친 듯합니다." },
        [79980] = { name = "허겁지겁", objective = "무엇이 기다리는지 알아내야 합니다." },
        [92401] = { name = "두려움에 찬 부탁", objective = "로데론의 폐허에서 에드워드 하트위버의 실종에 관해 조사해야 합니다." },
        [92415] = { name = "내가 사랑한다는 걸 기억해", objective = "피로 얼룩진 편지를 스톰윈드에 있는 보육원 원장님 나이팅게일에게 가져가야 합니다." },
        [92421] = { name = "빛의 정의", objective = "언더시티에 있는 모빈 라이트베인을 위해 로데론의 폐허에서 온전한 사지 25개를 수집해야 합니다." },
        [92422] = { name = "라스마엘의 격노", objective = "브릴의 죽음경비병 크리스토프를 위해 로데론의 폐허에 있는 라스마엘을 처치해야 합니다." },
        [92432] = { name = "다급한 요청", objective = "달라란 근처에 있는 대마법사 모데라의 환영에게 보고해야 합니다." },
        [92456] = { name = "녹빛 표본", objective = "스톰윈드에 있는 샤이라미르를 위해 달라란에서 지옥 마력이 주입된 꽃을 채집해야 합니다." },
        [92457] = { name = "비전에 굶주린 자들", objective = "달라란 바깥에 있는 대마법사 모데라를 위해 달라란 내부에서 추적하는 잔재 8마리와 포화된 잔재 8마리, 마나 메아리 8마리를 처치해야 합니다." },
        [92458] = { name = "분열의 심장", objective = "달라란 근처에 있는 대마법사 모데라의 환영을 위해 비전 티끌을 모아야 합니다." },
        [92489] = { name = "압도적인 힘", objective = "스톰윈드에 있는 고위마술사 안드로매스를 위해 달라란에서 마나 정령을 처치해야 합니다." },
        [92742] = { name = "우물 검사", objective = "얀센 농장과 몰센 농장 우물에서 우물물 표본 채취 도구를 사용해 표본을 채취해야 합니다." },
        [92744] = { name = "멀록 아가미", objective = "서부 몰락지대 해안선에서 기나긴 해안 멀록 아가미 7개를 입수해 알바 페어문에게 전달해야 합니다." },
        [92745] = { name = "광산의 실태", objective = "장고로드 광산에서 코볼트 채굴꾼 4마리를, 황금해안 채석장에서 갈퀴발 광부 6마리를 처치해야 합니다." },
        [92747] = { name = "문브룩 첩보 활동", objective = "문브룩에서 수상한 공업용 보급품 8개를 수집해야 합니다." },
        [92748] = { name = "폭파 전문가의 조언", objective = "스톰윈드 드워프 지구로 이동한 후 도움을 줄 수 있는 기술자를 찾아야 합니다." },
        [92749] = { name = "다이너마이트 계획", objective = "제작이나 거래, 경매장을 통해 천연 다이너마이트 10개를 입수한 후, 스톰윈드 드워프 지구에 있는 스프라이트 점프스프로켓에게 가야 합니다." },
        [92750] = { name = "폭파는 멀찍이서", objective = "스톰윈드 첩보부 구성원을 찾아가 원격 기폭장치에 관해 얘기해야 합니다." },
        [92751] = { name = "폭파는 멀찍이서", objective = "원격 기폭장치 도구를 스톰윈드 드워프 지구에 있는 스프라이트 점프스프로켓에게 가져가야 합니다." },
        [92752] = { name = "폭파 전문가의 조언", objective = "서부 몰락지대에 있는 알바 페어문에게 가야 합니다." },
        [92753] = { name = "죽음의 폐광 파괴 작전", objective = "죽음의 폐광에서 숨겨진 가열로를 찾아 주변에 강력 파괴 폭발물을 설치해야 합니다. 그런 다음 죽음의 폐광 출구에서 알바 페어문을 만나야 합니다." },
        [92819] = { name = "죽음의 폐광 파괴 작전", objective = "기폭장치를 사용해야 합니다." },
        [95034] = { name = "빚", objective = "공동묘지에서 루미나 윈드싱어와 대화해야 합니다." },
        [95036] = { name = "달빛이 입 맞춘 칼날", objective = "공동묘지에서 트레반 롤과 대화한 후, 그가 필요로 하는 재료를 가져가야 합니다." },
        [95111] = { name = "저평가된 재능", objective = "오트와 대화해 검을 벼려 달라고 부탁해야 합니다." },
        [95125] = { name = "오트의 걸작", objective = "오트가 당신의 검을 벼리는 모습을 지켜봐야 합니다." },
        [95126] = { name = "달빛은 칼날", objective = "오트의 걸작을 은빛소나무 숲에 있는 트레반 롤에게 가져가야 합니다." },
        [95140] = { name = "늙은 불꽃눈", objective = "은빛소나무 숲에서 달빛은 칼날을 사용해 늙은 불꽃눈을 처단해야 합니다." },
        [95189] = { name = "로데론의 문장", objective = "로데론의 문장을 스톰윈드에 있는 귀부인 디나 케네디에게 반환해야 합니다." },
        [95195] = { name = "피투성이 휘장", objective = "피투성이 휘장 10개를 모아 스톰윈드에 있는 장군 마커스 조나단에게 가져가야 합니다." },
        [95204] = { name = "로데론의 문장", objective = "로데론의 문장을 언더시티에 있는 오란 스네이크레이드에게 가져가야 합니다." },
        [95216] = { name = "새로운 역병", objective = "로데론의 폐허에 있는 쇠퇴송곳니에게서 고독성 변종을 채취해 언더시티에 있는 시어도어 그리프스에게 가져가야 합니다." },
        [95250] = { name = "흉측한 생명체", objective = "로데론의 폐허에서 남작의 머리카락을 획득해 대장 트루먼에게 가져가야 합니다." },
        [95646] = { name = "고원의 공포", objective = "발굴 현장에서 고원 공포를 처치한 후, 그 뿌리 핵을 저습지에 있는 신록수호자 레시엘에게 가져가야 합니다." },
        [95647] = { name = "덤불 속 실종자", objective = "발굴 현장에서 아딘 그래스맨을 찾아야 합니다." },
        [95663] = { name = "용아귀 소문", objective = "저습지로 이동한 후 용아귀 야영지 위쪽 언덕에서 죽음추적자를 만나야 합니다." },
        [95664] = { name = "장로의 지식", objective = "티탄의 유물을 썬더 블러프의 장로의 봉우리로 가져가서 자세한 이야기를 해 줄 만한 사람을 찾아야 합니다." },
        [95697] = { name = "달라지는 입맛", objective = "저습지의 발굴 현장에 진입해 덤불 랩터 고기를 가져와야 합니다." },
        [95772] = { name = "송블레이드 수색", objective = "웰가르의 발굴 현장에서 도린 송블레이드의 형제 대윈을 찾아야 합니다." },
        [95789] = { name = "수상쩍은 소금선견자", objective = "가라앉은 도시의 소금선견자 해적에게서 부두가 깃든 유물 10개를 수집해야 합니다." },
        [95791] = { name = "소금선견자 대장", objective = "가라앉은 도시에서 소금선견자 검시관 3명과 대장 드레드라이즈를 처치해야 합니다." },
