        [96264] = { name = "정기의 도움", objective = "가시덩굴 우리에서 서슬깃 차를가를 처치하고 가시멧돼지의 계획에 관한 정보를 수집해야 합니다." },
        [96391] = { name = "지하 지도", objective = "검은무쇠 지도를 던 모로에 있는 대지선견자 파르센에게 전달해야 합니다." },
        [96393] = { name = "구 아이언포지 침입", objective = "구 아이언포지 지하에 있는 영주의 전당에 진입해 드루겐 더지해머의 머리카락을 확보해야 합니다." },
        [96394] = { name = "안식 없는 죽음", objective = "분노한 원혼 15명과 고통받는 영혼 10명을 처치하고 앤빌마의 영혼을 안식에 들게 해야 합니다." },
