        [96403] = { name = "중요한 가보", objective = "영주의 전당에서 드워프 가보 8개를 입수해야 합니다." },
        [96984] = { name = "분열의 심장", objective = "타렌 밀농장에 있는 학자 워딘 보이드글레어를 위해 달라란에서 비전 티끌을 모아야 합니다." },
