        [98423] = { name = "이해의 조약", objective = "이해의 조약을 아이언포지에 있는 마그니 브론즈비어드에게 전달해야 합니다." },
        [98815] = { name = "고원 가죽", objective = "메네실 항구의 무두장이 제임스 할로란에게 덤불 랩터 가죽 4개를 가져가야 합니다." },
        [98823] = { name = "대지의 메아리", objective = "티탄의 유물을 멀고어 북서쪽의 하늘감시자 고원에 있는 멀른 어스퓨리에게 가져가야 합니다." },
        [98824] = { name = "태고의 분광경", objective = "티탄의 유물을 아이언포지 탐험가의 전당에 있는 선임탐험가 마겔라스에게 가져가야 합니다." },
        [99156] = { name = "후방 경비", objective = "죽음경비병 리니아에게 너덜토막의 심장을 가져가야 합니다." },
    }
    for id, fields in pairs(quests) do
        c.quests[id] = c.quests[id] or {}
        for field, text in pairs(fields) do c.quests[id][field] = text end
    end
end

