        [1838] = { name = "Armadura brutal", objective = "Leve para Thun'grim Olhafogo 15 Lingotes Fumegantes de Ferro, 10 Azuritas Pulverizadas, 10 Barras de Ferro e a Ampola de Flogisto." },
        [1848] = { name = "Cota brutal", objective = "Sei que a minha tarefa trouxe muita dificuldade e derramamento de sangue, <name>. Eis o resultado do seu esforço.\n\nQue ela lhe sirva bem. Que você ainda volte aqui um dia para me contar das suas conquistas com a cota." },
        [1954] = { name = "O Orbe Infernal", objective = "Leve um Orbe Infernal para Tabetha no Pântano Vadeoso." },
        [1955] = { name = "O Exorcismo", objective = "Mate o Demônio do Orbe, depois fale com Tabetha." },
        [1956] = { name = "Poder em Uldaman", objective = "Recupere uma Fonte de Energia de Obsidiana e leve-a para Tabetha no Pântano Vadeoso." },
        [2040] = { name = "Ataque subterrâneo", objective = "Recupere o Engrenotreco Gnomo das Minas Mortas e devolva a Shoni, a Shilenchiosa, em Ventobravo." },
        [2041] = { name = "Fale com Shoni", objective = "Fale com Shoni, a Shilenchiosa, em Ventobravo." },
        [2198] = { name = "O colar estilhaçado", objective = "Procure o criador original do colar estilhaçado para saber sobre seu valor potencial." },
        [2199] = { name = "Aí tem truta!", objective = "Leve cinco barras de prata para Didiê Du Mocó em Altaforja." },
        [2200] = { name = "De volta a Uldaman", objective = "Procure pistas sobre disposição atual do colar de Didiê dentro de Uldaman. O paladino morto que ele mencionou foi a última pessoa a portá-lo." },
        [2201] = { name = "Encontre as gemas", objective = "Encontre o rubi, a safira e o topázio que foram espalhados por toda Uldaman. Uma vez adquiridos, entre em contato com Didiê Du Mocó remotamente, usando o Frasco de Vidência que ele lhe deu.\n\nDe acordo com o diário...\n* O rubi está escondido em uma área barricada de Umbraforja.\n* O topázio está escondido numa urna em uma das áreas dos troggs, perto dos anões da Aliança.\n\n* A safira foi reivindicada por Grimlok, o líder dos troggs." },
        [2202] = { name = "Busca pelos reagentes de Uldaman", objective = "Leve 12 Campânulas de Fungo Magenta para Jarkal Limuno em Karrath." },
        [2204] = { name = "Restaurando o colar", objective = "Obtenha uma fonte de energia do constructo mais poderoso que você encontrar em Uldaman e entregue-a a Didiê Du Mocó em Altaforja." },
        [2240] = { name = "A câmara oculta", objective = "Leia o Diário de Baelog, explore a câmara oculta, depois fale com o Prospector Lançatroz." },
        [2258] = { name = "Busca pelos reagentes dos Ermos", objective = "Leve 5 Moelas de Urubu, 10 Presas de Coiote do Rochedo e 5 Estilhaços de Elemental da Rocha para Jarkal Limuno em Karrath, Ermos." },
        [2278] = { name = "Os discos de platina", objective = "Fale com o vigia de pedra e descubra quais são os segredos da história antiga que ele guarda. Após aprender os segredos históricos, ative os Discos de Norgannon." },
        [2279] = { name = "Os discos de platina", objective = "Leve a versão em miniatura dos Discos de Norgannon para a Liga dos Exploradores em Altaforja." },
        [2280] = { name = "Os discos de platina", objective = "Leve a versão em miniatura dos Discos de Norgannon para algum dos sábios no Penhasco do Trovão." },
        [2283] = { name = "O resgate do colar", objective = "Procure um colar valioso na escavação de Uldaman e leve-o para Dran Droffers em Orgrimmar. O colar pode estar danificado." },
        [2284] = { name = "O resgate do colar 2 – A missão", objective = "Encontre uma pista do paradeiro das gemas nas profundezas de Uldaman." },
        [2318] = { name = "Traduzindo o diário", objective = "Encontre alguém que consiga traduzir o diário do paladino. O local mais próximo que pode ter alguém que o faça é Karrath, nos Ermos." },
        [2338] = { name = "Traduzindo o diário", objective = "Empreste o colar a Jarkal. Em troca, ele vai traduzir o diário para você." },
        [2339] = { name = "Encontre as Gemas e a Fonte de Energia", objective = "Recupere todas as três gemas e uma fonte de energia para o colar de Uldaman e leve-as para Jarkal Limuno, em Karrath. Jarkal acredita que uma fonte de energia pode ser encontrada no constructo mais forte presente em Uldaman.\n\nDe acordo com o diário:\n* O rubi está escondido em uma área de Umbraforja protegida por barreiras.\n* O topázio está escondido numa urna em uma das áreas dos troggs, perto de alguns anões da Aliança.\n* A safira foi reclamada por Grimlok, o líder dos troggs." },
        [2340] = { name = "Entregue as gemas", objective = "Entregue o Colar e Gema Recuperados para Dran Droffers em Orgrimmar." },
        [2341] = { name = "O resgate do colar 3 – O Retorno", objective = "Visite Jarkal Limuno em Karrath para ver se ele obteve sucesso." },
        [2342] = { name = "Tesouros recuperados", objective = "Pegue o tesouro de Patrício Garreta no baú de sua família, que está no Saguão Sul de Uldaman, e entregue a ele na Cidade Baixa." },
        [2361] = { name = "Restaurando o colar", objective = "Eu lhe dou este colar com muita satisfação, imponente <class>. Você me prestou um serviço inestimável e tem a minha gratidão por isso. Use-o com orgulho não deixe de sempre mencionar alto e em bom som quem o fez para você!\n\nAh, e se você puder dizer de passagem que ele não é amaldiçoado, seria ótimo também." },
        [2398] = { name = "Os anões perdidos", objective = "Encontre Baelog em Uldaman." },
        [2418] = { name = "Pedras de energia", objective = "Leve 8 Pedras de Energia de Dêntrio e 8 Pedras de Energia de An'Alleum para Bertolezo nos Ermos." },
        [2439] = { name = "Os discos de platina", objective = "Leve o vale-recompensa para Dinita Itamanto no Cofre de Altaforja." },
        [2500] = { name = "Busca pelos reagentes dos Ermos", objective = "Consiga os reagentes dos Ermos de que Ghak Toquecura precisa, então fale novamente com ele em Thelsamar." },
        [2768] = { name = "Bastão divinomático", objective = "Leve o Bastão Divinomático ao Engenheiro-chefe Silvadágua em Geringontzan." },
        [2769] = { name = "Os irmãos Latafuso", objective = "Fale com Capu Latafuso no Salar Cintilante." },
        [2770] = { objective = "Leve a Escama Eletrificada de Gahz'rilla para Capu Latafuso no Salar Cintilante." },
        [2841] = { name = "Guerra dos robôs", objective = "Pegue a Combinação do Cofre do Termaplugue e o Projeto de Mecatraje e leve-os para Nogg em Orgrimmar." },
        [2842] = { name = "Engenheiro-chefe Scooty", objective = "Fale com Scooty na Angra do Butim." },
        [2843] = { name = "E lá vamos nós!", objective = "Esperar até Scooty calibrar o Transponder Goblínico." },
        [2846] = { name = "Tiara das Profundezas", objective = "Leve a Tiara das Profundezas para Tabetha no Pântano Vadeoso." },
        [2861] = { name = "A tarefa de Tabetha", objective = "Fale com Tabetha no Pântano Vadeoso." },
        [2864] = { objective = "Fale com Tran'rek em Geringontzan." },
        [2865] = { name = "Couraças de escaravelho", objective = "Leve 5 Couraças de Escaravelho Fechadas para Tran'rek em Geringontzan." },
        [2904] = { name = "Uma bela bagunça", objective = "Escolte Kernobill até a saída do Corredor dos Mecanismos, depois apresente-se a Scooty na Angra do Butim." },
        [2922] = { name = "Salve o cérebro do Tecnobô!", objective = "Leve o Núcleo de Memória do Tecnobô para o Mestre-faz-tudo Superchispa em Altaforja." },
        [2924] = { name = "Artifícios Essenciais", objective = "Leve 12 Artifícios Essenciais para Cronomorfus Espanafuso em Altaforja." },
        [2926] = { name = "Gnogaína", objective = "Use o Coletor de Chumbo Vazio nos Invasores Irradiados ou nos Pilhadores Irradiados para recolher resíduos radioativos. Depois que ele ficar cheio, leve-o de volta para Ozzie Mudavolt em Kharanos." },
        [2928] = { name = "Escavacionadores girobrocamáticos", objective = "Leve 24 Tripas Mecanobóticas para Shoni em Ventobravo." },
        [2929] = { name = "A grande traição", objective = "Vá para Gnomeregan e mate o Mecangenheiro Termaplugue. Fale novamente com o Grão-faz-tudo Mekkatorque depois que tiver terminado a tarefa." },
        [2930] = { name = "O resgate dos dados", objective = "Leve o Cartão Perfurado Prismático para o Mestre Mecânico Fundecano em Altaforja." },
        [2933] = { name = "Garrafas de peçonha", objective = "Leve uma Garrafa de Peçonha para um boticário na Serraria Tarren." },
        [2934] = { name = "Vesícula de peçonha intacta", objective = "Leve a Vesícula de Peçonha Intacta para o Boticário Lindolfo na Serraria Tarren." },
        [2935] = { name = "Consulte o Mestre Gadrin", objective = "Fale com o Mestre Gadrin na Aldeia Sen'jin." },
        [2936] = { name = "A deusa aranha", objective = "Leia a Tabuleta de Theka para descobrir o nome da deusa aranha dos Cascasseca, depois fale novamente com o Mestre Gadrin." },
        [2945] = { name = "Anel Encardido", objective = "Descubra uma maneira de remover a crosta de sujeira do Anel Encardido." },
        [2947] = { name = "Ficar ou não ficar... eis a questão!", objective = "Você pode ficar com o anel ou achar a pessoa que faz a gravação no interior dele." },
        [2948] = { name = "Aperfeiçoamento gnômico", objective = "Entregue o Anel de Ouro Brilhante, uma Barra de Prata, uma Ágata Musgosa e 30 moedas de prata para Didiê Du Mocó, em Altaforja." },
        [2949] = { name = "Ficar ou não ficar... eis a questão!", objective = "Você pode ficar com o anel ou achar a pessoa que faz a gravação no interior dele." },
        [2950] = { name = "Recauchutagem do anel do Nogg", objective = "Leve o Anel de Ouro Brilhante, uma Barra de Prata, uma Ágata Musgosa e 30 moedas de Prata para Nogg em Orgrimmar." },
        [2951] = { name = "A Brastematic 5200!", objective = "Coloque um Objeto Encardido e três moedas de prata na Brastematic 5200 para iniciar o processo de limpeza." },
        [2962] = { name = "A única cura é mais brilho verde", objective = "Vá até Gnomeregan e traga o Resíduo Radioativo de Alta Potência. Tome cuidado, pois a radiação é instável e pode se esvair rapidamente.\n\nOzzie também vai precisar do seu Coletor de Chumbo Pesado quando tiver terminado." },
        [2988] = { name = "Jaulas Cascasseca", objective = "Verifique as jaulas nas duas aldeias Cascasseca, depois fale novamente com o Mestre de Grifos Garra-de-acha." },
        [2989] = { name = "Altar de Zul", objective = "Verifique o topo do Altar de Zul, depois fale novamente com o Mestre de Grifos Garra-de-acha." },
        [2990] = { name = "Tádius Sombraustera", objective = "Leve a Pena de Bicoafiado para Tádius Sombraustera na Barreira do Inferno." },
        [2991] = { name = "Medalhão de Nekrum", objective = "Leve o Medalhão de Nekrum para Tádius Sombraustera na Barreira do Inferno." },
        [3042] = { name = "Têmpera de troll", objective = "Leve 20 Frascos de Têmpera de Troll para Trenton Lumartelo em Geringontzan." },
        [3341] = { name = "Arauto do fim", objective = "André Rosado quer que você mate Amnennar, o Frigífero, e volte com a cabeça dele." },
        [3373] = { name = "A Essência de Erânicos", objective = "Coloque a Essência de Erânicos na Fonte de Essência encontrada neste covil do Templo Submerso." },
        [3380] = { name = "O Templo Submerso", objective = "Encontre Marlon Catarrebite em Tanaris." },
        [3444] = { name = "O círculo de pedra", objective = "Busque o Círculo de Pedra na oficina de Marlon Catarrebite em Vila Catraca." },
        [3445] = { name = "O Templo Submerso", objective = "Encontre Marlon Catarrebite em Tanaris." },
        [3446] = { name = "Nas profundezas", objective = "Encontre o Altar de Hakkar no Templo Submerso, que fica no Pântano das Mágoas." },
        [3447] = { name = "Segredo do círculo", objective = "Entre no Templo Submerso e descubra o segredo escondido no círculo de estátuas." },
        [3520] = { name = "Espíritos guinchadores", objective = "Capture os espíritos de 3 guinchadores em Feralas, e depois fale novamente com Yeh'kinya no Porto de Bondebico." },
        [3523] = { name = "O Flagelo do Urzal", objective = "Se você concordar em ajudar Belnistrasz, fale novamente com ele e devolva a pedra de juramento que ele lhe deu." },
        [3525] = { name = "O ídolo nefando", objective = "Escolte Belnistrasz até o ídolo dos javatuscos no Urzal dos Mortos.\n\nProteja Belnistrasz enquanto ele realiza o ritual para desativar o ídolo." },
        [3527] = { name = "A profecia de Mosh'aru", objective = "Leve a Primeira e a Segunda Tabuleta Mosh'Aru para Yeh'kinya, em Tanaris." },
        [3528] = { name = "O deus Hakkar", objective = "Leve o Ovo de Hakkar Cheio para Yeh'kinya, em Tanaris." },
        [3636] = { name = "Trazer a luz", objective = "O Arcebispo Benedito quer que você mate Amnennar, o Frigífero, no Urzal dos Mortos." },
        [3701] = { name = "As fumegantes Ruínas de Thaurissan", objective = "Vá até as Ruínas de Thaurissan, nas Estepes Ardentes, e descubra informações sobre as Relíquias de Thaurissan. Fale novamente com a Historiadora Real Arquefilis quando terminar." },
        [3702] = { name = "As fumegantes Ruínas de Thaurissan", objective = "Escute a Historiadora Real Arquefilis recontar a história de Thaurissan." },
        [3765] = { name = "A corrupção estrangeira", objective = "Fale com Gershala Umbrurmúrio em Auberdine." },
        [3801] = { name = "Legado dos Ferro Negro", objective = "Fale com Franclorn Forjífice se tiver interesse em obter uma chave para a parte principal da cidade." },
        [3802] = { name = "Legado dos Ferro Negro", objective = "Mate Fineous Forçanegra e recupere o grande martelo Ferrovil. Leve-o para o Santuário de Thaurissan e coloque-o na estátua de Franclorn Forjífice." },
        [3906] = { name = "Desarmonia das chamas", objective = "Vá até a pedreira da Montanha Rocha Negra e mate o Mestre Supremo Piro. Fale novamente com Coração Trovejante quando tiver cumprido essa tarefa." },
        [3907] = { name = "Desarmonia do fogo", objective = "Entre no Abismo Rocha Negra e encontre o Lorde Incendius. Mate-o e leve todas as informações que puder para o Coração Trovejante." },
        [3981] = { name = "Comandante Gor'shak", objective = "Encontre o Comandante Gor'shak no Abismo Rocha Negra.\n\nVocê se lembra que o tosco desenho incluía barras rabiscadas sobre o orc. Talvez você devesse procurar algum tipo de prisão." },
        [3982] = { name = "O que está acontecendo?", objective = "Defenda Gor'shak." },
        [4001] = { name = "O que está acontecendo?", objective = "Fale com Kharan Feromalho para obter informações sobre o sequestro da Princesa Moira Barbabronze. Leve as informações para Thrall em Orgrimmar.\n\nGor'shak mencionou que Kharan estava preso em uma cela próxima." },
        [4002] = { name = "Os Reinos do Leste", objective = "Fale com Thrall se estiver <preparado/preparada> para assumir a missão que ele planejou." },
        [4003] = { name = "O resgate real", objective = "Mate o Imperador Dagran Thaurissan e liberte a Princesa Moira Barbabronze do feitiço maligno." },
        [4004] = { name = "A princesa foi resgatada?", objective = "Fale novamente com Thrall!" },
        [4024] = { name = "O gosto das chamas", objective = "Vá para o Abismo Rocha Negra e mate Bael'gar.\n\nA única coisa que você sabe é que o gigante mora no Abismo Rocha Negra. Lembre-se de usar a Muda de Pele Alterada da Revoada Negra nos restos mortais de Bael'gar para capturar a Essência Abrasadora.\n\nLeve a Essência Abrasadora Aprisionada para Ciro Terepento." },
        [4061] = { name = "O levante das máquinas", objective = "Vá para as Estepes Ardentes e recupere 10 Estilhaços Elementais Fraturados para a Hierofante Theodora Malvadania.\n\nVocê se lembra que Theodora mencionou que os golens e elementais dessa região são uma fonte desses estilhaços." },
        [4062] = { name = "O levante das máquinas", objective = "Leve a Amostra de Estilhaço Elemental para Lotwil Viriato.\n\nSegundo Theodora, Lotwil estava escalado em um acampamento ao leste." },
        [4063] = { name = "O levante das máquinas", objective = "Encontre e mate Lorde Golem Argelmach. Leve a cabeça dele para Lotwil. Você também precisará coletar 10 Núcleos de Elemental Intactos dos Golens Rasgafúria e Constructos Armipotentes que protegem Argelmach. Você sabe disso porque é paranormal." },
        [4081] = { name = "SE VIR, MATE: Anões Ferro Negro", objective = "Desbrave o Abismo Rocha Negra e destrua aqueles invasores degenerados!\n\nO Senhor da Guerra Trincador quer que você mate 15 Guardas Furiadastra, 10 Carcereiros Furiadastra e 5 Soldados Rasos Furiadastra. Fale novamente com ele quando o trabalho estiver terminado." },
        [4082] = { name = "SE VIR, MATE: Oficiais Ferro Negro de Alta Patente", objective = "Vá até o Abismo Rocha Negra e destrua aqueles invasores degenerados!\n\nO Senhor da Guerra Trincador quer que você mate 10 Socorristas Furiadastra, 10 Soldados Furiadastra e 10 Oficiais Furiadastra. Fale novamente com ele quando o trabalho for concluído." },
        [4083] = { name = "Cálice Espectral", objective = "O cálice espectral flutua no ar, subindo e descendo lentamente... como se seguisse o bater de um coração agonizante." },
        [4121] = { name = "Situação precária", objective = "Escolte seu prisioneiro, Grark Lorkrub, pelas Estepes Ardentes, atravessando a Montanha Rocha Negra até chegar à Garganta Abrasadora.\n\nVocê se lembra de ter ouvido Lexlort dizer que mandaria seus homens esperar no outro lado para levar Grark sob custódia.\n\nVocê também vai precisar entregar os Grilhões de Tório para Lexlort." },
        [4122] = { objective = "Vá para as Estepes Ardentes e encontre Grark Lorkrub. Segundo Lexlort, ele foi visto pela última vez em uma imensa fortaleza Rocha Negra.\n\nQuando encontrar Grark Lorkrub, use os Grilhões de Tório para prendê-lo e levá-lo de volta à Garganta Abrasadora, passando pela Montanha Rocha Negra. Os homens de Lexlort estarão esperando do outro lado para levar Grark sob sua custódia." },
        [4123] = { name = "O Coração da Montanha", objective = "Leve o Coração da Montanha para Maxwort Uberraio nas Estepes Ardentes." },
        [4126] = { name = "Hurley Bafonegro", objective = "Leve a Receita Perdida de Cervaforte para Ragnar Cervaforte em Kharanos." },
        [4128] = { name = "Ragnar Cervaforte", objective = "Fale com Ragnar Cervaforte." },
        [4132] = { name = "Operação: Morte ao Forjaversa", objective = "Viaje para o Abismo Rocha Negra e mate o General Forjaversa! Fale novamente com o Senhor da Guerra Trincador quando a tarefa estiver concluída." },
        [4133] = { name = "Vivian Latumba", objective = "Fale com a Mestra Sombria Vivian Latumba em Karrath." },
        [4134] = { name = "Receita Perdida de Cervaforte", objective = "Leve a Receita Perdida de Cervaforte para Vivian Latumba em Karrath." },
        [4136] = { name = "Ribas Parafuseta", objective = "Leve a Cabeça do Ribas para Yuka Parafuseta nas Estepes Ardentes." },
        [4141] = { name = "Melco e Lário", objective = "Colha 15 Pétalas Sangrentas e fale novamente com Melco." },
        [4142] = { name = "Uma visita a Gregan", objective = "Leve uma Pétala Sangrenta para Gregan Cospechope em Feralas." },
        [4143] = { name = "Brumas do mal", objective = "Colha 5 amostras de Bruma de Atal'ai, depois fale novamente com Melco na Cratera Un'Goro." },
        [4145] = { name = "Lário e Melco", objective = "Cace 5 Açoitadeiras Pétala Sangrenta, 5 Látegas Pétala Sangrenta, 5 Esfoladoras Pétala Sangrenta e 5 Laçadoras Pétala Sangrenta para Lário, do Refúgio do Marshal." },
        [4146] = { name = "Combustível de fulminadora", objective = "Entregue a Fulminadora Descarregada e 5 amostras de Bruma de Atal'ai a Lário, no Refúgio do Marshal." },
        [4147] = { name = "Oficina do Marlon", objective = "Vá até a oficina de Marlon Catarrebite na Vila Catraca." },
        [4182] = { name = "Ameaça draconiana", objective = "Mate 15 Filhotes Negros, 10 Dragomorfos Negros, 4 Draconoides Negros e 1 Draco Negro. Fale novamente com Helendis Flumicórnio quando a tarefa estiver concluída." },
        [4183] = { name = "Os verdadeiros mestres", objective = "Viaje até Vila Plácida e entregue a Carta de Helendis Flumicórnio ao Magistrado Salomão." },
        [4184] = { name = "Os verdadeiros mestres", objective = "Viaje para Ventobravo e entregue o Apelo de Salomão ao Grão-lorde Bolvar Fordragon.\n\nBolvar reside na Bastilha Ventobravo." },
        [4185] = { name = "Os verdadeiros mestres", objective = "Fale com o Grão-lorde Bolvar Fordragon depois de falar com a Lady Katrana Prestor." },
        [4186] = { name = "Os verdadeiros mestres", objective = "Leve o Decreto de Bolvar para o Magistrado Salomão, em Vila Plácida." },
        [4201] = { name = "A poção do amor", objective = "Leve 4 Sangues-de-grom, 10 Veios de Prata Gigantes e a Ampola da Nagmara Cheia para a Lady Nagmara no Abismo Rocha Negra." },
        [4223] = { name = "Os verdadeiros mestres", objective = "Fale com o Oficial Maxwell nas Estepes Ardentes." },
        [4224] = { name = "Os verdadeiros mestres", objective = "Fale com João Roto para saber o destino do Marechal Vilasboas e fale novamente com o Oficial Maxwell quando tiver completado essa tarefa.\n\nVocê se lembra do Oficial Maxwell lhe dizendo para procurá-lo em uma caverna ao norte." },
        [4241] = { name = "Marechal Vilasboas", objective = "Viaje para a Montanha Rocha Negra, a noroeste, e entre no Abismo Rocha Negra. Descubra o que aconteceu com o Marechal Vilasboas.\n\nVocê se lembra de João Roto falando sobre Vilasboas ter sido arrastado para uma prisão." },
        [4242] = { name = "Esperança abandonada", objective = "Leve as más notícias ao Oficial Maxwell." },
        [4262] = { name = "Mestre Supremo Piro", objective = "Mate o Mestre Supremo Piro e fale novamente com Jalinda Ramo.\n\nVocê se lembra de Jalinda ter dito que Piro guarda a pedreira. Que tal procurar por lá?" },
        [4263] = { objective = "Encontre Lorde Incendius no Abismo Rocha Negra e destrua-o!" },
        [4264] = { name = "Bilhete amassado", objective = "Você pode ter acabado de descobrir algo que o Marechal Vilasboas estaria interessado em ver. Pode haver esperança, afinal." },
        [4282] = { name = "Um fiapo de esperança", objective = "Recupere as Informações Perdidas do Marechal Vilasboas.\n\nO Marechal Vilasboas acredita que as informações estão sendo mantidas pelo Lorde Golem Argelmach e pelo General Forjaversa." },
        [4286] = { name = "Produto de primeira", objective = "Viaje para o Abismo Rocha Negra e recupere 20 Pochetes Ferro Negro. Fale novamente com Oralius quando tiver completado a tarefa. Você supõe que os anões Ferro Negro de dentro do Abismo Rocha Negra carregam essa tal de \"pochete\"." },
        [4295] = { name = "Cerveja Pedrosa", objective = "Ah, cerveja! O que eu não faria por uma cervejinha Ferro Negro!! Rápido, eu estou ficando sóbrio de novo! Percebo porque sobriedade deixa minha visão embaçada... e você está começando a ficar que nem o <race> que eu matei semana passada!" },
        [4322] = { name = "Fuga da prisão!", objective = "Ajude o Marechal Vilasboas a recuperar seu equipamento e libertar seus amigos. Se conseguir, fale novamente com o Oficial Maxwell." },
        [4324] = { name = "Yuka Parafuseta", objective = "Fale com Yuka Parafuseta nas Estepes Ardentes." },
        [4341] = { name = "Kharan Feromalho", objective = "Viaje para Abismo Rocha Negra e encontre Kharan Feromalho.\n\nO Rei mencionou que Kharan estava preso lá — talvez seja bom procurar uma prisão." },
        [4342] = { name = "O conto de Kharan", objective = "Ouça Kharan Feromalho contar a história dele." },
        [4361] = { name = "Informante das más notícias", objective = "Volte a Altaforja e dê as más notícias ao Rei Magni Barbabronze." },
        [4362] = { name = "O destino do reino", objective = "Volte ao Abismo Rocha Negra e resgate a Princesa Moira Barbabronze das garras malignas do Imperador Dagran Thaurissan." },
        [4363] = { name = "A surpresa da Princesa", objective = "Volte a Altaforja e fale com o Rei Magni Barbabronze." },
        [4701] = { name = "Acabando com ela", objective = "Vá ao Pico da Rocha Negra e destrua a fonte da ameaça worg. Quando você deixou Helendis, ele gritou um nome: Halycon. É assim que os orcs se referem aos worgs." },
        [4724] = { name = "Senhora do matilha", objective = "Mate Halycon, senhora da matilha dos Worgs Machado Sangrento." },
        [4726] = { name = "Essência da Reprodução", objective = "Leve 8 Essências da Reprodução e o Draco-incarcinatrix 900 a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes." },
        [4729] = { name = "Mascotes exóticas do Kibler", objective = "Vá para o Pico da Rocha Negra e encontre Filhotes de Worg Machado Sangrento. Use a jaula para carregar essas pequenas feras. Leve um Filhote de Worg Enjaulado para Kibler." },
        [4734] = { name = "Congelar os ovos", objective = "Use o Protótipo de Ovosciloscópio em um ovo no Viveiro." },
        [4735] = { name = "Coleção de ovos", objective = "Leve 8 Ovos de Dragão Recolhidos e o Módulo Colectrônico a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes." },
        [4742] = { name = "Selo da Ascensão", objective = "Encontre as três gemas da autoridade: a Gema de Espinho Fúmeo, a Gema de Agulhapétrea e a Gema de Machado Sangrento. Entregue-as, junto com o Selo da Ascensão sem Adorno, a Vaelan.\n\nOs generais, como informado a você por Vaelan, são: Senhor da Guerra Voone dos Fumocardo, Grão-lorde Omokk dos Agulhapétrea e Lorde Supremo Wyrmthalak dos Machado Sangrento." },
        [4743] = { name = "Selo da Ascensão", objective = "Vá para o Pântano da Serpe, que fica no Pântano Vadeoso. Encontre o draco ancião Ardeluta e ataque-o sem misericórdia até que sua vontade seja quebrada.\n\nÉ nesse momento que você deve colocar o Selo da Ascensão de Metal Bruto em frente a essa fera imponente. Você deve então ser <rápido/rápida> para usar o Orbe de Energia Dracônica em sua forma enfraquecida e dominar suas faculdades mentais. Controle a fera e lance as chamas da Revoada Dragônica Negra sobre o Selo da Ascensão de Metal Bruto!" },
        [4764] = { name = "Broche do Finitudo", objective = "Leve o Broche do Finitudo para Mayara Asaluz nas Estepes Ardentes." },
        [4766] = { name = "Mayara Asaluz", objective = "Fale com Mayara Asaluz nas Estepes Ardentes." },
        [4768] = { name = "A tabuleta de Pedranegra", objective = "Leve a Tabuleta de Pedranegra à Umbramante Vivian Latumba, em Karrath." },
        [4769] = { name = "Vivian Latumba e a Tabuleta de Pedranegra", objective = "Fale com a Umbramante Vivian Latumba." },
        [4771] = { name = "Aposta da Aurora", objective = "Coloque a Aposta da Aurora na Sala de Exibição de Scolomântia. Derrote Vectus, depois fale novamente com Betina Bigozinco." },
        [4787] = { name = "O ovo velho", objective = "Leve o Ovo Velho para Yeh'kinya, em Tanaris." },
        [4788] = { name = "As últimas tabuletas", objective = "Leve a Quinta e a Sexta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris." },
        [4808] = { name = "Felnok Molaço", objective = "Leve a Carta de Vera para Felnok Molaço." },
        [4809] = { name = "Chifres de ventogelante", objective = "Leve 8 Chifres Inteiriços de Quimera Ventogelante para Felnok Molaço." },
        [4810] = { name = "Fale novamente com Vera", objective = "Leve o Pacote do Felnok para Vera Brequim, nas Estepes Ardentes." },
        [4862] = { name = "Nojento!", objective = "Vá para o Pico da Rocha Negra e colete 15 Ovos de Aranha do Pináculo para Kibler.\n\nPelo nome, é de se pensar que eles fiquem perto das aranhas." },
        [4866] = { name = "Leite materno", objective = "No coração do Pico da Rocha Negra você vai encontrar a Mãe Queimateia. Chame a atenção dela e deixe-a envenenar você. É bem provável que você precise matá-la também. Fale novamente com João Roto depois que for envenenad<o/a> para que ele possa \"ordenhar\" você." },
        [4867] = { name = "Urok Uivo-da-ruína", objective = "Leia o Pergaminho do Warosh. Traga o Mojo do Warosh para Warosh." },
        [4903] = { name = "O comando do Senhor da Guerra", objective = "Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida." },
        [4907] = { name = "Vera Brequim", objective = "Fale com Vera Brequim." },
        [4941] = { name = "A sabedoria de Eitrigg", objective = "Fale com Eitrigg em Orgrimmar. Quando tiver discutido o assunto com Eitrigg, busque o conselho de Thrall.\n\nVocê se lembra de ter visto Eitrigg nos aposentos de Thrall." },
        [4974] = { name = "Pela Horda!", objective = "Viaje para o Pico da Rocha Negra e mate o Chefe Guerreiro Laceral Mão Negra. Pegue sua cabeça e volte para Orgrimmar." },
        [4981] = { name = "Agente Biju", objective = "Vá ao Pico da Rocha Negra e descubra o que aconteceu com Biju." },
        [4982] = { name = "Pertences da Biju", objective = "Encontre os Pertences de Biju e devolva-os a ela. Ela mencionou tê-los guardado no nível mais profundo da cidade." },
        [5001] = { name = "Pertences da Biju", objective = "Encontre os Pertences de Biju e devolva-os a ela. Boa sorte!" },
        [5002] = { name = "Mensagem para Maxwell", objective = "Viaje para as Estepes Ardentes e dê as Informações de Biju para o Oficial Maxwell." },
        [5047] = { name = "Jonas Tiragosto ao seu dispor!", objective = "Fale com Málifus Trevamalho em Visteterna." },
        [5065] = { name = "As tabuletas Mosh'Aru perdidas", objective = "Leve a Terceira e a Quarta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris." },
        [5081] = { name = "A missão de Maxwell", objective = "Vá para o Pico da Rocha Negra e mate o Senhor da Guerra Voone, o Grão-lorde Omokk e o Lorde Supremo Wyrmthalak. Fale novamente com o Oficial Maxwell quando terminar o trabalho." },
        [5089] = { name = "Comando do General Drakkisath", objective = "Leve o Comando do General Drakkisath para o Oficial Maxwell nas Estepes Ardentes." },
        [5102] = { name = "O fim do General Drakkisath", objective = "Viaje de volta ao Pico da Rocha Negra e destrua o General Drakkisath. Depois, fale novamente com o Oficial Maxwell." },
        [5122] = { name = "O Medalhão da Fé" },
        [5125] = { name = "O ajuste de contas de Aurius", objective = "<name>, estou morrendo... mas minha alma está salva. Não tenho nem palavras para dizer o quanto devo a você. Por favor, leve isto consigo. Continue lutando, valente <class>!" },
        [5127] = { name = "A forja demoníaca", objective = "Viaje para o Pico da Rocha Negra e encontre Goraluk Rachadastra. Mate-o e use o Pique Manchado de Sangue no cadáver dele. Quando a alma dele tiver sido canalizada, o pique ficará Manchado de Almas.\n\nVocê também precisa encontrar o Peitoral Rúnico de Metal Bruto.\n\nLeve o Pique Manchado de Almas e o Peitoral Rúnico de Metal Bruto para Vegax, em Hibérnia." },
        [5160] = { name = "A protetorada-máter", objective = "Viaje para Hibérnia e encontre Haleh. Entregue para ela a Escama do Albi." },
        [5212] = { name = "A carne não mente", objective = "Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne." },
        [5213] = { name = "O agente ativo", objective = "Vá para Stratholme e vasculhe os zigurates. Encontre novos Dados do Flagelo e leve-os para Betina Bigozinco." },
        [5214] = { name = "O grande Ezra Carranca", objective = "Encontre a tabacaria de Ezra Carranca em Stratholme e recolha uma caixa do Tabaco da Lata do Carranca. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço." },
        [5243] = { name = "Casas do sagrado", objective = "Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente." },
        [5244] = { name = "Ruínas de Kel'Theril", objective = "Fale com Jaron Moldapedra na Aldeia Chuva Estelar." },
        [5245] = { name = "Espíritos atormentados de Kel'Theril", objective = "Use a Picareta do Jaron para encontrar os quatro Fragmentos da Relíquia dos Altaneiros. Leve-os para Aurora Clamacéus nas Terras Pestilentas Orientais." },
        [5246] = { name = "Fragmentos do passado", objective = "Encontre os Escritos Sagrados dos Altaneiros no Templo de Zin-Malor, em Azshara, e leve-os para Aurora Clamacéus, perto da Torre do Passo Norte nas Terras Pestilentas Orientais." },
        [5247] = { name = "Fragmentos do passado", objective = "Leve uma Barra de Tório Encantado, 5 Restaurações de Cristal e uma Ampola de Água Hedionda para Aurora Clamacéus perto da Torre do Passo Norte nas Terras Pestilentas Orientais." },
        [5250] = { name = "Chuva Estelar", objective = "Encontre a Chuva Estelar, em Hibérnia, e fale com Eol Correnoite." },
        [5251] = { name = "O arquivista", objective = "Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate." },
        [5262] = { name = "A verdade desaba sobre todos", objective = "Leve a Cabeça do Balnazzar para o Duque Nicolau Zverenhoff nas Terras Pestilentas Orientais." },
        [5263] = { name = "Acima e além", objective = "Desbrave Stratholme e destrua o Barão Rivendare. Corte sua cabeça e leve-a de volta para o Duque Nicolau Zverenhoff." },
        [5281] = { name = "As almas inquietas", objective = "Encontre Egan. Ele foi visto pela última vez nos arredores de Stratholme." },
        [5282] = { name = "As almas inquietas", objective = "Use o Canhão de Ectoplasma do Egan nos moradores fantasmagóricos e espectrais de Stratholme. Depois de livrá-los da forma de fantasma, use o canhão de novo e BLAU: liberdade!\n\nLiberte 15 Almas Inquietas, depois fale novamente com Egan." },
        [5341] = { name = "A fortuna da família Barov", objective = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, A Escritura de Montalvo, A Escritura da Serraria Tarren e A Escritura de Costa Sul. Fale novamente com Alexei Barov quando tiver terminado a tarefa." },
        [5343] = { name = "A fortuna da família Barov", objective = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, a Escritura de Montalvo, a Escritura da Serraria Tarren e a Escritura de Costa Sul. Fale novamente com Weldon Barov quando tiver terminado a tarefa." },
        [5382] = { name = "Doutor Theolen Krastinov, o Carniceiro", objective = "Encontre o Doutor Theolen Krastinov em Scolomântia. Destrua-o, depois queime os Restos Mortais de Eva Sarkhoff e os Restos Mortais de Lucien Sarkhoff. Fale novamente com Eva Sarkhoff depois que tiver terminado a tarefa." },
        [5384] = { name = "Kirtonos, o Arauto", objective = "Volte a Scolomântia com o Sangue dos Inocentes em mãos. Encontre a varanda e derrame o Sangue dos Inocentes no braseiro. Kirtonos virá na intenção de devorar sua alma.\n\nLute com bravura, não dê nenhuma brecha! Destrua Kirtonos e fale novamente com Eva Sarkhoff." },
        [5461] = { name = "Ras Friomúrmuro, o humano", objective = "Viaje para o Planalto Arathi, até as ruínas de Stromgarde. Vasculhe Stromgarde em busca de um Livro de Recordações. Se encontrar o item, retorne com ele até o Magistrado Marduque." },
        [5462] = { name = "Ras Friomúrmuro, o moribundo", objective = "Viaje para a Capela Esperança da Luz, nas Terras Pestilentas Orientais, e procure por Leonid Bartolomeu, o Venerado. Mostre a ele o Livro de Recordações e conte tudo o que descobriu." },
        [5463] = { name = "Dádiva de Menethil", objective = "Vá até Stratholme e encontre a Dádiva de Menethil. Ponha o Livro de Recordações no solo profanado." },
        [5464] = { name = "Dádiva de Menethil", objective = "Leve a Lembrança Vinculada para Leonid Bartolomeu, nas Terras Pestilentas Orientais." },
        [5465] = { name = "Lembrança Vinculada", objective = "Fale novamente com o Magistrado Marduque, no Castro das Flechas. Mostre-lhe a Lembrança Vinculada." },
        [5466] = { name = "Ras Friomúrmuro, o lich", objective = "Procure por Ras Friomúrmuro em Scolomântia. Quando o encontrar, use a Lembrança Vinculada em sua versão morto-vivo. Quando conseguir transformá-lo novamente em mortal, mate-o e recupere a Cabeça Humana de Ras Friomúrmuro. Leve a cabeça de volta ao Magistrado Marduque." },
        [5515] = { name = "Saco de Horrores de Krastinov", objective = "Localize Janice Barov em Scolomântia e a destrua. Recupere o Saco de Horrores de Krastinov do cadáver dela. Entregue o saco a Eva Sarkhoff." },
        [5518] = { name = "O traje de ogro Gordok", objective = "Leve 4 Peças de Runatrama, 8 Couros Rústicos, 2 Fios Rúnicos e Tanino Ôgrico para Fiapo Agulhacerta. Atualmente, ele está acorrentado dentro da ala Gordok do Gládio Cruel." },
        [5522] = { name = "Leonid Bartolomeu", objective = "Leve os Ovos Congelados para Leonid Bartolomeu, nas Terras Pestilentas Orientais." },
        [5525] = { name = "Liberdade ainda que tardia", objective = "É chamada de chave dos grilhões dos Gordok. Bom, pelo menos é esse o nome que essas coisinhas fofas usam. Acho que qualquer um dos ogros pode ter a sua, mas é mais provável que os guardas tenham um exemplar...\n\nPeraí, onde é que eu estou com a cabeça? Já está com você, não é mesmo? Está aqui?" },
        [5526] = { name = "Pedaços de Vinhavil", objective = "Encontre a Vinhavil no Gládio Cruel e obtenha uma lasca dela. É bem provável que você só consiga encontrar uma depois da derrota de Azzin, o Selvamorfo. Use o Relicário da Pureza para selar a lasca com segurança e leve-a de volta para Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua." },
        [5527] = { name = "Relicário da Pureza", objective = "Viaje até Silithus e procure um Relicário da Pureza dentro das ruínas da Vila do Vento Sul. Se conseguir encontrá-lo, regresse com ele até Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua." },
        [5529] = { name = "Filhotes Pestilentos", objective = "Mate 20 Filhotes Pestilentos, depois fale novamente com Betina Bigozinco, na Capela Esperança da Luz." },
        [5531] = { name = "Betina Bigozinco", objective = "Leve os Ovos Congelados para Betina Bigozinco." },
        [5542] = { name = "Cães demoníacos", objective = "Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída." },
        [5543] = { name = "Céu tingido de sangue", objective = "Mate 30 Quirópragos e fale novamente com Tirion Fordring." },
        [5544] = { name = "Carne de verme carniceiro", objective = "Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro." },
        [5722] = { name = "Em busca da algibeira perdida", objective = "Investigue as Cavernas Ígneas em busca do corpo de Mauren Temível Totem e procure quaisquer itens de interesse." },
        [5723] = { name = "Testando a força do inimigo", objective = "Procure as Cavernas Ígneas em Orgrimmar e mate 8 Troggs Iraflama e 8 Xamãs Iraflama, depois fale novamente com Rahauro no Penhasco do Trovão." },
        [5724] = { name = "Devolvendo a algibeira perdida", objective = "Leve a Algibeira do Temível Totem para Rahauro no Penhasco do Trovão." },
        [5725] = { name = "O poder de destruir...", objective = "Leve os livros \"Feitiços da Sombra\" e \"Encantamentos do Éter\" para Varimatras na Cidade Baixa." },
        [5726] = { name = "Inimigos ocultos", objective = "Leve uma Insígnia do Tenente para Thrall em Orgrimmar." },
        [5727] = { name = "Inimigos ocultos", objective = "Leve a Insígnia do Tenente para Neeru Cortafogo e fale com ele. Avalie se ele acredita que você é um membro da Lâmina Ardente e, depois, fale novamente com Thrall em Orgrimmar." },
        [5728] = { name = "Inimigos ocultos", objective = "Mate Bazzalan e Jergosh, o Invocador e fale novamente com Thrall em Orgrimmar." },
        [5742] = { name = "Redenção", objective = "Escute o que Tirion Fordring tem a dizer." },
        [5761] = { name = "Mate a besta", objective = "Entre nas Cavernas Ígneas e mate Taragaman, o Famélico, depois leve o coração dele para Neeru Cortafogo em Orgrimmar." },
        [5781] = { name = "Elixir de memórias esquecidas", objective = "Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo." },
        [5845] = { name = "Da honra perdida", objective = "Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo." },
        [5846] = { name = "Do amor e da família", objective = "Viaje para a ilha de Castro das Flechas, na região centro-sul das Terras Pestilentas, e procure pistas sobre o paradeiro da pintura." },
        [5848] = { name = "Do amor e da família", objective = "Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo.\n\nLeve a pintura de volta para Tirion Fordring." },
        [5961] = { name = "O campeão da Rainha Banshees", objective = "Fale com Nathanos, o Arauto da Praga nas Terras Pestilentas Orientais. Dizem que ele fixou residência no Sítio dos Marris." },
        [6022] = { name = "Matar com propósito", objective = "Vá ao Cruzamento de Corin, a leste, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva em menos de 10 minutos. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada." },
        [6042] = { name = "Pequenos transtornos da Morte-em-Vida", objective = "Mate 20 Quirópragos Nóxios e 10 Quirópragos Monstruosos. Fale novamente com Nathanos Arauto da Praga quando você tiver terminado." },
        [6133] = { name = "A mando do lorde patrulheiro", objective = "Vá à fronteira norte das Terras Pestilentas Orientais e recupere os Arquivos de Quel'Thalas em algum lugar do Abrigo Quel'Lithien.\n\nVocê também precisa matar 8 Patrulheiros, 8 Trilheiros e 8 Mateiros." },
        [6135] = { name = "Ah, Quiroscuro, como vos odeio...", objective = "Encontre Quiroscuro e mate-o. Do cadáver, extraia um Tufo de Pele de Quiroscuro e leve para Nathanos Arauto da Praga.\n\nDizem que Quiroscuro vaga pelo campo ao norte do Sítio dos Marris." },
        [6136] = { name = "O corpulento", objective = "Encontre Brocassangre nos ermos do norte das Terras Pestilentas e destrua-o. Fale novamente com Nathanos Arauto da Praga quando tiver cumprido a missão." },
        [6141] = { name = "Irmão Anton", objective = "Fale com o Irmão Anton na Desolação." },
        [6163] = { objective = "Vá a Stratholme e mate Ramstein, o Devorador. Leve a cabeça dele como souvenir para Nathanos." },
        [6402] = { name = "Encontro marcado em Ventobravo", objective = "Viaje a Ventobravo e vá até os portões da cidade. Fale com o Escudeiro Rui para que ele avise ao Marechal Vilasboas que você chegou." },
        [6403] = { name = "O grande baile de máscaras", objective = "Siga Reginaldo Vilasboas através de Ventobravo. Proteja-o de qualquer ataque!" },
        [6501] = { name = "O Olho do Dragão", objective = "Você deve vasculhar o mundo em busca de uma criatura capaz de restaurar o poder do Fragmento do Olho do dragão. A única informação que você tem sobre essa criatura é que ela existe." },
        [6502] = { name = "Amuleto da Chama Dracônica", objective = "Confronte o General Drakkisath e consiga o Sangue do Campeão dos Dragões Negros. Drakkisath está na sala do trono atrás dos Salões da Ascensão, no Pico da Rocha Negra." },
        [6521] = { name = "Uma aliança profana", objective = "Leve a cabeça do Embaixador Malcin para Varimatras, na Cidade Baixa." },
        [6522] = { name = "Uma aliança profana", objective = "Leve o Pergaminho Pequeno para Varimatras, na Cidade Baixa." },
        [6561] = { name = "Vilania das Profundezas", objective = "Leve a cabeça do Senhor do Crepúsculo Kelris para Bashana Runa Totem, no Penhasco do Trovão." },
        [6562] = { name = "Problemas nas Profundezas", objective = "Fale com Je'neu Sancrea no Vale Gris." },
        [6563] = { name = "A essência de Aku'mai", objective = "Entregue 20 Safiras de Aku'Mai a Je'neu Sancrea no Vale Gris." },
        [6564] = { name = "Lealdade aos Deuses Antigos", objective = "Leve o Bilhete Úmido para Je'neu Sancrea, no Vale Gris." },
        [6565] = { name = "Lealdade aos Deuses Antigos", objective = "Mate Lorgus Jett nas Profundezas Negras e depois fale novamente com Je'neu Sancrea no Vale Gris." },
        [6566] = { name = "O que o vento carrega", objective = "Ouça Thrall." },
        [6567] = { name = "O campeão da Horda", objective = "Procure Rexxar. O Chefe Guerreiro <o/a> instruiu quanto ao paradeiro dele. Procure nos caminhos de Desolação, entre a Cordilheira das Torres de Pedra e Feralas." },
        [6568] = { name = "O testamento de Rexxar", objective = "Leve o Testamento de Rexxar para Myranda, a Bruxa Velha, nas Terras Pestilentas Ocidentais." },
        [6569] = { name = "Ilusões ópticas", objective = "Vá para o Pico da Rocha Negra e colete 20 Olhos de Dragomorfo Preto. Fale novamente com Myranda, a Bruxa Velha, depois que tiver terminado a tarefa." },
        [6570] = { name = "Ardeluta", objective = "Vá até o Pântano da Serpe, no Pântano Vadeoso, e procure o Covil de Ardeluta. Quando estiver lá, use o Amuleto de Subversão Dracônica e fale com Ardeluta." },
        [6582] = { name = "O teste dos crânios: Áugure", objective = "Encontre e mate o Áugure, o draco da Revoada Dragônica Azul. Arranque a cabeça do draco morto e leve-a para Ardeluta.\n\nVocê sabe que o Áugure se encontra em Hibérnia." },
        [6583] = { name = "O teste dos crânios: Somnus", objective = "Destrua Somnus, o draco campeão da Revoada Verde. Pegue seu crânio e leve-o para Ardeluta." },
        [6584] = { name = "O teste dos crânios: Chronalis", objective = "Guardando as Cavernas do Tempo no Deserto de Tanaris, encontra-se Chronalis, filho de Nozdormu. Destrua-o e leve seu crânio para Ardeluta." },
        [6585] = { name = "O teste dos crânios: Axtroz", objective = "Vá para Grim Batol e encontre Axtroz, o draco campeão da Revoada Vermelha. Destrua-o e arranque sua cabeça. Leve o crânio para Ardeluta." },
        [6601] = { name = "Ascensão...", objective = "Pelo jeito, a farsa chegou ao fim. Você já sabe que o Amuleto de Subversão Dracônica criado por Myranda, a Bruxa Velha, não vai funcionar no Pico da Rocha Negra. Você devia ir atrás de Rexxar e explicar a situação. Mostre a ele o Amuleto da Chama Dracônica Fraco. Pode ser que ele saiba o que fazer." },
        [6602] = { name = "Sangue do Campeão dos Dragões Negros", objective = "Viaje para o Pico da Rocha Negra e mate o General Drakkisath. Recolha seu sangue e leve-o para Rexxar." },
        [6626] = { name = "A hoste do mal", objective = "Mate 8 Guerreiros do Urzal, 8 Tecespinhos do Urzal e 8 Sectários da Cabeça da Morte, depois fale novamente com Mírian Lunacanto perto da entrada do Urzal dos Mortos." },
        [6627] = { name = "Teste de saber", objective = "Responda à pergunta de Braug Espírito Turvo corretamente, depois fale com ele novamente. Quando você estiver pront<o/a>, ele estará na Cordilheira das Torres de Pedra." },
        [6628] = { name = "Teste de saber", objective = "Responda à pergunta de Pasqual Fintallas corretamente, depois fale com ele novamente. Quando você estiver pront<o/a>, ele estará na Cidade Baixa." },
        [6921] = { name = "Nas ruínas", objective = "Leve o Núcleo das Profundezas para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris." },
        [6922] = { name = "O Barão Aquanis", objective = "Leve o Globo d'Água Estranho para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris." },
        [6981] = { name = "A lasca faiscante", objective = "Viaje para a Vila Catraca e procure alguém que possa contar mais alguma coisa sobre a lasca faiscante.\n\nDepois, entregue a lasca conforme as orientações." },
        [7028] = { name = "Raízes do mal", objective = "Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação." },
        [7029] = { name = "A corrupção de Torpelíngua", objective = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.\n\nUse a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir.\n\nCure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Vark Chaga de Guerra, na Aldeia Pescassombra." },
        [7041] = { name = "A corrupção de Torpelíngua", objective = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.\n\nUse a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir.\n\nCure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Talendria, no Posto do Nijel." },
        [7044] = { name = "Lendas de Maraudon", objective = "Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras.\n\nEncontre um jeito de falar com Celebras." },
        [7046] = { name = "O Cetro de Celebras", objective = "Ajude Celebras, o Redimido, a criar o Cetro de Celebras.\n\nFale com ele quando o ritual estiver concluído." },
        [7064] = { name = "Corrupção da terra e dos grãos", objective = "Mate a Princesa Theradras e fale novamente com Selendra perto da Aldeia Pescassombra, na Desolação." },
        [7065] = { name = "Corrupção da terra e dos grãos", objective = "Mate a Princesa Theradras e fale novamente com o Guardião Marandis no Posto do Nijel, na Desolação." },
        [7066] = { name = "A semente da vida", objective = "Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida." },
        [7067] = { name = "As instruções do pária", objective = "Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação." },
        [7068] = { name = "Fragmentos de lascanegra", objective = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para Uthel'nay, em Orgrimmar." },
        [7070] = { name = "Fragmentos de lascanegra", objective = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para o Arquimago Tervosh, em Theramore, na costa do Pântano Vadeoso." },
        [7201] = { name = "O último elemento", objective = "Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais." },
        [7441] = { name = "Pusillin e o Ancião Azj'Tordin", objective = "Vá ao Gládio Cruel e encontre o Diabrete Pusillin. Convença-o usando qualquer meio que for necessário a lhe dar o Livro de Encantamentos de Azj'Tordin.\n\nFale novamente com Azj'Tordin no Pavilhão Lariss, em Feralas, caso você recupere o Livro de Encantamentos." },
        [7461] = { name = "A loucura intrínseca", objective = "Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará.\n\nDestrua o terrível demônio que fica no coração da Prisão de Immol'thar. Por fim, enfrente o Príncipe Tortheldrin, no Ateneu.\n\nFale novamente com a Anciã Shen'dralar, no pátio, após cumprir a missão." },
        [7462] = { name = "O tesouro de Shen'dralar", objective = "Volte ao Ateneu e encontre o Tesouro dos Shen'dralar. Reclame sua recompensa!" },
        [7463] = { name = "Bebida arcana", objective = "Vá ao Distrito Lenhatorta, no Gládio Cruel, e mate o elemental da água, Rebentágua. Leve a Essência de Rebentágua para o Erudito Lydros, no Ateneu." },
        [7481] = { name = "Lendas élficas", objective = "Procure Kariel Winthalus em Gládio Cruel. Reporte-se, então, ao Sábio Korolusk na Aldeia Mojache com qualquer informação que você possa encontrar." },
        [7482] = { name = "Lendas élficas", objective = "Procure Kariel Winthalus em Gládio Cruel. Reporte-se, então, à Erudita Runacardos em Plumaluna com qualquer informação que você encontrar." },
        [7483] = { name = "Incunábulo de Rapidez", objective = "Leve 1 Incunábulo de Rapidez, 1 Diamante Preto Límpido, 2 Estilhaços Brilhantes Grandes, e 2 Sangues dos Heróis ao Erudito Lydros no Gládio Cruel para receber um Arcano de Rapidez." },
        [7484] = { name = "Incunábulo de Concentração", objective = "Leve 1 Incunábulo de Concentração, 1 Diamante Preto Límpido, 4 Estilhaços Brilhantes Grandes, e 2 Peles de Sombra ao Erudito Lydros no Gládio Cruel para receber um Arcano de Concentração." },
        [7485] = { name = "Incunábulo de Proteção", objective = "Leve 1 Incunábulo de Proteção, 1 Diamante Preto Límpido, 2 Estilhaços Brilhantes Grandes e 1 Sutura de Abominação Puída ao Erudito Lydros no Gládio Cruel para receber um Arcano de Proteção." },
        [7488] = { name = "A teia de Letendris", objective = "Leve a Teia de Letendris para Latrônicus Lunalança no Domínio de Plumaluna, em Feralas." },
        [7489] = { name = "A teia de Letendris", objective = "Leve a Teia de Letendris para Talo Casco de Espinhos na Aldeia Mojache, em Feralas." },
        [7492] = { name = "Aldeia Mojache", objective = "Fale com Talo Casco de Espinhos na Aldeia Mojache, em Feralas." },
        [7494] = { name = "Domínio de Plumaluna", objective = "Fale com Latrônicus Lunalança no Domínio de Plumaluna, em Feralas." },
        [7498] = { name = "Garona: Um Estudo sobre Furtividade e Traição", objective = "Devolva o livro aos legítimos donos." },
        [7499] = { name = "Códice de Defesa", objective = "Devolva o livro aos legítimos donos." },
        [7500] = { name = "Livro de Receitas do Arcanista", objective = "Devolva o livro aos legítimos donos." },
        [7501] = { name = "A Luz e Como Ativá-la", objective = "Devolva o livro aos legítimos donos." },
        [7502] = { name = "Sombras Agrilhoantes", objective = "Devolva o livro aos legítimos donos." },
        [7503] = { name = "A Grande Corrida dos Caçadores", objective = "Devolva o livro aos legítimos donos." },
        [7504] = { name = "Caçarolas: O Que a Luz Não lhe Contará", objective = "Devolva o livro aos legítimos donos." },
        [7505] = { name = "O Choque Gélido e Você", objective = "Devolva o livro aos legítimos donos." },
        [7506] = { name = "O Sonho Esmeralda...", objective = "Devolva o livro aos legítimos donos." },
        [7507] = { name = "O compêndio de Foror", objective = "Leve o Compêndio de Foror sobre Matar Dragões para o Ateneu." },
        [7563] = { name = "Raiva de Sangue", objective = "Leve 30 garrafas de Sangue de Fera em Fúria para Mor'zul Trazangre nas Estepes Ardentes." },
        [7564] = { name = "Olholouco", objective = "Leve o Caixote de Sangue para Gorzeeki Olholouco nas Estepes Ardentes." },
        [7604] = { name = "Contrato vinculante", objective = "Entregue o Contrato da Irmandade do Tório para Lokhtos Umbrarganha, caso tenha interesse em receber as instruções para Sulfuron." },
        [7623] = { name = "Lorde Nihilus", objective = "Compre Poções Sombrias de Gorzeeki nas Estepes Ardentes.\n\nUse as poções para viajar através de Jaedenar e fale com Lorde Nihilus." },
        [7624] = { name = "Ulathek, o traidor", objective = "Confronte Ulathek, depois leve o Coração do Traidor para o Lorde Nihilus em Jaedenar." },
        [7625] = { name = "Poeira Estelar Zorothiana", objective = "Compre Poeira Estelar Zorothiana de Ur'dan. Leve-a para Gorzeeki Olholouco nas Estepes Ardentes." },
        [7626] = { name = "Sino de Defimura", objective = "Leve 10 Elixires de Poder Sombrio para Gorzeeki Olholouco nas Estepes Ardentes." },
        [7627] = { name = "Roda da Marcha Negra", objective = "Leve 6 Estilhaços Brilhantes Grandes e 25 Minérios de Ferro Negro para Gorzeeki nas Estepes Ardentes." },
        [7628] = { name = "Vela do Juízo Final", objective = "Leve 35 Escamas de Dragão Negro para Gorzeeki Olholouco nas Estepes Ardentes." },
        [7629] = { name = "Entrega de diabrete", objective = "Leve o Diabrete numa Jarra para o laboratório de alquimia em Scolomântia. Depois que o pergaminho for criado, devolva a jarra para Gorzeeki Olholouco." },
        [7630] = { name = "Arcanita", objective = "Leve 3 Barras de Arcanita para Gorzeeki nas Estepes Ardentes." },
        [7631] = { name = "Corcel Medonho de Zoroth", objective = "Leia as Instruções de Mor'zul. Evoque um Corcel Medonho Zorothiano, derrote-o e então vincule o espírito dele a você." },
        [7637] = { name = "Ênfase em sacrifício", objective = "Viaje para Altaforja e obtenha o Incensório de Exorcismo do Sumo Sacerdote Rohan. Você precisará fazer uma doação de 150 moedas de ouro para obtê-lo." },
        [7639] = { name = "O devido julgamento", objective = "Leve o Incensório de Exorcismo para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo." },
        [7640] = { name = "Exorcizando a Várzea do Medo", objective = "Use o Incensório de Exorcismo para expulsar os espíritos que atormentam a Várzea do Medo. Quando você tiver eliminado 25 Espíritos da Várzea do Medo, fale novamente com Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo." },
        [7641] = { name = "O trabalho de Grimand Elmore", objective = "Fale com Grimand Elmore em Ventobravo no Distrito dos Anões de Ventobravo." },
        [7642] = { name = "Coleta de produtos", objective = "Leve 40 Runatramas, 6 Barras de Arcanita, 10 Lágrimas-de-arthas, 5 ampolas de Água Benta de Stratholme e 150 moedas de ouro para Grimand Elmore, no Distrito dos Anões de Ventobravo." },
        [7643] = { name = "O Espírito Equino Antigo", objective = "Obtenha uma ração de cavalo especial para alimentar o cavalo espiritual. Aparentemente, Judite Castanheira, que vive na Costa Sul, é a fornecedora da tal ração.\n\nEntre na masmorra de Gládio Cruel, em Feralas, e mate Gavíneo Lenhatorta. Isso libertará o Espírito Equino Antigo. Alimente-o com a ração de cavalo especial, o que acalmará o espírito. Finalmente, dê-lhe a Barda de Arcanita para que ele a abençoe." },
        [7644] = { name = "Barda de Arcanita Abençoada", objective = "Leve a Barda de Arcanita Abençoada para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo." },
        [7645] = { name = "Ração de Cavalo Enriquecida com Mana", objective = "Obtenha 20 Biscoitos de Maná Enriquecido — o ingrediente chave para fazer Ração de Cavalo Enriquecida com Mana — para Judite Castanheira da Costa Sul, no Contraforte de Eira dos Montes. A Aurora Argêntea é conhecida como a única fornecedora dos biscoitos.\n\nVocê também precisa dar a ela 50 moedas de ouro para a apaziguar os ânimos dela." },
        [7646] = { name = "O Cristal Divinatório", objective = "Leve um Diamante Azerotiano e um Diamante Preto Límpido para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo." },
        [7647] = { name = "Julgamento e redenção", objective = "Use o Cristal Divinatório no coração do porão do Grande Ossário, em Scolomântia. Isso invocará espíritos que você precisará julgar. A derrota dos espíritos evocará o Cavaleiro da Morte Noctilatrus. Derrote-o e reclame a alma perdida do corcel caído.\n\nEntregue a Alma Redimida do Corcel e a Barda Encantada Abençoada ao Corcel Caído de Noctilatrus." },
        [7648] = { name = "O melhor trabalho de Grimand", objective = "Leve a Barda de Arcanita para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo para que ele a inspecione." },
        [7667] = { name = "Ajuda material", objective = "Se você tiver interesse em ajudar Sagorne Monta Crista, no Vale da Sabedoria de Orgrimmar, leve para ele um Diamante Azerotiano e um Diamante Preto Límpido." },
        [7668] = { name = "A ameaça de Noctilatrus", objective = "Use o Cristal Divinatório no coração do porão do Grande Ossário, em Scolomântia. Isso invocará espíritos que você precisará enfrentar. A derrota dos espíritos evocará o Cavaleiro da Morte Noctilatrus. Derrote-o.\n\nLeve a Cabeça de Noctilatrus para Sagorne Monta Crista, no Vale da Sabedoria, em Orgrimmar." },
        [7703] = { name = "Negócios pendentes", objective = "Encontre as Manoplas do Poder de Gordok e devolva-as para o Capitão Kebrapaw no Gládio Cruel.\n\nDe acordo com Kebrapaw, a \"história de ancião\" diz que Tortheldrin — um elfo \"medonho\" que se diz príncipe — roubou as manoplas de um dos reis Gordok." },
        [7761] = { name = "Comando do Mão Negra", objective = "Sem dúvida, um orc excepcionalmente burro. Parece que para acessar o Orbe de Comando é necessário ter a Marca de Drakkisath.\n\nA carta indica que o próprio General Drakkisath a guarda. Talvez você devesse investigar." },
        [7848] = { name = "Harmonização com o Núcleo", objective = "Vá ao portal da entrada do Núcleo Derretido no Abismo Rocha Negra e recupere um Fragmento de Núcleo. Fale novamente com Lothos Fendespéril na Montanha Rocha Negra após recuperar o Fragmento de Núcleo." },
        [8151] = { name = "O amuleto do caçador", objective = "Encontre Ogtinc em Azshara." },
        [8153] = { name = "Galhada de ginete", objective = "Leve um par de Galhadas Perfeitas de Ginete para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath." },
        [8231] = { name = "Furando onda", objective = "Leve 6 Escamas de Fura-ondas para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath." },
        [8232] = { name = "O draco verde", objective = "Leve o Dente de Morphaz para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath." },
        [8233] = { name = "Um pedido simples", objective = "Fale com Lorde Jorach Corvoforte na Mansão de Corvoforte." },
        [8234] = { name = "Saco lazúli lacrado", objective = "Recupere o Saco Lazúli Lacrado com o Xamã Presamatos, em Azshara. Então o leve para o Arquimago Tauriel, também em Azshara." },
        [8235] = { name = "Fragmentos codificados", objective = "Leve 10 Fragmentos Codificados para o Arquimago Tauriel em Azshara." },
        [8236] = { name = "A chave lazúli", objective = "Leve a Chave Lazúli para o Lorde Jorach Corvoforte." },
        [8250] = { name = "Magiaria", objective = "Procure Sanath Lim-yo e consiga o transporte para ver o Arquimago Tauriel." },
        [8251] = { name = "Pó Mágico", objective = "Leve 10 Poeiras Reluzentes para o Arquimago Tauriel." },
        [8252] = { name = "Coral de sirenas", objective = "Obtenha 6 Corais Encantados e entregue-os ao Arquimago Tauriel." },
        [8253] = { name = "A destruição de Morphaz", objective = "Recupere o Estilhaço Arcano de posse de Morphaz e fale novamente com o Arquimago Tauriel." },
        [8254] = { name = "Ajuda aos cenarianos", objective = "Encontre Ogtinc em Azshara." },
        [8255] = { name = "Ginetes sagrados", objective = "Obtenha 4 Glândulas de Ginete Saudável leve-as para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath." },
        [8256] = { name = "A linfa de morte-viva", objective = "Obtenha uma Linfa de Morte-viva para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath." },
        [8257] = { name = "Sangue de Morphaz", objective = "Mate Morphaz no templo submerso de Atal'Hakkar e leve o sangue dele para Greta Musgo no Casco na Selva Maleva. A entrada do templo submerso fica no Pântano das Mágoas." },
        [8410] = { name = "Mestre dos elementos", objective = "Colete uma amostra de ar, fogo, terra e água para Bath'rah, o Vigia dos Ventos." },
        [8412] = { name = "Totem de espírito", objective = "Leve as partes para Bath'rah, o Vigia dos Ventos, fazer o totem de espírito." },
        [8413] = { name = "O Vodu", objective = "Leve as Penas Vodu para Bath'rah, o Vigia dos Ventos." },
        [8414] = { name = "Dissipando o mal", objective = "Colete 20 Pedras do Flagelo do Lacaio e leve-as ao Sumo Sacerdote Thel'danis nas Terras Pestilentas Ocidentais." },
        [8415] = { name = "Morro do Ventogelante", objective = "Fale com o Comandante Ashlam Punhobom no Morro do Ventogelante." },
        [8416] = { name = "Pedras do Flagelo inertes", objective = "Leve a Pedra do Flagelo Inerte ao Comandante Ashlam Punhobom no Morro do Ventogelante." },
        [8417] = { name = "Um espírito atormentado", objective = "Fale com o Herói Caído da Horda na entrada da Barreira do Inferno." },
        [8418] = { name = "Forjando o megalito", objective = "Leve as Penas Vodu para Ashlam Punhobom." },
        [8419] = { name = "Pedido de diabrete", objective = "Leve um pedaço de Tecido Vil para Diabretim, em Selva Maleva." },
        [8420] = { name = "Quente e pinicante", objective = "Leve um pedaço de Tecido Vil para Diabretim, em Selva Maleva." },
        [8421] = { name = "O enchimento errado", objective = "Leve 10 pedaços de Madeira Podre e 4 Essências de Peçonha para Diabretim em Selva Maleva." },
        [8422] = { name = "Penas de troll", objective = "Leve um total de 6 Penas Vodu dos trolls do templo submerso." },
        [8423] = { name = "Parentesco guerreiro", objective = "Mate 7 Javiltuscos na Barreira do Inferno e fale novamente com o Herói Caído da Horda." },
        [8424] = { name = "Guerra aos devotos da sombra", objective = "Mate os Devotos da Sombra na Barreira do Inferno e fale novamente com o Herói Caído da Horda." },
        [8425] = { name = "Penas Vodu", objective = "Leve as Penas Vodu dos trolls do Templo Submerso para o Herói Caído da Horda." },
        [8945] = { name = "Súplica de um morto", objective = "Entre em Stratholme e resgate Ysida Harmon do Barão Rivendare." },
        [8948] = { name = "Um velho amigo de Anthion", objective = "Leve o Estandarte Incompleto da Provocação para Falrin Arboril na biblioteca do Gládio Cruel." },
        [8949] = { name = "A vendeta de Falrin", objective = "Colete 25 Colares de Guerra dos Ogros dos Ogros no Gládio Cruel ou no Pico da Rocha Negra e fale novamente com Falrin Arboril no Ateneu do Gládio Cruel." },
        [8950] = { name = "O encantamento do instigador", objective = "Leve os seguintes materiais para Falrin Arboril no Gládio Cruel: 1 Essência de Espírito Zombeteiro, 4 Runas Negras e 8 Estilhaços Brilhantes Grandes." },
        [9015] = { name = "O desafio", objective = "Viaje até o Círculo da Lei no Abismo Rocha Negra e coloque o Estandarte da Provocação no centro enquanto ouve a sentença do Supremo Juiz Durólito. Mate Theldren e seus gladiadores e fale novamente com Anthion Harmon nas Terras Pestilentas Orientais em posse da primeira parte do amuleto de Lorde Valthalak." },
