        [1152] = { name = "Испытание знаний", objective = "Найдите Брауга Тусклый Дух возле входа в Туннель Когтя в Когтистых горах." },
        [1154] = { name = "Испытание знаний", objective = "Найдите книгу \"Наследие Аспектов\" и вернитесь к Браугу Тусклому Духу ко входу в Туннель Когтя." },
        [1159] = { name = "Испытание знаний", objective = "Найдите Парквела Финталласа в Подгороде." },
        [1160] = { name = "Испытание знаний", objective = "Найдите книгу \"Истоки угрозы нежити\" и отнесите ее Парквелу Финталласу в Подгород." },
        [1198] = { name = "В поисках Талрида", objective = "Найдите стража Талрида из ордена Серебряного Рассвета в Непроглядной Пучине." },
        [1199] = { name = "Наступление сумерек", objective = "Принесите 10 подвесок сумерек стражу Менадосу из ордена Серебряного Рассвета в Дарнасс." },
        [1200] = { name = "Злодейство в Непроглядной Пучине", objective = "Принесите голову повелителя сумрака Келриса Рассветному дозорному Селгорму в Дарнасс." },
        [1221] = { name = "Корни Синелиста", objective = "Возьмите ящик с дырками.\nВозьмите палочку-погонялочку для шмыгуносов.\nВозьмите справочник по шмыгуносам. \n\nВ Лабиринтах Иглошкурых выпустите шмыгуноса и воспользуйтесь стеком, чтобы он начал искать корни. \n\nПринесите 6 корней синелиста, стек и ящик с дырками Мебоку Миззриксу в Кабестан." },
        [1275] = { name = "Исследование порчи", objective = "Гершал Шепот Ночи в Аубердине хочет, чтобы вы принесли ему 8 оскверненных стволов мозга." },
        [1360] = { name = "Возвращенное сокровище", objective = "Достаньте сокровище Крома Крепкорука из сундука в северном зале Ульдамана и принесите ему в Стальгорн." },
        [1394] = { name = "Финальное испытание", objective = "Поговорите с Дорном Вольным Ловчим в Тысяче Игл." },
        [1424] = { name = "Озеро Слез", objective = "Соберите 10 артефактов Атал'ай для Фелзерула из Каменора." },
        [1429] = { name = "Изгнанник Атал'ай", objective = "Принесите сверток с артефактами Атал'ай к изгнаннику Атал'ай во Внутренние земли." },
        [1444] = { name = "Возвращение к Фел'зерулу", objective = "Вернитесь в Каменор к Фел'зерулу." },
        [1445] = { name = "Храм Атал'Хаккара", objective = "Соберите 20 фетишей Хаккара и принесите их  Фел'зерулу в Каменор." },
        [1446] = { name = "Джаммал'ан Пророк", objective = "Принесите изгнаннику Атал'ай из Внутренних земель голову Джаммал'ана." },
        [1448] = { name = "В поисках Храма", objective = "Найдите Храм Атал'Хаккара и сообщите о его местонахождении Брохану Бочкопузу из Штормграда." },
        [1449] = { name = "Во Внутренние земли", objective = "Поговорите с Верховным таном Фалстадом Громовым Молотом на Заоблачном Пике во Внутренних землях." },
        [1450] = { name = "Укротитель грифонов Разящий Коготь", objective = "Поговорите с укротителем грифонов Разящим Когтем в питомнике на Заоблачном Пике." },
        [1451] = { name = "Рапсод Землекоп", objective = "Найдите Рапсода Землекопа во Внутренних землях." },
        [1452] = { name = "Калимдорский коктейль", objective = "Принесите Рапсоду Землекопу 3 куска потрохов руха, 3 печени гроддока и 3 печени железномеха." },
        [1469] = { name = "Рапсодия о болоте", objective = "Отнесите фрагмент таблички Атал'ай Брохану Бочкопузу в Штормград." },
        [1475] = { name = "В Храме Атал'Хаккара", objective = "Соберите 10 табличек Атал'ай для Брохана Бочкопуза из Штормграда." },
        [1486] = { name = "Шкуры загадочных существ", objective = "Принесите 20 искаженных шкур Налпаку в Пещерах Стенаний." },
        [1487] = { name = "Искоренение Скверны", objective = "Убейте для Эбру 7 загадочных опустошителей, 7 загадочных гадюк, 7 загадочных шаркунов и 7 загадочных страхозубов." },
        [1489] = { name = "Хамуул Рунический Тотем", objective = "Поговорите с Хамуулом Руническим Тотемом." },
        [1490] = { name = "Нара Буйногривая", objective = "Поговорите с Нарой Буйногривой." },
        [1491] = { name = "Умный напиток", objective = "Принесите 6 порций воющей субстанции Мебоку Миззриксу в Кабестан." },
        [1651] = { name = "Фолиант Отваги", objective = "Защитите Дафну Стилвелл от нападения Братства Справедливости. Проследите, чтобы ни ее, ни ваша душа в случае смерти не покинули свои тела, иначе испытание не будет засчитано.\n\nПосле победы поговорите с Дафной Стилвелл." },
        [1652] = { name = "Фолиант Отваги", objective = "Поговорите с Даторианом Раллом в Штормграде." },
        [1653] = { name = "Испытание доблести", objective = "Поговорите с Джорданом Стилвеллом в Стальгорне." },
        [1654] = { name = "Испытание доблести", objective = "Возьмите список Джордана, добудьте немного древесины белокаменного дуба, партию очищенной руды Бэйлора, кузнечный молот Джордана и самоцвет Кора и отдайте их Джордану Стилвеллу в Стальгорне." },
        [1699] = { name = "Ретбанский вызов", objective = "Войдите в пещеры Ретбана, доберитесь до первой развилки и вернитесь к Йорусу Ячменовару за отведенное время.\n\nВы не должны умирать и освобождать свой дух." },
        [1701] = { name = "Закаленный доспех", objective = "Соберите все необходимые материалы для Фьюрена Длинноборода и отнесите их в Штормград." },
        [1702] = { name = "Щитник", objective = "Отнесите бочонок жгучего пива Фьюрену Длиннобороду." },
        [1740] = { name = "Шар Соран'рука", objective = "Соберите 3 фрагмента Соран'рука и 1 большой фрагмент Соран'рука и принесите их Доану Кархану в Степи." },
        [1782] = { name = "Доспехи Фьюрена", objective = "Вот твои доспехи, Ишт. Они выдержат любой удар, не будь я Фьюрен Длиннобород!\n\nИ спасибо большое. Я многому научился, работая с принесенными тобой материалами. Думаю, в один прекрасный день я совершу новое открытие!\n\nА результаты этого я отправлю другим кузнецам Альянса.\n\nЯ скажу им, что ты мне очень помог, может быть, они тоже решат отблагодарить тебя." },
        [1806] = { name = "Испытание доблести", objective = "Подождите, пока Джордан Стилвелл не закончит изготовление оружия." },
        [1824] = { name = "Испытание на Полях Великанов", objective = "Принесите 5 дергающихся усиков Руге Тотему Гнева в Лагерь Таурахо." },
        [1825] = { name = "Разговор с Тун'гримом", objective = "Поговорите с Тун'гримом Огневзором из Степей." },
        [1838] = { name = "Доспехи Жестокости", objective = "Принесите Тун'гриму Огневзору 15 закопченных железных слитков, 10 мер толченого азурита, 10 железных слитков и сосуд флогистона." },
        [1848] = { name = "Хауберк Жестокости", objective = "Тебе несомненно пришлось пролить немало крови, чтобы справиться с моим заданием, Коммибро. Вот плод твоих трудов.\n\nНоси с удовольствием. Как-нибудь заходи, расскажешь, как он тебе пригодился в бою." },
        [1954] = { name = "Сфера Подземного огня", objective = "Принесите сферу Подземного огня Табете из Пылевых топей." },
        [1955] = { name = "Поединок с демоном", objective = "Убейте демона сферы, а потом поговорите с Табетой." },
        [1956] = { name = "Сила Ульдамана", objective = "Добудьте обсидиановый источник силы и принесите его Табете в Пыльную трясину." },
        [2040] = { name = "Битва под землей", objective = "Принесите Шони Молшунье в Штормград зубчатый спрек-механизм гномов из Мертвых копей." },
        [2041] = { name = "Разговор с Шони", objective = "Поговорите с Шони Молшуньей в Штормграде." },
        [2198] = { name = "Порванное ожерелье", objective = "Найдите создателя ожерелья, чтобы узнать, чего оно стоит." },
        [2199] = { name = "Мудрость за деньги", objective = "Принесите пять серебряных слитков Талвашу де Кисселю в Стальгорн." },
        [2200] = { name = "Назад в Ульдаман", objective = "Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья." },
        [2201] = { name = "Время собирать камни", objective = "Найдите рубин, сапфир, и топаз, которые спрятаны в разных местах Ульдамана. Когда найдете, свяжитесь с Талвашем де Кисселем, используя фиал Видения, который он предоставил.\n\nИз дневника вы узнали следующее:\n*Рубин укрыт в забаррикадированной Кузне Теней.\n*Топаз спрятан в урне в одной из областей, занятых троггами, недалеко от расположения дворфов Альянса.\n\n*Сапфир присвоил себе Гримлок, лидер троггов." },
        [2202] = { name = "В Ульдаман за реактивом", objective = "Принести 12 грибов-малиновиков Джаркалу Замшелому Клыку в Каргат." },
        [2204] = { name = "Восстановление ожерелье", objective = "Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу де Кисселю в Стальгорн." },
        [2240] = { name = "Потайной чертог", objective = "Прочитайте журнал Бейлога, исследуйте, потайной чертог и потом доложите об увиденном геологу Грозовой Вершине." },
        [2258] = { name = "Пробежка по Бесплодным землям", objective = "Принесите 5 вторых желудков канюка, 10 клыков скального койота и 5 осколков каменных элементалей Джаркалу Смешанному Лишайнику в Каргат." },
        [2278] = { name = "Платиновые Диски", objective = "Поговорите с каменным Стражем и запомните все, что он передаст вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона." },
        [2279] = { name = "Платиновые Диски", objective = "Отнесите миниатюрную копию дисков Норганнона в Лигу Исследователей в Стальгорне." },
        [2280] = { name = "Платиновые Диски", objective = "Отнесите миниатюрную копию дисков Норганнона кому-то из мудрецов с Громового Утеса." },
        [2283] = { name = "Пропавшее ожерелье", objective = "Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу." },
        [2284] = { name = "Пропавшее ожерелье, этап 2", objective = "Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана." },
        [2318] = { name = "Трудности перевода", objective = "Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях." },
        [2338] = { name = "Трудности перевода", objective = "Одолжите ожерелье Джаркалу. Взамен он переведет дневник." },
        [2339] = { name = "Найти самоцветы и источник энергии", objective = "Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане. \n\nИз дневника следует... \n* Рубин спрятан на огражденной завалами территории Кузни Теней. \n*Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса.\n*Сапфир забрал Гримлок, старейшина троггов." },
        [2340] = { name = "Принести самоцветы", objective = "Доставьте ожерелье и драгоценности Драну Дрофферсу в Оргриммар." },
        [2341] = { name = "Пропавшее ожерелье, этап 3", objective = "Навестите Джаркала Замшелого Клыка в Каргате." },
        [2342] = { name = "Возвращенные сокровища", objective = "Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана." },
        [2361] = { name = "Восстановление ожерелья", objective = "Я с великой радостью вручаю тебе это ожерелье, могучий |3-6(Жрец). Ты оказал мне неоценимую услугу, и я благодарен тебе за это. Носи же его с гордостью и не забывай при этом все время упоминать о том, кто сделал его для тебя!\n\nДа, если еще добавишь, что на ожерелье нет проклятия, это будет великолепно." },
        [2398] = { name = "Потерянные дворфы", objective = "Найдите Бейлога в Ульдамане." },
        [2418] = { name = "Камни Силы", objective = "Принесите 8 дентриевых камней Силы и 8 энелиевых камней Силы Ригглфаззу в Бесплодные земли." },
        [2439] = { name = "Платиновые диски", objective = "Отнесите наградной сертификат Дините Каменной Мантии в хранилище Стальгорна." },
        [2500] = { name = "За реактивами в Бесплодные земли", objective = "Добудьте в Бесплодных землях реактивы для Гхака Целителя и отнесите их ему в Телcамар." },
        [2768] = { name = "Изыскательский стержень", objective = "Принесите изыскательский cтержень главному инженеру Чепухастеру в Прибамбасск." },
        [2769] = { name = "Братья Латунный Болт", objective = "Поговорите с Виззлом Медноштифом на Мерцающей равнине." },
        [2770] = { name = "Газ'рилла", objective = "Принесите искрящую чешую Газ'риллы Виззлу Медноштифу на Мерцающую равнину." },
        [2841] = { name = "Техновойны", objective = "Добудьте в Гномрегане чертежи боевой машины и код от сейфа Термоштепселя в Гномрегане и принесите их Ноггу в Оргриммар." },
        [2842] = { name = "Главный инженер Скути", objective = "Поговорите со Скути в Пиратской бухте." },
        [2843] = { name = "Поехалиии!", objective = "Дождитесь, пока Скути настроит гоблинский импульсный повторитель." },
        [2846] = { name = "Тиара глубин", objective = "Принесите Тиару Глубин Табете в Пыльную Трясину." },
        [2861] = { name = "Миссия Табеты", objective = "Поговорите с Табетой в Пылевых топях." },
        [2864] = { name = "Тран'рек", objective = "Поговорите с Тран'реком в Прибамбасске." },
        [2865] = { name = "Панцири скарабеев", objective = "Принести 5 целых панцирей скарабея Тран'реку в Прибамбасск." },
        [2904] = { name = "Катавасия", objective = "Отведите Керноби к Часовому ходу. Затем отправляйтесь с донесением к Скути в Пиратскую бухту." },
        [2922] = { name = "Промыть мозг Техботу", objective = "Принесите ядро памяти Техбота мехмастеру Замыкальцу в Стальгорн." },
        [2924] = { name = "Базовый элемент", objective = "Принесите 12 базовых элементов Клацморту Гайкокруту в Стальгорн." },
        [2926] = { name = "Новая формула", objective = "Соберите радиоактивный осадок, оставляемый облученными захватчиками и облученными погромщиками в пустой свинцовый фиал для образцов. Принесите полный фиал Оззи Триггервольту в Каранос." },
        [2928] = { name = "Сооружение автогиробуророек", objective = "Принесите Шони в Штормград 24 горсти механических внутренностей роботов." },
        [2929] = { name = "Великое предательство", objective = "Отправляйтесь в Гномреган и убейте Мекжинера Термоштепселя. Вернитесь к Главному Механику Меггакруту." },
        [2930] = { name = "Спасение данных", objective = "Принесите призматическую перфокарту главному механику Чугунотрубзу в Стальгорн." },
        [2933] = { name = "Бутыли с ядом", objective = "Принесите бутылку яда аптекарю на Мельницу Таррен." },
        [2934] = { name = "Неповрежденная ядовитая железа", objective = "Принесите неповрежденную ядовитую железу аптекарю Лидону на Мельницу Таррен." },
        [2935] = { name = "Разговор с мастером Гадрином", objective = "Поговорите с мастером Гадрином в деревне Сен'джин." },
        [2936] = { name = "Паучья богиня", objective = "Прочитайте надписи на табличке Теки, узнайте имя паучьей богини, которой поклоняются тролли Сухокожих, а потом возвращайтесь к мастеру Гадрину." },
        [2945] = { name = "Кольцо, покрытое грязью", objective = "Придумайте, как отчистить кольцо, покрытое грязью." },
        [2947] = { name = "Возвращение кольца", objective = "Вы можеть оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца." },
        [2948] = { name = "Гномское усовершенствование", objective = "Принесите блестящее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Талвашу де Кисселю в Стальгорн." },
        [2949] = { name = "Возвращение кольца", objective = "Вы можеть оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца." },
        [2950] = { name = "Переделка кольца", objective = "Принесите блестящее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Ноггу в Огргиммар." },
        [2951] = { name = "Чистер 5200!", objective = "Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200." },
        [2962] = { name = "Сильное зеленое свечение", objective = "Отправляйтесь в Гномреган и принесите высокорадиоактивные образцы. Внимание: отходы нестабильны и довольно быстро разрушаются.\n\nВерните Оззи тяжелую освинцованную склянку для проб, когда задача будет выполнена." },
        [2988] = { name = "Тролльи клетки", objective = "Проверьте клетки в двух деревнях Сухокожих и возвращайтесь к дрессировщику грифонов Разящему Когтю." },
        [2989] = { name = "Алтарь Зула", objective = "Осмотрите вершину Алтаря Зула и возвращайтесь к укротителю грифонов Разящему Когтю." },
        [2990] = { name = "Тадиус Мрачная Тень", objective = "Принесите перо Остроклюва Тадиусу Мрачной Тени в Выжженные земли." },
        [2991] = { name = "Медальон Некрума", objective = "Отнесите медальон Некрума Тадиусу Мрачной Тени в Выжженные земли." },
        [3042] = { name = "Троллье месиво", objective = "Принесите 20 фиалов с Тролльим месивом." },
        [3341] = { name = "Да сгинет Хладовей", objective = "Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп." },
        [3373] = { name = "Сущность Эраникуса", objective = "Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме." },
        [3380] = { name = "Затонувший храм", objective = "Найдите Марвона Клепальщика в Танарисе." },
        [3444] = { name = "Круглый камень", objective = "Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане." },
        [3445] = { name = "Затонувший храм", objective = "Найдите Марвона Клепальщика в Танарисе." },
        [3446] = { name = "Во глубине болот", objective = "Найдите алтарь Хаккара в затонувшем храме на Болоте Печали." },
        [3447] = { name = "Тайна камня", objective = "Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй." },
        [3520] = { name = "Духи крикунов", objective = "Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля." },
        [3523] = { name = "Плеть в холмах", objective = "Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам." },
        [3525] = { name = "Уничтожить идола", objective = "Сопроводите Белнистраза к идолу свинобразов на Курганах Иглошкурых. \n\nЗащищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола." },
        [3527] = { name = "Пророчество Мошару", objective = "Принесите первую и вторую таблички Мошару Йе'кинье в Танарис." },
        [3528] = { name = "Бог Хаккар", objective = "Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис." },
        [3636] = { name = "Нести свет", objective = "Убейте Амненнара Хладовея на Курганах Иглошкурых." },
        [3701] = { name = "Дымящиеся руины Тауриссана", objective = "Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону." },
        [3702] = { name = "Дымящиеся руины Тауриссана", objective = "Узнайте от королевского историка Аркессона историю Тауриссана." },
        [3765] = { name = "Проблема за морем", objective = "Отправляйтесь в Аубердин к Гершалу Шепоту Ночи." },
        [3801] = { name = "Наследие Черного Железа", objective = "Чтобы получить ключ от города, поговорите с Франклорном Искусником." },
        [3802] = { name = "Наследие Черного Железа", objective = "Убейте Точеня Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника." },
        [3906] = { name = "Дисгармония пламени", objective = "Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду." },
        [3907] = { name = "Дисгармония пламени", objective = "Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию." },
        [3981] = { name = "Командир Гор'шак", objective = "Найдите командира Гор'шака в Глубинах Черной горы. \n\nСудя по рисунку в записке, искать следует в темнице где-то вроде того." },
        [3982] = { name = "Что происходит?", objective = "Защитите Горшака." },
        [4001] = { name = "Что происходит?", objective = "Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар.\n\nКарана держат в темнице напротив." },
        [4002] = { name = "Восточные королевства", objective = "Поговорите с Траллом." },
        [4003] = { name = "Спасение принцессы", objective = "Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия." },
        [4004] = { name = "Спасенная принцесса", objective = "Вернитесь к Траллу." },
        [4024] = { name = "Вкус пламени", objective = "Отправьтесь в глубины Черной горы и убейте Бейл'Гора.\n\nИзвестно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл'Гора сущность Огня.\n\nОтнесите пойманную сущность Огня Цирусу Раскаивателю." },
        [4061] = { name = "Восстание машин", objective = "Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании. \n\nТеодора упоминала, что осколки можно найти у элементалей и големов." },
        [4062] = { name = "Восстание машин", objective = "Отнесите образец осколка элементаля Лотвилю Вериатусу. \n\nТеодора упоминала, что его лагерь находится на востоке." },
        [4063] = { name = "Восстание машин", objective = "Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии." },
        [4081] = { name = "УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа", objective = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! \n\nПо приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания." },
        [4082] = { name = "УНИЧТОЖИТЬ НА МЕСТЕ: Высокопоставленные чины Черного Железа", objective = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! \n\nПо приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания." },
        [4083] = { name = "Призрачный кубок", objective = "Призрачный кубок парит в воздухе, медленно поднимаясь и опускаясь... как будто следуя ритмам биения умирающего сердца." },
        [4121] = { name = "Опасное положение", objective = "Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью.\n\nЛекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму.\n\nТакже отдайте Лекслорту ториевые оковы." },
        [4122] = { name = "Грарк Лоркруб", objective = "Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. \n\nПо обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника." },
        [4123] = { name = "Сердце горы", objective = "Принесите сердце горы Максворту Суперблеску в Пылающие степи." },
        [4126] = { name = "Харли Пьянодых", objective = "Найдите украденный рецепт громоварского и верните его Рагнару Громовару в Каранос." },
        [4128] = { name = "Рагнар Громовар", objective = "Переговорите с Рагнаром Громоваром." },
        [4132] = { name = "Операция:смерть Кузне Гнева", objective = "Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания." },
        [4133] = { name = "Вивиана Лягроб", objective = "Переговорите с тенемагом Вивиан Лаграв в Каргате." },
        [4134] = { name = "Украденный рецепт громоварского", objective = "Принесите рецепт громоварского светлого Вивиан Лягроб в Каргат." },
        [4136] = { name = "Риббли Крутипроб", objective = "Принесите голову Риббли Юке Крутипроб в Пылающие степи." },
        [4141] = { name = "Майджин и Ларион", objective = "Соберите 15 кровоцветов и принесите их Майджину." },
        [4142] = { name = "Визит к Грегану", objective = "Отнесите кровоцвет Грегану Пивоплюю в Фералас." },
        [4143] = { name = "Туман зла", objective = "Соберите 5 образцов тумана Аталаи и принесите их Майджину в Кратер Ун'Горо." },
        [4145] = { name = "Ларион и Майджин", objective = "Уничтожьте 5 кровоцветов-хлестунов, 5 кровоцветов-крепкозубов, 5 кровоцветов-живодеров и 5 кровоцветов-звероловов по просьбе Лариона из Укрытия Маршалла." },
        [4146] = { name = "Питание для шокера", objective = "Доставьте незаряженный шокер и 5 образцов тумана Аталаи Лариону в Укрытие Маршалла." },
        [4147] = { name = "Мастерская Марвона", objective = "Отправьтесь к Марвону Клепальщику в его мастерскую в Кабестане." },
        [4182] = { name = "Драконья угроза", objective = "Убейте 15 детенышей черного дракона, 10 черных драконидов, 4 черных драконид и 1 черного дракона. По выполнении задания вернитесь к Хелендису Речному Мысу." },
        [4183] = { name = "Подлинные хозяева", objective = "Отправьтесь в Приозерье и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону." },
        [4184] = { name = "Подлинные хозяева", objective = "Передайте обращение Соломона верховному лорду Болвару Фордрагону.\n\nБолвар Фордрагон пребывает в Крепости Штормграда." },
        [4185] = { name = "Подлинные хозяева", objective = "Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор." },
        [4186] = { name = "Подлинные хозяева", objective = "Отнесите указ Болвара мировому судье Соломону в Приозерье." },
        [4201] = { name = "Приворотное зелье", objective = "Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы." },
        [4223] = { name = "Подлинные хозяева", objective = "Поговорите с маршалом Максвеллом в Пылающих степях." },
        [4224] = { name = "Подлинные хозяева", objective = "Поговорите с Джоном-Оборванцем и узнайте о судьбе маршала Виндзора. По выполнении задания вернитесь к маршалу Максвеллу.\n\nКажется, маршал Максвелл говорил, что Джона следует искать в пещере на севере." },
        [4241] = { name = "Маршал Винздор", objective = "Отправляйтесь на Черную гору на северо-западе и войдите в ее глубины. Узнайте, что сталось с маршалом Виндзором.\n\nКажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу." },
        [4242] = { name = "Утраченная надежда", objective = "Сообщите маршалу Максвеллу плохие новости." },
        [4262] = { name = "Подчинитель Пирон", objective = "Убейте подчинителя Пирона и вернитесь к Джалинде Тирлипуньке.\n\nКажется, Джалинда говорила, что Пирон охраняет каменоломню. Может, поискать его там?" },
        [4263] = { name = "Опалитель!", objective = "Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!" },
        [4264] = { name = "Измятая записка", objective = "Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива." },
        [4282] = { name = "Проблеск надежды", objective = "Верните маршалу Виндзору утерянную информацию.\n\nМаршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева." },
        [4286] = { name = "Хороший товар", objective = "Отправьтесь в глубины Черной горы и принесите 20 поясных сумок дворфов Черного Железа. По выполнении задания вернуться к Орелиусу. Предположительно поясные сумки можно отобрать у дворфов Черного Железа в глубинах Черной горы." },
        [4295] = { name = "Эль для Каменного Узла", objective = "Кружечка доброго эля Черного Железа была бы сейчас очень кстати! Быстрее, а то я уже начинаю трезветь! А когда я трезвею, у меня сразу мутится зрение... и все расплывается... и ты почему-то становишься очень похожим на того |3-6(человек), которого я грохнул на прошлой неделе." },
        [4322] = { name = "Побег!", objective = "Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции." },
        [4324] = { name = "Юка Крутипроб", objective = "Переговорите с Юкой Крутипроб в Пылающих степях." },
        [4341] = { name = "Каран Могучий Молот", objective = "Пойдите в Глубины Черной горы и найдите Карана Могучего Молота.\n\nКороль упомянул, что Каран сидит там в плену – может, стоит поискать темницу." },
        [4342] = { name = "Рассказ Карана", objective = "Выслушайте рассказ Карана Могучего Молота." },
        [4361] = { name = "Недобрые вести", objective = "Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду." },
        [4362] = { name = "Судьба королевства", objective = "Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана." },
        [4363] = { name = "Королевский сюрприз", objective = "Вернитесь в Стальгорн и переговорите с королем Магни Бронзобородом." },
        [4701] = { name = "Устранение опасности", objective = "Отправьтесь на пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами." },
        [4724] = { name = "Праматерь стаи", objective = "Убейте Халикон, праматерь стаи воргов Кровавого Топора." },
        [4726] = { name = "Сущность детеныша дракона", objective = "Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях." },
        [4729] = { name = "Редкие звери Киблера", objective = "Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру." },
        [4734] = { name = "Заморозка яйца", objective = "Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье." },
        [4735] = { name = "Сбор яиц", objective = "Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях." },
        [4742] = { name = "Печать Вознесения", objective = "Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения.\n\nКамни могут быть у трех генералов: у воеводы Вуна из клана Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора." },
        [4743] = { name = "Печать Вознесения", objective = "Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.\n\nКак только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати Вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку." },
        [4764] = { name = "Пряжка Роковой оснастки", objective = "Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи." },
        [4766] = { name = "Майра Светлое Крыло", objective = "Поговорите с Майрой в Пылающих степях." },
        [4768] = { name = "Табличка Темнокамня", objective = "Принесите табличку Темного Камня тенемагу Вивиан Лаграв в Каргат." },
        [4769] = { name = "Вивиан Лягроб и табличка Темнокамня", objective = "Переговорите с темным магом Вивианой Лягроб." },
        [4771] = { name = "Рассветный гамбит", objective = "Отнесите \"Рассветный гамбит\" в Демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк." },
        [4787] = { name = "Древнее яйцо", objective = "Принесите древнее яйцо Йе'кинье в Танарис." },
        [4788] = { name = "Последние таблички", objective = "Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе." },
        [4808] = { name = "Фелнок Сталлист", objective = "Отнесите письмо Тинки Фелноку Сталлисту." },
        [4809] = { name = "Рога стылодыхов", objective = "Принесите 8 безупречных рогов стылодыха Фелноку Сталлисту." },
        [4810] = { name = "Возвращение к Тинки", objective = "Отнесите ящик Фелнока Тинки Кипеллер в Пылающие степи." },
        [4862] = { name = "Товар на любителя", objective = "Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука.\n\nСудя по всему, яйца надо искать недалеко от пауков." },
        [4866] = { name = "Материнское молоко", objective = "Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд." },
        [4867] = { name = "Аррок Смертный Вопль", objective = "Прочитайте записку Вароша. Принесите Варошу его амулет." },
        [4903] = { name = "Приказ полководца", objective = "Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат." },
        [4907] = { name = "Тинки Кипеллер", objective = "Поговорите с Тинки Кипеллер." },
        [4941] = { name = "Мудрость Эйтригга", objective = "Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу. \n\nВ последний раз Эйтригг был в в зале приемов Тралла." },
        [4974] = { name = "За Орду!", objective = "Пойдите в Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар." },
        [4981] = { name = "Агент Блестяшка", objective = "Отправьтесь к пику Черной горы и выясните, что сталось с Блестяшкой." },
        [4982] = { name = "Вещи Блестяшки", objective = "Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья." },
        [5001] = { name = "Вещи Блестяшки", objective = "Найдите вещи Блестяшки и верните их владелице. Удачи!" },
        [5002] = { name = "Донесение Максвелла", objective = "Передайте маршалу Максвеллу информацию Блестяшки." },
        [5047] = { name = "Айс Вентурон, к вашим услугам!", objective = "Переговорите с Малифоем Черномолотом в Круговзоре." },
        [5065] = { name = "Утраченные таблички Мошару", objective = "Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис." },
        [5081] = { name = "Миссия Максвелла", objective = "Отправляйтесь на пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака. По выполнении задания вернитесь к маршалу Максвеллу." },
        [5089] = { name = "Приказ генерала Драккисата", objective = "Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи." },
        [5102] = { name = "Кончина генерала Драккисата", objective = "Отправьтесь на пик Черной горы и устраните генерала Драккисата. По выполнении задания вернитесь к маршалу Максвеллу." },
        [5122] = { name = "Медальон Веры", objective = "Укрывшись в этой часовне, я могу противостоять порче, заполняющей мое существо. Но если я покину эти стены, я немедленно превращусь в нежить. Я знаю, что есть на свете медальон, именуемый медальоном веры, который может дать мне силу противостоять порче. \n\nПрошу тебя, Димиллион, принеси мне медальон. Его охраняет безумный фанатик Малор Ревностный, один из Алых. Ты найдешь его в недрах бастиона Алого ордена в западной части Стратхольма." },
        [5125] = { name = "Слова Аурия", objective = "Я умираю, Арраон… но душа моя обрела спасение. Я так многим обязан тебе... Прошу, прими это... И продолжай биться за правое дело, храбрый |3-6(Друид)!" },
        [5127] = { name = "Демонова кузня", objective = "Отправляйтесь на пик Черной горы и найдите Горалука Треснувшую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей.\n\nКроме того, вам нужно найти заготовку рунической кирасы.\n\nОтнесите пику и кирасу Лораксу в Зимних Ключах." },
        [5160] = { name = "Матрона-защитница", objective = "Дойдите до Зимних Ключей и найдите Халех. Отдайте ей пластину чешуи Ауби." },
        [5212] = { name = "Плоть не лжет", objective = "Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат." },
        [5213] = { name = "Вирус чумы", objective = "Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк." },
        [5214] = { name = "Великий Эзра Гримм", objective = "Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней коробку отличного табака Эзры Гримма и принесите ее Дымку ЛаРу." },
        [5243] = { name = "Святая вода", objective = "Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно." },
        [5244] = { name = "Руины Кел'Терила", objective = "Поговорите с Джероном Гранильщиком в деревне Звездопада." },
        [5245] = { name = "Беспокойные духи Кел'Терила", objective = "Используйте кирку Джерона, чтобы добыть фрагменты реликвии высокорожденных, Принесите их Авроре Зову Небес в Восточные Чумные земли." },
        [5246] = { name = "Фрагменты прошлого", objective = "Найдите Священные письмена высокорожденных в Храме Зин-Малор, в Азшаре и принесите их Авроре Зову Небес к Башне Северного перевалa, в Восточных Чумных землях." },
        [5247] = { name = "Фрагменты прошлого", objective = "Принесите зачарованный слиток тория, 5 кристаллов Восстановления и фиал пугающей воды Авроре Зову Небес к башне Северного Перевала, в Восточных Чумных землях." },
        [5250] = { name = "Звездопад", objective = "Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником." },
        [5251] = { name = "Архивариус", objective = "Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых." },
        [5262] = { name = "Ошеломляющая истина", objective = "Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли." },
        [5263] = { name = "Быстрее, выше, сильнее", objective = "Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу." },
        [5281] = { name = "Мятущиеся души", objective = "Найдите Эгана. В последний раз его видели недалеко от Стратхольма." },
        [5282] = { name = "Мятущиеся души", objective = "Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.\n\nОсвободите 15 неупокоенных душ и возвращайтесь к Эгану." },
        [5341] = { name = "Сокровище Баровых", objective = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову." },
        [5343] = { name = "Сокровище Баровых", objective = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову." },
        [5382] = { name = "Доктор Теолен Крастинов – Мясник", objective = "Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф." },
        [5384] = { name = "Киртонос Глашатай", objective = "Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.\n\nСражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф." },
        [5461] = { name = "Рас Ледяной Шепот – человек", objective = "Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу Воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку." },
        [5462] = { name = "Рас Ледяной Шепот – гибель", objective = "Отправляйтесь в часовню Светлых надежд в Восточных Чумных землях и найдите Леонида Бартоломея Чтимого. Покажите ему книгу Воспоминаний и расскажите обо всем, о чем удалось узнать." },
        [5463] = { name = "Дар Менетила", objective = "Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу Воспоминаний на оскверненную землю." },
        [5464] = { name = "Дар Менетила", objective = "Отнесите Книгу Души Леониду Бартоломею в Восточные Чумные земли." },
        [5465] = { name = "Книга Души", objective = "Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души." },
        [5466] = { name = "Рас Снегошепот – лич", objective = "Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку." },
        [5515] = { name = "Мешок ужасов Крастинова", objective = "Найдите в Некроситете Джандис Баров и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф." },
        [5518] = { name = "Броня огров Гордока", objective = "Принесите 4 рулона рунной ткани, 8 кусков прочной кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе." },
        [5522] = { name = "Леонид Барталомей", objective = "Принесите охлажденные яйца Леониду Бартоломею в Восточные Чумные земли." },
        [5525] = { name = "Освободите Нотта!", objective = "Эта вещь называется \"ключ от оков Гордока\" – по крайней мере, так называют его эти \"остроумцы\". Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников…\n\nНо о чем я говорю? Он у вас есть, да? Он при вас?!" },
        [5526] = { name = "Осколки сквернита", objective = "Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне." },
        [5527] = { name = "Реликварий Чистоты", objective = "Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне." },
        [5529] = { name = "Зачумленные детеныши дракона", objective = "Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды." },
        [5531] = { name = "Бетина Биггльцинк", objective = "Принесите охлажденные яйца Бетине Биггльцинк." },
        [5542] = { name = "Псы-демоны", objective = "Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу." },
        [5543] = { name = "Окровавленные небеса", objective = "Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу." },
        [5544] = { name = "Мясо личинок-трупоедов", objective = "Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите из мяса. Возвращайтесь к Тириону Фордрингу, когда накопите 15 кусков мяса червей-трупоедов." },
        [5722] = { name = "В поисках потерянного ранца", objective = "Обыщите Огненную пропасть в поисках тела Маура Зловещего Тотема и найдите все необычные предметы." },
        [5723] = { name = "Испытание силы врага", objective = "Найдите в Оргриммаре Огненную пропасть, убейте 8 троггов и 8 шаманов Огненной пропасти и возвращайтесь к Рахауро в Громовой Утес." },
        [5724] = { name = "Возвращение потерянной сумки", objective = "Отнесите сумку Маура Зловещего Тотема Рахауро в Громовой Утес." },
        [5725] = { name = "Силы разрушения...", objective = "Принесите книги \"Заклинания Тьмы\" и \"Заклятия Пустоты\" Вариматрасу в Подгород." },
        [5726] = { name = "Тайные враги", objective = "Принесите лейтенантский знак отличия Траллу в Оргриммар." },
        [5727] = { name = "Тайные враги", objective = "Отнесите лейтенантский знак отличия Нииру Огненному Клинку. Убедите его в своей преданности Пылающему Клинку. Вернитесь к Траллу в Оргриммар." },
        [5728] = { name = "Тайные враги", objective = "Убейте Баззалана и Жергоша Призывателя Духов и вернитесь в Оргриммар к Траллу." },
        [5742] = { name = "Спасение", objective = "Выслушайте Тириона Фордринга." },
        [5761] = { name = "Убить тварь", objective = "Спуститесь в Огненную пропасть, убейте Тарагамана Ненасытного и принесите его сердце Нииру Огненному Клинку в Оргриммаре." },
        [5781] = { name = "Символ ушедших дней", objective = "Отправляйтесь в Крипту – в самой южной части Восточных Чумных земель – и добудьте молот Таэлана. Отнесите его Тириону Фордрингу." },
        [5845] = { name = "Символ утраченной чести", objective = "Отправляйтесь в Северный дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу." },
        [5846] = { name = "Символ семейной любви", objective = "Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину." },
        [5848] = { name = "Символ семейной любви", objective = "Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира.\n\nОтнесите картину Тириону Фордрингу." },
        [5961] = { name = "Защитник королевы банши", objective = "Поговорите с Натаносом Гнилостенем в Восточных Чумных землях. Он живет в Поместье Маррисов." },
        [6022] = { name = "Преднамеренное убийство", objective = "Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее, чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль." },
        [6042] = { name = "Мелочи нежизни", objective = "Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостеню." },
        [6133] = { name = "Охота на следопытов", objective = "Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель'Таласа. Документ находится где-то в Сторожке Кель'Литиен.\n\nТакже убейте 8 следопытов, 8 разведчиц дорог и 8 лесников." },
        [6135] = { name = "Проклятый Тенекрыл", objective = "Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостеню.\n\nГоворят, Тенекрыл рыщет в землях к северу от имения Марриса." },
        [6136] = { name = "Огромный червь", objective = "Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостеню по выполнению задания." },
        [6141] = { name = "Брат Антон", objective = "Найдите в Пустошах брата Антона и поговорите с ним." },
        [6163] = { name = "Рамштейн", objective = "Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира." },
        [6402] = { name = "Встреча в Штормграде", objective = "Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии." },
        [6403] = { name = "Великий Маскарад", objective = "Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!" },
        [6501] = { name = "Око дракона", objective = "Найдите существа, способные вернуть силу фрагменту амулета Ока дракона. Все, что об этих существах известно – это то, что они есть." },
        [6502] = { name = "Амулет Пламени дракона", objective = "Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы." },
        [6521] = { name = "Нечестивый союз", objective = "Принести голову посла Малкина Вариматрасу в Подгород." },
        [6522] = { name = "Нечестивый союз", objective = "Отнесите маленький свиток Вариматрасу в Подгород." },
        [6561] = { name = "Жестокость Черных Глубин", objective = "Принесите голову Повелителя сумрака Келриса Башане Руническому Тотему в Громовой Утес." },
        [6562] = { name = "Угроза из Глубин", objective = "Поговорите с Дже'неу Санкри в Ясеневом лесу." },
        [6563] = { name = "Сущность Аку'май", objective = "Принесите 20 сапфиров Аку'май Дже'неу Санкри в Ясеневый лес." },
        [6564] = { name = "Верность Древним богам", objective = "Принесите отсыревшую записку Дже'неу Санкри в Ясеневый лес." },
        [6565] = { name = "Верность Древним богам", objective = "Убейте Лоргуса Джетта в Непроглядной Пучине и вернитесь к Дже'неу Санкри в Ясеневый лес." },
        [6566] = { name = "Что принес ветер", objective = "Выслушайте Тралла." },
        [6567] = { name = "Защитник Орды", objective = "Найдите Рексара. Вождь сказал, что он бродит в Пустошах, по дороге, что ведет из Когтичтых гор в Фералас." },
        [6568] = { name = "Завет Рексара", objective = "Доставьте письмо Рексара Миранде Колдунье в Западные Чумные земли." },
        [6569] = { name = "Иллюзии Ока", objective = "Отправляйтесь на пик Черной горы и добудьте 20 глаз черных драконидов. По выполнении задания вернитесь к Миранде Колдунье." },
        [6570] = { name = "Огнебор", objective = "Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором." },
        [6582] = { name = "Черепа: Провидец", objective = "Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору." },
        [6583] = { name = "Черепа: Сомнус", objective = "Убейте вожака зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору." },
        [6584] = { name = "Черепа: Хроналис", objective = "Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору." },
        [6585] = { name = "Черепа: Акстроз", objective = "Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору." },
        [6601] = { name = "Вознесение", objective = "Казалось бы, загадка разгадана. Вы знаете, что амулет Обмана Драконов, который сделала для вас Миранда Колдунья, не будет работать на пике Черной горы. Найдите Рокаро и расскажите о ваших затруднениях. Покажите ему амулет Угасающего Пламени Дракона. Будем надеяться, он знает что делать." },
        [6602] = { name = "Кровь могучего черного дракона", objective = "Отправляйтесь к пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рокаро." },
        [6626] = { name = "Воинство зла", objective = "Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице на Курганы Иглошкурых." },
        [6627] = { name = "Испытание знаний", objective = "Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах." },
        [6628] = { name = "Испытание знаний", objective = "Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде." },
        [6921] = { name = "Среди руин", objective = "Принесите глубинный сердечник Дже'неу Санкри в форт Зорам'гар в Ясеневый лес." },
        [6922] = { name = "Барон Акванис", objective = "Принесите странную водяную сферу Дже'неу Санкри в форт Зорам'гар в Ясеневом лесу." },
        [6981] = { name = "Светящийся осколок", objective = "Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке.\n\nЗатем отнесите осколок туда, куда вас направят." },
        [7028] = { name = "Хрустальные орнаменты", objective = "Соберите 25 терадрических хрустальных орнаментов для Ивы из Пустошей." },
        [7029] = { name = "Порча Злоязыкого", objective = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.\n\nПолейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.\n\nИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников." },
        [7041] = { name = "Порча Злоязыкого", objective = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.\n\nПолейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.\n\nИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела." },
        [7044] = { name = "Легенды Мародона", objective = "Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса.\n\nНайдите способ поговорить с Келебрасом." },
        [7046] = { name = "Скипетр Келебраса", objective = "Помогите Селебрасу Искупленному воссоздать скипетр Селебраса.\n\nПо завершении ритуала снова обратитесь к нему." },
        [7064] = { name = "Яблочко от яблоньки...", objective = "Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах." },
        [7065] = { name = "Яблочко от яблоньки...", objective = "Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши." },
        [7066] = { name = "Семя Жизни", objective = "Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни." },
        [7067] = { name = "Инструкции кентавра-парии", objective = "Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей." },
        [7068] = { name = "Фрагменты осколка сумрака", objective = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар." },
        [7070] = { name = "Фрагменты осколка сумрака", objective = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей." },
        [7201] = { name = "Последняя Стихия", objective = "Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей." },
        [7441] = { name = "Пузиллин и старейший Аж'Тордин", objective = "Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.\n\nЕсли добудете книгу, вернитесь к Аж'Тордину в павильон Лорисс в Фераласе." },
        [7461] = { name = "Древнее безумие", objective = "Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.\n\nВойдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.\n\nЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар." },
        [7462] = { name = "Сокровище Шен'дралар", objective = "Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!" },
        [7463] = { name = "Магический напиток", objective = "Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари." },
        [7481] = { name = "Эльфийские легенды", objective = "Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать." },
        [7482] = { name = "Эльфийские легенды", objective = "Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в крепость Оперенной Луны к школяру Рунному Шипу и сообщите ей все, что вам удалось узнать." },
        [7483] = { name = "\"Манускрипт Скорости\"", objective = "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Скорости\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 2 образца крови героев, чтобы получить магический камень стремительности." },
        [7484] = { name = "\"Манускрипт Средоточия\"", objective = "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Средоточия\", 1 безупречный черный алмаз, 4 больших сияющих осколка и 2 образца шкуры Тени, чтобы получить магический камень сосредоточения." },
        [7485] = { name = "\"Манускрипт Защиты", objective = "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Защиты\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 1 потертый шовный материал поганища, чтобы получить магический камень защиты." },
        [7488] = { name = "Сеть Лефтендрис", objective = "Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе." },
        [7489] = { name = "Сеть Лефтендрис", objective = "Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе." },
        [7492] = { name = "Лагерь Мохаче", objective = "Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе." },
        [7494] = { name = "Крепость Оперенной Луны", objective = "Поговорите с Латроникусом Лунным Копьем в Крепости Оперенной Луны в Фераласе." },
        [7498] = { name = "Гарона: Исследование уловок и предательства", objective = "Верните книгу законным владельцам." },
        [7499] = { name = "Кодекс Обороны", objective = "Верните книгу законным владельцам." },
        [7500] = { name = "Поваренная книга чародея", objective = "Верните книгу законным владельцам." },
        [7501] = { name = "Свет и как его раскачать", objective = "Верните книгу законным владельцам." },
        [7502] = { name = "Укрощая тени", objective = "Верните книгу законным владельцам." },
        [7503] = { name = "Величайшая гонка охотников", objective = "Верните книгу законным владельцам." },
        [7504] = { name = "Святая Болонья: О чем не говорит Свет", objective = "Верните книгу законным владельцам." },
        [7505] = { name = "Ледяной шок и вы", objective = "Верните книгу законным владельцам." },
        [7506] = { name = "Изумрудный сон", objective = "Верните книгу законным владельцам." },
        [7507] = { name = "Справочник Форора", objective = "Верните \"Справочник Форора по убийству драконов\" в Читальню." },
        [7563] = { name = "Ярость крови", objective = "Принесите 30 бутылок крови яростных зверей Мор'зулу Кровопуску в Пылающие степи." },
        [7564] = { name = "Дикоглаз", objective = "Принесите ларец Крови Горзиеки Дикоглазу в Пылающие степи." },
        [7604] = { name = "Заключение договора", objective = "Подпишите договор с представителем братства Тория Локтосом Недобрым Торговцем, если вам нужен чертеж сульфуронского молота." },
        [7623] = { name = "Лорд Гиблопуст", objective = "Купите зелья Теней у Горзиеки в Пылающих степях.\n\nПриняв зелья, пройдите в Джеденар и поговорите с лордом Гиблопустом." },
        [7624] = { name = "Улатек Предатель", objective = "Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар." },
        [7625] = { name = "Зоротианская звездная пыль", objective = "Купите зоротианскую звездную пыль у Ур'Дана. Отнесите ее Горзиеки Дикоглазу в Пылающие степи." },
        [7626] = { name = "Колокол Детмуры", objective = "Отнесите 10 эликсиров Силы Теней Горзиеки Дикоглазу в Пылающие степи." },
        [7627] = { name = "Колесо Черного Похода", objective = "Отнесите 6 больших блестящих осколка и 25 кусков руды черного железа Дикоглазу в Пылающие степи." },
        [7628] = { name = "Свеча Судного Дня", objective = "Принесите 35 шкур черного дракона Горзиеки Дикоглазу в Пылающие степи." },
        [7629] = { name = "Доставка беса", objective = "Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу." },
        [7630] = { name = "Арканит", objective = "Принесите 3 арканитовых слитка Горзиеки в Пылающие степи." },
        [7631] = { name = "Ксоротианский конь погибели", objective = "Прочтите инструкции Мор'зула. Призовите ксоротианского коня погибели, одолейте его и подчините его дух." },
        [7637] = { name = "Жертва необходима", objective = "Доберитесь до Стальгорна и получите курильницу экзорцизма у Верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых монет." },
        [7639] = { name = "Демонстрация истинного правосудия", objective = "Принесите курильницу экзорцизма лорду Грейсону Тенелому в Храмовый квартал Штормграда." },
        [7640] = { name = "Изгнание призраков из Долины Ужаса", objective = "Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих Долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в Храмовый квартал Штормграда." },
        [7641] = { name = "Работа Гриманда Элмора", objective = "Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда." },
        [7642] = { name = "Сбор необходимого", objective = "Принесите Гриманду Элмору в Квартал Дворфов Штормграда 40 отрезов рунной ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой Стратхольма и 150 золотых монет." },
        [7643] = { name = "Дух древнего коня", objective = "Купите лошадиный корм для Духа древнего коня у Меридет Карлсон в Южнобережье.\n\nУбейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака." },
        [7644] = { name = "Благословенный арканитовый чепрак", objective = "Вернитесь вместе с благословенным арканитовым чепраком к лорду Грейсону Тенелому в Храмовый квартал Штормграда." },
        [7645] = { name = "Обогащенный манной лошадиный корм", objective = "Принесите 20 витаминизированных печений из манны – ключевых составляющих обогащенного манной лошадиного корма – Меридет Карлсон в Южнобережье в предгорьях Хилсбрада. Продаются они только в Серебряном Рассвете.\n\nКроме того, понадобится дать ей 50 золотых, чтобы успокоить ее ущемленное самолюбие." },
        [7646] = { name = "Магический кристалл", objective = "Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Храмовый квартал Штормграда." },
        [7647] = { name = "Суд и расплата", objective = "Используйте магический кристалл в центре подвала Главного склепа в Некроситете. Победите вызванных духов, а затем – рыцаря смерти Темного Терзателя, который появится после поражения духов.\n\nВерните падшему скакуну Темного Терзателя его спасенную душу и покройте его благословенным зачарованным чепраком." },
        [7648] = { name = "Шедевр Гриманда", objective = "Покажите арканитовый чепрак лорду Грейсону Тенелому в Храмовом квартале Штормграда." },
        [7667] = { name = "Существенная помощь", objective = "Принесите Сагорну Гребнестраннику в Аллею Мудрости в Оргриммаре азеротский алмаз и безупречный черный алмаз." },
        [7668] = { name = "Угроза Темного Губителя", objective = "Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.\n\nПринесите голову Темного Терзателя Сагорну Гривастому Страннику в Аллею Мудрости Оргриммара." },
        [7703] = { name = "Неоконченное дело Гордоков", objective = "Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.\n\nПо словам Давигрома, в \"старых байках\" говорится, что Тортелдрин – \"страшный эльф\", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков." },
        [7761] = { name = "Приказ Чернорука", objective = "Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа.\n\nВ письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить." },
        [7848] = { name = "Сродство с недрами", objective = "Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте фрагмент ядра. Принесите его Лотосу Хранителю Портала к Черной горе." },
        [8151] = { name = "Талисман охотника", objective = "Поговорите с Огтинком из Азшары." },
        [8153] = { name = "Рога и копыта", objective = "Принесите пару великолепных рогов мохоногого оленя Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
        [8231] = { name = "Охота на волномета", objective = "Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
        [8232] = { name = "Зеленый дракон", objective = "Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
        [8233] = { name = "Приглашение", objective = "Поговорите с лордом Джорахом Черным Вороном в его поместье." },
        [8234] = { name = "Запечатанная лазурная сумка", objective = "Добудьте запечатанную лазурную сумку у шамана из племени Древобрюхов в Азшаре. Затем отнесите сумку верховному магу Ксилему в Азшаре." },
        [8235] = { name = "Зашифрованные фрагменты", objective = "Принесите 10 зашифрованных фрагментов верховному магу Ксилему в Азшару." },
        [8236] = { name = "Лазурный ключ", objective = "Принесите лазурный ключ лорду Черному Ворону." },
        [8250] = { name = "Магическое искусство", objective = "Найдите Саната Лим-Йо и добейтесь, чтобы он доставил вас к верховному магу Ксилему." },
        [8251] = { name = "Волшебная пыль", objective = "Принесите 10 горстей сияющей пыли верховному магу Ксилему." },
        [8252] = { name = "Кораллы сирен", objective = "Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему." },
