        [8254] = { name = "Помощь Кенарию", objective = "Отыщи Огтинка в Азшаре." },
        [8255] = { name = "Охота на беговых оленей", objective = "Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
        [8256] = { name = "Лимфа нежити", objective = "Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
