        [1452] = { name = "拉普索迪的卡利姆多鸡尾酒", objective = "辛特兰的拉普索迪·铁铲要求你带给他3块大鹏的砂囊、3块格罗多克猩猩的肝脏和3块铁鬃熊的肝脏。" },
        [1469] = { name = "拉普索迪的故事", objective = "将阿塔莱石板碎片交给暴风城的布罗哈恩·铁桶。" },
        [1475] = { name = "进入阿塔哈卡神庙", objective = "为暴风城的布罗哈恩·铁桶收集10块阿塔莱石板。" },
        [1486] = { name = "变异皮革", objective = "哀嚎洞穴的纳尔帕克想要20张变异皮革。" },
        [1487] = { name = "清除变异者", objective = "哀嚎洞穴的厄布鲁要求你杀掉7只变异破坏者、7只剧毒飞蛇、7只变异蹒跚者和7只变异尖牙风蛇。" },
        [1489] = { name = "哈缪尔·符文图腾", objective = "和哈缪尔·符文图腾谈一谈。" },
        [1490] = { name = "纳拉·蛮鬃", objective = "和纳拉·蛮鬃谈一谈。" },
        [1491] = { name = "智慧饮料", objective = "收集6份哀嚎香精，把它们交给棘齿城的麦伯克·米希瑞克斯。" },
        [1651] = { name = "勇气之书", objective = "在迪菲亚兄弟会进攻时保护达芙妮·斯迪威尔的安全。\n\n如果你想成功的话，你和达芙妮都不能死在他们的剑下。" },
        [1652] = { name = "勇气之书", objective = "与暴风城的达索瑞恩·拉尔谈一谈。" },
        [1653] = { name = "正义试炼", objective = "去和铁炉堡的乔丹·斯迪威尔谈一谈。" },
        [1654] = { name = "正义试炼", objective = "按照乔丹的武器材料单上的说明去寻找一些白石橡木、精炼矿石、乔丹的铁锤和一块科尔宝石，然后回到铁炉堡去见乔丹·斯迪威尔。" },
        [1699] = { name = "往返瑞斯班洞穴", objective = "进入瑞斯班洞穴，然后在规定的时间内回到犹鲁斯·麦酒那里。\n\n在整个过程中你都不能死掉或者释放灵魂，否则任务就宣告失败。" },
        [1701] = { name = "弗伦的铠甲", objective = "收集必需的材料，将它们交给暴风城的弗伦·长须。" },
        [1702] = { name = "铸盾师", objective = "将这桶热酒交给弗伦·长须。" },
        [1740] = { name = "索兰鲁克宝珠", objective = "找到3块索兰鲁克宝珠的碎片和1块索兰鲁克宝珠的大碎片，把它们交给贫瘠之地的杜安·卡汉。" },
        [1782] = { name = "弗伦的铠甲" },
        [1806] = { name = "正义试炼", objective = "等待乔丹·斯迪威尔为你铸造武器。" },
        [1824] = { name = "巨人旷野的试炼", objective = "收集5根颤抖的触角，把它们带给贫瘠之地陶拉祖营地的鲁迦。" },
        [1825] = { name = "和索恩格瑞姆交谈", objective = "与贫瘠之地的索恩格瑞姆·火眼谈一谈。" },
        [1838] = { name = "野蛮护甲", objective = "为索恩格瑞姆收集15根烟雾铁锭、10份蓝铜粉、10块铁锭和1瓶燃素。" },
        [1848] = { name = "野蛮锁甲" },
        [1954] = { name = "地狱火宝珠", objective = "将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。" },
        [1955] = { name = "驱除魔鬼", objective = "杀死宝珠之魔，然后与塔贝萨谈一谈。" },
        [1956] = { name = "奥达曼的能量源", objective = "找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。" },
        [2040] = { name = "地底突袭", objective = "从死亡矿井中带回小型高能发动机，将其带给暴风城矮人区中的沉默的舒尼。" },
        [2041] = { name = "沉默的舒尼", objective = "去暴风城和舒尼谈一谈。" },
        [2198] = { name = "破碎的项链", objective = "找到破碎的项链的来源，从而了解其潜在的价值。" },
        [2199] = { name = "昂贵的知识", objective = "给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。" },
        [2200] = { name = "回到奥达曼", objective = "去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。" },
        [2201] = { name = "寻找宝石", objective = "在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。" },
        [2202] = { name = "奥达曼的蘑菇", objective = "收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。" },
        [2204] = { name = "修复项链", objective = "从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。" },
        [2240] = { name = "密室", objective = "阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。" },
        [2258] = { name = "荒芜之地的试剂", objective = "前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。" },
        [2278] = { name = "白金圆盘", objective = "和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。" },
        [2279] = { name = "白金圆盘", objective = "把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。" },
        [2280] = { name = "白金圆盘", objective = "把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。" },
        [2283] = { name = "搜寻项链", objective = "在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。" },
        [2284] = { name = "搜寻项链，再来一次", objective = "在奥达曼里找寻宝石的线索。" },
        [2318] = { name = "翻译日记", objective = "在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。" },
        [2338] = { name = "翻译日记", objective = "将项链借给加卡尔。作为交换，他将帮你翻译日记。" },
        [2339] = { name = "寻找宝贝", objective = "从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。\n\n红宝石被藏在暗影矮人层层设防的地区。\n\n黄宝石藏在石腭怪活动地区的一个瓮中。\n\n蓝宝石在格瑞姆洛克手中，他是石腭怪的领袖。\n\n能量源可能在奥达曼的某个最强生物的手中。" },
        [2340] = { name = "交付宝石", objective = "把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。" },
        [2341] = { name = "项链任务的终结", objective = "去卡加斯看看加卡尔是否成功了。" },
        [2342] = { name = "寻找宝物", objective = "从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。" },
        [2361] = { name = "修复项链", objective = "我很高兴能给你这条项链，强大的<class>。你对我的帮助是无价的，我为此对你表示万分的感谢。请把它戴上吧，这是属于你的荣耀，请在别人问及的时候告诉他们，是我制作了这条项链！\n\n另外，如果你证明这条项链根本没有受到诅咒，那就更棒了。" },
        [2398] = { name = "失踪的矮人", objective = "在奥达曼找到巴尔洛戈。" },
        [2418] = { name = "能量石", objective = "给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。" },
        [2439] = { name = "白金圆盘", objective = "把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。" },
        [2500] = { name = "荒芜之地的材料", objective = "从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。" },
        [2768] = { name = "探水棒", objective = "把探水棒交给加基森的首席工程师沙克斯·比格维兹。" },
        [2769] = { name = "铜栓兄弟", objective = "和闪光平原的维兹尔·铜栓谈一谈。" },
        [2770] = { name = "加兹瑞拉", objective = "把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。" },
        [2841] = { name = "设备之战", objective = "从诺莫瑞根拿到钻探设备蓝图和瑟玛普拉格的保险箱密码，把它们交给奥格瑞玛的诺格。" },
        [2842] = { name = "主工程师斯库提", objective = "和藏宝海湾的斯库提谈一谈。" },
        [2843] = { name = "出发！诺莫瑞根！", objective = "等斯库提调整好地精传送器。" },
        [2846] = { name = "深渊皇冠", objective = "将深渊皇冠交给尘泥沼泽的塔贝萨。" },
        [2861] = { name = "塔贝萨的任务", objective = "与尘泥沼泽的塔贝萨谈一谈。" },
        [2864] = { name = "特兰雷克", objective = "与加基森的特兰雷克谈一谈。" },
        [2865] = { name = "圣甲虫的壳", objective = "给加基森的特兰雷克带去5个完整的圣甲虫壳。" },
        [2904] = { name = "一团混乱", objective = "将克努比护送到出口，然后向藏宝海湾的斯库提汇报。" },
        [2922] = { name = "拯救尖端机器人！", objective = "将尖端机器人的存储器核心交给铁炉堡的工匠大师欧沃斯巴克。" },
        [2924] = { name = "基础模组", objective = "收集12个基础模组，把它们交给铁炉堡的科劳莫特·钢尺。" },
        [2926] = { name = "诺恩", objective = "用空铅瓶对着辐射入侵者或者辐射抢劫者，从它们身上收集放射尘。瓶子装满之后，把它交给卡拉诺斯的奥齐·电环。" },
        [2928] = { name = "陀螺式挖掘机", objective = "收集24副机械内胆，把它们交给暴风城的舒尼。" },
        [2929] = { name = "大叛徒", objective = "到诺莫瑞根去杀掉机械师瑟玛普拉格。完成任务之后向大工匠梅卡托克报告。" },
        [2930] = { name = "抢救数据", objective = "将彩色穿孔卡片交给铁炉堡的大机械师卡斯派普。" },
        [2933] = { name = "毒液瓶", objective = "将毒药瓶交给塔伦米尔的某个药剂师。" },
        [2934] = { name = "完好无损的毒囊", objective = "将完好无损的毒囊交给塔伦米尔的药剂师林度恩。" },
        [2935] = { name = "请教加德林大师", objective = "与森金村的加德林大师谈一谈。" },
        [2936] = { name = "蜘蛛之神", objective = "阅读塞卡石板，了解枯木巨魔的蜘蛛之神的名字，然后回到加德林大师那里。" },
        [2945] = { name = "脏兮兮的戒指", objective = "想方法把脏兮兮的戒指弄干净。" },
        [2947] = { name = "戒指归来", objective = "你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。" },
        [2948] = { name = "侏儒的手艺", objective = "将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给铁炉堡的塔瓦斯德·基瑟尔。" },
        [2949] = { name = "戒指归来", objective = "你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。" },
        [2950] = { name = "诺格的手艺", objective = "将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给奥格瑞玛的诺格。" },
        [2951] = { name = "超级清洁器5200型！", objective = "将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。" },
        [2962] = { name = "更多的辐射尘！", objective = "到诺莫瑞根去收集高强度辐射尘。要多加小心，这种辐射尘非常不稳定，很快就会分解。\n\n奥齐要求你把沉重的铅瓶也交给他。" },
        [2988] = { name = "枯木巨魔的牢笼", objective = "检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。" },
        [2989] = { name = "祖尔祭坛", objective = "检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。" },
        [2990] = { name = "萨迪斯·格希德", objective = "将沙普比克的羽毛交给诅咒之地的萨迪斯·格希德。" },
        [2991] = { name = "耐克鲁姆的徽章", objective = "将耐克鲁姆的徽章交给诅咒之地的萨迪斯·格希德。" },
        [3042] = { name = "巨魔调和剂", objective = "收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。" },
        [3341] = { name = "寒冰之王", objective = "安德鲁·布隆奈尔要你杀了寒冰之王亚门纳尔并将其头骨带回来。" },
        [3373] = { name = "伊兰尼库斯精华", objective = "把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。" },
        [3380] = { name = "沉没的神庙", objective = "到塔纳利斯找到玛尔冯·瑞文斯克。" },
        [3444] = { name = "石环", objective = "到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。" },
        [3445] = { name = "沉没的神庙", objective = "到塔纳利斯找到玛尔冯·瑞文斯克。" },
        [3446] = { name = "深入神庙", objective = "在悲伤沼泽沉没的神庙中找到哈卡祭坛。" },
        [3447] = { name = "雕像群的秘密", objective = "到沉没的神庙去，揭开雕像群中隐藏的秘密。" },
        [3520] = { name = "尖啸者的灵魂", objective = "在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。" },
        [3523] = { name = "剃刀高地的亡灵天灾", objective = "如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。" },
        [3525] = { name = "封印神像", objective = "保护奔尼斯特拉兹来到剃刀高地的野猪人神像处。\n\n当他在进行仪式封印神像时保护他。" },
        [3527] = { name = "摩沙鲁的预言", objective = "将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。" },
        [3528] = { name = "神灵哈卡", objective = "将装满的哈卡之卵交给塔纳利斯的叶基亚。" },
        [3636] = { name = "与圣光同在", objective = "大主教本尼迪塔斯要你去杀死剃刀高地的寒冰之王亚门纳尔。" },
        [3701] = { name = "索瑞森废墟", objective = "到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。" },
        [3702] = { name = "索瑞森废墟", objective = "听皇家历史学家阿克瑟努斯讲述索瑞森的历史。" },
        [3765] = { name = "遥远的旅途", objective = "到奥伯丁的戈沙拉·夜语那儿去。" },
        [3801] = { name = "黑铁的遗产", objective = "如果你想要得到进入这座城市主城区的钥匙，就去和弗兰克罗恩·铸铁谈一谈。" },
        [3802] = { name = "黑铁的遗产", objective = "杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。" },
        [3906] = { name = "不和谐的烈焰", objective = "到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。" },
        [3907] = { name = "不和谐的火焰", objective = "进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。" },
        [3981] = { name = "指挥官哥沙克", objective = "在黑石深渊里找到指挥官哥沙克。\n\n在那幅草图上画着的是一个铁栏后面的兽人，也许你应该到某个类似监狱的地方去找找看。" },
        [3982] = { name = "出了什么事？", objective = "保护哥沙克。" },
        [4001] = { name = "出了什么事？", objective = "与卡兰·巨锤谈一谈，收集关于绑架公主铁炉堡公主茉艾拉·铜须这一事件的情报。将情报反馈给奥格瑞玛城里的萨尔。\n\n哥沙克提到过卡兰被关在附近的某个牢房中。" },
        [4002] = { name = "东部王国", objective = "如果你准备好要接受萨尔所安排的任务，就去找他谈一谈。" },
        [4003] = { name = "拯救公主", objective = "杀掉达格兰·索瑞森大帝，然后将铁炉堡公主茉艾拉·铜须从他的邪恶诅咒中拯救出来。" },
        [4004] = { name = "拯救公主？", objective = "向萨尔报告！" },
        [4024] = { name = "烈焰精华", objective = "到黑石深渊去杀掉贝尔加。\n\n你只知道这个巨型怪物住在黑石深渊的最深处。记住你要使用特殊的黑龙皮从贝尔加的尸体上采集烈焰精华。\n\n将你采集到的烈焰精华交给塞勒斯·萨雷芬图斯。" },
        [4061] = { name = "机器的崛起", objective = "到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。\n\n塞朵拉曾经说过，那里的机械傀儡和元素生物是这种碎片的主要来源。" },
        [4062] = { name = "机器的崛起", objective = "将元素碎片样本交给鲁特维尔·沃拉图斯。\n\n塞朵拉说鲁特维尔就在东边的一处营地里。" },
        [4063] = { name = "机器的崛起", objective = "找到并杀掉傀儡统帅阿格曼奇，将他的头交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。" },
        [4081] = { name = "格杀勿论：黑铁矮人", objective = "到黑石深渊去消灭那些邪恶的侵略者！\n\n军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。" },
        [4082] = { name = "格杀勿论：高阶黑铁军官", objective = "到黑石深渊去消灭那些邪恶的侵略者！\n\n高图斯军阀要你杀死10个铁怒医师,、10个铁怒士兵和10个铁怒军官。完成任务之后回去向他复命。" },
        [4083] = { name = "鬼魂之杯" },
        [4121] = { name = "押送囚徒", objective = "押送你的囚犯格拉克·洛克鲁布。穿过燃烧平原和黑石山脉，一直走到灼热峡谷。\n\n雷克斯洛特曾经告诉过你，他会让他的人等在黑石山脉的另外一边准备接收格拉克。\n\n另外，你还要把瑟银镣铐一并还给雷克斯洛特。" },
        [4122] = { name = "格拉克·洛克鲁布", objective = "到燃烧平原去找到格拉克·洛克鲁布。你回忆起雷克斯洛特曾经提起过，格拉克应该是在一座大型的黑石要塞中。\n\n当你找到格拉克·洛克鲁布之后，用瑟银镣铐把他铐起来，然后将其带回灼热峡谷。雷克斯洛特会让他的部下等在那里接应你。" },
        [4123] = { name = "山脉之心", objective = "把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。" },
        [4126] = { name = "霍尔雷·黑须", objective = "把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。" },
        [4128] = { name = "拉格纳·雷酒", objective = "和拉格纳·雷酒谈一谈。" },
        [4132] = { name = "行动：杀死安格弗将军", objective = "到黑石深渊去杀掉安格弗将军！当任务完成之后向军官高图斯复命。" },
        [4133] = { name = "薇薇安·拉格雷", objective = "与卡加斯的暗法师薇薇安·拉格雷谈一谈。" },
        [4134] = { name = "遗失的雷酒秘方", objective = "把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。" },
        [4136] = { name = "雷布里·斯库比格特", objective = "把雷布里的头颅交给燃烧平原的尤卡·斯库比格特。" },
        [4141] = { name = "穆尔金和拉瑞安", objective = "从安戈洛尔环形山的血瓣花猛击者和血瓣花掠夺者身上收集15个血瓣花，然后向穆尔金回复。" },
        [4142] = { name = "造访格雷甘", objective = "把血瓣花交给菲拉斯的格雷甘·山酒。" },
        [4143] = { name = "邪恶之雾", objective = "收集5份阿塔莱之雾的样本，然后向安戈洛环形山的穆尔金复命。" },
        [4145] = { name = "拉瑞安和穆尔金", objective = "为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者、5个血瓣花捕兽者、5个血瓣花掠夺者和5个血瓣花猛击者。" },
        [4146] = { name = "除草器的燃料", objective = "收集5份阿塔莱之雾的样本，然后将它们送到马绍尔营地的拉瑞安那里。" },
        [4147] = { name = "玛尔冯的车间", objective = "到棘齿城去，在玛尔冯·瑞文斯克的车间里找到他。" },
        [4182] = { name = "黑龙的威胁", objective = "杀掉15条黑色小龙、10条黑色龙人和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。" },
        [4183] = { name = "真正的主人", objective = "把赫林迪斯·河角的信交给湖畔镇的所罗门镇长。" },
        [4184] = { name = "真正的主人", objective = "到暴风城去把所罗门的求援信交给伯瓦尔·弗塔根公爵。\n\n伯瓦尔在暴风要塞里。" },
        [4185] = { name = "真正的主人", objective = "与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。" },
        [4186] = { name = "真正的主人", objective = "把伯瓦尔的命令交给湖畔镇的所罗门镇长。" },
        [4201] = { name = "爱情药水", objective = "将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。" },
        [4223] = { name = "真正的主人", objective = "和燃烧平原的麦克斯韦尔元帅谈一谈。" },
        [4224] = { name = "真正的主人", objective = "和狼狈不堪的约翰谈谈来了解温德索尔元帅的命运，然后回到麦克斯韦尔元帅那里。\n\n你想起麦克斯韦尔元帅说过他在一个北面的洞穴那里。" },
        [4241] = { name = "温德索尔元帅", objective = "到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。\n\n狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。" },
        [4242] = { name = "被遗弃的希望", objective = "把这个坏消息传达给麦克斯韦尔元帅。" },
        [4262] = { name = "征服者派隆", objective = "杀掉征服者派隆，然后向加琳达复命。\n\n加琳达告诉过你，派隆守在采矿场中，也许你应该去那里找找。" },
        [4263] = { name = "伊森迪奥斯！", objective = "在黑石深渊里找到伊森迪奥斯，然后把他干掉！" },
        [4264] = { name = "弄皱的便笺", objective = "温德索尔元帅也许会对你手中的东西感兴趣。毕竟，希望还没有被完全扼杀。" },
        [4282] = { name = "一丝希望", objective = "找回温德索尔元帅遗失的情报。\n\n温德索尔元帅确信那些情报在安格弗将军和傀儡统帅阿格曼奇的手里。" },
        [4286] = { name = "好东西", objective = "到黑石深渊去找到20个黑铁挎包。当你完成任务之后，回到奥拉留斯那里复命。你认为黑石深渊里的黑铁矮人应该会有这些黑铁挎包。" },
        [4295] = { name = "罗克诺特的麦酒", objective = "哦，酒！为了黑铁矮人的酒，我甚至愿意去杀人！快点，我的酒劲正在消退！我的视线越来越模糊了……你看上去越来越像上个星期我干掉的那个<race>了！" },
        [4322] = { name = "冲破牢笼！", objective = "帮助温德索尔元帅拿回他的装备并救出他的朋友。当你成功之后就回去向麦克斯韦尔元帅复命。" },
        [4324] = { name = "尤卡·斯库比格特", objective = "与燃烧平原的尤卡·斯库比格特谈一谈。" },
        [4341] = { name = "卡兰·巨锤", objective = "去黑石深渊找到卡兰·巨锤。\n\n国王提到卡兰在那里负责看守囚犯——也许你应该在监狱附近寻找他。" },
        [4342] = { name = "卡兰的故事", objective = "听卡兰·巨锤说他的故事。" },
        [4361] = { name = "糟糕的消息", objective = "回到铁炉堡，把这个坏消息带给国王麦格尼·铜须。" },
        [4362] = { name = "王国的命运", objective = "回到黑石深渊，从达格兰·索瑞森大帝的魔掌中救出铁炉堡公主茉艾拉·铜须。" },
        [4363] = { name = "语出惊人的公主", objective = "回到铁炉堡去，与国王麦格尼·铜须谈一谈。" },
        [4701] = { name = "座狼之源", objective = "到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。" },
        [4724] = { name = "座狼的首领", objective = "杀死血斧座狼的领袖，哈雷肯。" },
        [4726] = { name = "雏龙精华", objective = "将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。" },
        [4729] = { name = "基布雷尔的特殊宠物", objective = "到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。" },
        [4734] = { name = "冷冻龙蛋", objective = "在孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。" },
        [4735] = { name = "收集龙蛋", objective = "将电动采集模块和8颗收集到的龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。" },
        [4742] = { name = "晋升印章", objective = "找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。\n\n可能携带者三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。" },
        [4743] = { name = "晋升印章", objective = "到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。\n\n此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！" },
        [4764] = { name = "末日扣环", objective = "将末日扣环交给燃烧平原的玛亚拉·布莱特文。" },
        [4766] = { name = "玛亚拉·布莱特文", objective = "与燃烧平原的玛亚拉·布莱特文谈一谈。" },
        [4768] = { name = "黑暗石板", objective = "将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。" },
        [4769] = { name = "薇薇安·拉格雷和黑暗石板", objective = "与卡加斯的暗法师薇薇安·拉格雷谈一谈。" },
        [4771] = { name = "黎明先锋", objective = "将黎明先锋放在通灵学院的观察室里。打败维克图斯，然后回到贝蒂娜·比格辛克那里去。" },
        [4787] = { name = "远古之卵", objective = "将远古之卵交给塔纳利斯的叶基亚。" },
        [4788] = { name = "最后的石板", objective = "将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。" },
        [4808] = { name = "菲诺克", objective = "把丁奇的信交给菲诺克。" },
        [4809] = { name = "冰风奇美拉角", objective = "将8支完整的冰风奇美拉角交给菲诺克。" },
        [4810] = { name = "返回丁奇身边", objective = "把菲诺克的包裹交给燃烧平原的丁奇·斯迪波尔。" },
        [4862] = { name = "蜘蛛卵", objective = "到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。\n\n听说那些蜘蛛周围有许多这样的卵。" },
        [4866] = { name = "蛛后的乳汁", objective = "你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。当你中毒之后，回到狼狈不堪的约翰那儿，他会从你的身体里抽取这些“蛛后的乳汁”。" },
        [4867] = { name = "乌洛克", objective = "阅读瓦罗什的卷轴。将瓦罗什的蟑螂交给他。" },
        [4903] = { name = "高图斯的命令", objective = "杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。" },
        [4907] = { name = "丁奇·斯迪波尔", objective = "与丁奇·斯迪波尔谈一谈。" },
        [4941] = { name = "伊崔格的智慧", objective = "和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。\n\n你回忆起曾在萨尔的大厅中见过伊崔格。" },
        [4974] = { name = "为部落而战！", objective = "去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。" },
        [4981] = { name = "狡猾的比修", objective = "到黑石塔去查明比修的下落。" },
        [4982] = { name = "比修的装置", objective = "找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。" },
        [5001] = { name = "比修的装置", objective = "找到比修的装置并把它们还给她。祝你好运！" },
        [5002] = { name = "给麦克斯韦尔的消息", objective = "到燃烧平原去，把比修的情报交给麦克斯韦尔元帅。" },
        [5047] = { name = "芬克·恩霍尔，为您效劳！", objective = "与永望镇的玛雷弗斯·暗锤谈一谈。" },
        [5065] = { name = "失落的摩沙鲁石板", objective = "把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。" },
        [5081] = { name = "麦克斯韦尔的任务", objective = "到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。完成任务之后回到麦克斯韦尔元帅处复命。" },
        [5089] = { name = "达基萨斯将军的命令", objective = "把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。" },
        [5102] = { name = "达基萨斯将军之死", objective = "到黑石塔去杀掉达基萨斯将军，完成任务之后就回到麦克斯韦尔元帅那里复命。" },
        [5122] = { name = "信仰奖章" },
        [5125] = { name = "奥里克斯的清算" },
        [5127] = { name = "恶魔熔炉", objective = "到黑石塔去找到古拉鲁克。杀死他，然后用血污长矛刺入他的尸体。当他的灵魂被吸干后，这支矛就会成为穿魂长矛。\n\n你还必须找到未铸造的符文覆饰胸甲。\n\n将穿魂长矛和未铸造的符文覆饰胸甲都交给冬泉谷的罗拉克斯。" },
        [5160] = { name = "监护者", objective = "到冬泉谷去找到哈尔琳，把奥比的鳞片交给她。" },
        [5212] = { name = "血肉不会撒谎", objective = "从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……" },
        [5213] = { name = "活跃的探子", objective = "到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。" },
        [5214] = { name = "弗拉斯·希亚比", objective = "找到弗拉斯·希亚比在斯坦索姆的烟草店，并从中找回一盒希亚比的烟草，把它交给烟鬼拉鲁恩。" },
        [5243] = { name = "神圣之屋", objective = "到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。" },
        [5244] = { name = "凯斯利尔废墟", objective = "与坠星村的加隆·石矛谈一谈。" },
        [5245] = { name = "凯斯利尔的怨灵", objective = "使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。" },
        [5246] = { name = "历史的残片", objective = "在艾萨拉的辛玛洛神殿里找到神圣的上层精灵笔迹，并将它带给位于东瘟疫之地的北地哨塔附近的奥萝拉。" },
        [5247] = { name = "历史的残片", objective = "给东瘟疫之地的奥萝拉带去一块魔化瑟银锭、5块恢复水晶，以及一小瓶恐怖之水。" },
        [5250] = { name = "坠星村", objective = "找到冬泉谷的坠星村，在那里与维恩德·夜风谈一谈。" },
        [5251] = { name = "档案管理员", objective = "在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。" },
        [5262] = { name = "可怕的真相", objective = "将巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。" },
        [5263] = { name = "超越", objective = "到斯坦索姆去杀掉瑞文戴尔男爵，把他的头颅交给尼古拉斯·瑟伦霍夫公爵。" },
        [5281] = { name = "永不安息的灵魂", objective = "找到埃根。你只知道他在斯坦索姆附近。" },
        [5282] = { name = "永不安息的灵魂", objective = "对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！\n\n解放15个永不安息的灵魂，然后回到埃根那里去。" },
        [5341] = { name = "巴罗夫家族的宝藏", objective = "到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。" },
        [5343] = { name = "巴罗夫家族的宝藏", objective = "到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到维尔顿·巴罗夫那儿去。" },
        [5382] = { name = "瑟尔林·卡斯迪诺夫教授", objective = "在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。" },
        [5384] = { name = "传令官基尔图诺斯", objective = "带着无辜者之血回到通灵学院，将它放在门廊的火盆下面，基尔图诺斯会前来吞噬你的灵魂。\n\n勇敢地战斗吧，不要退缩！杀死基尔图诺斯，然后回到艾瓦·萨克霍夫那儿。" },
        [5461] = { name = "莱斯·霜语", objective = "到阿拉希高地的激流堡遗迹里面寻找巫妖生前的遗物。如果你能找到这样的东西，就把它交给马杜克镇长。" },
        [5462] = { name = "亡灵莱斯·霜语", objective = "到东瘟疫之地的圣光之愿礼拜堂去找到莱尼德·巴萨罗梅，给他看看巫妖生前的遗物，并告诉他你收集到的情报。" },
        [5463] = { name = "米奈希尔的礼物", objective = "到斯坦索姆城里去找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。" },
        [5464] = { name = "米奈希尔的礼物", objective = "把禁锢灵魂的遗物交给东瘟疫之地的莱尼德·巴萨罗梅。" },
        [5465] = { name = "禁锢灵魂的遗物", objective = "回到凯尔达隆的马杜克镇长那里，把禁锢灵魂的遗物交给他。" },
        [5466] = { name = "巫妖莱斯·霜语", objective = "在通灵学院里找到莱斯·霜语。当你找到他之后，使用禁锢灵魂的遗物破除其亡灵的外壳。如果你成功地破除了他的不死之身，就杀掉他并拿到莱斯·霜语的头颅。把那个头颅交给马杜克镇长。" },
        [5515] = { name = "卡斯迪诺夫的恐惧之袋", objective = "在通灵学院找到詹迪斯·巴罗夫并打败她。从她的尸体上找到卡斯迪诺夫的恐惧之袋，然后将其交给艾瓦·萨克霍夫。" },
        [5518] = { name = "戈多克食人魔装", objective = "把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。" },
        [5522] = { name = "莱尼德·巴萨罗梅", objective = "把冰冻的龙蛋交给东瘟疫之地的莱尼德·巴萨罗梅。" },
        [5525] = { name = "逃出生天！" },
        [5526] = { name = "魔藤碎片", objective = "在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。" },
        [5527] = { name = "净化之匣", objective = "到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。" },
        [5529] = { name = "瘟疫之龙", objective = "杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。" },
        [5531] = { name = "贝蒂娜·比格辛克", objective = "将冰冻的龙蛋交给贝蒂娜·比格辛克。" },
        [5542] = { name = "恶魔之犬", objective = "杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。" },
        [5543] = { name = "血染的天空", objective = "杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。" },
        [5544] = { name = "腐肉虫", objective = "在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。" },
        [5722] = { name = "寻找背包", objective = "在怒焰裂谷搜寻玛尔·恐怖图腾的尸体以及他留下的东西。" },
        [5723] = { name = "试探敌人", objective = "在奥格瑞玛找到怒焰裂谷，杀掉8个怒焰穴居人和8个怒焰萨满祭司，然后向雷霆崖的拉哈罗复命。" },
        [5724] = { name = "归还背包", objective = "将恐怖图腾背包交给雷霆崖的拉哈罗。" },
        [5725] = { name = "毁灭之力", objective = "将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的瓦里玛萨斯。" },
        [5726] = { name = "隐藏的敌人", objective = "将军官的徽章交给奥格瑞玛的萨尔。" },
        [5727] = { name = "隐藏的敌人", objective = "将军官的徽章交给尼尔鲁·火刃并与他谈一谈，看看他是否相信你是火刃氏族中的一员，然后回到奥格瑞玛的萨尔那里。" },
        [5728] = { name = "隐藏的敌人", objective = "杀死巴扎兰和祈求者耶戈什，然后回到奥格瑞玛的萨尔那里。" },
        [5742] = { name = "救赎", objective = "听听提里奥·弗丁要说什么。" },
        [5761] = { name = "饥饿者塔拉加曼", objective = "进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的心脏交给奥格瑞玛的尼尔鲁·火刃。" },
        [5781] = { name = "遗忘的记忆", objective = "到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。" },
        [5845] = { name = "失落的荣耀", objective = "到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。" },
        [5846] = { name = "爱与家庭", objective = "到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。" },
        [5848] = { name = "爱与家庭", objective = "到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到“爱与家庭”这幅画，它被隐藏在另一幅描绘两个月亮的画之后。\n\n把这幅画还给提里奥·弗丁。" },
        [5961] = { name = "女妖之王的勇士", objective = "与东瘟疫之地的纳萨诺斯·凋零者谈一谈。据说他居住在玛瑞斯农场。" },
        [6022] = { name = "杀戮的理由", objective = "到东边的考林路口去屠杀镇里的亡灵天灾。在10分钟内收集7块生命腐质，使用研钵和捣杵将其研磨成凝固腐质。" },
        [6042] = { name = "讨厌的蝙蝠", objective = "杀掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然后回到纳萨诺斯·凋零者那里。" },
        [6133] = { name = "游侠之王的命令", objective = "到东瘟疫之地的北方边界去找回奎尔萨拉斯名册，这件物品在奎尔林斯小屋的某处。\n\n另外你还必须杀掉8个游侠、8个巡路者和8个护林者。" },
        [6135] = { name = "暗翼蝠", objective = "找到暗翼蝠并杀掉它。从尸体上取下一块暗翼蝠的皮，并把它交给纳萨诺斯·凋零者。\n\n据说暗翼蝠游荡在玛瑞斯农场北面的荒原上。" },
        [6136] = { name = "肥大的食腐虫", objective = "找到东瘟疫之地北方荒原中的淤血虫并消灭它。任务完成之后，向纳萨诺斯·凋零者复命。" },
        [6141] = { name = "安东修士", objective = "与凄凉之地的安东修士谈一谈。" },
        [6163] = { name = "吞咽者拉姆斯登", objective = "到斯坦索姆去，杀掉吞咽者拉姆斯登。把他的头颅交给纳萨诺斯。" },
        [6402] = { name = "集合在暴风城", objective = "前往暴风城的城门。与侍卫洛文交谈，他会通知温德索尔元帅你已经到达了。" },
        [6403] = { name = "潜藏者", objective = "跟随雷吉纳德·温德索尔元帅在暴风城中前进。保护他，别让他受到伤害！" },
        [6501] = { name = "巨龙之眼", objective = "你必须寻遍世界以找到一种能恢复龙眼碎片的能量的生物。你对这种生物的唯一了解就是：他们确实存在。" },
        [6502] = { name = "龙火护符", objective = "你必须从达基萨斯将军身上取回黑龙勇士之血，你可以在黑石塔的晋升大厅后面的房间里找到他。" },
        [6521] = { name = "邪恶的盟友", objective = "把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。" },
        [6522] = { name = "邪恶的盟友", objective = "把小卷轴交给幽暗城的瓦里玛萨斯。" },
        [6561] = { name = "黑暗深渊中的邪恶", objective = "把暮光领主克尔里斯的头颅交给雷霆崖的巴珊娜·符文图腾。" },
        [6562] = { name = "帮助耶努萨克雷", objective = "与灰谷的耶努萨克雷谈一谈。" },
        [6563] = { name = "阿库麦尔水晶", objective = "收集20颗阿库麦尔蓝宝石，把它们交给灰谷的耶努萨克雷。" },
        [6564] = { name = "上古之神的仆从", objective = "把潮湿的便笺交给灰谷的耶努萨克雷。" },
        [6565] = { name = "上古之神的仆从", objective = "杀掉黑暗深渊里的洛古斯·杰特，然后向灰谷的耶努萨克雷复命。" },
        [6566] = { name = "风吹来的消息", objective = "听萨尔讲话。" },
        [6567] = { name = "部落的勇士", objective = "按照酋长的指示找到雷克萨。他在石爪山和菲拉斯之间的凄凉之地游荡。" },
        [6568] = { name = "雷克萨的证明", objective = "把雷克萨的证明交给西瘟疫之地的巫女麦兰达。" },
        [6569] = { name = "黑龙幻象", objective = "到黑石塔去收集20颗黑色龙人的眼球，完成任务之后回到巫女麦兰达那里。" },
        [6570] = { name = "埃博斯塔夫", objective = "到尘泥沼泽中的巨龙沼泽去，找到埃博斯塔夫的洞穴。进入洞穴之后戴上龙形护符，然后跟埃博斯塔夫交谈。" },
        [6582] = { name = "龙骨试炼，斯克利尔", objective = "找到蓝龙斯克利尔并杀掉他。从他的身上取下他的颅骨，然后将其交给埃博斯塔夫。\n\n你可以在冬泉谷找到斯克利尔。" },
        [6583] = { name = "龙骨试炼，索姆努斯", objective = "杀掉绿龙索姆努斯，把他的颅骨交给埃博斯塔夫。" },
        [6584] = { name = "龙骨试炼，克鲁纳里斯", objective = "诺兹多姆的孩子克鲁纳里斯在塔纳利斯沙漠守卫着时光之穴。杀了他，把他的颅骨交给埃博斯塔夫。" },
        [6585] = { name = "龙骨试炼，埃克托兹", objective = "到格瑞姆巴托去杀掉红龙埃克托兹，把他的颅骨交给埃博斯塔夫。" },
        [6601] = { name = "晋升……", objective = "看来这场假面舞会就要结束了。你知道麦兰达为你制作的龙形护符在黑石塔里面不会发挥作用，也许你应该去找雷克萨，将你的困境告诉他。把黯淡的龙火护符给他看看，也许他知道下一步该怎么做。" },
        [6602] = { name = "黑龙勇士之血", objective = "到黑石塔去杀掉达基萨斯将军，把它的血交给雷克萨。" },
        [6626] = { name = "邪恶之地", objective = "杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。" },
        [6627] = { name = "知识试炼", objective = "成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。" },
        [6628] = { name = "知识试炼", objective = "成功回答帕科瓦·芬塔拉斯的问题，然后再次和他对话。他会一直在幽暗城等你回答问题。" },
        [6921] = { name = "废墟之间", objective = "把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。" },
        [6922] = { name = "阿奎尼斯男爵", objective = "把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。" },
        [6981] = { name = "发光的碎片", objective = "寻找更多有关这块噩梦碎片的信息。" },
        [7028] = { name = "扭曲的邪恶", objective = "为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。" },
        [7029] = { name = "维利塔恩的污染", objective = "在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。\n\n在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。\n\n治疗8株植物并杀死那些诺克赛恩幼体，然后向葬影村的瓦克·战痕复命。" },
        [7041] = { name = "维利塔恩的污染", objective = "在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。\n\n在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。\n\n治疗8株植物并杀死那些诺克赛恩幼体，然后向尼耶尔前哨站的塔琳德莉亚复命。" },
        [7044] = { name = "玛拉顿的传说", objective = "找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。\n\n然后设法和塞雷布拉斯对话。" },
        [7046] = { name = "塞雷布拉斯节杖", objective = "帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。\n\n当仪式完成之后再和他谈谈。" },
        [7064] = { name = "大地的污染", objective = "杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。" },
        [7065] = { name = "大地的污染", objective = "杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。" },
        [7066] = { name = "生命之种", objective = "到月光林地去找到雷姆洛斯，将生命之种交给他。" },
        [7067] = { name = "贱民的指引", objective = "阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。" },
        [7068] = { name = "暗影残片", objective = "从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。" },
        [7070] = { name = "暗影残片", objective = "从玛拉顿收集10块暗影残片，然后把它们交给尘泥沼泽塞拉摩岛上的大法师特沃什。" },
        [7201] = { name = "最后的元素", objective = "到黑石深渊去取得10份元素精华。你应该在那些作战傀儡和傀儡制造者身上找找，另外，薇薇安·拉格雷也提到了一些有关元素生物的话题……" },
        [7441] = { name = "普希林和埃斯托尔迪", objective = "到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。\n\n找到咒术之书后，回到拉瑞斯小亭的埃斯托尔迪那里。" },
        [7461] = { name = "伊莫塔尔的疯狂", objective = "你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。\n\n进入伊莫塔尔的监狱，干掉站在中间的那个恶魔。最后，在图书馆挑战托塞德林王子。\n\n当任务完成之后，到庭院中去找辛德拉古灵。" },
        [7462] = { name = "辛德拉的宝藏", objective = "返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！" },
        [7463] = { name = "久违的法师", objective = "到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。" },
        [7481] = { name = "精灵的传说", objective = "到厄运之槌去寻找卡里尔·温萨鲁斯。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。" },
        [7482] = { name = "精灵的传说", objective = "到厄运之槌去寻找卡里尔·温萨鲁斯。向羽月要塞的学者卢索恩·纹角报告你所找到的信息。" },
        [7483] = { name = "急速圣典", objective = "将急速圣典、1块原始黑钻石、2份大块魔光碎片和2份英雄之血交给厄运之槌的博学者莱德罗斯，以换取一份急速秘药。" },
        [7484] = { name = "专注圣典", objective = "将专注圣典、1块原始黑钻石、4份大块魔光碎片和2张暗影之皮交给厄运之槌的博学者莱德罗斯，以换取一份专注秘药。" },
        [7485] = { name = "防护圣典", objective = "将防护圣典、1块原始黑钻石、2份大块魔光碎片和1份磨损的憎恶缝合线交给厄运之槌的博学者莱德罗斯，以换取一份防护秘药。" },
        [7488] = { name = "蕾瑟塔蒂丝的网", objective = "把蕾瑟塔蒂丝的网交给菲拉斯羽月要塞的拉托尼库斯·月矛。" },
        [7489] = { name = "蕾瑟塔蒂丝的网", objective = "把蕾瑟塔蒂丝的网交给非拉斯莫沙彻营地的塔罗·刺蹄。" },
        [7492] = { name = "莫沙彻营地", objective = "和菲拉斯莫沙彻营地的塔罗·刺蹄谈一谈。" },
        [7494] = { name = "羽月要塞", objective = "和菲拉斯羽月要塞的拉托尼库斯·月矛谈一谈。" },
        [7498] = { name = "迦罗娜：潜行与诡计研究", objective = "将这本典籍交给它的主人。" },
        [7499] = { name = "防御宝典", objective = "将这本典籍交给它的主人。" },
        [7500] = { name = "奥法师的食谱", objective = "将这本典籍交给它的主人。" },
        [7501] = { name = "圣光之力", objective = "将这本典籍交给它的主人。" },
        [7502] = { name = "束缚之影", objective = "将这本典籍交给它的主人。" },
        [7503] = { name = "最伟大的猎手", objective = "将这本典籍交给它的主人。" },
        [7504] = { name = "光明不会告诉你的事情", objective = "将这本典籍交给它的主人。" },
        [7505] = { name = "你与冰霜震击", objective = "将这本典籍交给它的主人。" },
        [7506] = { name = "翡翠梦境……", objective = "将这本典籍交给它的主人。" },
        [7507] = { name = "弗洛尔的屠龙技术纲要", objective = "将《弗洛尔的屠龙技术纲要》还回图书馆。" },
        [7563] = { name = "血之狂暴", objective = "把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。" },
        [7564] = { name = "戈瑟奇·邪眼", objective = "把血箱交给燃烧平原的戈瑟奇·邪眼。" },
        [7604] = { name = "瑟银兄弟会契约", objective = "如果你愿意接受萨弗隆的设计图，请将瑟银兄弟会契约交给罗克图斯·暗契。" },
        [7623] = { name = "魔王贝恩霍勒", objective = "从燃烧平原的戈瑟奇那里购买暗影药水。\n\n使用这种药剂进入加德纳尔，然后与魔王贝恩霍勒谈一谈。" },
        [7624] = { name = "背叛者乌拉泰克", objective = "找到并杀死乌拉泰克，然后把叛徒之心交给加德纳尔的魔王贝恩霍勒。" },
        [7625] = { name = "克索诺斯星尘", objective = "从乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。" },
        [7626] = { name = "达斯莫拉之铃", objective = "把10瓶暗影之力药剂交给燃烧平原的戈瑟奇·邪眼。" },
        [7627] = { name = "黑暗战车之轮", objective = "把6份大块魔光碎片和25块黑铁矿石交给燃烧平原的戈瑟奇·邪眼。" },
        [7628] = { name = "末日蜡烛", objective = "把35块黑龙鳞片交给燃烧平原的戈瑟奇·邪眼。" },
        [7629] = { name = "瓶中的小鬼", objective = "把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。" },
        [7630] = { name = "奥金锭", objective = "把3块奥金锭交给燃烧平原的戈瑟奇·邪眼。" },
        [7631] = { name = "克索诺斯恐惧战马", objective = "阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。" },
        [7637] = { name = "牺牲精神", objective = "到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。" },
        [7639] = { name = "圣骑士的审判", objective = "把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。" },
        [7640] = { name = "恐惧谷的灵魂", objective = "使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。" },
        [7641] = { name = "格瑞曼德·艾尔默", objective = "与暴风城矮人区的格瑞曼德·艾尔默谈一谈。" },
        [7642] = { name = "收集材料", objective = "把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币交给暴风城矮人区的格瑞曼德·艾尔默。" },
        [7643] = { name = "上古圣马之魂", objective = "你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。\n\n到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。" },
        [7644] = { name = "被祝福的奥金马铠", objective = "将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。" },
        [7645] = { name = "魔法粮草", objective = "把制作魔法粮草所需要的重要材料：20块可口的魔法点心带给希尔斯布莱德丘陵的梅丽德丝·卡尔森。据说银色黎明会出售这种饼干。\n\n你还需要给她50金币来对她进行安抚。" },
        [7646] = { name = "预言水晶球", objective = "把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。" },
        [7647] = { name = "审判和救赎", objective = "在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。\n\n把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。" },
        [7648] = { name = "艾尔默的手艺", objective = "把奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。" },
        [7667] = { name = "收集材料", objective = "如果你愿意帮助奥格瑞玛智慧谷的萨格尼，就将一块艾泽拉斯钻石和一块原始黑钻石交给他。" },
        [7668] = { name = "达克雷尔的威胁", objective = "在通灵学院的尸骨储藏所地下室中心使用预言水晶球，这样将会召来一些灵魂，你必须与它们交战。将这些灵魂击败，死亡骑士达克雷尔就会出现。\n\n击败达克雷尔，将他的头颅交给奥格瑞玛智慧谷的萨格尼。" },
        [7703] = { name = "戈多克食人魔的事务", objective = "找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。\n\n根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。" },
        [7761] = { name = "黑手的命令", objective = "真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。\n\n你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。" },
        [7848] = { name = "熔火之心的传送门", objective = "进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。" },
        [8151] = { name = "猎人的护符", objective = "跟艾萨拉的奥汀克谈一谈。" },
        [8153] = { name = "苔蹄快步者的鹿角", objective = "将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。" },
        [8231] = { name = "碎浪多头怪", objective = "将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。" },
        [8232] = { name = "神庙中的绿龙", objective = "将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。" },
        [8233] = { name = "简单的要求", objective = "前往拉文霍德庄园，和乔拉齐·拉文霍德公爵谈一谈。" },
        [8234] = { name = "密封的蓝袋子", objective = "从艾萨拉的木喉萨满祭司那儿取回密封的蓝袋子，将它交给艾萨拉的大法师克希雷姆。" },
        [8235] = { name = "密文碎片", objective = "将10块密文碎片交给艾萨拉的大法师克希雷姆。" },
        [8236] = { name = "碧蓝钥匙", objective = "将碧蓝钥匙交给乔拉齐·拉文霍德公爵。" },
        [8250] = { name = "法师的会见", objective = "找到萨纳斯，让他将你传送到大法师克希雷姆那儿。" },
        [8251] = { name = "魔法的尘埃", objective = "为大法师克希雷姆收集10份闪光尘埃。" },
        [8252] = { name = "纳迦的珊瑚", objective = "收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。" },
        [8253] = { name = "毁灭摩弗拉斯", objective = "从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。" },
        [8254] = { name = "塞纳里奥议会的求助", objective = "找到艾萨拉的奥汀克。" },
        [8255] = { name = "苔蹄快步者", objective = "收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。" },
        [8256] = { name = "亡灵的腐液", objective = "为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。" },
        [8257] = { name = "摩弗拉斯之血", objective = "前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。" },
        [8410] = { name = "元素掌握", objective = "为捕风者巴斯拉收集一份空气样本、一份火元素样本、一份土元素样本和一份水元素样本。" },
        [8412] = { name = "灵魂图腾", objective = "将灵魂图腾所需的材料交给捕风者巴斯拉。" },
        [8413] = { name = "巫毒羽毛", objective = "将巫毒羽毛交给捕风者巴斯拉。" },
        [8414] = { name = "驱散邪恶", objective = "收集20个爪牙的天灾石，并将它们交给西瘟疫之地的高阶牧师赛尔丹尼斯。" },
        [8415] = { name = "冰风岗", objective = "与冰风岗的指挥官阿什拉姆·瓦罗菲斯特谈一谈。" },
        [8416] = { name = "惰性天灾石", objective = "将惰性天灾石交给冰风岗的指挥官阿什拉姆·瓦罗菲斯特。" },
        [8417] = { name = "困扰的灵魂", objective = "到诅咒之地的入口去，与部落英雄的灵魂谈一谈。" },
        [8418] = { name = "铸造力量之石", objective = "前往沉没的神庙，从巨魔守护者们身上取得巫毒羽毛，然后把它们交给阿什拉姆·瓦罗菲斯特。" },
        [8419] = { name = "小鬼的要求", objective = "将一块恶魔布交给费伍德森林的伊普斯。" },
        [8420] = { name = "灼热的疼痛", objective = "将一块恶魔布交给费伍德森林的伊普斯。" },
        [8421] = { name = "奇怪的材料", objective = "将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。" },
        [8422] = { name = "巨魔的羽毛", objective = "到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。" },
        [8423] = { name = "战士的血脉", objective = "杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。" },
        [8424] = { name = "魔誓者之战", objective = "杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。" },
        [8425] = { name = "巫毒羽毛", objective = "将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。" },
        [8945] = { name = "死人的请求", objective = "进入斯坦索姆，从瑞文戴尔男爵手中救出伊思达。" },
        [8948] = { name = "安泰恩的老朋友", objective = "将未完成的挑战之旗交给厄运之槌图书馆内的法尔林·树影。" },
        [8949] = { name = "法尔林的复仇", objective = "在厄运之槌和黑石塔的食人魔身上收集25串食人魔珠串，然后回去向厄运之槌图书馆内的法尔林·树影复命。" },
        [8950] = { name = "旗帜上的附魔", objective = "将1份游荡鬼灵的精华、4个黑暗符文和8个大块魔光碎片交给厄运之槌图书馆内的法尔林·树影。" },
        [9015] = { name = "挑战", objective = "到黑石深渊的竞技场去，在你被裁决者格里斯通宣判之后将挑战之旗插在场地中央。杀死塞尔德林和他的角斗士，然后将瓦塔拉克饰品第一部分交给东瘟疫之地的安泰恩·哈尔蒙。" },
        [9051] = { name = "毒性测试", objective = "将魔暴龙之刺扎入一只魔暴龙的体内。" },
        [9052] = { name = "血瓣毒药", objective = "收集一些血帽和格里什钉刺，然后向托尔瓦·寻路者复命。" },
        [9053] = { name = "更好的材料", objective = "从沉没的神庙底部的守卫身上得到一些腐烂藤蔓，把它们交给托尔瓦·寻路者。" },
        [9063] = { name = "托尔瓦·寻路者", objective = "与安戈洛环形山的托尔瓦·寻路者谈一谈。" },
        [78261] = { name = "谢尔索斯号角", objective = "找到影牙城堡内的谢尔索斯号角。然后，将它送回至焚木村附近C的秘密投放点。你必须独自完成这项任务。" },
        [79007] = { name = "……以及你找到的那张字条", objective = "残存的焦灼纸条是你唯一的向导。" },
